window.QDATA={"sessions":[{"id":"p1","eyebrow":"فارما ۱","title":"داروهای ضد درد و ضدالتهاب غیراستروئیدی (NSAID)","color":"navy","blurb":"۱۷ سوال. محور سوال‌ها آسپرین (مکانیسم، موارد ممنوعیت، تداخل با فنی‌توئین)، مقایسه‌ی داروهای مهارکننده‌ی <bdi>COX</bdi> (سلکوکسیب، سولنیداک، استامینوفن، ایبوپروفن، دیکلوفناک)، عوارض شاخص هر دارو (کبد، آنمی آپلاستیک، گوارش) و آنالوگ‌های پروستاگلاندین و مهارکننده‌های ۵-لیپواکسیژناز است.","count":17,"meta":"۱۷ سوال · سوال ۱ تا ۱۷"},{"id":"p2","eyebrow":"فارما ۲","title":"داروهای ضد نقرس","color":"navy","blurb":"۹ سوال. محور سوال‌ها مکانیسم داروهای ضد نقرس است: کاهش تولید اسید اوریک (آلوپورینول، فبوکسواستات)، افزایش دفع (پروبنسید، بنزبرومارون)، تجزیه‌ی اسید اوریک (رازبوریکاز، پگلوتیکاز) و درمان حمله‌ی حاد. سوال «مکانیسم فبوکسواستات مشابه کدام دارو است» و «کدام دارو اسید اوریک را تجزیه می‌کند» بارها تکرار شده‌اند.","count":9,"meta":"۹ سوال · سوال ۱۸ تا ۲۶"},{"id":"p3","eyebrow":"پاتو ۱","title":"بیماری‌های استخوان، مفاصل و ماهیچه (دکتر پناهی)","color":"teal","blurb":"۲۴ سوال. محور سوال‌ها بیماری‌های ژنتیکی استخوان (استئوژنز ایمپرفکتا، آکندروپلازی، استئوپتروزیس)، استئونکروز و استئومیلیت، آرتریت روماتوئید، تومورهای استخوان (استئوئید استئوما، استئوکندروم، کیست آنوریسمی، سارکوم یوئینگ، کندروسارکوم) و تومورهای بافت نرم (لیپوسارکوم، فیبروماتوز، رابدومیوسارکوم) است. سوال‌های جابجایی <bdi>t</bdi>(11;22)، گریدینگ تومور استخوانی و تشخیص ضایعه‌ی کودک ۱۲ ساله با درد ستون فقرات از پرتکرارترین‌ها هستند.","count":24,"meta":"۲۴ سوال · سوال ۲۷ تا ۵۰"},{"id":"p4","eyebrow":"پاتو ۲","title":"بیماری‌هایCNS(دکتر صداقتی)","color":"rust","blurb":"۲۵ سوال. محور سوال‌ها تومورهای گلیال و عصبی است: آستروسیتوم (پیلوسیتیک، دیفیوز، گلیوبلاستوم)، الیگودندروگلیوما (حذف 1<bdi>p</bdi> و 19<bdi>q</bdi>)، اپاندیموما (روزت و سودوروزت)، مدولوبلاستوما، منژیوم، شوانوم و نوروفیبروم، به‌علاوه‌ی چند سوال از عفونت‌ها و سندرم‌های پارانئوپلاستیک. بیشتر سوال‌ها از روی توصیف بافت‌شناسی تشخیص می‌خواهند.","count":25,"meta":"۲۵ سوال · سوال ۵۱ تا ۷۵"},{"id":"full","eyebrow":"آخرین دوره تابستان ۱۴۰۵","title":"تلفیقی روماتولوژی: کلیدواژه‌های آخرین دوره","color":"mustard","blurb":"","count":20,"meta":"۲۰ سوال · با همان ترتیب اصلی"}],"questions":[{"id":"p1q01","session":"p1","full":false,"num":1,"text":"اگر مجبور به تجویز طولانی مدت و همزمان آسپرین و داروی ضد صرع فنی توئین در یک بیمار شویم، چه اقدامی را توصیه می کنید؟","opts":["افزایش دوز فنی توئین","کاهش دوز فنی توئین","افزایش دوز آسپرین","کاهش دوز آسپرین"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[1]}],"answer":1,"explain":"<p>آسپرین به‌شدت به آلبومین متصل است (۸۰ تا ۹۰ درصد) و <strong>فنی‌توئین</strong> را از آلبومین جابه‌جا می‌کند؛ در نتیجه مقدار <strong>آزاد</strong> فنی‌توئین بالا می‌رود. غلظت بالای فنی‌توئین می‌تواند بیمار را به کما ببرد، پس در مصرف هم‌زمان طولانی‌مدت باید <strong>دوز فنی‌توئین را کم کرد</strong> (یا اصلاً آسپرین نداد).</p>\n<ul><li><strong>الف) افزایش دوز فنی‌توئین:</strong> مقدار آزاد دارو از قبل بالا رفته است؛ بالا بردن دوز مسمومیت (نیستاگموس، آتاکسی، کما) را بدتر می‌کند.</li><li><strong>ج) افزایش دوز آسپرین:</strong> جابه‌جایی بیشتری ایجاد می‌کند و فنی‌توئین آزاد را باز هم بالاتر می‌برد؛ ضمناً عوارض خود آسپرین را زیاد می‌کند.</li><li><strong>د) کاهش دوز آسپرین:</strong> راهکار جزوه تنظیم دوز داروی ضدصرع است، نه آسپرین؛ مسئله در غلظت آزاد فنی‌توئین (دارویی با پنجره‌ی درمانی باریک) است و باید همان کنترل شود.</li></ul>","flag":"","lesson":"<ul><li>آسپرین پروتئین‌باند است: ۸۰ تا ۹۰ درصد به آلبومین متصل می‌شود و داروهای دیگر را جابه‌جا می‌کند.</li><li>داروهایی که با آسپرین آزادشان بالا می‌رود: <strong>بیلی‌روبین، فنی‌توئین، تیوپنتال، <bdi>T3</bdi> و <bdi>T4</bdi></strong>، ناپروکسن و سولفین‌پیرازون.</li><li>فنی‌توئین + آسپرین: یا آسپرین نمی‌دهیم یا دوز فنی‌توئین را کم می‌کنیم.</li><li>بیمار کم‌آلبومین (کبدی/کلیوی) با همان دوز، مقدار آزاد بیشتری دارد؛ در داروهای با پنجره‌ی درمانی باریک حیاتی است.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: افزایش دوز داروی ضدصرع برای «جبران» اثر؛ برعکس، مشکل بالا رفتن مقدار آزاد دارو است.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش تداخلات دارویی آسپرین (جابه‌جایی داروهای با اتصال پروتئینی بالا)</p>","steps":"<p>کلیدواژه‌ها: «آسپرین» و «فنی‌توئین» هم‌زمان و طولانی‌مدت؛ هر دو داروی پروتئین‌باند هستند.</p>\n<p>آسپرین فنی‌توئین را از آلبومین جدا می‌کند و فنی‌توئین آزاد بالا می‌رود.</p>\n<p>خطر بالا رفتن فنی‌توئین مسمومیت و کما است؛ پس باید آن را کاهش داد، نه افزایش (حذف گزینه‌های الف و ج).</p>\n<p>تنظیم دوز روی داروی ضدصرع انجام می‌شود، نه آسپرین (حذف گزینه‌ی د).</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: افزایش دوز داروی ضدصرع برای «جبران» اثر؛ برعکس، مشکل بالا رفتن مقدار آزاد دارو است."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q02","session":"p1","full":false,"num":2,"text":"کدامیک از داروهای ضد التهابی غیر استروییدی به صورت کرم موضعی برای درمان استئوآرتریت زانو در بازار موجود است؟","opts":["<bdi>Meloxicam</bdi>","<bdi>Piroxicam</bdi>","<bdi>Ibuprofen</bdi>","<bdi>Diclofenac</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[2]}],"answer":2,"explain":"<p>در جزوه برای <strong>ایبوپروفن</strong> کرم موضعی مالشی ذکر شده است که روی مفصل (به‌ویژه زانو در آرتروز) مصرف می‌شود و جذب موضعی دارد؛ ژل لثه‌ای آن هم برای درد دندان کودکان کاربرد دارد.</p>\n<ul><li><strong>الف) <bdi>Meloxicam</bdi>:</strong> در جزوه به‌عنوان داروی نسبتاً جدید و مورد علاقه‌ی روماتولوژیست‌ها (با مهار بیشتر <bdi>COX-2</bdi>) معرفی شده، نه به‌صورت کرم موضعی.</li><li><strong>ب) <bdi>Piroxicam</bdi>:</strong> در جزوه بیشتر به‌صورت پماد (با بوی تند) شناخته می‌شود و نه «کرم آرتروز زانو»؛ ویژگی شاخص آن نیمه‌عمر طولانی است.</li><li><strong>د) <bdi>Diclofenac</bdi>:</strong> فرآورده‌هایی که جزوه برای آن می‌شمارد قطره‌ی چشمی، شیاف، آمپول عضلانی و دهان‌شویه است؛ شاخص‌ترین عارضه‌اش هم سمیت کبدی است.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون گزینه‌ی ج است، ولی پیروکسیکام (ب) و دیکلوفناک (د؛ ژل موضعی رایج برای آرتروز زانو) هم فرآورده‌ی موضعی دارند؛ چون جزوه صراحتاً کرم موضعی ایبوپروفن را برای آرتروز زانو ذکر می‌کند، ج به‌عنوان پاسخ مورد نظر انتخاب شد.","lesson":"<div class=\"tw\"><table><thead><tr><th>دارو</th><th>فرآورده‌ی شاخص در جزوه</th></tr></thead><tbody><tr><td>ایبوپروفن</td><td>کرم موضعی آرتروز زانو، ژل لثه</td></tr><tr><td>پیروکسیکام</td><td>پماد موضعی، نیمه‌عمر طولانی</td></tr><tr><td>دیکلوفناک</td><td>قطره‌ی چشمی، شیاف، آمپول، دهان‌شویه</td></tr><tr><td>ایندومتاسین</td><td>قطره‌ی چشمی، دهان‌شویه، تزریق اپیدورال پس از لامینکتومی</td></tr></tbody></table></div>\n<ul><li>ایبوپروفن (ژلوفن): دوزهای ۲۰۰ یا ۴۰۰ میلی‌گرم؛ برای اثر ضدالتهابی به دوز بیشتر نیاز دارد.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>نکته: ژل دیکلوفناک هم در عمل برای آرتروز زانو به کار می‌رود؛ ولی در این سؤال بر پایه‌ی جزوه، «کرم آرتروز زانو» یعنی ایبوپروفن.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش ایبوپروفن (کرم موضعی برای آرتروز، به‌ویژه زانو)</p>","steps":"<p>کلیدواژه‌ها: «کرم موضعی» و «استئوآرتریت زانو».</p>\n<p>در جزوه، این کاربرد برای ایبوپروفن آمده است: کرم مالشی روی مفصل با جذب موضعی.</p>\n<p>ملوکسیکام در جزوه فرآورده‌ی موضعی ندارد؛ پیروکسیکام بیشتر پماد است و دیکلوفناک با قطره، شیاف و آمپول شناخته می‌شود.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>نکته: ژل دیکلوفناک هم در عمل برای آرتروز زانو به کار می‌رود؛ ولی در این سؤال بر پایه‌ی جزوه، «کرم آرتروز زانو» یعنی ایبوپروفن."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q03","session":"p1","full":false,"num":3,"text":"عوارض گوارشی کدام داروی مهارکننده آنزیم سیکلواکسیژناز بسیار ناچیز است؟","opts":["سلکوکسیب","آسپرین","سولنیداک","استامینوفن"],"labels":["الف","ب","ج","د"],"exams":[{"name":"فارما 96A","nums":[2]}],"answer":3,"explain":"<p><strong>استامینوفن</strong> سیکلواکسیژناز را ضعیف مهار می‌کند و پروستاگلاندین‌های حفاظت‌کننده‌ی معده (<bdi>PGE2</bdi> و <bdi>PGI2</bdi>) را به‌طور قابل‌توجه کم نمی‌کند؛ مزیت آن نسبت به <bdi>NSAID</bdi>ها در جزوه همین «نداشتن عوارض گوارشی (زخم)» است.</p>\n<ul><li><strong>الف) سلکوکسیب:</strong> عوارض گوارشی‌اش به‌مراتب کمتر از <bdi>NSAID</bdi>های غیرانتخابی است، ولی صفر نیست (فایده‌ی بلندمدت هنوز روشن نیست)؛ تنها گزینه‌ی رقیب و قابل دفاع.</li><li><strong>ب) آسپرین:</strong> مهار <bdi>COX-1</bdi> معده و جریان خون مخاط را کم می‌کند؛ از شایع‌ترین عوامل زخم و خونریزی گوارشی است.</li><li><strong>ج) سولنیداک:</strong> یک <bdi>NSAID</bdi> غیرانتخابی (نسبت <bdi>IC50</bdi> برابر ۱۰۰ در جدول جزوه) است و عوارض گوارشی <bdi>NSAID</bdi>ها را دارد.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی سلکوکسیب (الف) هم از نظر عوارض گوارشی «به‌مراتب کمتر» است و قابل دفاع است؛ چون عبارت «بسیار ناچیز» به داروی بدون زخم گوارشی نزدیک‌تر است (استامینوفن در جزوه: مزیت، نداشتن عوارض گوارشی) گزینه‌ی د انتخاب شد.","lesson":"<ul><li>پروستاگلاندین‌های معده (<bdi>PGE2</bdi> و <bdi>PGI2</bdi>): کاهش ترشح اسید، افزایش جریان خون مخاط، افزایش ترشح بی‌کربنات و موکوس.</li><li>مهار <bdi>COX-1</bdi> باعث زخم گوارشی می‌شود؛ مهار <bdi>COX-2</bdi> اثر ضدالتهاب، ضددرد و تب‌بر می‌دهد.</li><li>سلکوکسیب: عوارض گوارشی به‌مراتب کمتر، ولی اثر ضدانعقادی ندارد و عارضه‌ی قلبی‌عروقی گزارش شده است.</li><li>استامینوفن: تب‌بر و ضددرد، بدون اثر ضدالتهابی و ضدانعقادی؛ سمیت کبدی در دوز بالا و پادزهر آن <bdi>N-acetylcysteine</bdi>.</li><li>قاعده: بیمار با زخم گوارشی <bdi>NSAID</bdi> نمی‌گیرد؛ استامینوفن جایگزین مناسب است.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: «کمتر» را با «ناچیز/نداشتن» یکی گرفتن؛ سلکوکسیب کمتر است، استامینوفن عملاً زخم‌زا نیست.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش استامینوفن و بخش مهارکننده‌های اختصاصی <bdi>COX-2</bdi></p>","steps":"<p>کلیدواژه‌ها: «بسیار ناچیز» بودن عارضه‌ی گوارشی در بین مهارکننده‌های <bdi>COX</bdi>.</p>\n<p>آسپرین و سولنیداک <bdi>NSAID</bdi> غیرانتخابی‌اند و زخم گوارشی می‌دهند (حذف ب و ج).</p>\n<p>سلکوکسیب عارضه‌ی گوارشی کمتر دارد، اما کاملاً بدون عارضه نیست.</p>\n<p>استامینوفن مزیتش نسبت به <bdi>NSAID</bdi>ها همین نداشتن عوارض گوارشی است.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: «کمتر» را با «ناچیز/نداشتن» یکی گرفتن؛ سلکوکسیب کمتر است، استامینوفن عملاً زخم‌زا نیست."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q04","session":"p1","full":false,"num":4,"text":"کدامیک از آنالوگ‌های پروستاگلاندین به صورت قطره چشمی برای درمان گلوکوم استفاده می‌شود؟","opts":["داینوپروستون","آلپروستادیل","لاتانوپروست","میزوپروستول"],"labels":["الف","ب","ج","د"],"exams":[{"name":"فارما 96A","nums":[3]}],"answer":2,"explain":"<p><strong>لاتانوپروست</strong> مشتق پایدار و طولانی‌اثر <bdi>PGF2</bdi>α و اولین پروستانوئید مصرف‌شده در گلوکوم است؛ به‌صورت قطره در کیسه‌ی ملتحمه، یک یا دو بار در روز، فشار چشم را پایین می‌آورد.</p>\n<ul><li><strong>الف) داینوپروستون:</strong> همان <bdi>PGE2</bdi> مصنوعی است که به‌صورت واژینال برای رسیدگی سرویکس و القای زایمان یا سقط به‌کار می‌رود.</li><li><strong>ب) آلپروستادیل:</strong> آنالوگ <bdi>PGE1</bdi> است و کاربردهایش باز نگه‌داشتن مجرای شریانی نوزاد و اختلال نعوظ است، نه گلوکوم.</li><li><strong>د) میزوپروستول:</strong> آنالوگ <bdi>PGE1</bdi> است که همراه <bdi>NSAID</bdi> برای محافظت گوارشی (و در زنان‌وزایی) استفاده می‌شود.</li></ul>","flag":"","lesson":"<div class=\"tw\"><table><thead><tr><th>دارو</th><th>گروه</th><th>کاربرد</th></tr></thead><tbody><tr><td>لاتانوپروست</td><td><bdi>PGF2</bdi>α</td><td>گلوکوم (قطره‌ی چشمی)</td></tr><tr><td>دینوپروستون</td><td><bdi>PGE2</bdi></td><td>القای زایمان/سقط (واژینال)</td></tr><tr><td>میزوپروستول</td><td><bdi>PGE1</bdi> (جزوه <bdi>PGE2</bdi> نوشته؛ مراجع استاندارد <bdi>PGE1</bdi>)</td><td>محافظت معده در مصرف <bdi>NSAID</bdi></td></tr><tr><td>آلپروستادیل</td><td><bdi>PGE1</bdi></td><td>مجرای شریانی باز نوزاد، نعوظ</td></tr></tbody></table></div>\n<ul><li>عوارض لاتانوپروست: رنگدانه‌ی قهوه‌ای برگشت‌ناپذیر عنبیه، خشکی چشم و ملتحمه.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: اشتباه گرفتن آنالوگ‌های <bdi>PGE</bdi> با <bdi>PGF2</bdi>α؛ پایان نام «پروست» در چشم یعنی لاتانوپروست (<bdi>PGF2</bdi>α).</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش اثرات پروستاگلاندین‌ها (گلوکوم و لاتانوپروست)؛ آلپروستادیل: مرجع <bdi>Katzung</bdi> (در جزوه نبود)</p>","steps":"<p>کلیدواژه‌ها: «آنالوگ پروستاگلاندین»، «قطره‌ی چشمی» و «گلوکوم».</p>\n<p>داینوپروستون (<bdi>PGE2</bdi>) واژینال است و میزوپروستول برای معده؛ آلپروستادیل برای مجرای شریانی و نعوظ.</p>\n<p>تنها آنالوگ <bdi>PGF2</bdi>α برای کاهش فشار چشم لاتانوپروست است.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: اشتباه گرفتن آنالوگ‌های <bdi>PGE</bdi> با <bdi>PGF2</bdi>α؛ پایان نام «پروست» در چشم یعنی لاتانوپروست (<bdi>PGF2</bdi>α)."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q05","session":"p1","full":false,"num":5,"text":"کدامیک از اثرات آسپرین نمی‌باشد؟","opts":["ضد التهاب","ضد تجمع پلاکت‌ها","ضد فاکتور ۲ انعقادی","پایین آورنده تب"],"labels":["الف","ب","ج","د"],"exams":[{"name":"فارما 96A","nums":[6]}],"answer":2,"explain":"<p>آسپرین چهار اثر <bdi>NSAID</bdi>ها را دارد: ضددرد، تب‌بر، ضدالتهاب (در دوز بالا) و ضدانعقاد در دوز پایین. اثر ضدانعقادی آن از <strong>مهار <bdi>COX-1</bdi> پلاکت و کاهش <bdi>TXA2</bdi></strong> است که لخته‌ی سفید پلاکتی را نمی‌سازد؛ یعنی روی <strong>تجمع پلاکتی</strong> اثر می‌کند، نه روی عامل انعقادی مثل فاکتور ۲ (که هدف داروهایی مثل هپارین، وارفارین و مهارکننده‌های ترومبین است).</p>\n<ul><li><strong>الف) ضدالتهاب:</strong> از اثرات آسپرین است، ولی دوز لازم بالا است (۴ تا ۶ گرم در روز).</li><li><strong>ب) ضد تجمع پلاکت‌ها:</strong> اثر شاخص آسپرین در دوز پایین (۸۰ تا ۱۰۰ میلی‌گرم) است.</li><li><strong>د) پایین‌آورنده‌ی تب:</strong> با کاهش <bdi>PGE2</bdi> هیپوتالاموس، ست‌پوینت را به حدود ۳۷ درجه برمی‌گرداند.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی عبارت «ضد فاکتور ۲ انعقادی» دقیق نیست؛ اثر ضدانعقادی آسپرین از راه مهار تجمع پلاکتی است، نه مهار عوامل انعقادی (فقط در دوزهای بسیار بالا هیپوپروترومبینمی گزارش شده)، و سؤال را «اثر شاخص آسپرین نیست» خوانده‌ایم.","lesson":"<div class=\"tw\"><table><thead><tr><th>کاربرد آسپرین</th><th>دوز</th></tr></thead><tbody><tr><td>ضدانعقاد (ضدپلاکت)</td><td>۸۰ تا ۱۰۰ <bdi>mg</bdi> در روز</td></tr><tr><td>ضددرد و تب‌بر</td><td>۳۲۵ تا ۶۵۰ <bdi>mg</bdi> هر ۴ ساعت</td></tr><tr><td>ضدالتهاب</td><td>۴ تا ۶ <bdi>g</bdi> در روز</td></tr></tbody></table></div>\n<ul><li>دوز پایین فقط <bdi>COX-1</bdi> پلاکت و <bdi>TXA2</bdi> را مهار می‌کند؛ دوز بالا <bdi>PGI2</bdi> را هم کم می‌کند و اثر ضدانعقاد برعکس می‌شود.</li><li>نیمه‌عمر: ۲ تا ۳ ساعت در دوز درمانی، حدود ۱۲ ساعت در دوز ضدالتهاب، ۱۵ تا ۳۰ ساعت در دوز سمی.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: ضدانعقاد بودن آسپرین را مهار فاکتورهای انعقادی دانستن؛ آسپرین ضدپلاکت است.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش اثر ضدانعقاد آسپرین</p>","steps":"<p>کلیدواژه: «کدام اثر آسپرین نیست».</p>\n<p>ضدالتهاب، ضدپلاکت و تب‌بر هر سه از اثرات شناخته‌شده‌ی آسپرین هستند.</p>\n<p>آسپرین با مهار <bdi>TXA2</bdi> پلاکت عمل می‌کند و عامل انعقادی (فاکتور ۲) را هدف نمی‌گیرد.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: ضدانعقاد بودن آسپرین را مهار فاکتورهای انعقادی دانستن؛ آسپرین ضدپلاکت است."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q06","session":"p1","full":false,"num":6,"text":"داروی سلکوکسیب چه مزیتی نسبت به ناپروکسن دارد؟","opts":["کاهش بروز زخم معده","کاهش عوارض کلیوی","افزایش اثر ضد انعقادی","کاهش عوارض قلبی-عروقی"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی 96A","nums":[1]}],"answer":0,"explain":"<p><strong>سلکوکسیب</strong> مهارکننده‌ی اختصاصی <bdi>COX-2</bdi> است؛ تب را پایین می‌آورد، درد و التهاب را کنترل می‌کند و چون <bdi>COX-1</bdi> معده را کمتر مهار می‌کند، <strong>زخم و عوارض گوارشی</strong> به‌مراتب کمتری نسبت به ناپروکسن (<bdi>NSAID</bdi> غیراختصاصی؛ در جدول جزوه کمترین نسبت <bdi>IC50</bdi> یعنی ۰٫۶ را دارد و هر دو <bdi>COX</bdi> را مهار می‌کند) دارد.</p>\n<ul><li><strong>ب) کاهش عوارض کلیوی:</strong> عوارض کلیوی این گروه دست‌کم به اندازه‌ی <bdi>NSAID</bdi>های معمول است، چون کلیه برای حفظ جریان خون به پروستاگلاندین وابسته است.</li><li><strong>ج) افزایش اثر ضدانعقادی:</strong> برعکس، سلکوکسیب اثر ضدترومبوتیک ندارد، چون <bdi>COX-1</bdi> پلاکت را مهار نمی‌کند.</li><li><strong>د) کاهش عوارض قلبی‌عروقی:</strong> اثر محافظتی بر قلب ندارد و درباره‌ی بعضی از این گروه عوارض قلبی‌عروقی گزارش شده است (روفکوکسیب به همین دلیل از بازار جمع شد).</li></ul>","flag":"","lesson":"<ul><li>نسبت <bdi>IC50</bdi>(<bdi>COX-2</bdi>)/<bdi>IC50</bdi>(<bdi>COX-1</bdi>) هرچه کمتر باشد، دارو اختصاصی‌تر برای <bdi>COX-2</bdi> است: سلکوکسیب و روفکوکسیب کمتر از ۰٫۰۰۱؛ ناپروکسن ۰٫۶؛ دیکلوفناک ۰٫۷؛ ایبوپروفن ۱۵؛ ایندومتاسین ۶۰؛ سولنیداک ۱۰۰.</li><li>مزیت سلکوکسیب: عوارض گوارشی کمتر (مطالعات کوتاه‌مدت ۱ تا ۲ سال)؛ فایده‌ی بلندمدت هنوز روشن نیست.</li><li>هیچ‌گاه نگویید «فقط <bdi>COX-2</bdi>»؛ اختصاصی یعنی <bdi>COX-2</bdi> بیشتر و <bdi>COX-1</bdi> کمتر مهار می‌شود.</li><li>در ایران از این گروه سلکوکسیب در بازار است.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: تصور اینکه مهارکننده‌ی <bdi>COX-2</bdi> «قلب و کلیه را هم حفظ می‌کند»؛ فقط مزیت گوارشی دارد.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش مهارکننده‌های اختصاصی <bdi>COX-2</bdi> (سلکوکسیب)</p>","steps":"<p>کلیدواژه‌ها: «سلکوکسیب» (مهارکننده‌ی اختصاصی <bdi>COX-2</bdi>) و «مزیت» نسبت به ناپروکسن.</p>\n<p><bdi>COX-1</bdi> محافظ معده و کلیه است؛ سلکوکسیب آن را کمتر مهار می‌کند، پس مزیت اصلی روی معده است.</p>\n<p>کلیه بهتر نمی‌شود، اثر ضدانعقادی ندارد و قلب هم محافظت نمی‌شود (حذف ب، ج، د).</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: تصور اینکه مهارکننده‌ی <bdi>COX-2</bdi> «قلب و کلیه را هم حفظ می‌کند»؛ فقط مزیت گوارشی دارد."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q07","session":"p1","full":false,"num":7,"text":"کدام داروی مهار کننده آنزیم سیکلواکسیژناز اثر ضد التهابی ندارد؟","opts":["استامینوفن","آسپرین","سلکوکسیب","سولنیداک"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[5]},{"name":"تلفیقی 96A","nums":[2]}],"answer":0,"explain":"<p><strong>استامینوفن</strong> <bdi>COX-1</bdi> و <bdi>COX-2</bdi> را فقط ضعیف مهار می‌کند و تب‌بر و ضددرد است، ولی <strong>ضدالتهاب نیست</strong> و ضدانعقاد هم نیست؛ این از سؤال‌های همیشگی استاد است.</p>\n<ul><li><strong>ب) آسپرین:</strong> ضدالتهاب است (در دوز بالا، حدود ۴ تا ۶ گرم در روز).</li><li><strong>ج) سلکوکسیب:</strong> مهارکننده‌ی اختصاصی <bdi>COX-2</bdi> است که درد و التهاب را کنترل می‌کند.</li><li><strong>د) سولنیداک:</strong> <bdi>NSAID</bdi> غیرانتخابی است (در جدول جزوه) و اثر ضدالتهابی دارد.</li></ul>","flag":"","lesson":"<div class=\"tw\"><table><thead><tr><th>دارو</th><th>تب‌بر</th><th>ضددرد</th><th>ضدالتهاب</th><th>ضدانعقاد</th></tr></thead><tbody><tr><td>آسپرین</td><td>بله</td><td>بله</td><td>بله (دوز بالا)</td><td>بله (دوز پایین)</td></tr><tr><td><bdi>NSAID</bdi>های دیگر</td><td>بله</td><td>بله</td><td>بله</td><td>اثر پلاکتی متغیر</td></tr><tr><td>سلکوکسیب</td><td>بله</td><td>بله</td><td>بله</td><td>ندارد</td></tr><tr><td>استامینوفن</td><td>بله</td><td>بله</td><td>ندارد</td><td>ندارد</td></tr></tbody></table></div>\n<ul><li>مزیت استامینوفن: نداشتن عوارض گوارشی؛ در بیمار با زخم گوارشی یا اختلال انعقاد ترجیح دارد.</li><li>سمیت: متابولیت واکنش‌پذیر (<bdi>P450</bdi>) با گلوتاتیون خنثی می‌شود؛ در دوز سمی (۱۰ تا ۱۵ گرم) نکروز کبد؛ پادزهر <bdi>N-acetylcysteine</bdi>.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: استامینوفن را «<bdi>NSAID</bdi> ضدالتهاب» دانستن؛ فقط تب‌بر و ضددرد است.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش استامینوفن (تأکید استاد)</p>","steps":"<p>کلیدواژه‌ها: «مهارکننده‌ی <bdi>COX</bdi>» و «اثر ضدالتهابی ندارد».</p>\n<p>آسپرین، سلکوکسیب و سولنیداک همگی <bdi>NSAID</bdi> هستند و ضدالتهابند.</p>\n<p>تنها دارویی که <bdi>COX</bdi> را ضعیف مهار می‌کند ولی ضدالتهاب نیست استامینوفن است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: استامینوفن را «<bdi>NSAID</bdi> ضدالتهاب» دانستن؛ فقط تب‌بر و ضددرد است."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q08","session":"p1","full":false,"num":8,"text":"آسپرین در کدامیک از موارد زیر ممنوع می‌باشد؟","opts":["پرکاری تیروئید","همزمان با مصرف داروی ضد صرع کاربامازپین","همزمان با بی‌هوشی با داروی کتامین","پانکراتیت حاد"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی 96A","nums":[3]}],"answer":0,"explain":"<p>در <strong>تیروتوکسیکوز (پرکاری تیروئید)</strong> یا بیماری که داروی ضدتیروئید مصرف می‌کند، آسپرین نباید داده شود، چون <bdi>T3</bdi> و <bdi>T4</bdi> را از پروتئین جابه‌جا و مقدار آزاد هورمون را بالا می‌برد.</p>\n<ul><li><strong>ب) هم‌زمان با کاربامازپین:</strong> در فهرست تداخلات و موارد منع آسپرین در جزوه نیامده است؛ داروهایی که با آسپرین آزادشان بالا می‌رود فنی‌توئین، تیوپنتال، بیلی‌روبین و هورمون‌های تیروئید هستند.</li><li><strong>ج) هم‌زمان با کتامین:</strong> جزوه فقط تیوپنتال (بیهوشی تزریقی) را ذکر می‌کند که با آسپرین آزادش بالا می‌رود و کنترل بیهوشی دشوار می‌شود؛ کتامین ذکر نشده است.</li><li><strong>د) پانکراتیت حاد:</strong> منع مصرف آسپرین به این صورت در جزوه نیامده است؛ موارد منع/احتیاط جزوه گوارش (زخم)، زردی، پرکاری تیروئید، کودکان با عفونت ویروسی (سندرم ری) و نزدیک زایمان است.</li></ul>","flag":"","lesson":"<ul><li>موارد منع/احتیاط آسپرین: <strong>بیمار زردی‌دار، پرکاری تیروئید، کودک با عفونت ویروسی (سندرم ری)، زخم گوارشی، نزدیک زایمان</strong>.</li><li>تیروئید: <bdi>T3</bdi> و <bdi>T4</bdi> با آسپرین آزاد می‌شوند؛ بیماری که ضدتیروئید می‌گیرد هم آسپرین نمی‌گیرد.</li><li>تیوپنتال (نه کتامین) با آسپرین آزاد می‌شود؛ فنی‌توئین (نه کاربامازپین) هم همین‌طور.</li><li>ایبوپروفن در مصرف چندروزه (۳ تا ۴ روز) اثر ضدپلاکتی آسپرین را خنثی می‌کند (یک نوبت مصرف آن را از بین نمی‌برد).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: جایگزین کردن نام داروهای هم‌گروه (کتامین به‌جای تیوپنتال، کاربامازپین به‌جای فنی‌توئین).</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش تداخلات دارویی آسپرین (هورمون‌های تیروئیدی، تیوپنتال، فنی‌توئین، بیلی‌روبین)</p>","steps":"<p>کلیدواژه: «آسپرین ممنوع است».</p>\n<p>آسپرین داروهای پروتئین‌باند را آزاد می‌کند: <bdi>T3</bdi> و <bdi>T4</bdi>، فنی‌توئین، تیوپنتال، بیلی‌روبین.</p>\n<p>کاربامازپین و کتامین جزو این فهرست نیستند و پانکراتیت هم ذکر نشده است (حذف ب، ج، د).</p>\n<p>پرکاری تیروئید به‌خاطر بالا رفتن <bdi>T3</bdi> و <bdi>T4</bdi> آزاد مصرف آسپرین را ممنوع می‌کند.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: جایگزین کردن نام داروهای هم‌گروه (کتامین به‌جای تیوپنتال، کاربامازپین به‌جای فنی‌توئین)."],"dupOf":null,"dupNote":"","xrefs":["p1q14"]},{"id":"p1q09","session":"p1","full":false,"num":9,"text":"کدامیک از آنالوگ‌های پروستاگلاندین به صورت ژل واژینال برای القای زایمان استفاده می‌شود؟","opts":["داینوپروستون","لاتانوپروست","میزوپروستول","آلپروستادیل"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی 96A","nums":[4]}],"answer":0,"explain":"<p><strong>داینوپروستون (دینوپروستون)</strong> فرآورده‌ی مصنوعی <strong><bdi>PGE2</bdi></strong> است که به‌صورت واژینال و به‌عنوان اکسی‌توسیک تجویز می‌شود؛ برای القای سقط در سه‌ماهه‌ی دوم، سقط فراموش‌شده، مول هیداتیفورم خوش‌خیم و رسیدگی سرویکس برای القای زایمان در بیمار نزدیک به ترم یا ترم تأیید شده است.</p>\n<ul><li><strong>ب) لاتانوپروست:</strong> <bdi>PGF2</bdi>α است و برای گلوکوم به‌صورت قطره‌ی چشمی به‌کار می‌رود.</li><li><strong>ج) میزوپروستول:</strong> آنالوگ <bdi>PGE1</bdi> است (جزوه آن را <bdi>PGE2</bdi> نوشته؛ در <bdi>Katzung</bdi> و مراجع استاندارد <bdi>PGE1</bdi> است) که در جزوه برای محافظت معده همراه <bdi>NSAID</bdi> (مثلاً در ترکیب با ناپروکسن) آمده؛ مصرف واژینال آن در زایمان در منابع دیگر هم هست، ولی «ژل واژینال» دینوپروستون است.</li><li><strong>د) آلپروستادیل:</strong> <bdi>PGE1</bdi> است و کاربرد آن مجرای شریانی باز نوزاد و اختلال نعوظ است.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون گزینه‌ی الف است، ولی میزوپروستول (ج) هم در عمل به‌صورت واژینال برای القای زایمان به‌کار می‌رود و قابل دفاع است؛ چون جزوه فقط دینوپروستون واژینال را برای رسیدگی سرویکس و القای زایمان ذکر می‌کند (میزوپروستول را فقط برای محافظت گوارشی)، الف انتخاب شد.","lesson":"<ul><li>دینوپروستون = <bdi>PGE2</bdi>، واژینال: رسیدگی سرویکس، القای زایمان، سقط سه‌ماهه‌ی دوم، سقط فراموش‌شده، مول هیداتیفورم خوش‌خیم.</li><li><bdi>PGE2</bdi> و اکسی‌توسین برهم‌کنش حیاتی در شروع زایمان دارند.</li><li>لاتانوپروست = <bdi>PGF2</bdi>α، قطره‌ی چشمی گلوکوم؛ میزوپروستول = <bdi>PGE1</bdi>، محافظ معده.</li><li><bdi>NSAID</bdi>ها انقباض رحم را مهار می‌کنند؛ نزدیک زایمان ممنوع‌اند.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: انتخاب میزوپروستول چون «ضد زخم» به‌ذهن می‌آید؛ آنالوگ مخصوص ژل واژینال القای زایمان در درس، دینوپروستون است.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش اثرات پروستاگلاندین‌ها (دستگاه تناسلی زنانه، دینوپروستون)</p>","steps":"<p>کلیدواژه‌ها: «ژل واژینال» و «القای زایمان».</p>\n<p><bdi>PGE2</bdi> و اکسی‌توسین در شروع زایمان نقش دارند؛ فرآورده‌ی واژینال <bdi>PGE2</bdi> دینوپروستون است.</p>\n<p>لاتانوپروست (چشم) و آلپروستادیل (مجرای شریانی/نعوظ) مربوط نیستند.</p>\n<p>میزوپروستول در جزوه برای معده است، پس گزینه‌ی الف.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: انتخاب میزوپروستول چون «ضد زخم» به‌ذهن می‌آید؛ آنالوگ مخصوص ژل واژینال القای زایمان در درس، دینوپروستون است."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q10","session":"p1","full":false,"num":10,"text":"اختلال عملکرد کبد در مصرف کدام داروی ضد التهاب غیر استروئیدی شایع‌تر است؟","opts":["<bdi>ASA</bdi>","<bdi>Diclofenac</bdi>","<bdi>Iboprofen</bdi>","<bdi>Piroxicam</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی پاییز ۱۴۰۰","nums":[3]}],"answer":1,"explain":"<p>در جزوه تصریح شده است که <strong>دیکلوفناک</strong> بیشترین عوارض کبدی را در میان <bdi>NSAID</bdi>ها دارد، آنزیم‌های کبدی را بالا می‌برد و در بیمار کبدی داده نمی‌شود.</p>\n<ul><li><strong>الف) <bdi>ASA</bdi> (آسپرین):</strong> عارضه‌های شاخصش گوارشی، خونریزی و سندرم ری در کودکان است؛ بیماری کبدی در جزوه به دیکلوفناک نسبت داده شده است.</li><li><strong>ج) <bdi>Ibuprofen</bdi>:</strong> عارضه‌های شاخصش اثر کلیوی (احتباس آب)، حساسیت و برونکواسپاسم است.</li><li><strong>د) <bdi>Piroxicam</bdi>:</strong> ویژگی شاخصش نیمه‌عمر طولانی و پماد موضعی است، نه سمیت کبدی.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی نام گزینه‌ی ج «<bdi>Iboprofen</bdi>» غلط املایی <bdi>Ibuprofen</bdi> است و به پاسخ آسیب نمی‌زند.","lesson":"<ul><li>دیکلوفناک: <strong>بیشترین عوارض کبدی</strong> (بالا رفتن آنزیم‌های کبدی) در بین <bdi>NSAID</bdi>ها؛ در بیمار کبدی ممنوع.</li><li>ایبوپروفن: اثر کلیوی (احتباس آب)، حساسیت‌زا (آسم/آنژیوادم)؛ ایندومتاسین: انتخاب اول <bdi>PDA</bdi>.</li><li>پیروکسیکام: نیمه‌عمر طولانی؛ ملوکسیکام: <bdi>COX-2</bdi> بیشتر و عوارض گوارشی کمتر.</li><li>استامینوفن: سمیت کبدی با دوز بالا، نه از نوع عارضه‌ی معمول <bdi>NSAID</bdi>.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: به‌خاطر مسمومیت کبدی استامینوفن، «کبد» را به آن نسبت دادن؛ در بین <bdi>NSAID</bdi>ها دیکلوفناک شاخص است.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش دیکلوفناک (تأکید استاد)</p>","steps":"<p>کلیدواژه‌ها: «اختلال عملکرد کبد» و «شایع‌تر» در بین <bdi>NSAID</bdi>ها.</p>\n<p>در جزوه یک دارو بیشترین عوارض کبدی (بالا رفتن آنزیم‌های کبدی) را دارد: دیکلوفناک.</p>\n<p>آسپرین، ایبوپروفن و پیروکسیکام عوارض شاخص دیگری دارند.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: به‌خاطر مسمومیت کبدی استامینوفن، «کبد» را به آن نسبت دادن؛ در بین <bdi>NSAID</bdi>ها دیکلوفناک شاخص است."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q11","session":"p1","full":false,"num":11,"text":"آنمی آپلاستیک عارضه جانبی نادر کدام داروی ضد التهاب غیراستروئیدی است؟","opts":["<bdi>Diclofenac</bdi>","<bdi>Iboprofen</bdi>","<bdi>Meloxicam</bdi>","<bdi>Naproxen</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی پاییز ۱۴۰۰","nums":[4]}],"answer":1,"explain":"<p>آنمی آپلاستیک عارضه‌ی بسیار نادر هماتولوژیک <bdi>NSAID</bdi>ها است (شاخص‌ترین نمونه‌های تاریخی فنیل‌بوتازون و ایندومتاسین). در بین گزینه‌ها <strong>ایبوپروفن</strong> با فهرست صریح «<bdi>agranulocytosis</bdi>, <bdi>aplastic anemia</bdi>, <bdi>hemolytic anemia</bdi>» در اطلاعات دارویی خود بهترین انتخاب است.</p>\n<ul><li><strong>الف) <bdi>Diclofenac</bdi>:</strong> عارضه‌ی شاخص آن در جزوه بالا رفتن آنزیم‌های کبدی و آسیب کبدی است؛ ولی آنمی آپلاستیک نادر در برچسب دیکلوفناک هم فهرست شده، پس این گزینه کاملاً رد نمی‌شود و سؤال پاسخ یکتای قوی ندارد.</li><li><strong>ج) <bdi>Meloxicam</bdi>:</strong> مهار بیشتر <bdi>COX-2</bdi> دارد و عوارض گوارشی و پلاکتی کمتر؛ عارضه‌ی مغز استخوانی شاخصی برایش مطرح نیست.</li><li><strong>د) <bdi>Naproxen</bdi>:</strong> عارضه‌های شاخصش گوارشی و کلیوی (و قلبی‌عروقی) است؛ نادر بودن عوارض خونی در آن کمتر مطرح می‌شود.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی موضوع در جزوه نیامده و در برچسب چند <bdi>NSAID</bdi> (از جمله ایبوپروفن، ناپروکسن و دیکلوفناک) آنمی آپلاستیک به‌عنوان عارضه‌ی نادر فهرست شده است؛ ایبوپروفن (که نام آن در گزینه‌ی ب «<bdi>Iboprofen</bdi>» نوشته شده) به‌عنوان پاسخ محتمل‌تر انتخاب شد و سؤال از نظر منبع ضعیف است.","lesson":"<ul><li>عوارض نادر خونی <bdi>NSAID</bdi>ها: آگرانولوسیتوز، آنمی آپلاستیک، آنمی همولیتیک، ترومبوسیتوپنی؛ همه نادرند.</li><li>عوارض شاخص هر دارو: دیکلوفناک = کبد؛ ایبوپروفن = کلیه/حساسیت؛ پیروکسیکام = نیمه‌عمر طولانی؛ ناپروکسن = کمترین نسبت <bdi>IC50</bdi>.</li><li>استامینوفن: سمیت کبدی در دوز بالا؛ پادزهر <bdi>N-acetylcysteine</bdi>.</li><li><bdi>NSAID</bdi>ها: مهار تجمع پلاکتی و خطر خونریزی را هم به یاد داشته باشید.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: «نادر» را معادل «شایع‌ترین عارضه‌ی دارو» گرفتن؛ آنمی آپلاستیک عارضه‌ی نادر است و عارضه‌ی شاخص هیچ‌یک از این داروها نیست.</p><p class=\"ref\">مرجع: برچسب دارویی و <bdi>Katzung/Goodman</bdi> &amp; <bdi>Gilman</bdi> (در جزوه نبود)</p>","steps":"<p>کلیدواژه‌ها: «آنمی آپلاستیک» و «عارضه‌ی نادر».</p>\n<p>دیکلوفناک با کبد شناخته می‌شود و ملوکسیکام عوارض کمتری دارد.</p>\n<p>ناپروکسن عمدتاً گوارشی و کلیوی است و ایبوپروفن در فهرست عوارض نادر خونی صراحتاً آنمی آپلاستیک دارد.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: «نادر» را معادل «شایع‌ترین عارضه‌ی دارو» گرفتن؛ آنمی آپلاستیک عارضه‌ی نادر است و عارضه‌ی شاخص هیچ‌یک از این داروها نیست."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q12","session":"p1","full":false,"num":12,"text":"کدامیک از مهار کننده های آنزیم 5-لیپواکسیژناز می باشد و در درمان آسم استفاده می شود؟","opts":["زفیرلوکاست","لاتانوپروست","زیلوتن","آلپروستادیل"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[2]}],"answer":2,"explain":"<p><strong>زیلوتون (زیلوتن، <bdi>Zyflo</bdi>)</strong> مهارکننده‌ی آنزیم <strong>5-<bdi>lipoxygenase</bdi></strong> است و ساخت لکوترین‌ها را کم می‌کند؛ لکوترین‌ها در انقباض نایژک‌ها در آسم نقش دارند.</p>\n<ul><li><strong>الف) زافیرلوکاست:</strong> آنتاگونیست <strong>گیرنده‌ی لکوترین</strong> است (مانند مونته‌لوکاست)، یعنی آنزیم را مهار نمی‌کند.</li><li><strong>ب) لاتانوپروست:</strong> آنالوگ <bdi>PGF2</bdi>α برای گلوکوم است.</li><li><strong>د) آلپروستادیل:</strong> آنالوگ <bdi>PGE1</bdi> است و ربطی به مسیر لیپواکسیژناز و آسم ندارد.</li></ul>","flag":"","lesson":"<div class=\"tw\"><table><thead><tr><th>دارو</th><th>مکانیسم</th></tr></thead><tbody><tr><td>زیلوتون (<bdi>Zyflo</bdi>)</td><td>مهار آنزیم 5-<bdi>lipoxygenase</bdi></td></tr><tr><td>مونته‌لوکاست (<bdi>Singulair</bdi>)</td><td>آنتاگونیست گیرنده‌ی لکوترین</td></tr><tr><td>زافیرلوکاست (<bdi>Accolate</bdi>)</td><td>آنتاگونیست گیرنده‌ی لکوترین</td></tr></tbody></table></div>\n<ul><li>5-<bdi>lipoxygenase</bdi> اسید آراشیدونیک را به 5-<bdi>HPETE</bdi> و سپس لکوترین <bdi>A4</bdi> و سایر لکوترین‌ها (<bdi>B4</bdi>، <bdi>C4</bdi>، <bdi>D4</bdi>، <bdi>E4</bdi>) تبدیل می‌کند.</li><li>مصرف <bdi>NSAID</bdi> در بیمار آسمی ممکن است با انحراف آراشیدونات به مسیر لیپواکسیژناز برونکواسپاسم بدهد (حدود ۱۰ درصد مصرف‌کنندگان).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: «لوکاست» را مهارکننده‌ی آنزیم دانستن؛ داروهای «-لوکاست» گیرنده‌ی لکوترین را مسدود می‌کنند و فقط زیلوتون آنزیم را مهار می‌کند.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش لکوترین‌ها و داروهای آسم</p>","steps":"<p>کلیدواژه‌ها: «مهارکننده‌ی آنزیم 5-لیپواکسیژناز» و «آسم».</p>\n<p>لاتانوپروست و آلپروستادیل آنالوگ پروستاگلاندین‌اند و ربطی ندارند.</p>\n<p>زافیرلوکاست گیرنده‌ی لکوترین را می‌بندد، نه آنزیم را.</p>\n<p>مهارکننده‌ی آنزیم 5-<bdi>lipoxygenase</bdi> زیلوتون است.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: «لوکاست» را مهارکننده‌ی آنزیم دانستن؛ داروهای «-لوکاست» گیرنده‌ی لکوترین را مسدود می‌کنند و فقط زیلوتون آنزیم را مهار می‌کند."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q13","session":"p1","full":false,"num":13,"text":"مهار کننده های اختصاصی آنزیم <bdi>COX-2</bdi> چه مزیتی نسبت به دیکلوفناک دارند؟","opts":["کاهش عوارض قلبی- عروقی","کاهش بروز زخم معده","کاهش عوارض کلیوی","افزایش اثر ضد انعقادی"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[4]}],"answer":1,"explain":"<p>مهارکننده‌های اختصاصی <strong><bdi>COX-2</bdi></strong> (مثل سلکوکسیب) <bdi>COX-1</bdi> معده را کمتر مهار می‌کنند، پس مزیت آن‌ها نسبت به دیکلوفناک <strong>کاهش بروز زخم و عوارض گوارشی</strong> است؛ اثر تب‌بر، ضددرد و ضدالتهاب را حفظ می‌کنند.</p>\n<ul><li><strong>الف) کاهش عوارض قلبی‌عروقی:</strong> اثر محافظتی بر عوارض قلبی‌عروقی ندارند و درباره‌ی بعضی از آن‌ها عوارض قلبی‌عروقی گزارش شده است (روفکوکسیب جمع شد).</li><li><strong>ج) کاهش عوارض کلیوی:</strong> عوارض کلیوی این گروه دست‌کم به اندازه‌ی <bdi>NSAID</bdi>های متداول است.</li><li><strong>د) افزایش اثر ضدانعقادی:</strong> این گروه اثر ضدترومبوتیک ندارند، چون <bdi>COX-1</bdi> پلاکت را مهار نمی‌کنند.</li></ul>","flag":"","lesson":"<ul><li>مزیت مهارکننده‌های اختصاصی <bdi>COX-2</bdi>: عوارض گوارشی کمتر (در مطالعات ۱ تا ۲ ساله)؛ بقیه‌ی گزینه‌ها مزیت نیستند.</li><li><bdi>COX-1</bdi> سازنده: حفاظت معده و کلیه؛ <bdi>COX-2</bdi> القاشونده: التهاب، درد، تب.</li><li>در جدول جزوه، دیکلوفناک ضریب <bdi>IC50</bdi> حدود ۰٫۷ دارد (نزدیک به ۱، یعنی تقریباً غیراختصاصی)، سلکوکسیب کمتر از ۰٫۰۰۱.</li><li>هیچ‌گاه نگویید دارو «فقط <bdi>COX-2</bdi>» را مهار می‌کند؛ <bdi>COX-1</bdi> هم کم مهار می‌شود.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: انتظار مزیت قلبی یا کلیوی از مهارکننده‌ی <bdi>COX-2</bdi>؛ مزیت فقط گوارشی است.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش مهارکننده‌های اختصاصی <bdi>COX-2</bdi> و جدول ضریب <bdi>IC50</bdi></p>","steps":"<p>کلیدواژه‌ها: «مهارکننده‌ی اختصاصی <bdi>COX-2</bdi>» و «مزیت» نسبت به دیکلوفناک.</p>\n<p><bdi>COX-1</bdi> محافظ معده است و <bdi>COX-2</bdi> اختصاصی‌ها آن را کمتر مهار می‌کنند؛ پس مزیت، زخم کمتر است.</p>\n<p>قلب و کلیه بهتر نمی‌شوند و اثر ضدانعقادی هم ندارند (حذف الف، ج، د).</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: انتظار مزیت قلبی یا کلیوی از مهارکننده‌ی <bdi>COX-2</bdi>؛ مزیت فقط گوارشی است."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q14","session":"p1","full":false,"num":14,"text":"آسپرین در کدامیک از موارد زیر ممنوع می باشد؟","opts":["کم کاری غده تیروئید","همزمان با مصرف داروی ضد صرع کاربامازپین","همزمان با بی هوشی با داروی کتامین","افزایش بیلی روبین خون به هر علت"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[6]}],"answer":3,"explain":"<p>به بیمار <strong>زردی‌دار</strong> آسپرین نمی‌دهیم، چون آسپرین بیلی‌روبین را از آلبومین جابه‌جا و <strong>بیلی‌روبین آزاد</strong> را بالا می‌برد؛ بیلی‌روبین آزاد وارد مغز می‌شود و مشکل ایجاد می‌کند. این نکته‌ی تأکیدی استاد است.</p>\n<ul><li><strong>الف) کم‌کاری تیروئید:</strong> منع مصرف در جزوه برای <strong>پرکاری</strong> تیروئید است (<bdi>T3</bdi> و <bdi>T4</bdi> آزاد بالا می‌رود)، نه کم‌کاری.</li><li><strong>ب) هم‌زمان با کاربامازپین:</strong> در جزوه نیامده؛ داروی ضدصرعی که با آسپرین مشکل دارد فنی‌توئین است.</li><li><strong>ج) هم‌زمان با کتامین:</strong> در جزوه نیامده؛ داروی بیهوشی تزریقی که با آسپرین مشکل دارد تیوپنتال است.</li></ul>","flag":"","lesson":"<ul><li>آسپرین → بالا رفتن بیلی‌روبین آزاد → خطر ورود به مغز؛ بیمار زردی‌دار آسپرین نمی‌گیرد.</li><li>پرکاری (نه کم‌کاری) تیروئید و بیمار تحت درمان ضدتیروئید: آسپرین ممنوع.</li><li>فنی‌توئین: کاهش دوز یا عدم مصرف آسپرین؛ تیوپنتال: کنترل بیهوشی دشوار می‌شود.</li><li>آسپرین را به کودکان با عفونت ویروسی ندهید (سندرم ری)؛ نیمه‌عمر ۲ تا ۳ ساعت، ۱۲ ساعت و ۱۵ تا ۳۰ ساعت بسته به دوز.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: جابه‌جا کردن «پرکاری» با «کم‌کاری» تیروئید و کاربامازپین/کتامین به‌جای فنی‌توئین/تیوپنتال.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش تداخلات دارویی آسپرین (بیلی‌روبین، تیروئید، تیوپنتال، فنی‌توئین)، تأکید استاد</p>","steps":"<p>کلیدواژه: «آسپرین ممنوع است».</p>\n<p>آسپرین داروها و مواد پروتئین‌باند را آزاد می‌کند: بیلی‌روبین، فنی‌توئین، تیوپنتال، <bdi>T3</bdi> و <bdi>T4</bdi>.</p>\n<p>کم‌کاری تیروئید، کاربامازپین و کتامین در این فهرست نیستند (حذف الف، ب، ج).</p>\n<p>افزایش بیلی‌روبین (زردی) مصرف آسپرین را ممنوع می‌کند.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: جابه‌جا کردن «پرکاری» با «کم‌کاری» تیروئید و کاربامازپین/کتامین به‌جای فنی‌توئین/تیوپنتال."],"dupOf":null,"dupNote":"","xrefs":["p1q08"]},{"id":"p1q15","session":"p1","full":false,"num":15,"text":"براساس <bdi>IC50 COX-2 / IC50 COX-1</bdi> کدام داروی زیر عوارض گوارشی کمتری دارد؟","opts":["<bdi>Indomethacin</bdi>","<bdi>Ibuprofen</bdi>","<bdi>Naproxen</bdi>","<bdi>Celecoxib</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۱","nums":[]}],"answer":3,"explain":"<p>در منبع آزمون فقط صورت این سوال چاپ شده بود و گزینه‌ها نیامده بود؛ گزینه‌ها را برای تمرین خودمان ساخته‌ایم.</p>\n<p>هرچه نسبت <strong><bdi>IC50 COX-2 / IC50 COX-1</bdi></strong> کمتر باشد، دارو <bdi>COX-2</bdi> را در غلظت پایین‌تری مهار می‌کند و <bdi>COX-1</bdi> (آنزیم محافظ مخاط معده و عامل پلاکت‌ها) را کمتر مهار می‌کند؛ پس <strong>عوارض گوارشی کمتر</strong> دارد. در جدول جزوه، کمترین نسبت مربوط به <strong>سلکوکسیب</strong> (کمتر از ۰٫۰۰۱) است.</p>\n<ul><li><strong>الف) <bdi>Indomethacin</bdi>:</strong> نسبت حدود ۶۰ دارد، یعنی نسبت به <bdi>COX-1</bdi> تمایل بیشتری دارد؛ از داروهای پرعارضه‌ی گوارشی است و هر دو <bdi>COX</bdi> را (و فسفولیپاز <bdi>A</bdi> و <bdi>C</bdi>) مهار می‌کند.</li><li><strong>ب) <bdi>Ibuprofen</bdi>:</strong> نسبت حدود ۱۵ دارد؛ غیرانتخابی و با اثر قابل‌توجه روی <bdi>COX-1</bdi> است.</li><li><strong>ج) <bdi>Naproxen</bdi>:</strong> نسبت ۰٫۶ است؛ این عدد فقط کمترین مقدار در میان <bdi>NSAID</bdi>های غیراختصاصی جدول است، ولی هنوز صدها برابر بیشتر از سلکوکسیب است و عارضه‌ی گوارشی قابل‌توجه دارد.</li></ul>","flag":"","lesson":"<ul><li><strong>قاعده:</strong> نسبت <bdi>IC50 COX-2 / IC50 COX-1</bdi> کوچک‌تر = اختصاصی‌تر برای <bdi>COX-2</bdi> = عارضه‌ی گوارشی و اثر ضدپلاکتی کمتر. <bdi>IC50</bdi> کمتر یعنی دارو قوی‌تر (در غلظت کمتر اثر می‌کند).</li></ul>\n<div class=\"tw\"><table><thead><tr><th>دارو</th><th><bdi>IC50 COX-2 / IC50 COX-1</bdi></th><th>نکته</th></tr></thead><tbody><tr><td><bdi>Sulindac</bdi></td><td>۱۰۰</td><td>بیشترین تمایل به <bdi>COX-1</bdi> در جدول</td></tr><tr><td><bdi>Indomethacin</bdi></td><td>۶۰</td><td><bdi>PDA</bdi> (انتخاب اول)، نقرس حاد</td></tr><tr><td><bdi>Ibuprofen</bdi></td><td>۱۵</td><td><bdi>PDA</bdi> (انتخاب دوم)، حساسیت‌زا</td></tr><tr><td><bdi>Diclofenac</bdi></td><td>۰٫۷</td><td>بیشترین عارضه‌ی کبدی</td></tr><tr><td><bdi>Naproxen</bdi></td><td>۰٫۶</td><td>کمترین نسبت میان غیراختصاصی‌های جدول</td></tr><tr><td><bdi>Celecoxib</bdi></td><td>کمتر از ۰٫۰۰۱</td><td>تنها مهارکننده‌ی اختصاصی <bdi>COX-2</bdi> در بازار ایران</td></tr></tbody></table></div>\n<ul><li>مهارکننده‌های اختصاصی <bdi>COX-2</bdi> (سلکوکسیب، روفکوکسیب، والدکوکسیب): ضدتب، ضددرد و ضدالتهاب هستند ولی <strong>اثر ضدانعقادی ندارند</strong> (<bdi>COX-1</bdi> پلاکت دست‌نخورده است) و <strong>محافظت قلبی-عروقی ندارند</strong>؛ روفکوکسیب به دلیل افزایش عوارض از بازار جمع شد.</li><li>ملوکسیکام اثر نسبی بیشتر روی <bdi>COX-2</bdi> دارد: عارضه‌ی گوارشی کمتر از پیروکسیکام، دیکلوفناک و ناپروکسن، ولی نه به اندازه‌ی سلکوکسیب.</li><li>«اختصاصی» به معنای بی‌خطر نیست: سلکوکسیب هم عوارض کلیوی (دست‌کم هم‌اندازه‌ی سایر <bdi>NSAID</bdi>ها) و حساسیت (کمتر، ولی ممکن) دارد؛ در مطالعات کوتاه‌مدت (حدود ۱ تا ۲ سال) عوارض گوارشی کمتر شده است. سلکوکسیب در حساسیت به سولفونامید با احتیاط/ممنوع است (<bdi>Katzung</bdi>).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: «ناپروکسن کمترین عدد را دارد، پس کمترین عارضه‌ی گوارشی را دارد». کمترین عدد فقط در گروه غیراختصاصی‌هاست؛ سلکوکسیب چند صد برابر کمتر است.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) کدام داروی جدول کمترین نسبت <bdi>IC50</bdi> را در میان <bdi>NSAID</bdi>های غیراختصاصی دارد؟ (۲) کدام دارو اختصاصی‌تر <bdi>COX-2</bdi> را مهار می‌کند؟ (۳) کدام <bdi>NSAID</bdi> اثر ضدانعقادی ندارد؟ (۴) کدام داروی بازار ایران مهارکننده‌ی انتخابی <bdi>COX-2</bdi> است؟</li></ul><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش «ضریب <bdi>IC50</bdi> و گزینش‌پذیری» و جدول <bdi>IC50 COX-2 / IC50 COX-1</bdi> (ایبوپروفن ۱۵، ناپروکسن ۰٫۶، دیکلوفناک ۰٫۷، ایندومتاسین ۶۰، سلکوکسیب کمتر از ۰٫۰۰۱) و بخش مهارکننده‌های اختصاصی <bdi>COX-2</bdi>. مرجع: <bdi>Katzung</bdi> (در جزوه نبود) برای حساسیت به سولفونامید و هشدارهای قلبی-عروقی.</p>","steps":"<p>کلیدواژه‌ی سوال «<bdi>IC50 COX-2 / IC50 COX-1</bdi>» و «عوارض گوارشی کمتر» است؛ یعنی دنبال دارویی می‌گردیم که <bdi>COX-2</bdi> را اختصاصی‌تر مهار کند.</p>\n<p>قاعده: نسبت کوچک‌تر = اختصاصی‌تر برای <bdi>COX-2 = COX-1</bdi> (محافظ معده) کمتر مهار می‌شود = عارضه‌ی گوارشی کمتر.</p>\n<p>عددهای جدول جزوه: ایندومتاسین ۶۰، ایبوپروفن ۱۵، ناپروکسن ۰٫۶ و سلکوکسیب کمتر از ۰٫۰۰۱.</p>\n<p>ایندومتاسین، ایبوپروفن و ناپروکسن غیراختصاصی‌اند؛ ناپروکسن فقط در میان همین‌ها کمترین عدد را دارد، ولی سلکوکسیب بسیار کوچک‌تر است.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: «ناپروکسن کمترین عدد را دارد، پس کمترین عارضه‌ی گوارشی را دارد». کمترین عدد فقط در گروه غیراختصاصی‌هاست؛ سلکوکسیب چند صد برابر کمتر است."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q16","session":"p1","full":false,"num":16,"text":"کدام یک از داروهای زیر جهت بستن مجرای شریانی باز کاربرد دارد؟","opts":["<bdi>Celecoxib</bdi>","<bdi>Naproxen</bdi>","<bdi>Diclofenac</bdi>","<bdi>Ibuprofen</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۱","nums":[]}],"answer":3,"explain":"<p>در منبع آزمون فقط صورت این سوال چاپ شده بود و گزینه‌ها نیامده بود؛ گزینه‌ها را برای تمرین خودمان ساخته‌ایم.</p>\n<p>در <strong><bdi>PDA</bdi></strong> (<bdi>Patent Ductus Arteriosus</bdi>) مجرا باید بعد از تولد بسته شود وگرنه شانت و هیپوکسی ایجاد می‌کند. بستن دارویی مجرا با مهار سیکلواکسیژناز و کاهش پروستاگلاندین‌ها (<bdi>PGE2</bdi>) انجام می‌شود. طبق جزوه، <strong>ایندومتاسین</strong> انتخاب اول و <strong>ایبوپروفن</strong> انتخاب دوم است؛ چون ایندومتاسین در گزینه‌ها نیست، پاسخ <strong>ایبوپروفن</strong> است.</p>\n<ul><li><strong>الف) <bdi>Celecoxib</bdi>:</strong> مهارکننده‌ی اختصاصی <bdi>COX-2</bdi> است که برای دردهای التهابی/آرتروز به کار می‌رود؛ در جزوه کاربردی برای بستن مجرا ندارد.</li><li><strong>ب) <bdi>Naproxen</bdi>:</strong> برای بیماری‌های التهابی و روماتولوژی به کار می‌رود، نه برای <bdi>PDA</bdi>.</li><li><strong>ج) <bdi>Diclofenac</bdi>:</strong> داروی نسبتاً قوی برای بیماری‌های روماتولوژیک است و بیشترین عارضه‌ی کبدی را در میان <bdi>NSAID</bdi>ها دارد؛ کاربرد استاندارد در <bdi>PDA</bdi> ندارد.</li></ul>","flag":"","lesson":"<ul><li><strong><bdi>PDA</bdi>:</strong> مجرای شریانی در جنین باز است (خون ریه را دور می‌زند) و پس از تولد باید ببندد؛ باز ماندن آن = شانت چپ به راست و هیپوکسی/اختلال همودینامیک، به‌ویژه در نوزاد نارس.</li><li><strong>مکانیسم دارویی:</strong> پروستاگلاندین‌ها (<bdi>PGE2</bdi>) مجرا را باز نگه می‌دارند ← مهار <bdi>COX</bdi> توسط <bdi>NSAID</bdi> باعث بسته شدن مجرا می‌شود.</li><li><strong>ترتیب (جزوه):</strong> ایندومتاسین = انتخاب اول؛ ایبوپروفن = انتخاب دوم. در بالین، ایبوپروفن وریدی به‌خاطر اثر کمتر روی جریان کلیه و مزانتر هم جایگزین مناسبی است و گاهی استامینوفن هم استفاده می‌شود (خارج از جزوه).</li></ul>\n<div class=\"tw\"><table><thead><tr><th>وضعیت</th><th>دارو</th><th>هدف</th></tr></thead><tbody><tr><td><bdi>PDA</bdi></td><td>ایندومتاسین (اول)، ایبوپروفن (دوم)</td><td>مهار <bdi>PG</bdi> ← بستن مجرا</td></tr><tr><td>بیماری قلبی مادرزادی وابسته به مجرا</td><td>آلپروستادیل (<bdi>PGE1</bdi>)</td><td>باز نگه داشتن مجرا</td></tr><tr><td>بارداری (به‌ویژه سه‌ماهه‌ی آخر)</td><td><bdi>NSAID</bdi> توصیه نمی‌شود</td><td>خطر بسته شدن زودرس مجرا و اثر روی جنین</td></tr></tbody></table></div>\n<ul><li>ایبوپروفن: عارضه‌ی کلیوی/احتباس آب؛ نسبتاً حساسیت‌زا (در آسم و برونکواسپاسم و آنژیوادم ممنوع)؛ مصرف چندروزه‌ی هم‌زمان اثر محافظتی آسپرین در <bdi>MI</bdi> را برمی‌گرداند. ایندومتاسین: علاوه بر <bdi>COX</bdi>، فسفولیپاز <bdi>A</bdi> و <bdi>C</bdi> را هم مهار می‌کند؛ در نقرس حاد و تزریق اپیدورال بعد از لامینکتومی هم کاربرد دارد.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: انتخاب دارویی که فقط «قوی‌ترین ضدالتهاب» است (دیکلوفناک/ناپروکسن) برای <bdi>PDA</bdi>؛ در <bdi>PDA</bdi> فقط ایندومتاسین و ایبوپروفن (و تجربی استامینوفن) مطرح‌اند. و برعکس: <bdi>PGE1</bdi> برای باز نگه داشتن مجرا است نه بستن آن.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) انتخاب اول برای بستن <bdi>PDA</bdi> چیست؟ (۲) انتخاب دوم برای بستن <bdi>PDA</bdi> کدام است؟ (۳) کدام دارو برای باز نگه داشتن مجرا در بیماری قلبی مادرزادی وابسته به مجرا مصرف می‌شود؟ (۴) کدام <bdi>NSAID</bdi> در سه‌ماهه‌ی آخر بارداری ممنوع است و چرا؟</li></ul><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش ایبوپروفن و ایندومتاسین (بستن مجرای شریانی باز، <bdi>PDA</bdi>: ایندومتاسین انتخاب اول، ایبوپروفن انتخاب دوم) و بخش دیکلوفناک. مرجع: <bdi>Katzung/Robbins</bdi> (در جزوه نبود) برای نقش <bdi>PGE2</bdi> در باز نگه‌داشتن مجرا و <bdi>PGE1</bdi> در بیماری‌های قلبی وابسته به مجرا.</p>","steps":"<p>کلیدواژه‌ی سوال «بستن مجرای شریانی باز» یعنی <bdi>PDA</bdi>.</p>\n<p>در <bdi>PDA</bdi> دارو با مهار <bdi>COX</bdi> و کاهش پروستاگلاندین‌ها مجرا را می‌بندد؛ طبق جزوه ایندومتاسین انتخاب اول و ایبوپروفن انتخاب دوم است.</p>\n<p>ایندومتاسین در گزینه‌ها نیست؛ از میان گزینه‌ها فقط ایبوپروفن در این فهرست آمده است.</p>\n<p>سلکوکسیب، ناپروکسن و دیکلوفناک برای التهاب و روماتولوژی به کار می‌روند و کاربردشان در <bdi>PDA</bdi> مطرح نیست.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: انتخاب دارویی که فقط «قوی‌ترین ضدالتهاب» است (دیکلوفناک/ناپروکسن) برای <bdi>PDA</bdi>؛ در <bdi>PDA</bdi> فقط ایندومتاسین و ایبوپروفن (و تجربی استامینوفن) مطرح‌اند. و برعکس: <bdi>PGE1</bdi> برای باز نگه داشتن مجرا است نه بستن آن."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p1q17","session":"p1","full":false,"num":17,"text":"این داروی موکولیتیک در درمان مسمومیت ناشی از … (ادامه‌ی صورت سوال در منبع بریده شده) کاربرد دارد.","opts":["دفروکسامین","سولفات پروتامین","پنی‌سیلامین","ان‌استیل سیستئین"],"labels":["الف","ب","ج","د"],"exams":[{"name":"فارما 96A","nums":[5]}],"answer":3,"explain":"<p>صورت سوال می‌گوید «داروی <strong>موکولیتیک</strong>» که در درمان یک مسمومیت به‌کار می‌رود؛ طبق جزوه <strong>ان‌استیل سیستئین (<bdi>N-acetylcysteine</bdi>)</strong> هم موکولیتیک است و هم <strong>پادزهر مسمومیت با استامینوفن</strong>؛ مانند گلوتاتیون عمل می‌کند و متابولیت سمی را خنثی می‌کند.</p>\n<ul><li><strong>الف) دفروکسامین:</strong> پادزهر مسمومیت با آهن است و موکولیتیک نیست.</li><li><strong>ب) سولفات پروتامین:</strong> پادزهر هپارین است و موکولیتیک نیست.</li><li><strong>ج) پنی‌سیلامین:</strong> شلاتور (مثلاً برای مس) است و موکولیتیک نیست.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی بخشی از صورت سوال در منبع بریده شده است («مسمومیت ناشی از …»)؛ با توجه به اینکه گزینه‌ی «ان‌استیل سیستئین» تنها داروی موکولیتیک فهرست است و جزوه آن را پادزهر استامینوفن و موکولیتیک می‌داند، پاسخ د است.","lesson":"<ul><li><strong>استامینوفن:</strong> در دوز درمانی داروی بسیار ایمنی است؛ ضدالتهاب نیست و فقط تب‌بر و ضددرد است و ضدانعقاد هم نیست.</li><li><strong>مسمومیت:</strong> در دوز سمی مسیر متابولیسم تغییر می‌کند و متابولیت سمی تولید می‌شود که کبد را درگیر می‌کند.</li><li><strong>پادزهر:</strong> ان‌استیل سیستئین مانند گلوتاتیون عمل می‌کند و متابولیت سمی را خنثی می‌کند؛ اگر مسمومیت شدید باشد و زمان بگذرد اثرش کم می‌شود. این دارو موکولیتیک هم هست.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>نکته‌ی تأکیدی استاد: «ان‌استیل سیستئین پادزهر استامینوفن است.»</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) پادزهر استامینوفن چیست؟ (۲) کدام داروی موکولیتیک در مسمومیت به‌کار می‌رود؟ (۳) کدام دارو مانند گلوتاتیون عمل می‌کند؟</li></ul><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش استامینوفن (متابولیسم، مسمومیت و پادزهر ان‌استیل سیستئین)</p>","steps":"<p>کلیدواژه‌ها «موکولیتیک» و «مسمومیت» هستند.</p>\n<p>ان‌استیل سیستئین هم موکولیتیک است و هم پادزهر استامینوفن (مانند گلوتاتیون).</p>\n<p>دفروکسامین، پروتامین و پنی‌سیلامین موکولیتیک نیستند.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>نکته‌ی تأکیدی استاد: «ان‌استیل سیستئین پادزهر استامینوفن است.»"],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p2q01","session":"p2","full":false,"num":18,"text":"مکانیسم کدام داروی ضد نقرس صحیح می باشد؟","opts":["<bdi>Febuxostat</bdi> : پایین آوردن اسید اوریک خون با افزایش دفع اسید اوریک","<bdi>Benzbromarone</bdi> : پایین آوردن اسید اوریک خون با کاهش تولید اسید اوریک","<bdi>Colchicine</bdi> : پایین آوردن اسید اوریک خون با افزایش تجزیه اسید اوریک","<bdi>Indomethacin</bdi> : کاهش التهاب ناشی از تجمع اسید اوریک در مفصل"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[3]}],"answer":3,"explain":"<p>تنها گزینه‌ای که مکانیسم و دارو در آن درست جفت شده، <strong>ایندومتاسین</strong> است: یک <strong><bdi>NSAID</bdi></strong> ضدالتهاب قوی که اثر اوریکوزوریک ندارد و در مرحله‌ی حاد و پروفیلاکسی به کار می‌رود؛ یعنی فقط التهاب ناشی از کریستال‌های اورات را کم می‌کند.</p>\n<ul><li><strong>الف) <bdi>Febuxostat</bdi>:</strong> مهارکننده‌ی <strong>زانتین اکسیداز</strong> است و اسید اوریک را با <strong>کاهش تولید</strong> پایین می‌آورد، نه با افزایش دفع.</li><li><strong>ب) <bdi>Benzbromarone</bdi>:</strong> داروی <strong>اوریکوزوریک</strong> است و با مهار بازجذب لوله‌ای، <strong>دفع</strong> اسید اوریک را زیاد می‌کند؛ کاهش تولید مکانیسم آلوپورینول و فبوکسوستات است.</li><li><strong>ج) <bdi>Colchicine</bdi>:</strong> داروی ضدالتهاب اختصاصی نقرس است (مهار مهاجرت گرانولوسیت‌ها) و اسید اوریک خون را پایین نمی‌آورد؛ «تجزیه‌ی اسید اوریک» مکانیسم اوریکازهای نوترکیب (راسبوریکاز و پگلوتیکاز) است.</li></ul>","flag":"","lesson":"<div class=\"tw\"><table><thead><tr><th>گروه</th><th>داروها</th><th>مکانیسم</th></tr></thead><tbody><tr><td>کاهش تولید</td><td>آلوپورینول، فبوکسوستات</td><td>مهار <bdi>xanthine oxidase</bdi></td></tr><tr><td>افزایش دفع</td><td>پروبنسید، سولفین‌پیرازون، بنزبرومارون</td><td>مهار بازجذب لوله‌ای (اوریکوزوریک)</td></tr><tr><td>تجزیه</td><td>راسبوریکاز، پگلوتیکاز</td><td>اسید اوریک ← آلانتوئین</td></tr><tr><td>ضدالتهاب</td><td>کلشی‌سین، <bdi>NSAID</bdi>ها (مثل ایندومتاسین)، کورتیکواستروئیدها</td><td>بدون اثر بر سطح اسید اوریک</td></tr></tbody></table></div>\n<ul><li>ایندومتاسین: ضدالتهاب قوی، بدون اثر اوریکوزوریک؛ مصرف در حمله‌ی حاد و پروفیلاکسی.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>کلشی‌سین را «داروی کاهنده‌ی اسید اوریک» نکنید؛ فقط التهاب را مهار می‌کند.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش داروهای نقرس (گروه‌بندی درمان، کلشی‌سین، ایندومتاسین)</p>","steps":"<p>کلیدواژه‌ی سؤال «کدام مکانیسم صحیح است» است؛ پس هر گزینه را با مکانیسم واقعی دارو مقایسه کن.</p>\n<p>فبوکسوستات مهارکننده‌ی زانتین اکسیداز است، نه افزایش‌دهنده‌ی دفع؛ الف غلط.</p>\n<p>بنزبرومارون اوریکوزوریک است و دفع را زیاد می‌کند، نه تولید را؛ ب غلط.</p>\n<p>کلشی‌سین فقط ضدالتهاب است و اسید اوریک را تجزیه نمی‌کند؛ ج غلط.</p>\n<p>ایندومتاسین یک <bdi>NSAID</bdi> ضدالتهاب است؛ د درست.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>کلشی‌سین را «داروی کاهنده‌ی اسید اوریک» نکنید؛ فقط التهاب را مهار می‌کند."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p2q02","session":"p2","full":false,"num":19,"text":"مکانیسم اثر کدام دو دارو در کاهش اسید اوریک خون در بیماری نقرس یکسان می باشد؟","opts":["<bdi>Probenecid / Benzbromarone</bdi>","<bdi>Benzbromarone / Pegloticase</bdi>","<bdi>Probenecid / Febuxostat</bdi>","<bdi>Sufinpyrazon / Rasburicase</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[4]}],"answer":0,"explain":"<p><strong><bdi>Probenecid</bdi></strong> و <strong><bdi>Benzbromarone</bdi></strong> هر دو <strong>اوریکوزوریک</strong> هستند: بازجذب لوله‌ای (لوله‌ی پروگزیمال) اسید اوریک را مهار می‌کنند و دفع کلیوی آن را زیاد می‌کنند.</p>\n<ul><li><strong>ب) <bdi>Benzbromarone / Pegloticase</bdi>:</strong> بنزبرومارون دفع را زیاد می‌کند ولی پگلوتیکاز یک اوریکاز نوترکیب است که اسید اوریک را به آلانتوئین تجزیه می‌کند؛ مکانیسم‌ها متفاوت‌اند.</li><li><strong>ج) <bdi>Probenecid / Febuxostat</bdi>:</strong> پروبنسید دفع را زیاد می‌کند، اما فبوکسوستات با مهار زانتین اکسیداز تولید را کم می‌کند.</li><li><strong>د) <bdi>Sulfinpyrazone / Rasburicase</bdi>:</strong> سولفین‌پیرازون (در گزینه به شکل «<bdi>Sufinpyrazon</bdi>» نوشته شده) اوریکوزوریک است ولی راسبوریکاز اوریکاز نوترکیب و تجزیه‌کننده است.</li></ul>","flag":"","lesson":"<ul><li>سه مسیر کاهش اسید اوریک: <strong>تولید</strong> (مهار <bdi>xanthine oxidase</bdi>)، <strong>دفع</strong> (مهار بازجذب)، <strong>تجزیه</strong> (اوریکاز نوترکیب).</li><li>هم‌مکانیسم‌ها: آلوپورینول با فبوکسوستات؛ پروبنسید با سولفین‌پیرازون و بنزبرومارون؛ پگلوتیکاز با راسبوریکاز.</li><li>سولفین‌پیرازون از پروبنسید قوی‌تر است و ضددرد و ضدالتهاب نیست.</li><li>پگلوتیکاز و راسبوریکاز هیچ‌گاه انتخاب اول نیستند و در جزوه فقط برای نقرس مزمن مقاوم به درمان آمده‌اند (در عمل راسبوریکاز بیشتر برای هیپراوریسمی ناشی از سندرم لیز تومور به کار می‌رود).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دو داروی «اوریکوزوریک» یک جفت هم‌مکانیسم‌اند؛ اوریکوزوریک را با اوریکاز (تجزیه) اشتباه نگیرید.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش داروهای نقرس (داروهای اوریکوزوریک)</p>","steps":"<p>«مکانیسم یکسان» یعنی دو دارو از یک گروه باشند: کاهش تولید، افزایش دفع یا تجزیه.</p>\n<p>پروبنسید و بنزبرومارون هر دو اوریکوزوریک (مهار بازجذب) هستند.</p>\n<p>در ب، پگلوتیکاز اوریکاز است؛ در ج، فبوکسوستات مهارکننده‌ی زانتین اکسیداز است؛ در د، راسبوریکاز اوریکاز است.</p>\n<p>فقط یک جفت هم‌مکانیسم است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دو داروی «اوریکوزوریک» یک جفت هم‌مکانیسم‌اند؛ اوریکوزوریک را با اوریکاز (تجزیه) اشتباه نگیرید."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p2q03","session":"p2","full":false,"num":20,"text":"مکانیسم کدامیک از داروهای ضد نقرس زیر درست می‌باشد؟","opts":["پروبنسید: کاهش تولید اسید اوریک","رازبوریکاز: افزایش تجزیه اسید اوریک","آلوپورینول: افزایش تجزیه اسید اوریک","بنزبرومارون: کاهش تولید اسید اوریک"],"labels":["الف","ب","ج","د"],"exams":[{"name":"فارما 96A","nums":[1]}],"answer":1,"explain":"<p><strong>رازبوریکاز</strong> (<bdi>Rasburicase</bdi>) یک <strong>اوریکاز نوترکیب</strong> است و اسید اوریک را به <strong>آلانتوئین</strong> تجزیه می‌کند؛ بنابراین عبارت «افزایش تجزیه‌ی اسید اوریک» برای آن درست است.</p>\n<ul><li><strong>الف) پروبنسید:</strong> اوریکوزوریک است و با مهار بازجذب لوله‌ای <strong>دفع</strong> را زیاد می‌کند؛ تولید را کم نمی‌کند.</li><li><strong>ج) آلوپورینول:</strong> مهارکننده‌ی <strong>زانتین اکسیداز</strong> است و <strong>تولید</strong> اسید اوریک را کم می‌کند (پیش‌دارو است و به اکسی‌پورینول تبدیل می‌شود)؛ تجزیه نمی‌کند.</li><li><strong>د) بنزبرومارون:</strong> مثل پروبنسید اوریکوزوریک است و <strong>دفع</strong> را زیاد می‌کند، نه کاهش تولید.</li></ul>","flag":"","lesson":"<div class=\"tw\"><table><thead><tr><th>دارو</th><th>مکانیسم</th></tr></thead><tbody><tr><td>آلوپورینول، فبوکسوستات</td><td>کاهش تولید (مهار <bdi>xanthine oxidase</bdi>)</td></tr><tr><td>پروبنسید، سولفین‌پیرازون، بنزبرومارون</td><td>افزایش دفع (مهار بازجذب)</td></tr><tr><td>راسبوریکاز، پگلوتیکاز</td><td>تجزیه‌ی اسید اوریک به آلانتوئین</td></tr></tbody></table></div>\n<ul><li>در انسان اوریکاز وجود ندارد؛ این دو دارو فرآورده‌ی نوترکیب‌اند و بدن علیه آن‌ها آنتی‌بادی می‌سازد.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>«افزایش تجزیه» فقط مخصوص اوریکازهای نوترکیب است؛ آلوپورینول اسید اوریک را تجزیه نمی‌کند، تولیدش را کم می‌کند.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش داروهای نقرس (اوریکازهای نوترکیب)</p>","steps":"<p>هر گزینه یک دارو با یک مکانیسم است؛ مکانیسم واقعی را به یاد بیاور.</p>\n<p>پروبنسید ← افزایش دفع، نه کاهش تولید؛ الف غلط. آلوپورینول ← کاهش تولید، نه تجزیه؛ ج غلط. بنزبرومارون ← افزایش دفع؛ د غلط.</p>\n<p>راسبوریکاز اوریکاز نوترکیب است و اسید اوریک را به آلانتوئین تجزیه می‌کند؛ ب درست.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>«افزایش تجزیه» فقط مخصوص اوریکازهای نوترکیب است؛ آلوپورینول اسید اوریک را تجزیه نمی‌کند، تولیدش را کم می‌کند."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p2q04","session":"p2","full":false,"num":21,"text":"مکانیسم اثر بنزبرومارون مشابه کدامیک از داروهای ضد نقرس زیر است؟","opts":["پروبنسید","آلوپورینول","رازبوریکاز","کلشی‌سین"],"labels":["الف","ب","ج","د"],"exams":[{"name":"فارما 96A","nums":[4]}],"answer":0,"explain":"","flag":"","lesson":"","steps":"","traps":[],"dupOf":"p2q08","dupNote":"<p>این سوال تکرار <a class=\"xref\" href=\"#/q/p2q08\">سوال ۲۵</a> است. پاسخ تشریحی و درس‌نامه را زیر همان سوال ببین.</p>","xrefs":["p2q08"]},{"id":"p2q05","session":"p2","full":false,"num":22,"text":"مکانیسم اثر فبوکسواستات مشابه کدامیک از داروهای ضد نقرس زیر است؟","opts":["آلوپورینول","کلشی‌سین","بنزبرومارون","پروبنسید"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۱","nums":[]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[1]},{"name":"تلفیقی 96A","nums":[5]}],"answer":0,"explain":"<p><strong>فبوکسوستات</strong> مثل <strong>آلوپورینول</strong> زانتین اکسیداز را مهار می‌کند و با <strong>کاهش تولید</strong> اسید اوریک اثر می‌کند؛ این دو تنها اعضای گروه مهارکننده‌های زانتین اکسیداز در گزینه‌ها هستند.</p>\n<ul><li><strong>ب) کلشی‌سین:</strong> ضدالتهاب اختصاصی نقرس است (مهار مهاجرت گرانولوسیت‌ها) و روی تولید یا دفع اسید اوریک اثری ندارد.</li><li><strong>ج) بنزبرومارون:</strong> اوریکوزوریک است و با مهار بازجذب لوله‌ای، <strong>دفع</strong> را زیاد می‌کند.</li><li><strong>د) پروبنسید:</strong> اوریکوزوریک است و مهارکننده‌ی بازجذب لوله‌ای اسید اوریک است.</li></ul>","flag":"","lesson":"<ul><li>فبوکسوستات و آلوپورینول: مهار <strong><bdi>xanthine oxidase</bdi></strong> ← کاهش تولید اسید اوریک؛ اثر آن‌ها کند است و توفوس‌ها را سریع از بین نمی‌برند.</li><li>آلوپورینول <strong>پیش‌دارو</strong> است (اکسی‌پورینول فرم فعال) و چون اکسی‌پورینول از کلیه دفع می‌شود، در نارسایی کلیه تنظیم دوز می‌خواهد.</li><li>فبوکسوستات تقریباً به‌طور مساوی از ادرار و مدفوع دفع می‌شود و در <bdi>GFR</bdi> بیش از ۳۰ تنظیم دوز نمی‌خواهد؛ در بارداری، شیردهی و کودکان مصرف نمی‌شود.</li><li>عوارض فبوکسوستات: افزایش آنزیم‌های کبدی (حدود ۷ درصد) و افزایش چربی و قند خون.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>«مشابه فبوکسوستات» یعنی هم‌گروه (مهار زانتین اکسیداز)، نه هم‌هدف درمانی (کلشی‌سین هم ضد نقرس است ولی مکانیسمش فرق دارد).</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش داروهای نقرس (مهارکننده‌های زانتین اکسیداز)</p>","steps":"<p>«مشابه فبوکسوستات» یعنی هم‌گروه: مهارکننده‌ی زانتین اکسیداز.</p>\n<p>کلشی‌سین ضدالتهاب است؛ بنزبرومارون و پروبنسید اوریکوزوریک‌اند و دفع را زیاد می‌کنند؛ هر سه کنار می‌روند.</p>\n<p>آلوپورینول هم زانتین اکسیداز را مهار می‌کند.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>«مشابه فبوکسوستات» یعنی هم‌گروه (مهار زانتین اکسیداز)، نه هم‌هدف درمانی (کلشی‌سین هم ضد نقرس است ولی مکانیسمش فرق دارد)."],"dupOf":null,"dupNote":"","xrefs":["p2q08"]},{"id":"p2q06","session":"p2","full":false,"num":23,"text":"کدامیک از داروهای ضد نقرس باعث تجزیه اسیداوریک می‌شود؟","opts":["رازبوریکاز","بنزبرومارون","آلوپورینول","پروبنسید"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی پاییز ۱۴۰۰","nums":[2]},{"name":"تلفیقی 96A","nums":[6]}],"answer":0,"explain":"<p>دارویی که اسید اوریک موجود را <strong>تجزیه</strong> می‌کند، <strong>رازبوریکاز</strong> است: اوریکاز نوترکیبی که اسید اوریک را به <strong>آلانتوئین</strong> (و در واکنش <bdi>CO2</bdi> و <bdi>H2O2</bdi> هم تولید می‌شود) تبدیل می‌کند. پگلوتیکاز هم‌گروه آن است، ولی در گزینه‌ها نیست.</p>\n<ul><li><strong>ب) بنزبرومارون:</strong> با مهار بازجذب لوله‌ای <strong>دفع</strong> اسید اوریک را زیاد می‌کند و آن را تجزیه نمی‌کند.</li><li><strong>ج) آلوپورینول:</strong> با مهار زانتین اکسیداز <strong>تولید</strong> را کم می‌کند.</li><li><strong>د) پروبنسید:</strong> اوریکوزوریک است و بازجذب را مهار می‌کند.</li></ul>","flag":"","lesson":"<ul><li>در انسان آنزیم <strong><bdi>uricase</bdi></strong> وجود ندارد؛ اسید اوریک محصول نهایی متابولیسم پورین‌هاست. در موش و پریمات‌های پایین‌تر اسید اوریک به آلانتوئین تبدیل می‌شود.</li><li>راسبوریکاز و پگلوتیکاز اوریکاز نوترکیب‌اند ← اسید اوریک → آلانتوئین (آلانتوئین از ادرار دفع می‌شود).</li><li>چون این پروتئین در انسان سابقه ندارد، بدن علیه آن‌ها <strong>آنتی‌بادی</strong> می‌سازد.</li><li>هرگز انتخاب اول نیستند؛ در جزوه فقط برای نقرس مزمن مقاوم به درمان‌های دیگر آمده‌اند (راسبوریکاز در عمل بیشتر در سندرم لیز تومور استفاده می‌شود).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>آلوپورینول اسید اوریک را «کم می‌کند» ولی تجزیه نمی‌کند؛ کلمه‌ی «تجزیه» = اوریکاز نوترکیب.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش داروهای نقرس (اوریکازهای نوترکیب)</p>","steps":"<p>کلیدواژه‌ی سؤال «تجزیه‌ی اسید اوریک» است که فقط کار اوریکاز نوترکیب است.</p>\n<p>بنزبرومارون و پروبنسید دفع را زیاد می‌کنند؛ آلوپورینول تولید را کم می‌کند؛ هیچ‌کدام تجزیه نمی‌کنند.</p>\n<p>رازبوریکاز اسید اوریک را به آلانتوئین تبدیل می‌کند.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>آلوپورینول اسید اوریک را «کم می‌کند» ولی تجزیه نمی‌کند؛ کلمه‌ی «تجزیه» = اوریکاز نوترکیب."],"dupOf":null,"dupNote":"","xrefs":["p2q07"]},{"id":"p2q07","session":"p2","full":false,"num":24,"text":"کدامیک از داروهای ضد نقرس باعث کاهش تولید اسید اوریک می‌شود؟","opts":["آلوپورینول","رازبوریکاز","پروبنسید","بنزبرومارون"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[1]}],"answer":0,"explain":"<p><strong>آلوپورینول</strong> آنزیم <strong>زانتین اکسیداز</strong> را مهار می‌کند؛ این آنزیم زانتین را به اسید اوریک تبدیل می‌کند، پس مهارش <strong>تولید</strong> اسید اوریک را کم می‌کند. خودِ آلوپورینول پیش‌دارو است و فرم فعال آن اکسی‌پورینول است.</p>\n<ul><li><strong>ب) رازبوریکاز:</strong> اوریکاز نوترکیب است و اسید اوریک ساخته‌شده را به آلانتوئین <strong>تجزیه</strong> می‌کند؛ در تولید دخالتی ندارد.</li><li><strong>ج) پروبنسید:</strong> با مهار بازجذب لوله‌ای <strong>دفع</strong> را زیاد می‌کند.</li><li><strong>د) بنزبرومارون:</strong> اوریکوزوریک است و <strong>دفع</strong> را زیاد می‌کند.</li></ul>","flag":"","lesson":"<ul><li>مسیر تولید: پورین‌ها ← هیپوزانتین ← زانتین ← (<bdi>xanthine oxidase</bdi>) ← اسید اوریک.</li><li>آلوپورینول و فبوکسوستات این آنزیم را مهار می‌کنند؛ آلوپورینول محبوب‌ترین داروی کاهنده‌ی اسید اوریک است.</li><li>عوارض آلوپورینول: گوارشی، کبدی و عصبی (<bdi>CNS</bdi>) خفیف.</li><li>داروهای کاهنده‌ی تولید دیرتر اثر می‌کنند؛ داروهای افزایش‌دهنده‌ی دفع (پروبنسید) سریع‌تر.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>کاهش تولید با کاهش اسید اوریک خون یکی نیست؛ هر سه گروه سطح خون را پایین می‌آورند، ولی فقط مهارکننده‌های زانتین اکسیداز «تولید» را کم می‌کنند.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش داروهای نقرس (مهارکننده‌های زانتین اکسیداز)</p>","steps":"<p>کلیدواژه‌ی سؤال «کاهش تولید» است؛ یعنی مهار زانتین اکسیداز.</p>\n<p>رازبوریکاز تجزیه می‌کند؛ پروبنسید و بنزبرومارون دفع را زیاد می‌کنند؛ این سه کنار می‌روند.</p>\n<p>آلوپورینول مهارکننده‌ی زانتین اکسیداز و کاهنده‌ی تولید است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>کاهش تولید با کاهش اسید اوریک خون یکی نیست؛ هر سه گروه سطح خون را پایین می‌آورند، ولی فقط مهارکننده‌های زانتین اکسیداز «تولید» را کم می‌کنند."],"dupOf":null,"dupNote":"","xrefs":["p2q06"]},{"id":"p2q08","session":"p2","full":false,"num":25,"text":"مکانیسم اثر بنزبرومارون مشابه کدامیک از داروهای ضد نقرس زیر است؟","opts":["فبوکسواستات","کلشی سین","آلوپورینول","پروبنسید"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[3]}],"answer":3,"explain":"<p><strong>بنزبرومارون</strong> مثل <strong>پروبنسید</strong> اوریکوزوریک است: بازجذب لوله‌ای اسید اوریک را مهار می‌کند و <strong>دفع</strong> آن را زیاد می‌کند.</p>\n<ul><li><strong>الف) فبوکسوستات:</strong> مهارکننده‌ی زانتین اکسیداز است و <strong>تولید</strong> را کم می‌کند.</li><li><strong>ب) کلشی‌سین:</strong> فقط ضدالتهاب است و بر سطح اسید اوریک اثر ندارد.</li><li><strong>ج) آلوپورینول:</strong> مهارکننده‌ی زانتین اکسیداز و کاهنده‌ی <strong>تولید</strong> است.</li></ul>","flag":"","lesson":"<div class=\"tw\"><table><thead><tr><th>ویژگی</th><th>بنزبرومارون</th><th>پروبنسید</th></tr></thead><tbody><tr><td>مکانیسم</td><td>مهار بازجذب لوله‌ای</td><td>مهار بازجذب لوله‌ای</td></tr><tr><td>نکته‌ی خاص</td><td>ساختار شبیه آمیودارون ← احتیاط در بیمار قلبی (آریتمی)؛ افزایش آنزیم‌های کبدی</td><td>اتصال پروتئینی حدود ۹۰ درصد ← تداخل دارویی؛ تحریک <bdi>CNS</bdi> و برگرداندن تشنج در بیمار صرعی</td></tr></tbody></table></div>\n<ul><li>بنزبرومارون در نارسایی خفیف تا متوسط کلیه قابل استفاده است و برای کسانی مطرح است که نمی‌توانند پروبنسید مصرف کنند.</li><li>سولفین‌پیرازون هم‌مکانیسم و قوی‌تر از پروبنسید است.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>بنزبرومارون را با فبوکسوستات هم‌گروه نکنید؛ هر دو «جدیدتر» اند ولی یکی دفع را زیاد می‌کند و دیگری تولید را کم.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش داروهای نقرس (داروهای اوریکوزوریک: پروبنسید و بنزبرومارون)</p>","steps":"<p>بنزبرومارون اوریکوزوریک است (مهار بازجذب لوله‌ای).</p>\n<p>فبوکسوستات و آلوپورینول کاهش تولید می‌دهند؛ کلشی‌سین ضدالتهاب است؛ سه گزینه کنار می‌روند.</p>\n<p>هم‌مکانیسم با بنزبرومارون، پروبنسید است.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>بنزبرومارون را با فبوکسوستات هم‌گروه نکنید؛ هر دو «جدیدتر» اند ولی یکی دفع را زیاد می‌کند و دیگری تولید را کم."],"dupOf":null,"dupNote":"","xrefs":["p2q04","p2q05"]},{"id":"p2q09","session":"p2","full":false,"num":26,"text":"درمان حمله حاد نقرس چیست؟","opts":["آلوپورینول","پروبنسید","<bdi>NSAIDs</bdi>","بنزبرومارون"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۱","nums":[]}],"answer":2,"explain":"<p>در <strong>حمله‌ی حاد نقرس</strong> مشکل فوری <strong>التهاب</strong> ناشی از کریستال‌های اورات است؛ پس باید یک داروی <strong>ضدالتهاب</strong> داد: <strong><bdi>NSAID</bdi>ها</strong> (مثل ایندومتاسین)، کلشی‌سین یا کورتیکواستروئیدها. از میان گزینه‌ها فقط <bdi>NSAID</bdi>ها این نقش را دارند.</p>\n<ul><li><strong>الف) آلوپورینول:</strong> داروی کاهنده‌ی اسید اوریک برای کنترل درازمدت است و ضدالتهاب نیست؛ شروع آن در میان حمله‌ی حاد ممکن است حمله را تشدید کند.</li><li><strong>ب) پروبنسید:</strong> اوریکوزوریک برای کاهش اسید اوریک است و اثر ضدالتهابی ندارد.</li><li><strong>د) بنزبرومارون:</strong> اوریکوزوریک است و برای حمله‌ی حاد کاربرد ندارد.</li></ul>","flag":"","lesson":"<ul><li>حمله‌ی حاد: <strong><bdi>NSAID</bdi></strong> (مثل ایندومتاسین)، <strong>کلشی‌سین</strong> یا <strong>کورتیکواستروئید</strong>؛ همین داروها در پروفیلاکسی هم به کار می‌روند.</li><li>کنترل اسید اوریک (آلوپورینول، فبوکسوستات، پروبنسید، بنزبرومارون) برای بعد از فروکش حمله و پایین نگه‌داشتن اسید اوریک است.</li><li>شست پا شایع‌ترین مفصل درگیر است؛ سطح طبیعی اسید اوریک حدود ۲ تا ۵ و در نقرس ۶ تا ۱۶ <bdi>mg/dL</bdi>.</li><li>عارضه‌ی اختصاصی کلشی‌سین: اسهال آبکی و خونی (خطر دهیدراتاسیون که خودش نقرس را بدتر می‌کند).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>«داروی نقرس» یعنی دو کار متفاوت: ضدالتهاب برای حمله‌ی حاد، و کاهنده‌ی اسید اوریک برای درمان پایه؛ این دو را جابه‌جا نکنید.</p><p class=\"ref\">منبع: جزوه‌ی فارماکولوژی (دکتر رحیمی‌مقدم)، بخش داروهای نقرس (گروه‌بندی درمان)؛ اثر آلوپورینول در حمله‌ی حاد: <bdi>Katzung</bdi> (در جزوه نبود)</p>","steps":"<p>«حمله‌ی حاد» یعنی نیاز به داروی ضدالتهاب، نه کاهنده‌ی اسید اوریک.</p>\n<p>آلوپورینول، پروبنسید و بنزبرومارون هر سه برای کنترل اسید اوریک‌اند و ضدالتهاب نیستند.</p>\n<p><bdi>NSAID</bdi>ها (همراه با کلشی‌سین و کورتیکواستروئیدها) درمان حمله‌ی حاد هستند.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>«داروی نقرس» یعنی دو کار متفاوت: ضدالتهاب برای حمله‌ی حاد، و کاهنده‌ی اسید اوریک برای درمان پایه؛ این دو را جابه‌جا نکنید."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p3q01","session":"p3","full":false,"num":27,"text":"کودک 12 ساله ای با سابقه شکستگی های استخوانی متعدد ، اسکلرای آبی رنگ و اختلال شنوایی به درمانگاه مراجعه کرده است ، نقص ژنتیکی در سنتز کدامیک می تواند علت بیماری باشد؟","opts":["کلاژن تیپ <bdi>I</bdi>","فیبریلین","غضروف","الاستین"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[5]},{"name":"تلفیقی بهار ۱۴۰۱","nums":[]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[9]},{"name":"تلفیقی بهار ۱۴۰۰","nums":[15]},{"name":"تلفیقی 96A","nums":[7]}],"answer":0,"explain":"<p>شکستگی‌های مکرر در کودک همراه با <strong>اسکلرای آبی</strong> و <strong>کاهش شنوایی</strong> تابلوی <strong>استئوژنزیس ایمپرفکتا</strong> (بیماری استخوان شکننده) است؛ نقص در سنتز <strong>کلاژن تیپ <bdi>I</bdi></strong> (زنجیره‌های α1 یا α2) علت آن است. اسکلرای نازک اجازه می‌دهد کوروئید زیر آن دیده شود و کاهش شنوایی به خاطر ناهنجاری استخوانک‌های گوش میانی است.</p>\n<ul><li><strong>ب) فیبریلین:</strong> نقص آن سندرم مارفان را می‌دهد (قد بلند، انگشتان بلند، دررفتگی عدسی، آنوریسم آئورت)، نه شکنندگی استخوان.</li><li><strong>ج) غضروف:</strong> نام یک بافت است، نه محصول ژنی که سنتزش مختل شود؛ بیماری‌های غضروفی از اختلال در کلاژن‌های تیپ ۲، ۱۰ و ۱۱ دیده می‌شوند و تابلوی اسکلرای آبی و کاهش شنوایی را نمی‌دهند.</li><li><strong>د) الاستین:</strong> اختلال آن به مشکلات پوست و عروق (مثل سندرم‌های لاکسیتی پوستی) مربوط است، نه شکستگی‌های مکرر استخوان.</li></ul>","flag":"","lesson":"<ul><li><bdi>OI</bdi>: نقص کمیت یا کیفیت <strong>کلاژن تیپ <bdi>I</bdi></strong>؛ بیشتر موارد اتوزومال غالب و با مکانیسم <bdi>dominant negative</bdi>.</li><li>تریاد کلاسیک: شکستگی‌های مکرر، <strong>اسکلرای آبی</strong>، کاهش شنوایی؛ علاوه بر آن دندان‌های کوچک و بدشکل (کمبود عاج) و اندام‌های لاغر.</li><li>شایع‌ترین اختلال ارثی بافت همبند؛ طیف بالینی از کشنده در رحم (تیپ <bdi>II</bdi>) تا عمر طبیعی با شکستگی در کودکی (تیپ <bdi>I</bdi>).</li><li>بخش معدنی استخوان سالم است؛ مشکل در ماتریکس آلی (کلاژن) است.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>در <bdi>OI</bdi> استخوان «کم» و شکننده است (نقص ماتریکس)؛ آن را با استئوپتروزیس (استخوان سفت ولی شکننده، نقص استئوکلاست) اشتباه نگیرید.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش استئوژنزیس ایمپرفکتا؛ نقش فیبریلین و الاستین: <bdi>Robbins</bdi> (در جزوه نبود)</p>","steps":"<p>کلیدواژه‌ها: شکستگی‌های متعدد، اسکلرای آبی، اختلال شنوایی در کودک ← استئوژنزیس ایمپرفکتا.</p>\n<p>بیماری نقص در سنتز کلاژن تیپ <bdi>I</bdi> است.</p>\n<p>فیبریلین ← مارفان؛ الاستین ← بافت همبند الاستیک؛ غضروف نام بافت است، نه یک پروتئین.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>در <bdi>OI</bdi> استخوان «کم» و شکننده است (نقص ماتریکس)؛ آن را با استئوپتروزیس (استخوان سفت ولی شکننده، نقص استئوکلاست) اشتباه نگیرید."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p3q02","session":"p3","full":false,"num":28,"text":"ضایعه ی تومورال دردناک ستون فقرات در کودک 12 ساله به سایز یک سانتی متر نمایانگر ترابکولهای استخوانی <bdi>woven</bdi> می‌باشد که با یک ردیف استئوبلاست پوشیده شده اند. در بین ترابکولها بافت همبندی عروقی شلی دیده میشود. کدام تشخیص محتملتر است؟","opts":["<bdi>Osteosarcoma</bdi>","<bdi>Osteoblastoma</bdi>","<bdi>Osteoid osteoma</bdi>","<bdi>Osteochondroma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[6]},{"name":"تلفیقی بهار ۱۴۰۱","nums":[]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[11]},{"name":"تلفیقی بهار ۱۴۰۰","nums":[22]},{"name":"تلفیقی 96A","nums":[10]}],"answer":2,"explain":"<p>بیمار نوجوان/کودک با <strong>ضایعه‌ی دردناک خوش‌خیم</strong>، ترابکول‌های <strong><bdi>woven</bdi></strong> با حاشیه‌ی <strong>استئوبلاستی</strong> (<bdi>osteoblastic rimming</bdi>) و بافت همبندی عروقی شل بین آن‌ها، تصویر <strong>استئوئید استئوما</strong> و استئوبلاستوما است. این دو از نظر بافت‌شناسی تقریباً یکسان‌اند و تفاوتشان در <strong>اندازه</strong> است: ضایعه‌ی کوچک‌تر از <strong>۲ سانتی‌متر</strong> استئوئید استئوما است و این ضایعه‌ی ۱ سانتی‌متری در همان گروه می‌افتد.</p>\n<ul><li><strong>الف) <bdi>Osteosarcoma</bdi>:</strong> تومور بدخیم با سلول‌های آتیپیک و <strong>استئوئید</strong> تولیدشده توسط سلول‌های بدخیم است، معمولاً بزرگ و مهاجم و با پاره شدن قشر؛ شرح بافتی ضایعه‌ی کوچک و منظم با حاشیه‌ی استئوبلاستی به نفع آن نیست.</li><li><strong>ب) <bdi>Osteoblastoma</bdi>:</strong> همان تصویر میکروسکوپی را دارد ولی ضایعه‌ی <strong>بزرگ‌تر از ۲ سانتی‌متر</strong> است، بیشتر مهره را درگیر می‌کند و درد آن به آسپرین/<bdi>NSAID</bdi> پاسخ نمی‌دهد؛ اندازه‌ی ۱ سانتی‌متر با آن نمی‌خواند.</li><li><strong>د) <bdi>Osteochondroma</bdi>:</strong> زائده‌ی استخوانی با <strong>کلاهک غضروفی</strong> است (اگزوستوز) و بافت‌شناسی آن غضروف روی استخوان است، نه ترابکول‌های <bdi>woven</bdi> با حاشیه‌ی استئوبلاستی.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون گزینه‌ی ج است، ولی محل ستون فقرات و تصویر بافتی یکسان با استئوبلاستوما گزینه‌ی ب را هم قابل بحث می‌کند؛ چون اندازه‌ی یک سانتی‌متر (کمتر از ۲ سانتی‌متر) ملاک افتراق این دو تومور است، ج بهتر است.","lesson":"<div class=\"tw\"><table><thead><tr><th>ویژگی</th><th><bdi>Osteoid osteoma</bdi></th><th><bdi>Osteoblastoma</bdi></th></tr></thead><tbody><tr><td>اندازه</td><td>کمتر از ۲ سانتی‌متر</td><td>بزرگ‌تر</td></tr><tr><td>محل</td><td>قشری، پروگزیمال فمور و تیبیا</td><td>ستون مهره‌ها (زوائد خاری و عرضی)</td></tr><tr><td>درد</td><td>موضعی، به آسپرین/<bdi>NSAID</bdi> پاسخ می‌دهد</td><td>به آسپرین پاسخ نمی‌دهد</td></tr><tr><td>نایدوس</td><td>دارد، با اسکلروز اطراف</td><td>ندارد</td></tr></tbody></table></div>\n<ul><li>هر دو خوش‌خیم، سن ۱۰ تا ۲۰ سال، مرد بیشتر از زن؛ استئوبلاستوما ممکن است خیلی بزرگ شود و به بدخیمی (استئوسارکوم) برسد.</li><li>درد شبانه که با بروفن خوب می‌شود ← استئوئید استئوما (نقش پروستاگلاندین‌ها).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>محل ستون فقرات را دلیل قطعی استئوبلاستوما نگیرید؛ این دو تومور بافت‌شناسی یکسان دارند و وقتی اندازه‌ی کمتر از ۲ سانتی‌متر داده شده، اندازه ملاک است.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش استئوئید استئوما و استئوبلاستوما</p>","steps":"<p>کلیدواژه‌ها: کودک ۱۲ ساله، دردناک، ترابکول <bdi>woven</bdi> با حاشیه‌ی استئوبلاستی، اندازه‌ی ۱ سانتی‌متر.</p>\n<p>استئوسارکوم بدخیم است و استئوئید می‌سازد؛ استئوکندروما کلاهک غضروفی دارد؛ هر دو کنار می‌روند.</p>\n<p>بین دو ضایعه‌ی هم‌بافت، ملاک افتراق اندازه است: کمتر از ۲ سانتی‌متر = استئوئید استئوما، بزرگ‌تر = استئوبلاستوما.</p>\n<p>اندازه‌ی ۱ سانتی‌متر یعنی استئوئید استئوما.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>محل ستون فقرات را دلیل قطعی استئوبلاستوما نگیرید؛ این دو تومور بافت‌شناسی یکسان دارند و وقتی اندازه‌ی کمتر از ۲ سانتی‌متر داده شده، اندازه ملاک است."],"dupOf":null,"dupNote":"","xrefs":["f06"]},{"id":"p3q03","session":"p3","full":false,"num":29,"text":"در کدامیک از تومورهای بدخیم استخوان گزارش گریدینگ تومور حائز اهمیت بوده و مستقیما با شانس متاستاز ضایعه مرتبط است؟","opts":["<bdi>Conventional Osteosarcoma</bdi>","<bdi>Conventional Chondrosarcoma</bdi>","<bdi>Ewing sarcoma</bdi>","<bdi>Metastatic tumors</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[7]},{"name":"تلفیقی بهار ۱۴۰۱","nums":[]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[19]},{"name":"تلفیقی بهار ۱۴۰۰","nums":[25]},{"name":"تلفیقی 96A","nums":[11]}],"answer":1,"explain":"<p>در <strong>کندروسارکوم</strong> تمایز همان <strong>گرید</strong> است و گرید مستقیماً با رفتار بیولوژیک و پیش‌آگهی ارتباط دارد: گرید پایین (خوب تمایزیافته) متاستاز نادر دارد و گرید بالا (تمایز ضعیف) متاستاز شایع و بقای کمتر. به همین دلیل گزارش گرید در این تومور حیاتی است.</p>\n<ul><li><strong>الف) <bdi>Conventional Osteosarcoma</bdi>:</strong> تومور بدخیم با رفتار تهاجمی است و پیش‌آگهی آن عمدتاً با میزان <strong>نکروز</strong> بعد از شیمی‌درمانی (و اولیه/ثانویه بودن) سنجیده می‌شود، نه با گرید به‌عنوان ملاک مستقیم احتمال متاستاز.</li><li><strong>ج) <bdi>Ewing sarcoma</bdi>:</strong> تومور گرد سلول کوچک با درجات مختلف تمایز نوروانکتودرمی و بدخیمی بالا است؛ گریدبندی چندپله‌ای مثل کندروسارکوم ملاک پیش‌آگهی آن نیست.</li><li><strong>د) <bdi>Metastatic tumors</bdi>:</strong> این ضایعات خودشان متاستاز تومورهای دیگر (پروستات، پستان، کلیه، ریه) به استخوان‌اند؛ گرید مطرح‌شده مربوط به تومور اولیه است و گزارش گرید استخوانی برای تعیین «شانس متاستاز همین ضایعه» معنایی ندارد.</li></ul>","flag":"","lesson":"<div class=\"tw\"><table><thead><tr><th>گرید کندروسارکوم</th><th>بقای ۵ ساله</th><th>متاستاز</th></tr></thead><tbody><tr><td>گرید ۱ (پایین)</td><td>حدود ۸۰ تا ۹۰ درصد</td><td>نادر</td></tr><tr><td>گرید ۳ (بالا)</td><td>حدود ۴۳ درصد</td><td>حدود ۷۰ درصد</td></tr></tbody></table></div>\n<ul><li>کندروسارکوم: سن ۴۰ سال و بالاتر، مرد بیشتر از زن؛ محل لگن، شانه، دنده‌ها؛ ماکروسکوپی شفاف و آبی‌خاکستری؛ انتشار خونی به ریه و اسکلت.</li><li>انواع: کلاسیک (<bdi>conventional</bdi>)، میکزوئید، دیفرانسیه‌شده (<bdi>dedifferentiated</bdi>)، سلول روشن، مزانشیمال.</li><li>در کندروسارکوم تمایز = گرید و گرید پیش‌آگهی را تعیین می‌کند.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>کندروسارکوم را با استئوسارکوم اشتباه نگیرید: مشخصه‌ی کندروسارکوم گرید است و در استئوسارکوم دیدن استئوئید برای تشخیص لازم است.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش کندروسارکوم (رابطه‌ی گرید و رفتار بیولوژیک)</p>","steps":"<p>کلیدواژه‌ی سؤال: گرید تومور با شانس متاستاز مستقیماً مرتبط است.</p>\n<p>در کندروسارکوم تمایز همان گرید است؛ گرید ۱ متاستاز نادر و گرید ۳ حدود ۷۰ درصد متاستاز.</p>\n<p>استئوسارکوم با نکروز بعد از درمان سنجیده می‌شود؛ ایوینگ با گرید تقسیم‌بندی نمی‌شود؛ تومور متاستاتیک گرید خاص خودش را ندارد.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>کندروسارکوم را با استئوسارکوم اشتباه نگیرید: مشخصه‌ی کندروسارکوم گرید است و در استئوسارکوم دیدن استئوئید برای تشخیص لازم است."],"dupOf":null,"dupNote":"","xrefs":["f10"]},{"id":"p3q04","session":"p3","full":false,"num":30,"text":"شایع ترین ارگانیسم مسئول در استئومیلیت در دوره نوزادی کدام است؟","opts":["<bdi>E.Coli</bdi>","<bdi>Staph aureus</bdi>","<bdi>Salmonella</bdi>","<bdi>Streptococcus</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[8]}],"answer":3,"explain":"<p>در جزوه برای <strong>نوزادان</strong> عوامل استئومیلیت <strong>استرپتوکوک گروه <bdi>B</bdi></strong> و <strong><bdi>Haemophilus influenzae</bdi></strong> ذکر شده است؛ بنابراین از میان گزینه‌ها <strong><bdi>Streptococcus</bdi></strong> پاسخ مناسب است. استئومیلیت در بچه‌ها بیشتر از راه خونی ایجاد می‌شود.</p>\n<ul><li><strong>الف) <bdi>E. coli</bdi>:</strong> در استئومیلیت بیماران تزریق‌کننده‌ی مواد (و عفونت ادراری همراه) از گرم‌منفی‌ها مطرح است، نه به‌عنوان عامل شاخص نوزادی در جزوه.</li><li><strong>ب) <bdi>Staph aureus</bdi>:</strong> «سردسته»‌ی عوامل استئومیلیت در کل است (مثلاً بزرگسال و عارضه‌ی شکستگی/پای دیابتی)، ولی برای دوره‌ی نوزادی جزوه آن را نام نمی‌برد.</li><li><strong>ج) <bdi>Salmonella</bdi>:</strong> عامل شاخص استئومیلیت در <strong>کم‌خونی داسی‌شکل</strong> است.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون گزینه‌ی د است، ولی در بسیاری از مراجع بالینی (مثل <bdi>Nelson</bdi>) <bdi>Staph aureus</bdi> شایع‌ترین عامل استئومیلیت نوزادی است و ب را به‌شدت قابل بحث می‌کند؛ طبق جزوه در دوره‌ی نوزادی عوامل اصلی استرپتوکوک گروه <bdi>B</bdi> و <bdi>H. influenzae</bdi> هستند، پس د انتخاب می‌شود.","lesson":"<div class=\"tw\"><table><thead><tr><th>زمینه</th><th>عامل</th></tr></thead><tbody><tr><td>به‌طور کلی (سردسته)</td><td><bdi>Staphylococcus aureus</bdi></td></tr><tr><td>کم‌خونی داسی‌شکل</td><td><bdi>Salmonella</bdi></td></tr><tr><td>تزریق‌کننده‌ی مواد <bdi>IV</bdi> / عفونت ادراری</td><td>گرم‌منفی‌ها: <bdi>E. coli</bdi>، <bdi>Pseudomonas</bdi>، <bdi>Klebsiella</bdi></td></tr><tr><td>نوزادان</td><td>استرپتوکوک گروه <bdi>B</bdi>، <bdi>Haemophilus influenzae</bdi></td></tr><tr><td>شکستگی باز</td><td>بی‌هوازی‌ها یا عفونت مختلط</td></tr></tbody></table></div>\n<ul><li>راه‌های ورود: خونی (بیشتر کودکان)، شکستگی/جراحی، مستقیم (مثل پای دیابتی).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>«شایع‌ترین کلی = <bdi>Staph aureus</bdi>» را به همه‌ی گروه‌ها تعمیم ندهید؛ زمینه‌ی بیمار (داسی‌شکل، تزریقی، نوزاد) عامل را عوض می‌کند.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش استئومیلیت (راه‌های ورود و عوامل بیماری‌زا)</p>","steps":"<p>سؤال درباره‌ی دوره‌ی نوزادی است و نه استئومیلیت به‌طور کلی.</p>\n<p><bdi>Salmonella</bdi> مال داسی‌شکل است و <bdi>E. coli</bdi> مال تزریق‌کننده‌ها؛ <bdi>Staph aureus</bdi> سردسته در کل است.</p>\n<p>در جزوه برای نوزادان استرپتوکوک گروه <bdi>B</bdi> و <bdi>H. influenzae</bdi> آمده است.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>«شایع‌ترین کلی = <bdi>Staph aureus</bdi>» را به همه‌ی گروه‌ها تعمیم ندهید؛ زمینه‌ی بیمار (داسی‌شکل، تزریقی، نوزاد) عامل را عوض می‌کند."],"dupOf":null,"dupNote":"","xrefs":["f03","p3q16"]},{"id":"p3q05","session":"p3","full":false,"num":31,"text":"موتاسیون در کدام ژن عامل ایجاد بیماری استئوپتروزیس می باشد؟","opts":["<bdi>FGFR3</bdi>","<bdi>Carbonic anhydrase 2 gene</bdi>","<bdi>SQSTM1</bdi>","<bdi>Collagen type I</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[9]}],"answer":1,"explain":"<p><strong>استئوپتروزیس</strong> (بیماری استخوان مرمری) از نقص عملکرد <strong>استئوکلاست</strong> است؛ شایع‌ترین علت، نقص آنزیم <strong>کربنیک آنهیدراز (<bdi>CA II</bdi>)</strong> است که باید حفره‌ی تحلیل را اسیدی کند. پس جهش در ژن <strong><bdi>Carbonic anhydrase 2</bdi></strong> عامل بیماری است.</p>\n<ul><li><strong>الف) <bdi>FGFR3</bdi>:</strong> جهش فعال‌کننده‌ی (<bdi>gain-of-function</bdi>) این ژن <strong>آکندروپلازی</strong> (و دیسپلازی تاناتوفوریک) را می‌دهد، چون رشد اندوکندرال را مهار می‌کند.</li><li><strong>ج) <bdi>SQSTM1</bdi>:</strong> از ژن‌های دخیل در <strong>بیماری پاژه</strong> است.</li><li><strong>د) <bdi>Collagen type I</bdi>:</strong> جهش آن <strong>استئوژنزیس ایمپرفکتا</strong> را ایجاد می‌کند.</li></ul>","flag":"","lesson":"<ul><li>استئوپتروزیس: تحلیل استخوان مختل ← استخوان <strong>سفت، متراکم و در عین حال شکننده</strong> («سنگ مرمر»).</li><li>نقص رایج: <strong>کربنیک آنهیدراز</strong> (اسیدی نشدن حفره)؛ نقص‌های دیگر: پمپ پروتون و کانال کلرید.</li><li>پیامدها: نبود فضای مدولاری ← پان‌سیتوپنی و خون‌سازی خارج مدولاری با بزرگی کبد و طحال؛ فشار بر اعصاب جمجمه‌ای (کاهش شنوایی و بینایی)؛ اسیدوز توبولی کلیوی.</li><li>رادیوگرافی: اسکلروز منتشر، نمای «استخوان در استخوان» و فلاسک ارلن مایر.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>استئوپتروزیس (کم‌کاری استئوکلاست، استخوان سفید) و <bdi>OI</bdi> (نقص کلاژن <bdi>I</bdi>) هر دو شکستگی می‌دهند؛ با ژن و تراکم استخوان جدایشان کنید.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش استئوپتروزیس</p>","steps":"<p>کلیدواژه: استئوپتروزیس = نقص استئوکلاست.</p>\n<p>شایع‌ترین نقص آنزیم کربنیک آنهیدراز (<bdi>CA II</bdi>) است که حفره‌ی تحلیل را اسیدی می‌کند.</p>\n<p><bdi>FGFR3</bdi> ← آکندروپلازی؛ <bdi>SQSTM1</bdi> ← پاژه؛ کلاژن <bdi>I</bdi> ← <bdi>OI</bdi>.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>استئوپتروزیس (کم‌کاری استئوکلاست، استخوان سفید) و <bdi>OI</bdi> (نقص کلاژن <bdi>I</bdi>) هر دو شکستگی می‌دهند؛ با ژن و تراکم استخوان جدایشان کنید."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p3q06","session":"p3","full":false,"num":32,"text":"آقای 15 ساله با ضایعه متافیزی لیتیک با حاشیه مشخص در استخوان تیبیا مراجعه کرده است در نمای میکروسکوپی دارای فضاهای سیستیک حاوی خون که با یک جدار فیبروز حاوی فیبروبلاستهای تکثیری و سلولهای چند هسته ای و استخوان واکنشی در هم بافته احاطه شده است دیده می شود .تشخیص کدام است ؟","opts":["<bdi>osteoma</bdi>","<bdi>Aneurysmal bone cyst</bdi>","<bdi>Osteoid osteoma</bdi>","<bdi>Osteochondroma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[10]},{"name":"تلفیقی بهار ۱۴۰۱","nums":[]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[14]}],"answer":1,"explain":"<p>ضایعه‌ی <strong>لیتیک متافیزی با حاشیه‌ی مشخص</strong> در <strong>دهه‌ی دوم زندگی</strong>، متشکل از <strong>فضاهای کیستیک پر از خون</strong> با دیواره‌ی فیبروز (فیبروبلاست‌های تکثیری + <strong>سلول‌های غول‌آسای چندهسته‌ای</strong> + <strong>استخوان واکنشی وُون</strong>) تصویر کلاسیک <strong><bdi>Aneurysmal bone cyst</bdi> (<bdi>ABC</bdi>)</strong> است.</p>\n<ul><li><strong>الف) <bdi>Osteoma</bdi>:</strong> رشد اگزوفیتیک و متراکم روی سطح استخوان‌های جمجمه و صورت (۴۰ تا ۵۰ سالگی) است؛ شبیه استخوان طبیعی و فاقد فضای کیستیک خونی.</li><li><strong>ج) <bdi>Osteoid osteoma</bdi>:</strong> ضایعه‌ی کوچک قشری با درد، با <bdi>nidus</bdi> از ترابکول‌های درهم‌بافته‌ی استخوان وُون است؛ فضاهای کیستیک بزرگ پر از خون ندارد.</li><li><strong>د) <bdi>Osteochondroma</bdi>:</strong> زائده‌ی استخوانی با کلاهک غضروفی است و کیستیک نیست.</li></ul>","flag":"","lesson":"<ul><li><bdi>ABC</bdi>: دو دهه‌ی اول زندگی، <strong>متافیز</strong> استخوان‌های بلند و عناصر خلفی مهره؛ ضایعه‌ی لیتیک با مرز مشخص و نمای <strong><bdi>fluid-air level</bdi></strong> در <bdi>MRI/CT</bdi>.</li><li>نام آنوریسمال <strong><bdi>misnomer</bdi></strong> است: فضاها <strong>اندوتلیوم ندارند</strong> و ربطی به رگ ندارند؛ سپتاها از فیبروبلاست، سلول غول‌آسا و استخوان وُون واکنشی ساخته شده‌اند.</li><li>پاتوژنز: بازآرایی <strong><bdi>USP6</bdi></strong> (17<bdi>p13</bdi>) ← افزایش <bdi>NF</bdi>-κ<bdi>B</bdi> و فعالیت متالوپروتئینازها ← تحلیل استخوان.</li><li>ممکن است همراه تومور دیگری (مثلاً تومور سلول غول‌آسا) باشد؛ پس رادیولوژی را باید دید.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>ضایعه</th><th>محل / سن</th><th>نشانه‌ی کلیدی</th></tr></thead><tbody><tr><td><bdi>ABC</bdi></td><td>متافیز، دهه‌ی ۲</td><td>فضاهای پر از خون + سپتای فیبروز</td></tr><tr><td>تومور سلول غول‌آسا</td><td>اپی‌فیز، ۲۰ تا ۴۰ سال</td><td>لیتیک خارج از مرکز، عود</td></tr><tr><td><bdi>Osteoid osteoma</bdi></td><td>قشر متافیز فمور/تیبیا</td><td>درد، <bdi>nidus</bdi> کوچک</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دیدن سلول غول‌آسا اختصاصی هیچ توموری نیست؛ «کیست پر از خون + متافیز + جوان» یعنی <bdi>ABC</bdi> نه تومور سلول غول‌آسا.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و بافت نرم (دکتر پناهی)، بخش کیست آنوریسمال استخوان</p>","steps":"<p>کلیدواژه‌ها: «لیتیک متافیزی»، «فضاهای کیستیک حاوی خون» و «سلول چندهسته‌ای + استخوان واکنشی».</p>\n<p>اسم کیست + خون یعنی <bdi>Aneurysmal bone cyst</bdi>.</p>\n<p><bdi>Osteoma</bdi> روی سطح جمجمه است، <bdi>Osteoid osteoma</bdi> ضایعه‌ی کوچک قشری دردناک است و <bdi>Osteochondroma</bdi> زائده‌ی استخوانی با کلاهک غضروفی است؛ هیچ‌کدام کیستیک نیستند.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دیدن سلول غول‌آسا اختصاصی هیچ توموری نیست؛ «کیست پر از خون + متافیز + جوان» یعنی <bdi>ABC</bdi> نه تومور سلول غول‌آسا."],"dupOf":null,"dupNote":"","xrefs":["f05"]},{"id":"p3q07","session":"p3","full":false,"num":33,"text":"کدامیک از تغییرات زیر جز یافته‌های بافت شناسی آرتریت روماتوئید نمی باشد ؟","opts":["صیقلی شدن استخوان مفصلی","هیپرپلازی سلولهای سینویال","تشکیل پانوس","جوش خوردگی استخوانی مفصل"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[11]},{"name":"تلفیقی بهار ۱۴۰۱","nums":[]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[23]},{"name":"تلفیقی بهار ۱۴۰۰","nums":[16]},{"name":"تلفیقی 96A","nums":[16]}],"answer":0,"explain":"<p>در آرتریت روماتوئید (<bdi>RA</bdi>) سینوویوم دچار <strong>هیپرپلازی سلول‌های پوشاننده</strong>، نفوذ لنفوپلاسموسیتی (با فولیکول لنفوئید) و تشکیل <strong>پانوس</strong> می‌شود؛ در مراحل پیشرفته نیز <strong>آنکیلوز فیبروز و استخوانی</strong> رخ می‌دهد. <strong>صیقلی شدن (<bdi>eburnation</bdi>) سطح استخوان مفصلی</strong> از یافته‌های <strong>استئوآرتریت</strong> است و در <bdi>RA</bdi> وجود ندارد.</p>\n<ul><li><strong>ب) هیپرپلازی سلول‌های سینوویال:</strong> جزو یافته‌های اصلی <bdi>RA</bdi> است.</li><li><strong>ج) تشکیل پانوس:</strong> بافت گرانولاسیون التهابی سینوویال که روی غضروف و استخوان مفصلی می‌خزد و آن را تخریب می‌کند؛ علامت شاخص <bdi>RA</bdi> است.</li><li><strong>د) جوش خوردگی استخوانی مفصل:</strong> آنکیلوز استخوانی (و فیبروز) نتیجه‌ی دیررس تخریب مفصل در <bdi>RA</bdi> است.</li></ul>","flag":"","lesson":"<ul><li><bdi>RA</bdi>: التهاب مزمن خودایمن سینوویوم ← <strong>هیپرپلازی سینوویال</strong> + ارتشاح سلول‌های <bdi>T</bdi> و <bdi>B</bdi> و پلاسماسل + <strong>پانوس</strong> ← فرسایش غضروف و استخوان.</li><li>پیامد: <strong>آنکیلوز</strong> فیبروز یا استخوانی، دفورمیتی مفصل (مثلاً انحراف اولنار و گردن‌قو).</li><li>استئوآرتریت: از بین رفتن غضروف، <strong><bdi>eburnation</bdi></strong> (استخوان صیقلی و عاج‌مانند)، استئوفیت، کیست ساب‌کندرال، <bdi>joint mouse</bdi>.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>یافته</th><th><bdi>RA</bdi></th><th><bdi>OA</bdi></th></tr></thead><tbody><tr><td>پانوس</td><td>دارد</td><td>ندارد</td></tr><tr><td>هیپرپلازی سینوویال</td><td>برجسته</td><td>خفیف و ثانویه</td></tr><tr><td><bdi>eburnation</bdi> / استئوفیت</td><td>ندارد</td><td>دارد</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span><bdi>eburnation</bdi> و استئوفیت را به <bdi>OA</bdi> نسبت بدهید؛ در سؤال‌های «به جز»، گزینه‌ی مخصوص <bdi>OA</bdi> پاسخ است.</p><p class=\"ref\">مرجع: <bdi>Robbins</bdi> (در جزوه نبود)</p>","steps":"<p>سؤال «به جز» است؛ پس سه گزینه از یافته‌های <bdi>RA</bdi> و یکی از <bdi>OA</bdi> است.</p>\n<p>هیپرپلازی سینوویال، پانوس و آنکیلوز همگی از یافته‌های <bdi>RA</bdi> هستند.</p>\n<p>صیقلی شدن (<bdi>eburnation</bdi>) استخوان زیر غضروف از <bdi>OA</bdi> است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span><bdi>eburnation</bdi> و استئوفیت را به <bdi>OA</bdi> نسبت بدهید؛ در سؤال‌های «به جز»، گزینه‌ی مخصوص <bdi>OA</bdi> پاسخ است."],"dupOf":null,"dupNote":"","xrefs":["f12"]},{"id":"p3q08","session":"p3","full":false,"num":34,"text":"در کدامیک از تومورهای زیر جا بجایی متعادل کروموزم (<bdi>q24</bdi>:<bdi>q12</bdi>)(11:22) دیده می شود؟","opts":["<bdi>Osteosarcoma</bdi>","<bdi>Chondrosarcoma</bdi>","<bdi>Ewing sarcoma</bdi>","<bdi>Giant cell tumor of bone</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[12]},{"name":"تلفیقی بهار ۱۴۰۱","nums":[]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[20]},{"name":"تلفیقی بهار ۱۴۰۰","nums":[17]},{"name":"تلفیقی 96A","nums":[18]}],"answer":2,"explain":"<p>جابه‌جایی متعادل <strong><bdi>t</bdi>(11;22)(<bdi>q24</bdi>;<bdi>q12</bdi>)</strong> ژن‌های <strong><bdi>EWS</bdi></strong> و <strong><bdi>FLI1</bdi></strong> را به هم می‌رساند و پروتئین کایمریک <strong><bdi>EWS-FLI1</bdi></strong> (یک فاکتور رونویسی فعال) می‌سازد؛ این ناهنجاری شاخص <strong>سارکوم یوئینگ</strong> است.</p>\n<ul><li><strong>الف) <bdi>Osteosarcoma</bdi>:</strong> کاریوتیپ پیچیده‌ی نامتعادل دارد و جهش‌های <strong><bdi>RB</bdi></strong> و <strong><bdi>TP53</bdi></strong> مهم‌اند؛ جابه‌جایی اختصاصی ندارد.</li><li><strong>ب) <bdi>Chondrosarcoma</bdi>:</strong> جهش‌های <strong><bdi>IDH1/IDH2</bdi></strong> در آن مطرح است و <bdi>t</bdi>(11;22) ندارد.</li><li><strong>د) <bdi>Giant cell tumor of bone</bdi>:</strong> تومور خوش‌خیم موضعاً مهاجم اپی‌فیز است و ژنتیک اختصاصی آن جهش <strong><bdi>H3F3A</bdi></strong> است، نه این جابه‌جایی.</li></ul>","flag":"","lesson":"<ul><li>سارکوم یوئینگ: تومور <strong>سلول گرد کوچک</strong> (آبی) با تمایز نورواکتودرمی؛ ۱۰ تا ۲۰ سالگی؛ <strong>دیافیز</strong> استخوان‌های بلند (به‌ویژه فمور) و استخوان‌های پهن.</li><li>رادیولوژی: <strong>پوست پیازی (<bdi>onion skin</bdi>)</strong>؛ علائم سیستمیک ممکن است؛ هم در استخوان و هم در بافت نرم دیده می‌شود.</li><li><strong><bdi>t</bdi>(11;22)(<bdi>q24</bdi>;<bdi>q12</bdi>) = <bdi>EWS-FLI1</bdi></strong> (حدود ۸۵ درصد)؛ <strong><bdi>t</bdi>(21;22) = <bdi>EWS-ERG</bdi></strong> (واریانت کمتر شایع).</li><li>همین تومور با نام <bdi>PNET</bdi> خارج‌استخوانی (<bdi>Askin</bdi>) نیز شناخته می‌شود.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span><bdi>t</bdi>(11;22) را با <bdi>t</bdi>(<bdi>X</bdi>;18) (سینوویال سارکوم) و <bdi>t</bdi>(12;16) (لیپوسارکوم میگزوئید) و <bdi>t</bdi>(2;13) (رابدومیوسارکوم آلوئولر) قاطی نکنید.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی تومورهای استخوان و بافت نرم (دکتر پناهی)، بخش سارکوم یوئینگ؛ مرجع برای جهش‌های سایر تومورها: <bdi>Robbins</bdi> (در جزوه نبود)</p>","steps":"<p>جابه‌جایی (11;22)(<bdi>q24</bdi>;<bdi>q12</bdi>) یعنی همجوشی <bdi>EWS-FLI1</bdi>.</p>\n<p>این ناهنجاری مخصوص سارکوم یوئینگ است.</p>\n<p>استئوسارکوم (<bdi>RB/TP53</bdi>)، کندروسارکوم (<bdi>IDH</bdi>) و تومور سلول غول‌آسا (<bdi>H3F3A</bdi>) با ژنتیک دیگری شناخته می‌شوند.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span><bdi>t</bdi>(11;22) را با <bdi>t</bdi>(<bdi>X</bdi>;18) (سینوویال سارکوم) و <bdi>t</bdi>(12;16) (لیپوسارکوم میگزوئید) و <bdi>t</bdi>(2;13) (رابدومیوسارکوم آلوئولر) قاطی نکنید."],"dupOf":null,"dupNote":"","xrefs":["f14"]},{"id":"p3q09","session":"p3","full":false,"num":35,"text":"محل شایع همه تومورهای زیر متافیز استخوانهای بلند است به جز؟","opts":["<bdi>Osteochondroma</bdi>","<bdi>Osteoid Osteoma</bdi>","<bdi>Osteosarcoma</bdi>","<bdi>Giant cell tumor of bone</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[13]}],"answer":3,"explain":"<p>محل شایع <strong><bdi>Giant cell tumor</bdi></strong> در <strong>اپی‌فیز</strong> استخوان‌های بلند (اطراف زانو) است، در حالی که سایر گزینه‌ها در متافیز یا نزدیک آن قرار دارند.</p>\n<ul><li><strong>الف) <bdi>Osteochondroma</bdi>:</strong> زائده‌ی استخوانی با کلاهک غضروفی در متافیز استخوان‌های بلند (نزدیک صفحه‌ی رشد) است.</li><li><strong>ب) <bdi>Osteoid osteoma</bdi>:</strong> ضایعه‌ی قشری با محل شایع متافیز فمور و تیبیا (در جدول جزوه).</li><li><strong>ج) <bdi>Osteosarcoma</bdi>:</strong> محل شایع آن متافیز فمور دیستال و تیبیای پروگزیمال است.</li></ul>","flag":"","lesson":"<ul><li>قاعده‌ی محل: <strong>اپی‌فیز</strong> ← تومور سلول غول‌آسا (و کندروبلاستوم)؛ <strong>متافیز</strong> ← اکثر تومورها (استئوسارکوم، استئوکندروما، <bdi>ABC</bdi>، فیبروم غیراستخوانی‌شونده)؛ <strong>دیافیز</strong> ← سارکوم یوئینگ.</li><li>تومور سلول غول‌آسا: ۲۰ تا ۴۰ سال، ضایعه‌ی کاملاً لیتیک و <strong>خارج از مرکز</strong>، عود ۴۰ تا ۶۰ درصد، متاستاز ریوی حدود ۴ درصد.</li><li>در تشخیص هر تومور استخوانی سن و محل (اپی‌فیز، متافیز، دیافیز) بسیار مهم است.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>تومور</th><th>محل</th></tr></thead><tbody><tr><td>تومور سلول غول‌آسا</td><td>اپی‌فیز</td></tr><tr><td>استئوسارکوم / استئوکندروما</td><td>متافیز</td></tr><tr><td>سارکوم یوئینگ</td><td>دیافیز</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>سلول غول‌آسا در چند ضایعه دیده می‌شود (<bdi>ABC</bdi>، فیبروم غیراستخوانی‌شونده، تومور قهوه‌ای)؛ مشخصه‌ی تومور سلول غول‌آسای واقعی «اپی‌فیز + عود» است.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل بخش اول و دوم (دکتر پناهی)، جدول تومورهای استخوان</p>","steps":"<p>سؤال «به جز» است؛ دنبال تومور غیرمتافیزی بگرد.</p>\n<p>استئوکندروما و استئوسارکوم متافیزی‌اند و استئوئید استئوما هم در جدول جزوه در متافیز فمور و تیبیا آمده است.</p>\n<p>تومور سلول غول‌آسا اپی‌فیزی است (اطراف زانو).</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>سلول غول‌آسا در چند ضایعه دیده می‌شود (<bdi>ABC</bdi>، فیبروم غیراستخوانی‌شونده، تومور قهوه‌ای)؛ مشخصه‌ی تومور سلول غول‌آسای واقعی «اپی‌فیز + عود» است."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p3q10","session":"p3","full":false,"num":36,"text":"تومور بافت نرم آقای 50 ساله در برش میکروسکوپی دارای ماده زمینه ای فراوان و یک شبکه مویرگی غنی که در ان سلولهای چربی نابالغ به صورت پراکنده و سلولهای ابتدایی تر ستاره ای شکل قرار دارند تشخیص کدام است ؟","opts":["لیپوسارکوم با تمایز خوب","لیپوسارکوم میگزوئید","لیپوسارکوم پلئومورفیک","لیپوم"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[14]}],"answer":1,"explain":"<p><strong>ماتریکس میگزوئید فراوان</strong> (شل و آبی‌رنگ)، <strong>شبکه‌ی مویرگی غنی</strong> (عروق «توری لانه‌ی مرغ» یا <bdi>plexiform</bdi>) و <strong>لیپوبلاست‌های نابالغ</strong> پراکنده در کنار سلول‌های ابتدایی ستاره‌ای، سه جزء تشخیصی <strong>لیپوسارکوم میگزوئید</strong> هستند.</p>\n<ul><li><strong>الف) لیپوسارکوم با تمایز خوب:</strong> از سلول‌های چربی بالغ با آتیپی و سپتاهای ضخیم تشکیل شده و میگزوئید نیست؛ محل شایع آن رتروپریتوئن و تقویت <bdi>MDM2/CDK4</bdi> است.</li><li><strong>ج) لیپوسارکوم پلئومورفیک:</strong> سلول‌های بسیار آتیپیک با لیپوبلاست‌های پلئومورف و درجه‌ی بالا دارد و زمینه‌ی میگزوئید با شبکه‌ی عروقی ظریف مشخصه‌ی آن نیست.</li><li><strong>د) لیپوم:</strong> تومور خوش‌خیم از سلول‌های چربی بالغ با هسته‌ی کوچک کناری است و لیپوبلاست ندارد.</li></ul>","flag":"","lesson":"<ul><li>لیپوم شایع‌ترین تومور بافت نرم است: توده‌ی زرد کپسول‌دار، سلول‌های چربی بالغ با هسته‌ی کوچک کناری.</li><li>لیپوسارکوم میگزوئید: <strong>لیپوبلاست</strong> (واکوئل سیتوپلاسمی + هسته‌ی بزرگ‌تر) + <strong>عروق شبکه‌ی مرغی</strong> + <strong>استرومای میگزوئید</strong>.</li><li>ژنتیک: <strong><bdi>t</bdi>(12;16)(<bdi>q13</bdi>;<bdi>p11</bdi>)</strong> (ژن‌های <bdi>CHOP/TLS</bdi> یا <bdi>FUS-DDIT3</bdi>).</li><li>محل شایع: اندام تحتانی (ران) و رتروپریتوئن (تومور حجیم).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>لیپوبلاست یعنی بدخیمی چربی‌ساز؛ سلول چربی بالغ بدون آتیپی یعنی لیپوم.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی تومورهای استخوان و بافت نرم (دکتر پناهی)، بخش لیپوم و لیپوسارکوم</p>","steps":"<p>کلیدواژه‌ها: «ماده‌ی زمینه‌ای فراوان» (میگزوئید)، «شبکه‌ی مویرگی غنی» و «سلول چربی نابالغ».</p>\n<p>لیپوم و لیپوسارکوم با تمایز خوب از سلول چربی بالغ ساخته شده‌اند و پلئومورفیک آتیپی شدید دارد.</p>\n<p>سه‌گانه‌ی میگزوئید + عروق شبکه‌ای + لیپوبلاست = لیپوسارکوم میگزوئید.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>لیپوبلاست یعنی بدخیمی چربی‌ساز؛ سلول چربی بالغ بدون آتیپی یعنی لیپوم."],"dupOf":null,"dupNote":"","xrefs":["f01"]},{"id":"p3q11","session":"p3","full":false,"num":37,"text":"کدام یک از تومورهای بافت نرم زیر جهش در ژن (<bdi>CTNNB1</bdi>)بتاکاتنین را نشان می دهد ؟","opts":["فاشئیت ندولر","فیبروماتوزیس عمقی","لیومیوم","فیبروماتوزیس سطحی"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[15]}],"answer":1,"explain":"<p><strong>فیبروماتوزیس عمقی (دسموئید)</strong> با جهش <strong><bdi>CTNNB1</bdi> (بتاکاتنین)</strong> (یا جهش <bdi>APC</bdi>) همراه است و در ایمونوهیستوشیمی بتاکاتنین <strong>هسته‌ای</strong> مثبت می‌شود؛ تشخیص بر همین اساس تأیید می‌شود.</p>\n<ul><li><strong>الف) فاشئیت ندولر:</strong> تکثیر خوش‌خیم خودمحدودشونده‌ی فیبروبلاست/میوفیبروبلاست است و ژن اختصاصی آن بازآرایی <strong><bdi>USP6</bdi></strong> (نه <bdi>CTNNB1</bdi>) است.</li><li><strong>ج) لیومیوم:</strong> تومور خوش‌خیم عضله‌ی صاف (فاسیکل‌های دوکی یکنواخت) است و با جهش <bdi>CTNNB1</bdi> مشخص نمی‌شود.</li><li><strong>د) فیبروماتوزیس سطحی:</strong> در کف دست و پا و آلت (<bdi>palmar</bdi>، <bdi>plantar</bdi>، <bdi>penile</bdi>) دیده می‌شود و تشخیص آن بالینی است؛ آزمون ژنتیکی شاخص ندارد.</li></ul>","flag":"","lesson":"<ul><li>فیبروماتوزیس دو نوع دارد: <strong>سطحی</strong> (کف دست/پا، جمع شدن انگشتان) و <strong>عمقی (دسموئید)</strong> (بیشتر داخل شکم).</li><li>دسموئید بدخیم نیست ولی <strong>موضعاً مهاجم</strong> است (رشد نفوذی): انسداد روده، فشار روی حالب و هیدرونفروز، پس از جراحی عود می‌کند.</li><li>ایمونوهیستوشیمی: <strong>بتاکاتنین هسته‌ای</strong>؛ همتای بدخیم فیبروماتوزیس، فیبروسارکوم (الگوی <bdi>herringbone</bdi>) است.</li><li>دسموئید در سندرم گاردنر (پولیپوز <bdi>FAP</bdi> با جهش <bdi>APC</bdi>) هم دیده می‌شود.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دسموئید «بدخیم» نیست و متاستاز نمی‌دهد، ولی رفتار مهاجم و عود دارد؛ فاشئیت ندولر را با سارکوم اشتباه نگیرید.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی تومورهای استخوان و بافت نرم (دکتر پناهی)، بخش فیبروماتوزیس؛ جهش‌های سایر تومورها: <bdi>Robbins</bdi> (در جزوه نبود)</p>","steps":"<p>ژن <bdi>CTNNB1</bdi> همان بتاکاتنین است و بتاکاتنین هسته‌ای را با فیبروماتوزیس به خاطر بسپار.</p>\n<p>فیبروماتوزیس سطحی بالینی تشخیص داده می‌شود و فاشئیت ندولر و لیومیوم ژن اختصاصی دیگری دارند یا تومور عضله‌ی صاف‌اند.</p>\n<p>نوع عمقی (دسموئید) با جهش <bdi>CTNNB1</bdi> همراه است.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دسموئید «بدخیم» نیست و متاستاز نمی‌دهد، ولی رفتار مهاجم و عود دارد؛ فاشئیت ندولر را با سارکوم اشتباه نگیرید."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p3q12","session":"p3","full":false,"num":38,"text":"در برش میکروسکوپی تومور بافت نرم ناحیه سر گردن آقای 30 ساله شبکه ای از تیغه های بافت فیبرو سلولهای گرد و یک شکل را از هم جدا کرده اند که شباهت ناکاملی به الوئول ریه ایجاد کرده است . با توجه به تشخیص تمایز این تومور به سمت کدام نوع سلول می باشد ؟","opts":["بافت هیستوسیتی","بافت فیبروز","بافت عضله صاف","بافت عضله مخطط"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[16]}],"answer":3,"explain":"<p>سلول‌های گرد یکنواخت که تیغه‌های فیبروز آن‌ها را از هم جدا کرده و نمای شبیه <strong>آلوئول ریه</strong> می‌دهند، تصویر <strong>رابدومیوسارکوم نوع آلوئولر</strong> است؛ پس تمایز تومور به سمت <strong>عضله‌ی مخطط</strong> (اسکلتی) است.</p>\n<ul><li><strong>الف) بافت هیستوسیتی:</strong> تومورهای فیبروهیستیوسیتیک (مثل فیبروهیستیوسیتوم) نمای آلوئولی ندارند.</li><li><strong>ب) بافت فیبروز:</strong> فیبروسارکوم از فاسیکل‌های دوکی با نمای استخوان ماهی (<bdi>herringbone</bdi>) تشکیل شده است.</li><li><strong>ج) عضله‌ی صاف:</strong> لیومیوسارکوم از فاسیکل‌های دوکی با هسته‌های پلئومورف ساخته شده و الگوی آلوئولی ندارد.</li></ul>","flag":"","lesson":"<ul><li>رابدومیوسارکوم: همتای بدخیم رابدومیوم (تومور عضله‌ی مخطط)؛ سه نوع <strong>امبریونال، آلوئولر، پلئومورفیک</strong> که نام آن‌ها از شکل میکروسکوپی گرفته شده است.</li><li>نوع آلوئولر: سلول‌های گرد با تیغه‌های فیبروز و نمای «آلوئول ریه»؛ ژنتیک: <strong><bdi>t</bdi>(2;13)(<bdi>q35</bdi>;<bdi>q14</bdi>) = <bdi>PAX3-FKHR</bdi></strong> (یا <bdi>t</bdi>(1;13) = <bdi>PAX7-FKHR</bdi>).</li><li>در سلول‌ها هسته‌ی کناری و سیتوپلاسم ائوزینوفیلی دیده می‌شود؛ تشخیص آن مهم است چون درمانش با سایر سارکوم‌ها فرق دارد.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>«آلوئول ریه» فقط نام شکل است؛ تومور نه از ریه است و نه اپیتلیال، بلکه از عضله‌ی مخطط است.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی تومورهای استخوان و بافت نرم (دکتر پناهی)، بخش تومورهای عضله‌ی مخطط</p>","steps":"<p>نمای «شبیه الوئول ریه» با سلول‌های گرد و تیغه‌های فیبروز یعنی رابدومیوسارکوم آلوئولر.</p>\n<p>پیشوند «رابدو» یعنی عضله‌ی مخطط، نه عضله‌ی صاف (لیومیو) و نه فیبروز یا هیستیوسیت.</p>\n<p>پس تمایز تومور به سمت عضله‌ی مخطط است.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>«آلوئول ریه» فقط نام شکل است؛ تومور نه از ریه است و نه اپیتلیال، بلکه از عضله‌ی مخطط است."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p3q13","session":"p3","full":false,"num":39,"text":"کدامیک از انواع استئونکروز معمولا علامتدار شده و منجر به استئوآرتریت می‌شود؟","opts":["انفارکتوس مدولاری","انفارکتوس کورتکس","انفارکتوس ساب کندرال","انفارکتوس ساب پریوستال"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[14]},{"name":"تلفیقی 96A","nums":[8]}],"answer":2,"explain":"<p>در استئونکروز (نکروز آواسکولار) <strong>انفارکتوس‌های ساب‌کندرال</strong> با درد هنگام فعالیت تظاهر می‌کنند؛ استخوان نکروتیک به‌دلیل جایگزینی بسیار کند فرومی‌ریزد، غضروف مفصلی تغییر شکل می‌دهد و در نهایت <strong>بیماری دژنراتیو شدید مفصل (استئوآرتریت)</strong> ایجاد می‌شود.</p>\n<ul><li><strong>الف) انفارکتوس مدولاری:</strong> معمولاً بدون علامت است، مگر وقتی وسیع باشد (مثل بیماری گوشه و کم‌خونی داسی‌شکل)؛ مفصل را درگیر نمی‌کند.</li><li><strong>ب) انفارکتوس کورتکس:</strong> در استئونکروز قشر معمولاً درگیر نمی‌شود، و الگوی آسیب بیشتر مدولاری و ساب‌کندرال است.</li><li><strong>د) انفارکتوس ساب‌پریوستال:</strong> الگوی شناخته‌شده‌ای که منجر به استئوآرتریت شود نیست و در جزوه جزو الگوهای علامت‌دار مفصلی نیامده است.</li></ul>","flag":"","lesson":"<ul><li>علل استئونکروز: تروما/شکستگی، <strong>کورتیکواستروئید</strong>، ترومبوز/آمبولی، <strong>بیماری کیسون</strong>، داسی‌شکل، گوشه، الکل، پانکراتیت، پرتودرمانی، بیس‌فسفونات (استخوان فک).</li><li>محل کلاسیک ساب‌کندرال: <strong>سر فمور</strong>؛ انفارکت گوه‌ای با فضای جداشدگی بین غضروف و استخوان (نمای کلاپس).</li><li>میکروسکوپی: استخوان مرده با صابون کلسیمی؛ جایگزینی خزنده (<bdi>creeping substitution</bdi>) که در انفارکت ساب‌کندرال بسیار کند است.</li><li>بیشتر موارد پس از شکستگی یا مصرف کورتیکواستروئید رخ می‌دهند.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>انفارکت مدولاری معمولاً بی‌علامت است و ساب‌کندرال علامت‌دار؛ این دو را جابه‌جا نکنید.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل بخش اول و دوم (دکتر پناهی)، بخش استئونکروز</p>","steps":"<p>کلیدواژه‌ها: «علامت‌دار» و «منجر به استئوآرتریت».</p>\n<p>انفارکتوس مدولاری معمولاً بدون علامت است و قشر معمولاً درگیر نمی‌شود.</p>\n<p>انفارکت ساب‌کندرال (مثلاً سر فمور) فرومی‌ریزد و بیماری دژنراتیو مفصل می‌دهد.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>انفارکت مدولاری معمولاً بی‌علامت است و ساب‌کندرال علامت‌دار؛ این دو را جابه‌جا نکنید."],"dupOf":null,"dupNote":"","xrefs":["f13"]},{"id":"p3q14","session":"p3","full":false,"num":40,"text":"در سندروم <bdi>Ollier</bdi> کدامیک از ضایعات زیر به طور متعدد وجود دارد؟","opts":["انکندروما","فیبروز دیسپلازی","استئوکندروما","استئوما"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی پاییز ۱۴۰۰","nums":[10]},{"name":"تلفیقی بهار ۱۴۰۰","nums":[18]},{"name":"تلفیقی 96A","nums":[9]}],"answer":0,"explain":"<p><strong>بیماری <bdi>Ollier</bdi></strong> یعنی <strong>انکندروماهای متعدد</strong> (کندروماهای داخل مدولا) که ترجیحاً یک سمت بدن را درگیر می‌کنند و بیشتر استخوان‌های لوله‌ای کوتاه را می‌گیرند.</p>\n<ul><li><strong>ب) فیبروز دیسپلازی:</strong> حالت پلی‌استوتیک آن با سندرم‌های مک‌کیون-آلبرایت و مازابرو همراه است، نه اولیر.</li><li><strong>ج) استئوکندروما:</strong> حالت متعدد ارثی آن «اگزوستوز ارثی متعدد» با جهش <bdi>EXT1/EXT2</bdi> است و بیماری جداگانه‌ای است.</li><li><strong>د) استئوما:</strong> استئوم‌های متعدد در سندرم گاردنر دیده می‌شوند، نه اولیر.</li></ul>","flag":"","lesson":"<ul><li>کندروما (انکندروما): تومور خوش‌خیم غضروف‌ساز در استخوان‌های کوچک دست و پا، معمولاً یافته‌ی اتفاقی؛ رادیوگرافی: ضایعه‌ی مرزدار و دانه‌دانه.</li><li><strong><bdi>Ollier</bdi></strong> = کندروماهای متعدد؛ <strong><bdi>Maffucci</bdi></strong> = کندروماهای متعدد + <strong>همانژیوم</strong> بافت نرم.</li><li>پاتوژنز: جهش‌های هتروزیگوت <strong><bdi>IDH1/IDH2</bdi></strong>؛ تبدیل بدخیم نادر (به کندروسارکوم).</li><li>کندروسارکوم: ۴۰ سال به بالا، لگن/شانه/دنده‌ها؛ ماکروسکوپی شفاف و آبی‌خاکستری؛ تمایز = گرید و تعیین‌کننده‌ی پیش‌آگهی.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span><bdi>Ollier</bdi> ← «انکندروما» و <bdi>Maffucci</bdi> ← «انکندروما + همانژیوم»؛ استئوکندروماهای متعدد مربوط به اگزوستوز ارثی است.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل بخش اول و دوم (دکتر پناهی)، بخش کندروما (بیماری اولیر)</p>","steps":"<p><bdi>Ollier</bdi> یعنی بیماری کندروماهای متعدد (همراهی با همانژیوم = <bdi>Maffucci</bdi>).</p>\n<p>کندروما همان انکندروما است.</p>\n<p>استئوکندروماهای متعدد به اگزوستوز ارثی و فیبروز دیسپلازی چنداستخوانی به مک‌کیون-آلبرایت مربوط است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span><bdi>Ollier</bdi> ← «انکندروما» و <bdi>Maffucci</bdi> ← «انکندروما + همانژیوم»؛ استئوکندروماهای متعدد مربوط به اگزوستوز ارثی است."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p3q15","session":"p3","full":false,"num":41,"text":"در رادیوگرافی کودک 5 ساله‌ای که پس از افتادن و با هدف بررسی آسیب استخوانی انجام شده است ضایعه‌ای استئولیتیک در دیستال فمور به چشم می‌خورد. بررسی میکروسکوپی ضایعه پس از جراحی نمایانگر تومور فیبروبلاستی با نمای گردبادی و با تجمعات ماکروفاژی می‌باشد. سلول‌های آتیپیک ندارد. کدام تشخیص محتمل‌تر است؟","opts":["<bdi>Non ossifying fibroma</bdi> (فیبروم غیراستخوانی)","<bdi>Fibrous dysplasia</bdi> (دیسپلازی فیبرو)","کیست آنوریسمی استخوان","استئوبلاستوما"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[20]},{"name":"تلفیقی 96A","nums":[12]}],"answer":0,"explain":"<p>کودک، ضایعه‌ی <strong>لیتیک متافیزی دیستال فمور</strong>، <strong>یافته‌ی اتفاقی</strong>، فیبروبلاست‌های <strong>گردبادی (<bdi>storiform</bdi>)</strong> با ماکروفاژ/سلول غول‌آسا و <strong>بدون آتیپی</strong> یعنی <strong><bdi>Non-ossifying fibroma</bdi> (نقص فیبروزی کورتکس)</strong>؛ ضایعه‌ای رشدی و غیرنئوپلاستیک.</p>\n<ul><li><strong>ب) <bdi>Fibrous dysplasia</bdi>:</strong> تیغه‌های استخوانی نازک و خمیده («حروف چینی») در زمینه‌ی فیبروز دارد (جهش <bdi>GNAS</bdi>)، نه نمای گردبادی با ماکروفاژ.</li><li><strong>ج) کیست آنوریسمی استخوان:</strong> فضاهای پر از خون با سپتای فیبروز و استخوان واکنشی است، نه تومور فیبروبلاستی پرسلول با ماکروفاژ.</li><li><strong>د) استئوبلاستوما:</strong> معمولاً در ستون مهره (زوائد عرضی و خاری) با نمای شبیه استئوئید استئوما دیده می‌شود، نه دیستال فمور.</li></ul>","flag":"","lesson":"<ul><li>نقص فیبروزی کورتکس (فیبروم غیراستخوانی‌شونده): ۳۰ تا ۵۰ درصد کودکان بالای ۲ سال؛ معمولاً کوچک‌تر از ۰٫۵ سانتی‌متر در <strong>متافیز فمور دیستال/تیبیای پروگزیمال</strong>؛ ۵۰ درصد دوطرفه یا متعدد.</li><li>بالین: بی‌علامت و <strong>یافته‌ی اتفاقی</strong>؛ بیشتر موارد <strong>خودبه‌خود</strong> تمایز می‌یابند و ناپدید می‌شوند (ضایعه‌ی بزرگ‌تر از ۵ تا ۶ سانتی‌متر را فیبروم غیراستخوانی‌شونده می‌نامند).</li><li>میکروسکوپی: <strong>فاسیکل‌های سلول دوکی (فیبروبلاست)</strong> با سلول غول‌آسا و ماکروفاژ، بسیار پرسلول ولی بدون آتیپی.</li><li>نام: چون فیبروز و سلول غول‌آسا دارد ولی استئوئید و تیغه‌ی استخوانی ندارد.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>پرسلولاریته‌ی بالا ترساننده است، ولی در کودک با ضایعه‌ی کوچک متافیزی و بدون آتیپی، تشخیص <bdi>NOF</bdi> است نه سارکوم.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی تومورهای استخوان و بافت نرم (دکتر پناهی)، بخش نقص فیبروزی کورتکس / فیبروم غیراستخوانی‌شونده</p>","steps":"<p>کلیدواژه‌ها: کودک، دیستال فمور، فیبروبلاست گردبادی، ماکروفاژ و بدون آتیپی.</p>\n<p>کیست آنوریسمی خونی و سپتادار است، استئوبلاستوما مهره‌ای است و فیبروز دیسپلازی تیغه‌های خمیده‌ی استخوانی دارد.</p>\n<p>باقی می‌ماند فیبروم غیراستخوانی‌شونده.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>پرسلولاریته‌ی بالا ترساننده است، ولی در کودک با ضایعه‌ی کوچک متافیزی و بدون آتیپی، تشخیص <bdi>NOF</bdi> است نه سارکوم."],"dupOf":null,"dupNote":"","xrefs":["f18","p3q21"]},{"id":"p3q16","session":"p3","full":false,"num":42,"text":"شایع‌ترین ارگانیسم مسئول در استئومیلیت کدام است؟","opts":["<bdi>E.Coli</bdi>","<bdi>Staph aureus</bdi>","<bdi>tuberculosis</bdi>","<bdi>Pneumococcus</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی پاییز ۱۴۰۰","nums":[16]},{"name":"تلفیقی بهار ۱۴۰۰","nums":[12]},{"name":"تلفیقی 96A","nums":[13]}],"answer":1,"explain":"<p><strong><bdi>Staphylococcus aureus</bdi></strong> سردسته‌ی میکروارگانیسم‌های استئومیلیت (بیشتر موارد هماتوژن در کودکان و پس از شکستگی/جراحی در بزرگسالان) است.</p>\n<ul><li><strong>الف) <bdi>E. coli</bdi>:</strong> در استئومیلیت گرم‌منفی‌ها (<bdi>E. coli</bdi>، <bdi>Pseudomonas</bdi>، <bdi>Klebsiella</bdi>) در مصرف‌کنندگان داروی تزریقی و عفونت ادراری مطرح‌اند، ولی شایع‌ترین عامل نیستند.</li><li><strong>ج) <bdi>tuberculosis</bdi>:</strong> نام بیماری است (عامل آن مایکوباکتریوم است) و استئومیلیت سلی (بیماری پات) نوع نسبتاً نادر و «سرد» و گرانولوماتو است.</li><li><strong>د) <bdi>Pneumococcus</bdi>:</strong> عامل شایعی در استئومیلیت نیست.</li></ul>","flag":"","lesson":"<ul><li>راه‌های ورود: <strong>خونی</strong> (بیشتر در کودکان)، <strong>شکستگی باز/جراحی</strong>، <strong>مستقیم</strong> (مثلاً پای دیابتی).</li><li>عامل بر اساس زمینه: <strong>داسی‌شکل ← <bdi>Salmonella</bdi></strong>؛ <strong>تزریق‌کننده‌ی دارو ← <bdi>Pseudomonas</bdi> و گرم‌منفی‌ها</strong>؛ نوزاد ← <bdi>H. influenzae</bdi> و استرپتوکوک گروه <bdi>B</bdi>؛ شکستگی باز ← بی‌هوازی/مختلط.</li><li>مزمن‌شدن: <strong><bdi>sequestrum</bdi></strong> (استخوان مرده) و <strong><bdi>involucrum</bdi></strong> (استخوان تازه‌ی اطراف)؛ ۵ تا ۲۵ درصد موارد مزمن می‌شوند.</li><li>استئومیلیت سلی: گرانولوم؛ درگیری مهره = <strong>بیماری پات</strong> (آبسه‌ی سوآس، کلاپس مهره).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>بدون زمینه‌ی خاص، پاسخ استاف اورئوس است؛ فقط با زمینه (داسی‌شکل، اعتیاد تزریقی، نوزاد) عامل عوض می‌شود.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل بخش اول و دوم (دکتر پناهی)، بخش استئومیلیت</p>","steps":"<p>شایع‌ترین عامل استئومیلیت بدون ذکر زمینه‌ی ویژه <bdi>Staph aureus</bdi> است.</p>\n<p><bdi>E. coli</bdi> فقط در عفونت ادراری و مصرف تزریقی و <bdi>Pneumococcus</bdi> شایع نیست.</p>\n<p><bdi>tuberculosis</bdi> اسم بیماری است و استئومیلیت سلی نوع سرد و کم‌شایع‌تر است.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>بدون زمینه‌ی خاص، پاسخ استاف اورئوس است؛ فقط با زمینه (داسی‌شکل، اعتیاد تزریقی، نوزاد) عامل عوض می‌شود."],"dupOf":null,"dupNote":"","xrefs":["f03","p3q04"]},{"id":"p3q17","session":"p3","full":false,"num":43,"text":"در کدامیک از بیماری‌های زیر حجم استخوان افزایش می‌یابد؟","opts":["ریکتز","آکندروپلازی","پاژه","استئوژنز ایمپرفکتا"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی پاییز ۱۴۰۰","nums":[13]},{"name":"تلفیقی بهار ۱۴۰۰","nums":[13]},{"name":"تلفیقی 96A","nums":[14]}],"answer":2,"explain":"<p>در <strong>بیماری پاژه (<bdi>osteitis deformans</bdi>)</strong> فعالیت بیش‌ازحد استئوکلاست و سپس استئوبلاست باعث ساخت استخوان زیاد، ضخیم و متراکم (ولی نامنظم و ضعیف) می‌شود؛ بنابراین حجم/توده‌ی استخوان افزایش می‌یابد.</p>\n<ul><li><strong>الف) ریکتز:</strong> اختلال مینرالیزاسیون صفحه‌ی رشد در کمبود ویتامین <bdi>D</bdi> است؛ استخوان نرم می‌شود و تجمع اوستئوئید کم‌مینرال دارد، نه افزایش توده‌ی استخوان.</li><li><strong>ب) آکندروپلازی:</strong> کوتولگی ناشی از کاهش تکثیر کندروسیت صفحه‌ی رشد (جهش <bdi>FGFR3</bdi>) است و استخوان‌ها کوتاه می‌مانند.</li><li><strong>د) استئوژنزیس ایمپرفکتا:</strong> نقص کلاژن تیپ ۱ است و استخوان بسیار کم و شکننده می‌شود.</li></ul>","flag":"","lesson":"<ul><li>پاژه: سه مرحله‌ی <strong>لیتیک ← مختلط ← اسکلروتیک</strong>؛ استخوان «جیگساو/موزاییکی» با <strong>خطوط سیمانی</strong> نامنظم.</li><li>تظاهرات: درد (میکروفراکچر)، کیفوز و ضعف عضلانی، تنگی سوراخ‌های عصبی (گیرافتادگی عصب، ناشنوایی)، رادیوگرافی: قشر ضخیم؛ <bdi>ALP</bdi> بالا و اسکن استخوان با جذب زیاد.</li><li>عوارض: شکستگی و <strong>استئوسارکوم ثانویه</strong> (بالای ۴۰ سال؛ در فمور، هومروس، لگن).</li><li>استئوپتروزیس (نقص تحلیل استخوان) هم توده‌ی استخوان را زیاد می‌کند، ولی در گزینه‌ها نیامده؛ ریکتز، <bdi>OI</bdi> و استئوپروز توده‌ی استخوان را زیاد نمی‌کنند.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>استخوان پاژه «متراکم» ولی «بی‌فایده و ضعیف» است؛ افزایش حجم به معنای افزایش استحکام نیست.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل بخش اول و دوم (دکتر پناهی)، بخش بیماری پاژه</p>","steps":"<p>حجم استخوان زیاد می‌شود یعنی استخوان متراکم و ضخیم می‌شود.</p>\n<p>ریکتز (نقص مینرالیزاسیون)، آکندروپلازی (کوتولگی) و <bdi>OI</bdi> (استخوان شکننده و کم) حجم را زیاد نمی‌کنند.</p>\n<p>بیماری پاژه با استخوان متراکم و موزاییکی این ویژگی را دارد.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>استخوان پاژه «متراکم» ولی «بی‌فایده و ضعیف» است؛ افزایش حجم به معنای افزایش استحکام نیست."],"dupOf":null,"dupNote":"","xrefs":["f02","f04"]},{"id":"p3q18","session":"p3","full":false,"num":44,"text":"خانم 22 ساله به توده پایه‌دار دو سانتی‌متری اپی‌فیز استخوان فمور مراجعه کرده است که دارای یک کلاهک غضروفی دیده می‌شود بهترین تشخیص کدام است؟","opts":["استئوکندروم","دیسپلازی فیبرو","کندروما","استئوبلاستوما"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی پاییز ۱۴۰۰","nums":[21]},{"name":"تلفیقی بهار ۱۴۰۰","nums":[19]},{"name":"تلفیقی 96A","nums":[15]}],"answer":0,"explain":"<p><strong>توده‌ی پایه‌دار</strong> (زائده‌ی استخوانی) با <strong>کلاهک غضروفی</strong> در استخوان بلند (فمور دیستال)، تصویر <strong>استئوکندروما (اگزوستوز)</strong> است؛ بیشتر در نوجوانی و ابتدای بزرگسالی دیده می‌شود. کلاهک غضروفی زیر خود اندکی استخوانی شده و کانال مدولاری آن با مدولای استخوان اصلی پیوسته است.</p>\n<ul><li><strong>ب) دیسپلازی فیبرو:</strong> ضایعه‌ی داخل‌استخوانی با تیغه‌های استخوانی خمیده در زمینه‌ی فیبروز است و کلاهک غضروفی ندارد.</li><li><strong>ج) کندروما:</strong> تومور داخل‌مدولایی غضروف‌ساز در استخوان‌های کوچک دست و پا است و زائده‌ی پایه‌دار نمی‌سازد.</li><li><strong>د) استئوبلاستوما:</strong> تومور استخوان‌ساز مهره (زوائد عرضی و خاری) با نمای شبیه استئوئید استئوما است و کلاهک غضروفی ندارد.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی ذکر «اپی‌فیز» در صورت سؤال دقیق نیست، چون استئوکندروم در متافیز (نزدیک صفحه‌ی رشد) قرار دارد؛ با توجه به «توده‌ی پایه‌دار با کلاهک غضروفی» که مشخصه‌ی آن است، گزینه‌ی الف انتخاب شد.","lesson":"<ul><li>استئوکندروما شایع‌ترین تومور خوش‌خیم استخوان است: <strong>متافیز</strong> استخوان‌های بلند (اطراف زانو)، ۱۰ تا ۳۰ سال، منفرد یا متعدد ارثی (<strong><bdi>EXT1/EXT2</bdi></strong>، اگزوستوز ارثی).</li><li>نشانه: زائده‌ی شاخ‌مانند با <strong>کلاهک غضروفی</strong>؛ <strong>ارتباط مدولاری</strong> با استخوان اصلی در رادیوگرافی.</li><li>خطر تبدیل به <strong>کندروسارکوم</strong>: کلاهک غضروفی <strong>بزرگ‌تر از ۳ سانتی‌متر</strong>، حالت متعدد/سندرمی.</li><li>کندروما ← استخوان‌های کوچک دست/پا؛ کندروسارکوم ← میانسال، لگن و شانه.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>کلاهک بیش از ۳ سانتی‌متر یا درد و رشد در بزرگسال یعنی احتمال کندروسارکوم؛ کلاهک غضروفی به‌خودی‌خود ایجاد نگرانی نمی‌کند.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل بخش اول و دوم (دکتر پناهی)، بخش استئوکندروما</p>","steps":"<p>کلیدواژه‌ها: «توده‌ی پایه‌دار» و «کلاهک غضروفی».</p>\n<p>این ترکیب مخصوص استئوکندروما است.</p>\n<p>دیسپلازی فیبرو و استئوبلاستوما کلاهک غضروفی ندارند و کندروما در استخوان‌های کوچک دست و پا و داخل مدولا است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>کلاهک بیش از ۳ سانتی‌متر یا درد و رشد در بزرگسال یعنی احتمال کندروسارکوم؛ کلاهک غضروفی به‌خودی‌خود ایجاد نگرانی نمی‌کند."],"dupOf":null,"dupNote":"","xrefs":["f11"]},{"id":"p3q19","session":"p3","full":false,"num":45,"text":"کدامیک از اختلالات مادرزادی زیر دیسپلازی می‌باشد؟","opts":["آکندروپلازی","آپلازی انگشت","فیوژن غیرطبیعی استخوان‌های جمجمه","انگشت اضافه"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[8]},{"name":"تلفیقی 96A","nums":[17]}],"answer":0,"explain":"<p><strong>دیسپلازی</strong> یعنی اختلال سراسری در تشکیل، رشد یا نگهداری ماتریکس استخوان یا غضروف (به‌دلیل جهش ژن‌هایی که تکامل کل اسکلت را کنترل می‌کنند)؛ <strong>آکندروپلازی</strong> (جهش <bdi>FGFR3</bdi> در صفحه‌ی رشد) نمونه‌ی کلاسیک آن است.</p>\n<ul><li><strong>ب) آپلازی انگشت:</strong> نبود یک استخوان یا انگشت، یک نقص موضعی و <strong>دیس‌استوز</strong> است.</li><li><strong>ج) فیوژن غیرطبیعی استخوان‌های جمجمه:</strong> بسته شدن زودرس درزها (<bdi>craniosynostosis</bdi>) از دیس‌استوزها است.</li><li><strong>د) انگشت اضافه:</strong> <bdi>polydactyly</bdi> نیز دیس‌استوز است و مشکل موضعی مهاجرت و تراکم مزانشیم دارد.</li></ul>","flag":"","lesson":"<ul><li><strong>دیس‌استوز (<bdi>dysostosis</bdi>):</strong> نقص موضعی در مهاجرت و تراکم مزانشیم؛ نمونه‌ها: <bdi>aplasia</bdi>، انگشت اضافه (<bdi>polydactyly</bdi>)، <bdi>syndactyly</bdi>، <bdi>craniosynostosis</bdi>؛ علت: جهش ژن‌های هومئوباکس و فاکتورهای رونویسی.</li><li><strong>دیسپلازی (<bdi>dysplasia</bdi>):</strong> درگیری سراسری و منتشر استخوان/غضروف؛ شامل <bdi>chondrodysplasia</bdi> و <bdi>osteodysplasia</bdi>؛ مثال‌ها: آکندروپلازی، دیسپلازی تاناتوفوریک، <bdi>OI</bdi>.</li><li>دیسپلازی استخوانی یعنی الگوی رشد غیرطبیعی، نه حالت پیش‌بدخیم.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>گروه</th><th>ماهیت</th><th>نمونه</th></tr></thead><tbody><tr><td>دیس‌استوز</td><td>موضعی</td><td>انگشت اضافه، آپلازی، فیوژن جمجمه</td></tr><tr><td>دیسپلازی</td><td>منتشر</td><td>آکندروپلازی</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>اسم «دیسپلازی» در استخوان به معنای پیش‌بدخیمی نیست (<bdi>misnomer</bdi>)؛ و به‌خاطر شباهت اسمی، دیس‌استوز را با دیسپلازی قاطی نکنید.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل بخش اول و دوم (دکتر پناهی)، بخش اختلالات تکوینی (دیس‌استوز و دیسپلازی)</p>","steps":"<p>دیسپلازی یعنی اختلال منتشر غضروف و استخوان در سراسر اسکلت.</p>\n<p>آپلازی انگشت، انگشت اضافه و فیوژن زودرس جمجمه نقص‌های موضعی (دیس‌استوز) هستند.</p>\n<p>آکندروپلازی نمونه‌ی دیسپلازی است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>اسم «دیسپلازی» در استخوان به معنای پیش‌بدخیمی نیست (<bdi>misnomer</bdi>)؛ و به‌خاطر شباهت اسمی، دیس‌استوز را با دیسپلازی قاطی نکنید."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p3q20","session":"p3","full":false,"num":46,"text":"موتاسیون در کدام ژن عامل ایجاد آکندروپلازی است؟","opts":["<bdi>Carbonic anhydrase 2 gene</bdi>","<bdi>Collagen type I</bdi>","<bdi>FGFR3</bdi>","<bdi>TCIRG1 gene</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی پاییز ۱۴۰۰","nums":[6]}],"answer":2,"explain":"<p>آکندروپلازی ناشی از <strong>جهش فعال‌کننده (<bdi>gain-of-function</bdi>)</strong> در ژن گیرنده‌ی فاکتور رشد فیبروبلاست ۳ (<strong><bdi>FGFR3</bdi></strong>) روی کروموزوم 4<bdi>p</bdi> است؛ فعالیت دائمی گیرنده تکثیر کندروسیت صفحه‌ی رشد را مهار می‌کند.</p>\n<ul><li><strong>الف) <bdi>Carbonic anhydrase 2</bdi>:</strong> نقص آن (شایع‌ترین علت) باعث <strong>استئوپتروزیس</strong> می‌شود، چون حفره‌ی تحلیل اسیدی نمی‌شود.</li><li><strong>ب) <bdi>Collagen type I</bdi>:</strong> نقص آن علت <strong>استئوژنزیس ایمپرفکتا</strong> (بیماری استخوان شکننده) است.</li><li><strong>د) <bdi>TCIRG1</bdi>:</strong> پمپ پروتون استئوکلاست را کد می‌کند و نقص آن از علل <strong>استئوپتروزیس</strong> است.</li></ul>","flag":"","lesson":"<ul><li>آکندروپلازی: شایع‌ترین دیسپلازی اسکلتی و کوتولگی (حدود ۷۰ درصد)؛ <strong>اتوزومال غالب</strong>، حدود ۹۰ درصد جهش جدید (آلل پدری)؛ هوش و طول عمر طبیعی.</li><li>جهش شایع: جایگزینی <strong>گلیسین با آرژنین</strong> در دمین ترانس‌ممبران <bdi>FGFR3</bdi>؛ تقریباً همه‌ی جهش‌های جدید روی آلل پدری رخ می‌دهند و هموزیگوت‌ها به‌دلیل نارسایی تنفسی معمولاً زنده نمی‌مانند.</li><li>فنوتیپ: کوتاهی نامتناسب اندام‌های پروگزیمال، سر بزرگ با پیشانی برجسته و ریشه‌ی بینی فرورفته؛ تنه تقریباً طبیعی.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>بیماری</th><th>ژن/نقص</th></tr></thead><tbody><tr><td>آکندروپلازی</td><td><bdi>FGFR3</bdi> (فعال‌کننده)</td></tr><tr><td>استئوژنزیس ایمپرفکتا</td><td>کلاژن تیپ ۱</td></tr><tr><td>استئوپتروزیس</td><td><bdi>CA2</bdi>، پمپ پروتون (<bdi>TCIRG1</bdi>)، کانال کلرید</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>جهش <bdi>FGFR3</bdi> فعال‌کننده است نه از دست رفتن عملکرد؛ همین فعالیت زیاد رشد استخوان را مهار می‌کند.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل بخش اول و دوم (دکتر پناهی)، بخش آکندروپلازی</p>","steps":"<p>آکندروپلازی یعنی کوتولگی با <bdi>FGFR3</bdi> فعال‌کننده.</p>\n<p><bdi>Collagen I</bdi> مربوط به <bdi>OI</bdi> و <bdi>CA2</bdi> و <bdi>TCIRG1</bdi> مربوط به استئوپتروزیس‌اند.</p>\n<p>پس ژن درست <bdi>FGFR3</bdi> است.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>جهش <bdi>FGFR3</bdi> فعال‌کننده است نه از دست رفتن عملکرد؛ همین فعالیت زیاد رشد استخوان را مهار می‌کند."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p3q21","session":"p3","full":false,"num":47,"text":"در رادیوگرافی کودک 5 ساله‌ای که پس از افتادن و با هدف بررسی آسیب استخوانی انجام شده است ضایعه‌ای استئولیتیک در دیستال فمور به چشم می‌خورد. بررسی میکروسکوپی ضایعه پس از جراحی نمایانگر تومور فیبروبلاستی با نمای گردبادی و با تجمعات ماکروفاژی می‌باشد. سلول‌های آتیپیک ندارد. کدام تشخیص محتملتر است؟","opts":["<bdi>Ossifying fibroma</bdi>","<bdi>Fibrous dysplasia</bdi>","<bdi>Non ossifying fibroma</bdi>","هیچکدام"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی پاییز ۱۴۰۰","nums":[15]}],"answer":2,"explain":"","flag":"","lesson":"","steps":"","traps":[],"dupOf":"p3q15","dupNote":"<p>این سوال تکرار <a class=\"xref\" href=\"#/q/p3q15\">سوال ۴۱</a> است. پاسخ تشریحی و درس‌نامه را زیر همان سوال ببین.</p>","xrefs":["p3q15"]},{"id":"p3q22","session":"p3","full":false,"num":48,"text":"کدام یک از تومورهای زیر درگیری متافیز ندارد؟","opts":["<bdi>Osteosarcoma</bdi>","<bdi>Osteochondroma</bdi>","<bdi>Giant cell tumor of bone</bdi>","<bdi>Aneurysmal bone cyst</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۱","nums":[]}],"answer":2,"explain":"<p>در منبع آزمون فقط صورت این سوال چاپ شده بود و گزینه‌ها نیامده بود؛ گزینه‌ها را برای تمرین خودمان ساخته‌ایم.</p>\n<p>در جزوه، <strong>تومور سلول غول‌آسا (<bdi>GCT</bdi>)</strong> محلش <strong>اپی‌فیز</strong> استخوان‌های بلند اطراف زانو ذکر شده و «اپی‌فیز بودن» از مشخصه‌های بارز آن است؛ در مقابل، سه تومور دیگر کلاسیک در <strong>متافیز</strong> قرار دارند.</p>\n<ul><li><strong>الف) <bdi>Osteosarcoma</bdi>:</strong> ضایعه‌ی متافیزی، بیشتر متافیز فمور دیستال و تیبیای پروگزیمال (اطراف زانو) در سنین ۱۰ تا ۲۰ سال؛ پس متافیز را درگیر می‌کند.</li><li><strong>ب) <bdi>Osteochondroma</bdi>:</strong> زائده‌ی استخوانی با کلاهک غضروفی در متافیز استخوان‌های بلند؛ متافیز را درگیر می‌کند.</li><li><strong>د) <bdi>Aneurysmal bone cyst</bdi>:</strong> ضایعه‌ی کیستیک لیتیک با مرز مشخص در متافیز استخوان‌های بلند (در دو دهه‌ی اول زندگی)؛ متافیز را درگیر می‌کند.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی تومور سلول غول‌آسا در بزرگسالان از اپی‌فیز به سمت متافیز هم گسترش می‌یابد؛ سوال را بر اساس تأکید جزوه (مشخصه‌ی بارز: محل اپی‌فیز) خوانده‌ایم و سه گزینه‌ی دیگر همگی متافیزیِ کلاسیک‌اند.","lesson":"<ul><li><strong>قاعده‌ی محل تومورهای استخوان:</strong> اپی‌فیز (سر استخوان)، متافیز (نزدیک صفحه‌ی رشد) و دیافیز (تنه). بیشتر تومورهای اولیه‌ی استخوان در اطراف زانو و در متافیز دیده می‌شوند، چون رشد استخوان در آنجا بیشتر است.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>تومور</th><th>محل در استخوان</th><th>نکته‌ی شاخص</th></tr></thead><tbody><tr><td>استئوسارکوم</td><td>متافیز (فمور دیستال، تیبیای پروگزیمال)</td><td>سن ۱۰ تا ۲۰؛ مثلث کادمن؛ استئوئید صورتی</td></tr><tr><td>استئوکندروما</td><td>متافیز استخوان‌های بلند</td><td>کلاهک غضروفی؛ شایع‌ترین خوش‌خیم</td></tr><tr><td>کیست آنوریسمال استخوان</td><td>متافیز (و المان‌های خلفی مهره)</td><td>هوا-مایع (<bdi>fluid-air level</bdi>)؛ بازآرایی <bdi>USP6</bdi></td></tr><tr><td>نقص قشری فیبروز</td><td>متافیز فمور دیستال/تیبیای پروگزیمال</td><td>کمتر از نیم سانتی‌متر، اغلب دوطرفه</td></tr><tr><td>تومور سلول غول‌آسا</td><td><strong>اپی‌فیز</strong></td><td>سن ۲۰ تا ۴۰؛ لیتیک و خارج از مرکز؛ عود ۴۰ تا ۶۰ درصد؛ متاستاز ریوی ۴ درصد</td></tr><tr><td>سارکوم یوئینگ</td><td><strong>دیافیز</strong> (در جزوه‌ی استخوان‌ها: دیافیز و متافیز)</td><td>پوست پیازی؛ <bdi>t</bdi>(11;22)</td></tr><tr><td>کندروبلاستوم (<bdi>Robbins</bdi>)</td><td>اپی‌فیز</td><td>نوجوانان</td></tr></tbody></table></div>\n<ul><li>سلول غول‌آسا اختصاصی <bdi>GCT</bdi> نیست (<bdi>ABC</bdi>، نان‌اسیفایینگ فیبروما و تومور قهوه‌ای هم دارند)؛ مشخصه‌ی بارز <bdi>GCT</bdi> <strong>عود و اپی‌فیز بودن</strong> است.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: دیدن «سلول غول‌آسا» و برگزیدن <bdi>GCT</bdi> برای هر ضایعه‌ی متافیزی؛ <bdi>ABC</bdi> هم سلول غول‌آسا دارد ولی متافیزی است. و برعکس: «همه‌ی تومورهای اطراف زانو = متافیز»؛ <bdi>GCT</bdi> اطراف زانو است ولی اپی‌فیزی.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) کدام تومور اپی‌فیز را درگیر می‌کند؟ (۲) محل اصلی سارکوم یوئینگ کجاست (دیافیز)؟ (۳) ضایعه‌ی لیتیک خارج از مرکز در اپی‌فیز زانوی ۳۰ ساله؛ (۴) محل شایع استئوسارکوم؟</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی تومورهای استخوان و بافت نرم و جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش تومور سلول غول‌آسا (اپی‌فیز، اطراف زانو)، کیست آنوریسمال استخوان (متافیز)، استئوسارکوم (متافیز فمور دیستال و تیبیای پروگزیمال)، استئوکندروما (متافیز)، سارکوم یوئینگ (دیافیز). مرجع: <bdi>Robbins</bdi> (در جزوه نبود) برای کندروبلاستوم.</p>","steps":"<p>کلیدواژه‌ی سوال «متافیز ندارد» است؛ باید دنبال تومور غیرمتافیزی بگردی.</p>\n<p>استئوسارکوم (متافیز فمور دیستال و تیبیای پروگزیمال) و استئوکندروما (متافیز استخوان‌های بلند) هر دو متافیزی‌اند.</p>\n<p>کیست آنوریسمال استخوان هم طبق جزوه متافیز استخوان‌های بلند را درگیر می‌کند.</p>\n<p>تومور سلول غول‌آسا مشخصه‌اش «عود و اپی‌فیز بودن» است (اطراف زانو، سن ۲۰ تا ۴۰ سال)، پس گزینه‌ی غیرمتافیزی همین است.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: دیدن «سلول غول‌آسا» و برگزیدن <bdi>GCT</bdi> برای هر ضایعه‌ی متافیزی؛ <bdi>ABC</bdi> هم سلول غول‌آسا دارد ولی متافیزی است. و برعکس: «همه‌ی تومورهای اطراف زانو = متافیز»؛ <bdi>GCT</bdi> اطراف زانو است ولی اپی‌فیزی."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p3q23","session":"p3","full":false,"num":49,"text":"پترن آلوئولار رابدومیوسارکوما چیست؟","opts":["شبکه‌ای از تیغه‌های فیبری که سلول‌های تومور را به خوشه‌ها یا توده‌ها تقسیم می‌کند و شبیه آلوئول‌های ریه است","سلول‌های دوکی در زمینه‌ی میکزوئید شل و کم‌رنگ، همراه با عروق شبکه‌ی مرغی","سلول‌های بسیار بزرگ چندشکل با هسته‌های غول‌آسا و میتوز آتیپیک فراوان","سلول‌های بزرگ و بالغ با سیتوپلاسم فراوان ائوزینوفیلی و هسته‌ی کناری مشابه رابدومیوم"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۱","nums":[]}],"answer":0,"explain":"<p>در منبع آزمون فقط صورت این سوال چاپ شده بود و گزینه‌ها نیامده بود؛ گزینه‌ها را برای تمرین خودمان ساخته‌ایم.</p>\n<p>در جزوه آمده که رابدومیوسارکوم <strong>نوع آلوئولار</strong> «الگوی شبیه ریه» دارد: تومور با <strong>تیغه‌های فیبری (سپتا)</strong> به خوشه‌ها و فضاهای شبیه آلوئول تقسیم می‌شود که سلول‌های گرد کوچک تومور آن‌ها را پوشانده یا پر کرده‌اند. نام «آلوئولار» به همین شباهت بافتی اشاره دارد.</p>\n<ul><li><strong>ب) سلول‌های دوکی در زمینه‌ی میکزوئید با عروق شبکه‌ی مرغی:</strong> عروق شبکه‌ی مرغی نشانه‌ی <strong>لیپوسارکوم میکزوئید</strong> است؛ سلول دوکی در زمینه‌ی شل هم بیشتر یادآور نوع <strong>امبریونال</strong> رابدومیوسارکوم است. در هر حال الگوی آلوئولار (تیغه‌های فیبری و فضاهای شبیه آلوئول) نیست.</li><li><strong>ج) سلول‌های غول‌آسای چندشکل با میتوز آتیپیک فراوان:</strong> این تصویر <strong>سارکوم پلئومورفیک/نوع پلئومورفیک</strong> است (در رابدومیوسارکوم، نوع پلئومورفیک جدا از آلوئولار است).</li><li><strong>د) سلول‌های بزرگ بالغ با سیتوپلاسم فراوان ائوزینوفیلی:</strong> این وصف <strong>رابدومیوم</strong> (همتای خوش‌خیم و بالغ، بیشتر در زبان) است. سلول‌های رابدومیوسارکوم هم سیتوپلاسم ائوزینوفیل و هسته‌ی کناری دارند، ولی این گزینه فقط شکل سلول را می‌گوید، نه «الگوی آلوئولار» (تیغه‌های فیبری و فضاهای شبیه آلوئول) را.</li></ul>","flag":"","lesson":"<ul><li><strong>جفت خوش‌خیم/بدخیم:</strong> رابدومیوم (خوش‌خیم؛ بیشتر زبان؛ سلول‌های بزرگ با سیتوپلاسم ائوزینوفیلی فراوان) ← رابدومیوسارکوم (بدخیم؛ سلول با هسته‌ی کناری و سیتوپلاسم ائوزینوفیل).</li><li>نام سه نوع رابدومیوسارکوم از <strong>شکل</strong> گرفته شده است: <strong>امبریونال، آلوئولار</strong> (شبیه ریه) و <strong>پلئومورفیک</strong>.</li><li>ژنتیک نوع آلوئولار: <strong><bdi>t</bdi>(2;13)(<bdi>q35</bdi>;<bdi>q14</bdi>)</strong> با ژن همجوش <strong><bdi>PAX3-FKHR</bdi></strong> (شایع‌تر) و <strong><bdi>t</bdi>(1;13)(<bdi>p36</bdi>;<bdi>q14</bdi>)</strong> با <strong><bdi>PAX7-FKHR</bdi></strong>.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>نوع</th><th>الگوی بافتی</th><th>نکته‌ها</th></tr></thead><tbody><tr><td>امبریونال</td><td>سلول‌های کوچک و دوکی در زمینه‌ی شل (در <bdi>Robbins</bdi>: نمای <bdi>botryoid</bdi> در حفره‌ها)</td><td>بیشتر کودکان؛ سر و گردن و دستگاه ادراری-تناسلی (<bdi>Robbins</bdi>)</td></tr><tr><td>آلوئولار</td><td>تیغه‌های فیبرو‌واسکولار که سلول‌های گرد را به فضاهای شبیه آلوئول تقسیم می‌کنند</td><td>نوجوانان؛ اندام‌ها؛ <bdi>PAX3/7-FKHR</bdi></td></tr><tr><td>پلئومورفیک</td><td>سلول‌های بسیار بزرگ و چندشکل با هسته‌های غول‌آسا</td><td>بزرگسالان؛ درجه‌ی بالا؛ شبیه سارکوم پلئومورفیک تمایزنیافته</td></tr></tbody></table></div>\n<ul><li>رابدومیوسارکوم از گروه <strong>تومورهای سلول گرد کوچک</strong> است (با سارکوم یوئینگ، لنفوم و تومورهای نوروآندوکرین)؛ برای افتراق ایمونوهیستوشیمی (در <bdi>Robbins</bdi>: <bdi>desmin</bdi>، <bdi>myogenin</bdi>، <bdi>MyoD</bdi>)، سیتوژنتیک و سن/محل لازم است. تشخیص آن مهم است چون <strong>درمانش با بقیه‌ی سارکوم‌ها فرق دارد</strong> (شیمی‌درمانی اختصاصی)، در حالی که درمان بیشتر سارکوم‌ها برداشتن و پرتودرمانی است.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: «آلوئولار» را به «ریه» یا «<bdi>Alveolar soft part sarcoma</bdi>» ربط دادن؛ فقط شباهت الگوی بافتی به آلوئول مراد است. همچنین رابدومیوم (بالغ، خوش‌خیم) را با رابدومیوسارکوم یکی نگیرید.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) کدام نوع رابدومیوسارکوم الگوی شبیه ریه دارد؟ (۲) <bdi>t</bdi>(2;13) با کدام تومور همراه است؟ (۳) ژن همجوش <bdi>PAX3-FKHR</bdi> مربوط به کدام تومور است؟ (۴) کدام تومور سلول گرد کوچک عضله‌ی مخطط است؟</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی تومورهای استخوان و بافت نرم (دکتر پناهی)، بخش تومورهای عضله‌ی مخطط (رابدومیوم و رابدومیوسارکوم: انواع امبریونال، آلوئولار و پلئومورفیک؛ <bdi>t</bdi>(2;13) <bdi>PAX3-FKHR</bdi> و <bdi>t</bdi>(1;13) <bdi>PAX7-FKHR</bdi>). مرجع: <bdi>Robbins</bdi> (در جزوه نبود) برای تیغه‌های فیبروواسکولار، سن و محل هر نوع و نشانگرهای <bdi>desmin/myogenin</bdi>.</p>","steps":"<p>کلیدواژه‌ی سوال «آلوئولار» است؛ در جزوه این نوع رابدومیوسارکوم «الگوی شبیه ریه» دارد.</p>\n<p>الگوی آلوئولار یعنی تیغه‌های فیبری که تومور را به خوشه‌ها و فضاهای شبیه آلوئول تقسیم می‌کنند.</p>\n<p>گزینه‌ی میکزوئید با عروق شبکه‌ی مرغی مربوط به لیپوسارکوم میکزوئید است و گزینه‌ی سلول‌های غول‌آسا مربوط به نوع پلئومورفیک است.</p>\n<p>گزینه‌ی سلول بالغ با سیتوپلاسم ائوزینوفیلی فراوان وصف رابدومیوم (خوش‌خیم) است، نه الگوی آلوئولار.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: «آلوئولار» را به «ریه» یا «<bdi>Alveolar soft part sarcoma</bdi>» ربط دادن؛ فقط شباهت الگوی بافتی به آلوئول مراد است. همچنین رابدومیوم (بالغ، خوش‌خیم) را با رابدومیوسارکوم یکی نگیرید."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p3q24","session":"p3","full":false,"num":50,"text":"ویژگی‌های هیستولوژیک لیپوسارکوم میکسوئید چیست؟","opts":["زمینه‌ی میکزوئید با ماتریکس بازوفیل، شبکه‌ی مویرگی غنی (<bdi>arborizing capillaries</bdi>) و لیپوبلاست‌ها/سلول‌های ابتدایی (<bdi>primitive</bdi>)","سلول‌های چربی بالغ با هسته‌های آتیپیک و باندهای فیبروز","لیپوبلاست‌های بسیار بزرگ و چندشکل با هسته‌های غول‌آسا و میتوز فراوان","سلول‌های چربی بالغ و یکنواخت با هسته‌ی کوچک کناری و بدون آتیپی"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۱","nums":[]}],"answer":0,"explain":"<p>در منبع آزمون فقط صورت این سوال چاپ شده بود و گزینه‌ها نیامده بود؛ گزینه‌ها را برای تمرین خودمان ساخته‌ایم.</p>\n<p>طبق نکته‌ی تأکیدی جزوه، <strong>لیپوسارکوم میکزوئید سه جزء</strong> دارد: <strong>لیپوبلاست</strong>، <strong>عروق شبکه‌ی مرغی (شبکه‌ی مویرگی غنی)</strong> و <strong>استرومای میکزوئید</strong> (شل و کم‌رنگ و آبی‌مایل). گزینه‌ای که این سه را با هم دارد صحیح است.</p>\n<ul><li><strong>ب) سلول‌های چربی بالغ با هسته‌های آتیپیک و باندهای فیبروز:</strong> این تصویر <strong>لیپوسارکوم با تمایز خوب (<bdi>well-differentiated</bdi>)</strong> است، نه نوع میکزوئید.</li><li><strong>ج) لیپوبلاست‌های بسیار بزرگ و چندشکل با میتوز فراوان:</strong> این تصویر <strong>لیپوسارکوم پلئومورفیک</strong> است؛ نوع میکزوئید لیپوبلاست‌های کوچک تا نابالغ و زمینه‌ی میکزوئید دارد.</li><li><strong>د) سلول‌های چربی بالغ و یکنواخت با هسته‌ی کوچک کناری:</strong> این تصویر <strong>لیپوم</strong> (تومور خوش‌خیم) است؛ در لیپوم همه‌ی سلول‌ها شبیه چربی طبیعی‌اند.</li></ul>","flag":"","lesson":"<ul><li><strong>لیپوم:</strong> شایع‌ترین تومور بافت نرم؛ خوش‌خیم؛ توده‌ی زرد کپسول‌دار؛ همه‌ی سلول‌ها شبیه چربی با هسته‌ی کوچک کناری.</li><li><strong>لیپوسارکوم:</strong> همتای بدخیم؛ محل اصلی <strong>رتروپریتوئن</strong> (توده‌ی بزرگ)، گاهی اندام تحتانی.</li><li><strong>لیپوبلاست:</strong> سلولی با واکوئل‌های سیتوپلاسمی که می‌خواهد شبیه سلول چربی شود ولی <strong>هسته‌ی بزرگ‌تر</strong> از لیپوسیت دارد؛ شرط تشخیص لیپوسارکوم است.</li><li><strong>لیپوسارکوم میکزوئید:</strong> لیپوبلاست + <strong>عروق شبکه‌ی مرغی (<bdi>chicken-wire</bdi>)</strong> + <strong>استرومای میکزوئید</strong>؛ ژنتیک <strong><bdi>t</bdi>(12;16)(<bdi>q13</bdi>;<bdi>p11</bdi>)</strong> (<bdi>CHOP/TLS</bdi>، یعنی <bdi>FUS-DDIT3</bdi>).</li></ul>\n<div class=\"tw\"><table><thead><tr><th>نوع</th><th>ریزنما</th><th>ژنتیک / نکته</th></tr></thead><tbody><tr><td>لیپوم</td><td>چربی بالغ یکنواخت</td><td>خوش‌خیم</td></tr><tr><td>لیپوسارکوم با تمایز خوب</td><td>چربی بالغ + هسته‌ی آتیپیک + فیبروز</td><td>آمپلی‌فیکاسیون <bdi>MDM2/CDK4</bdi> (<bdi>Robbins</bdi>)؛ شایع در رتروپریتوئن</td></tr><tr><td>لیپوسارکوم میکزوئید</td><td>لیپوبلاست + زمینه‌ی میکزوئید + عروق شبکه‌ی مرغی</td><td><bdi>t</bdi>(12;16)</td></tr><tr><td>لیپوسارکوم پلئومورفیک</td><td>لیپوبلاست‌های غول‌آسای چندشکل، میتوز زیاد</td><td>درجه‌ی بالا</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: هر تومور چربی با اجزای «آتیپیک» را میکزوئید دانستن؛ نشانه‌ی میکزوئید = زمینه‌ی شل آبی‌مایل + عروق شبکه‌ی مرغی، نه صرفاً آتیپی هسته.</p>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>لیپوسارکومی که پلئومورفیک یا دی‌دیفرانسیه شود شبیه سارکوم تمایزنیافته می‌شود (جزوه)؛ نباید با میکزوئید اشتباه شود.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) سه جزء لیپوسارکوم میکزوئید کدام‌اند؟ (۲) کدام لیپوسارکوم با <bdi>t</bdi>(12;16) همراه است؟ (۳) عروق شبکه‌ی مرغی در کدام تومور؟ (۴) محل اصلی لیپوسارکوم کجاست؟</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی تومورهای استخوان و بافت نرم (دکتر پناهی)، بخش لیپوم و لیپوسارکوم (لیپوسارکوم میکزوئید: لیپوبلاست، عروق شبکه‌ی مرغی، زمینه‌ی میکزوئید؛ <bdi>t</bdi>(12;16) <bdi>CHOP/TLS</bdi>؛ محل اصلی رتروپریتوئن). مرجع: <bdi>Robbins</bdi> (در جزوه نبود) برای <bdi>MDM2/CDK4</bdi> و ریزنمای انواع دیگر.</p>","steps":"<p>کلیدواژه‌ی سوال «لیپوسارکوم میکزوئید» است؛ جزوه سه جزء را تأکید کرده است: لیپوبلاست، عروق شبکه‌ی مرغی و استرومای میکزوئید.</p>\n<p>گزینه‌ای را بردار که هر سه (زمینه‌ی میکزوئید، شبکه‌ی مویرگی غنی و لیپوبلاست/سلول ابتدایی) را با هم دارد.</p>\n<p>چربی بالغ با هسته‌ی آتیپیک و فیبروز، لیپوسارکوم با تمایز خوب است؛ لیپوبلاست‌های غول‌آسا و میتوز فراوان، پلئومورفیک است.</p>\n<p>چربی بالغ یکنواخت با هسته‌ی کناری هم لیپوم (خوش‌خیم) است و ربطی به سلول ابتدایی و زمینه‌ی میکزوئید ندارد.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: هر تومور چربی با اجزای «آتیپیک» را میکزوئید دانستن؛ نشانه‌ی میکزوئید = زمینه‌ی شل آبی‌مایل + عروق شبکه‌ی مرغی، نه صرفاً آتیپی هسته.","<span class=\"tag\">نکته‌ی دام</span>لیپوسارکومی که پلئومورفیک یا دی‌دیفرانسیه شود شبیه سارکوم تمایزنیافته می‌شود (جزوه)؛ نباید با میکزوئید اشتباه شود."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p4q01","session":"p4","full":false,"num":51,"text":"کدامیک از موارد زیر از کرایتریای لازم برای تشخیص گلیوبلاستوما می باشد؟","opts":["نکروز پالیسید","هیپرکرومازی هسته","میتوز چند قطبی","اجسام روزنتال"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[17]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[24]}],"answer":0,"explain":"<p>گلیوبلاستوما همان آستروسیتوم درجه‌ی ۴ است و معیار تشخیصی آن نسبت به آستروسیتوم آناپلاستیک (درجه‌ی ۳) افزوده شدن <strong>نکروز</strong> (اغلب به صورت <strong>پالیسیدینگ</strong>، یعنی ردیف شدن هسته‌ها دور ناحیه‌ی نکروتیک) و/یا <strong>پرولیفراسیون میکروواسکولار</strong> است. پس «نکروز پالیسید» از شرط‌های لازم تشخیص است.</p>\n<ul><li><strong>ب) هیپرکرومازی هسته:</strong> در همه‌ی آستروسیتوم‌ها (از درجه‌ی ۲ به بعد) دیده می‌شود و اختصاصی گلیوبلاستوما نیست؛ معیار تشخیصی محسوب نمی‌شود.</li><li><strong>ج) میتوز چندقطبی:</strong> میتوز آتیپیک در تومورهای بدخیم مختلف دیده می‌شود؛ معیار گلیوبلاستوما «میتوز بسیار زیاد» است، نه نوع خاصی از میتوز.</li><li><strong>د) اجسام روزنتال:</strong> رشته‌های ائوزینوفیلیک مخصوص <strong>آستروسیتوم پیلوسیتیک</strong> (درجه‌ی ۱) هستند و ربطی به گلیوبلاستوما ندارند.</li></ul>","flag":"","lesson":"<ul><li>آستروسیتوم درجه‌ی ۲: سلولاریته‌ی کم، بدون نکروز و میتوز کم.</li><li>آناپلاستیک (درجه‌ی ۳): سلولاریته و پلئومورفیسم بیشتر، میتوز زیاد، شروع پرولیفراسیون عروقی ولی <strong>بدون نکروز</strong>.</li><li>گلیوبلاستوما (درجه‌ی ۴): میتوز بسیار زیاد + <strong>نکروز (پالیسیدینگ)</strong> + <strong>پرولیفراسیون میکروواسکولار</strong>.</li><li>در ماکروسکوپی نواحی زرد = نکروز و همراه با خونریزی؛ اساس درجه‌بندی بالاتر = تمایز کمتر.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>ویژگی</th><th>درجه‌ی ۳</th><th>درجه‌ی ۴ (<bdi>GBM</bdi>)</th></tr></thead><tbody><tr><td>نکروز</td><td>ندارد</td><td>دارد (پالیسید)</td></tr><tr><td>پرولیفراسیون میکروواسکولار</td><td>شروع</td><td>شدید</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دام: نکروز را با «آتیپی هسته» یا «میتوز» عوض نکنید؛ آتیپی در درجه‌ی ۲ و ۳ هم هست، ولی نکروز پالیسید فقط در درجه‌ی ۴ است.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش آستروسیتوم و گلیوبلاستوما</p>","steps":"<p>کلیدواژه‌ی سؤال «کرایتریای لازم برای گلیوبلاستوما» است؛ یعنی چیزی که آن را از آستروسیتوم آناپلاستیک جدا می‌کند.</p>\n<p>هیپرکرومازی هسته و میتوز آتیپیک در همه‌ی آستروسیتوم‌های بدخیم‌تر هم هست، پس اختصاصی نیست.</p>\n<p>اجسام روزنتال مخصوص پیلوسیتیک (درجه‌ی ۱) هستند.</p>\n<p>آنچه گلیوبلاستوما را می‌سازد نکروز (پالیسیدینگ) و پرولیفراسیون میکروواسکولار است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دام: نکروز را با «آتیپی هسته» یا «میتوز» عوض نکنید؛ آتیپی در درجه‌ی ۲ و ۳ هم هست، ولی نکروز پالیسید فقط در درجه‌ی ۴ است."],"dupOf":null,"dupNote":"","xrefs":["f08"]},{"id":"p4q02","session":"p4","full":false,"num":52,"text":"در میکروسکوپی تومور کیستیک با مورال ندول در مخچه کودک 5 ساله، آستروسیتوم های کشیده موئی دیده می شوند که جا به جا در مابینشان اجسام روزنتال قرار دارد. میتوز نیز دیده نمی شود. تشخیص تومور کدامیک از موارد زیر می باشد؟","opts":["دیفیوز آستروسیتوم","پیلوسیتیک آستروسیتوم","گلیوبلاستوم","گانگلیوگلیوما"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[18]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[5]}],"answer":1,"explain":"<p>کودک ۵ ساله، محل <strong>مخچه</strong>، تومور <strong>کیستیک با ندول جداری (<bdi>mural nodule</bdi>)</strong>، سلول‌های مومانند (<bdi>hair-like</bdi>) و <strong>اجسام روزنتال</strong> و نبودن میتوز، همگی تابلوی <strong>آستروسیتوم پیلوسیتیک</strong> (<bdi>WHO</bdi> درجه‌ی ۱) هستند.</p>\n<ul><li><strong>الف) دیفیوز آستروسیتوم:</strong> تومور نفوذی بزرگسالان در نیمکره‌های مخ با زمینه‌ی فیبریلری و پلئومورفیسم است؛ ندول جداری و اجسام روزنتال ندارد.</li><li><strong>ج) گلیوبلاستوم:</strong> تومور بزرگسالان با نکروز، میتوز فراوان و پرولیفراسیون میکروواسکولار است؛ «بدون میتوز» با آن جور نیست.</li><li><strong>د) گانگلیوگلیوما:</strong> تومور مخلوط نورونی و گلیال است (سلول‌های گانگلیونی دیسپلاستیک) و ویژگی اصلی آن اجسام روزنتال نیست.</li></ul>","flag":"","lesson":"<ul><li>پیلوسیتیک: درجه‌ی ۱، کودکان و جوانان، مخچه، بطن سوم و مسیرهای بینایی؛ ماکروسکوپی <strong>کیستیک + ندول جداری</strong>.</li><li>میکروسکوپی: سلول‌های <strong>بایپولار</strong> با زائده‌ی مومانند (<bdi>GFAP</bdi> مثبت) + <strong>فیبر روزنتال</strong> (اجسام ائوزینوفیلیک گرانولر) + نواحی میکروسیستیک.</li><li>نکروز و میتوز معمولاً ندارد.</li><li>ژنتیک: جهش فعال‌کننده‌ی <strong><bdi>BRAF</bdi></strong> (کیناز سرین-ترئونین).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دام: «کیستیک با ندول جداری در مخچه‌ی کودک» را با مدولوبلاستوما (توده‌ی توپر و شکننده، سلول‌های آبی کوچک، میتوز زیاد) اشتباه نگیرید.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش آستروسیتوم پیلوسیتیک</p>","steps":"<p>کلیدواژه‌ها: کودک ۵ ساله، مخچه، کیستیک با ندول جداری، سلول‌های مومانند و اجسام روزنتال، بدون میتوز.</p>\n<p>بدون میتوز و در کودک یعنی تومور خوش‌خیم؛ گلیوبلاستوم (نکروز و میتوز) حذف می‌شود.</p>\n<p>دیفیوز آستروسیتوم تومور نفوذی بزرگسالان است و اجسام روزنتال ندارد؛ گانگلیوگلیوما سلول گانگلیونی دارد.</p>\n<p>اجسام روزنتال و ندول جداری یعنی پیلوسیتیک.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دام: «کیستیک با ندول جداری در مخچه‌ی کودک» را با مدولوبلاستوما (توده‌ی توپر و شکننده، سلول‌های آبی کوچک، میتوز زیاد) اشتباه نگیرید."],"dupOf":null,"dupNote":"","xrefs":["f15"]},{"id":"p4q03","session":"p4","full":false,"num":53,"text":"وجود اجسام وروکی(<bdi>Verocay bodies</bdi>) از مشخصات کدامیک از تومورهای اعصاب محیطی می باشد؟","opts":["شوانوم","نوروفیبروم","<bdi>MPNST</bdi>","<bdi>PNET</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[19]},{"name":"تلفیقی بهار ۱۴۰۱","nums":[]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[17]}],"answer":0,"explain":"<p><strong>جسم وروکای (<bdi>Verocay body</bdi>)</strong> از ویژگی‌های کلاسیک <strong>شوانوما</strong> است: در نواحی پرسلول <strong>آنتونی <bdi>A</bdi></strong> هسته‌ها در دو ردیف پالیسید می‌شوند و بین آن‌ها ناحیه‌ای از زوائد سیتوپلاسمی بدون هسته قرار می‌گیرد.</p>\n<ul><li><strong>ب) نوروفیبروم:</strong> از سلول‌های شوان، فیبروبلاست و فیبرهای کلاژن «شبه‌سیم» (<bdi>wire-like</bdi>) تشکیل شده و آنتونی <bdi>A/B</bdi> و جسم وروکای ندارد.</li><li><strong>ج) <bdi>MPNST</bdi>:</strong> تومور بدخیم غلاف عصب محیطی است؛ سلولاریته‌ی بالا، آتیپی و میتوز دارد، نه ساختار منظم وروکای.</li><li><strong>د) <bdi>PNET</bdi>:</strong> تومور امبریونال سلول‌آبی کوچک است و ربطی به اعصاب محیطی با الگوی پالیسید ندارد.</li></ul>","flag":"","lesson":"<ul><li>شوانوما: کپسول‌دار، مرزدار و مجاور عصب؛ تکثیر یکنواخت سلول‌های شوان.</li><li>آنتونی <bdi>A</bdi> = پرسلول، اسپیندل با دسته‌های متقاطع + جسم وروکای؛ آنتونی <bdi>B</bdi> = کم‌سلول و میکزوئید.</li><li>عروق <strong>هیالینیزه</strong> با دیواره‌ی ضخیم؛ خونریزی یا تغییر کیستیک ممکن است.</li><li>شوانومای وستیبولار دوطرفه نشانه‌ی کلاسیک <strong><bdi>NF2</bdi></strong> است.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دام: شوانوما (کپسول‌دار، وروکای) را با نوروفیبروم (بدون کپسول، سلول‌های شوان + فیبروبلاست، مرتبط با <bdi>NF1</bdi>) عوض نکنید.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش شوانوما (آنتونی <bdi>A</bdi> و <bdi>B</bdi>)</p>","steps":"<p>کلیدواژه‌ی سؤال «<bdi>Verocay body</bdi>» است.</p>\n<p>وروکای = ردیف هسته‌ها (پالیسید) با زوائد بدون هسته در بین آن‌ها، در ناحیه‌ی آنتونی <bdi>A</bdi>.</p>\n<p>نوروفیبروم و <bdi>MPNST</bdi> چنین ساختار منظمی ندارند و <bdi>PNET</bdi> اصلاً تومور غلاف عصب نیست.</p>\n<p>این الگو متعلق به شوانوم است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دام: شوانوما (کپسول‌دار، وروکای) را با نوروفیبروم (بدون کپسول، سلول‌های شوان + فیبروبلاست، مرتبط با <bdi>NF1</bdi>) عوض نکنید."],"dupOf":null,"dupNote":"","xrefs":["f16"]},{"id":"p4q04","session":"p4","full":false,"num":54,"text":"سودو روزت دور عروقی، از مشخصات اصلی کدام تومور می باشد؟","opts":["اپاندیموما","الیگودندروگلیوما","مننژیوم","نوروفیبروم"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[20]},{"name":"تلفیقی بهار ۱۴۰۱","nums":[]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[12]}],"answer":0,"explain":"<p><strong>سودوروزت دور عروقی (<bdi>perivascular pseudorosette</bdi>)</strong> یعنی زوائد سیتوپلاسمی بدون هسته‌ی سلول‌های تومور که به سمت دیواره‌ی یک رگ کشیده شده‌اند؛ این ویژگی اصلی <strong>اپاندیموما</strong> است (در کنار روزت واقعی که دور لومن بدون رگ است).</p>\n<ul><li><strong>ب) الیگودندروگلیوما:</strong> هسته‌ی گرد با هاله‌ی روشن (<bdi>fried egg</bdi>)، شبکه‌ی ظریف مویرگی (<bdi>chicken wire</bdi>) و کلسیفیکاسیون دارد؛ سودوروزت ندارد.</li><li><strong>ج) مننژیوم:</strong> الگوی گردابی (<bdi>whorl</bdi>) و اجسام ساموما دارد.</li><li><strong>د) نوروفیبروم:</strong> تومور غلاف عصب محیطی با دسته‌های رشته‌ای موج‌دار است و ساختار روزت‌مانند ندارد.</li></ul>","flag":"","lesson":"<ul><li>سودوروزت: زوائد بدون هسته به سمت <strong>رگ</strong>؛ روزت واقعی (اپاندیمی): اطراف <strong>لومن بدون رگ</strong>.</li><li>هومر رایت روزت: سلول‌ها دور تا دور و سیتوپلاسم در مرکز، بدون لومن و رگ؛ ویژه‌ی <strong>مدولوبلاستوما</strong>.</li><li>اپاندیموما: مجاور سیستم بطنی؛ در دو دهه‌ی اول نزدیک <strong>بطن چهارم</strong>، در بزرگسالان شایع‌ترین محل نخاع؛ ارتباط با <bdi>NF2</bdi>.</li><li>لنفوم اولیه‌ی مغز: تجمع سلول‌های مونومورف <strong>دور رگ</strong> که نباید با سودوروزت اشتباه شود.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دام: تجمع سلول‌ها دور رگ (لنفوم) یا روزت دور سلول‌ها (مدولوبلاستوما) را سودوروزت اپاندیموما نخوانید.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش اپاندیموم</p>","steps":"<p>کلیدواژه‌ی سؤال «سودوروزت دور عروقی» است.</p>\n<p>زوائد بدون هسته‌ی سلول‌های تومور به سمت رگ کشیده می‌شوند؛ این در اپاندیموما دیده می‌شود.</p>\n<p>الیگودندروگلیوم (<bdi>fried egg</bdi> و <bdi>chicken wire</bdi>)، مننژیوم (گردابی و ساموما) و نوروفیبروم (اعصاب محیطی) این ساختار را ندارند.</p>\n<p>بنابراین پاسخ اپاندیموما است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دام: تجمع سلول‌ها دور رگ (لنفوم) یا روزت دور سلول‌ها (مدولوبلاستوما) را سودوروزت اپاندیموما نخوانید."],"dupOf":null,"dupNote":"","xrefs":["f09"]},{"id":"p4q05","session":"p4","full":false,"num":55,"text":"کدامیک از پترن های میکروسکوپی زیر در الیگودندروگلیوما دیده نمی شود؟","opts":["میکروکلسیفیکاسیون","عروق ریز زمینه","سلولهای شبیه تخم مرغی","زمینه نوروپیل"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[21]},{"name":"تلفیقی بهار ۱۴۰۱","nums":[]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[22]}],"answer":3,"explain":"<p>الیگودندروگلیوما از <strong>ورقه‌هایی از سلول‌های منظم با هسته‌ی گرد و هاله‌ی روشن</strong> و <strong>شبکه‌ی ظریف مویرگ‌های آناستوموزکننده</strong> و معمولاً <strong>کلسیفیکاسیون</strong> ساخته شده است. «زمینه‌ی نوروپیل» جزو الگوهای شاخص این تومور نیست (بیشتر مخصوص تومورهای نورونی مثل نوروسیتوم مرکزی است)، پس همان الگوی دیده‌نشده است.</p>\n<ul><li><strong>الف) میکروکلسیفیکاسیون:</strong> در حدود ۹۰٪ این تومورها دیده می‌شود؛ پس «دیده می‌شود».</li><li><strong>ب) عروق ریز زمینه:</strong> شبکه‌ی مویرگی ظریف (<bdi>chicken wire</bdi>) از هالمارک‌های آن است؛ پس «دیده می‌شود».</li><li><strong>ج) سلول‌های شبیه تخم‌مرغ:</strong> همان هاله‌ی روشن دور هسته (<bdi>fried egg</bdi>) است؛ پس «دیده می‌شود».</li></ul>","flag":"","lesson":"<ul><li>هالمارک‌های میکروسکوپی: <strong><bdi>fried egg</bdi></strong> + <strong><bdi>chicken wire</bdi></strong> + <strong>کلسیفیکاسیون</strong>.</li><li>محل: نیمکره‌های مخ، معمولاً لوب فرونتال و تمپورال؛ دهه‌ی چهارم و پنجم؛ ۵ تا ۱۵٪ گلیوم‌ها.</li><li>مولکولی: <strong>کودلیشن 1<bdi>p/19q</bdi></strong>، همراه با پاسخ بسیار خوب به شیمی‌درمانی و رادیوتراپی.</li><li>ماکروسکوپی: توده‌ی ژلاتینی خاکستری، نفوذی.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دام: <bdi>chicken wire</bdi> (مویرگ‌های ظریف آناستوموزکننده) با پرولیفراسیون میکروواسکولار گلیوبلاستوما فرق دارد؛ اولی طبیعی و ظریف است.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش الیگودندروگلیوم (زمینه‌ی نوروپیل در جزوه برای نوروسیتوم مرکزی آمده است، نه الیگودندروگلیوم)</p>","steps":"<p>سؤال به صورت منفی است: الگویی را بیابید که در الیگودندروگلیوما «دیده نمی‌شود».</p>\n<p>میکروکلسیفیکاسیون، مویرگ‌های ظریف (<bdi>chicken wire</bdi>) و سلول‌های تخم‌مرغی (<bdi>fried egg</bdi>) هر سه هالمارک این تومور هستند.</p>\n<p>زمینه‌ی نوروپیل در این فهرست نمی‌گنجد (مخصوص تومورهای نورونی).</p>\n<p>بنابراین گزینه‌ی د پاسخ است.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دام: <bdi>chicken wire</bdi> (مویرگ‌های ظریف آناستوموزکننده) با پرولیفراسیون میکروواسکولار گلیوبلاستوما فرق دارد؛ اولی طبیعی و ظریف است."],"dupOf":null,"dupNote":"","xrefs":["f17"]},{"id":"p4q06","session":"p4","full":false,"num":56,"text":"شایعترین ژرم سل تومور اولیه مغزی، در غده پینه آل کدامیک از موارد زیر است؟","opts":["ژرمینوما","مننزیوما","اپاندیموما","تراتوم"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[22]}],"answer":0,"explain":"<p>تومورهای سلول زایا (<bdi>Germ cell</bdi>) در جوانان و خط وسط (ناحیه‌ی پینه‌آل و سوپراسلار) دیده می‌شوند و <strong>ژرمینوما</strong> شایع‌ترین تومور سلول زایای اولیه‌ی <bdi>CNS</bdi> است، به ویژه در غده‌ی پینه‌آل با غلبه‌ی جنس مرد.</p>\n<ul><li><strong>ب) مننژیوما:</strong> تومور سلول‌های عنکبوتیه است، نه سلول زایا.</li><li><strong>ج) اپاندیموما:</strong> از سلول‌های اپاندیم است، نه سلول زایا؛ و سلول زایا بودن در صورت سؤال شرط است.</li><li><strong>د) تراتوم:</strong> از تومورهای سلول زایا است ولی در این ناحیه شایع‌ترین نیست.</li></ul>","flag":"","lesson":"<ul><li>تومورهای سلول زایا: ۹۰٪ در دو دهه‌ی اول، خط وسط؛ ۰٫۲ تا ۱٪ تومورهای مغزی.</li><li>محل‌ها: <strong>پینه‌آل</strong> (غلبه‌ی پسران) و <strong>سوپراسلار</strong>.</li><li>شایع‌ترین نوع: <strong>ژرمینوما</strong> (شبیه سمینوم/دیس‌ژرمینوم).</li><li>سایر انواع: تراتوم، کوریوکارسینوم، تومور کیسه‌ی زرده.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دام: تراتوم هم تومور سلول زایا است و در پینه‌آل دیده می‌شود، ولی «شایع‌ترین» ژرمینوما است.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش تومورهای سلول زایا</p>","steps":"<p>کلیدواژه‌ها: «ژرم سل»، «غده‌ی پینه‌آل» و «شایع‌ترین».</p>\n<p>مننژیوما و اپاندیموما سلول زایا نیستند و حذف می‌شوند.</p>\n<p>بین ژرمینوما و تراتوم، شایع‌ترین تومور سلول زایای اولیه‌ی <bdi>CNS</bdi> ژرمینوم است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دام: تراتوم هم تومور سلول زایا است و در پینه‌آل دیده می‌شود، ولی «شایع‌ترین» ژرمینوما است."],"dupOf":null,"dupNote":"","xrefs":["f20"]},{"id":"p4q07","session":"p4","full":false,"num":57,"text":"در گریدینگ <bdi>WHO</bdi> به آستروسیتوم آناپلاستیک چه گریدی اطلاق می شود؟","opts":["گرید <bdi>I</bdi>","گرید <bdi>II</bdi>","گرید <bdi>III</bdi>","گرید <bdi>IV</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[23]},{"name":"تلفیقی بهار ۱۴۰۱","nums":[]},{"name":"تلفیقی پاییز ۱۴۰۰","nums":[8]}],"answer":2,"explain":"<p>در درجه‌بندی <bdi>WHO</bdi> آستروسیتوم با تمایز خوب = <strong>درجه‌ی ۲</strong>، <strong>آستروسیتوم آناپلاستیک = درجه‌ی ۳</strong> و گلیوبلاستوما = <strong>درجه‌ی ۴</strong> است.</p>\n<ul><li><strong>الف) درجه‌ی <bdi>I</bdi>:</strong> مخصوص تومورهای خوش‌خیم مثل آستروسیتوم پیلوسیتیک است.</li><li><strong>ب) درجه‌ی <bdi>II</bdi>:</strong> آستروسیتوم با تمایز خوب (سلولاریته‌ی کمتر، بدون نکروز) است.</li><li><strong>د) درجه‌ی <bdi>IV</bdi>:</strong> گلیوبلاستوما با نکروز و پرولیفراسیون میکروواسکولار است.</li></ul>","flag":"","lesson":"<div class=\"tw\"><table><thead><tr><th>تومور</th><th>درجه‌ی <bdi>WHO</bdi></th></tr></thead><tbody><tr><td>پیلوسیتیک</td><td>۱</td></tr><tr><td>آستروسیتوم با تمایز خوب</td><td>۲</td></tr><tr><td>آستروسیتوم آناپلاستیک</td><td>۳</td></tr><tr><td>گلیوبلاستوما</td><td>۴</td></tr></tbody></table></div>\n<ul><li>آناپلاستیک: سلولاریته و پلئومورفیسم زیاد، میتوز زیاد، شروع پرولیفراسیون عروقی ولی بدون نکروز.</li><li>تمایز کمتر = درجه‌ی بالاتر = میتوز بیشتر = تومور بدخیم‌تر.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دام: «آناپلاستیک» را درجه‌ی ۴ نخوانید؛ درجه‌ی ۴ به نکروز نیاز دارد.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش درجه‌بندی آستروسیتوم</p>","steps":"<p>اطلاعات لازم: درجه‌ی ۲ = آستروسیتوم با تمایز خوب، درجه‌ی ۴ = گلیوبلاستوما.</p>\n<p>بین این دو، آناپلاستیک قرار می‌گیرد: سلولاریته و میتوز زیاد، ولی هنوز بدون نکروز.</p>\n<p>پس درجه‌ی ۳ است.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دام: «آناپلاستیک» را درجه‌ی ۴ نخوانید؛ درجه‌ی ۴ به نکروز نیاز دارد."],"dupOf":null,"dupNote":"","xrefs":["f07"]},{"id":"p4q08","session":"p4","full":false,"num":58,"text":"حذف کروموزوم‌های 1<bdi>p and 19q</bdi> از مشخصات کدام تومور سیستم عصبی مرکزی می باشد؟","opts":["مننژیوم","الیگودندروگلیوما","پیلوسیتیک آستروسیتوما","گلیوبلاستوما"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی ۲۰ مهر ۱۴۰۱","nums":[24]}],"answer":1,"explain":"<p><strong>کودلیشن (<bdi>co-deletion</bdi>) بازوی کوتاه کروموزوم ۱ (1<bdi>p</bdi>) و بازوی بلند کروموزوم ۱۹ (19<bdi>q</bdi>)</strong> ویژگی مولکولی بسیار مهم <strong>الیگودندروگلیوما</strong> است و برای تشخیص قطعی آن لازم است.</p>\n<ul><li><strong>الف) مننژیوم:</strong> جهش/حذف ژن <bdi>NF2</bdi> روی 22<bdi>q</bdi> دارد.</li><li><strong>ج) پیلوسیتیک آستروسیتوما:</strong> جهش فعال‌کننده‌ی <bdi>BRAF</bdi> دارد.</li><li><strong>د) گلیوبلاستوما:</strong> جهش‌های <bdi>p53</bdi> و <bdi>Rb</bdi> و مسیر <bdi>PI3K</bdi> دارد.</li></ul>","flag":"","lesson":"<ul><li>الیگودندروگلیوم: <strong>1<bdi>p/19q co-deletion</bdi></strong> (باید هر دو با هم باشند) + معمولاً جهش <bdi>IDH</bdi>.</li><li>اگر مورفولوژی الیگودندروگلیوم باشد ولی دلیشن نباشد، نام الیگودندروگلیوم نمی‌گذاریم.</li><li>حذف 1<bdi>p/19q</bdi> = پاسخ بسیار خوب به شیمی‌درمانی/رادیوتراپی و پیش‌آگهی بهتر از آستروسیتوم هم‌درجه.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>تومور</th><th>ژنتیک شاخص</th></tr></thead><tbody><tr><td>پیلوسیتیک</td><td><bdi>BRAF</bdi></td></tr><tr><td>مننژیوم</td><td><bdi>NF2</bdi> (22<bdi>q</bdi>)</td></tr><tr><td>الیگودندروگلیوم</td><td>1<bdi>p/19q</bdi></td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دام: <bdi>p</bdi> و <bdi>q</bdi> را قاطی نکنید؛ 1<bdi>p</bdi> و 19<bdi>q</bdi> (نه 1<bdi>q</bdi> و 19<bdi>p</bdi>).</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش الیگودندروگلیوم</p>","steps":"<p>کلیدواژه‌ی سؤال «حذف 1<bdi>p</bdi> و 19<bdi>q</bdi>» است.</p>\n<p>این کودلیشن نشانه‌ی مولکولی الیگودندروگلیوما است.</p>\n<p>مننژیوم <bdi>NF2</bdi> و 22<bdi>q</bdi>، پیلوسیتیک <bdi>BRAF</bdi> و گلیوبلاستوما <bdi>p53/Rb</bdi> دارند.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دام: <bdi>p</bdi> و <bdi>q</bdi> را قاطی نکنید؛ 1<bdi>p</bdi> و 19<bdi>q</bdi> (نه 1<bdi>q</bdi> و 19<bdi>p</bdi>)."],"dupOf":null,"dupNote":"","xrefs":["f19"]},{"id":"p4q09","session":"p4","full":false,"num":59,"text":"کدامیک از موتاسیون‌های زیر در آستروسیتوم‌های با گرید پایین در مقایسه با گلیوبلاستوم مولتی فرم بطور شایع‌تر دیده می‌شود؟","opts":["<bdi>p53</bdi>","<bdi>p53</bdi>","<bdi>Rb</bdi>","<bdi>IDH1</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی 96A","nums":[19]}],"answer":3,"explain":"<p>طبق جزوه، در <strong>گلیوبلاستوما</strong> جهش از دست دادن عملکرد در <strong><bdi>p53</bdi></strong> و <strong><bdi>Rb</bdi></strong> (مهارکننده‌های تومور) و جهش افزایش عملکرد در مسیر <strong><bdi>PI3K</bdi></strong> دیده می‌شود؛ در مقابل، در <strong>آستروسیتوم‌های درجه‌ی پایین‌تر</strong> جهش‌های <strong><bdi>IDH1</bdi></strong> و <bdi>IDH2</bdi> شایع‌ترند.</p>\n<ul><li><strong>الف و ب) <bdi>p53</bdi>:</strong> (دو گزینه‌ی یکسان) طبق جزوه، <bdi>p53</bdi> و <bdi>Rb</bdi> به گلیوبلاستوما نسبت داده می‌شوند و جهش شاخص آستروسیتوم‌های درجه‌ی پایین‌تر <bdi>IDH1/IDH2</bdi> است؛ دو گزینه‌ی یکسان هم نمی‌توانند پاسخ متمایز باشند.</li><li><strong>ج) <bdi>Rb</bdi>:</strong> از دست رفتن مسیر <bdi>Rb</bdi> از ویژگی‌های گلیوبلاستوما است.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی در سؤال گزینه‌های الف و ب هر دو «<bdi>p53</bdi>» نوشته شده‌اند (متن یکی از آن‌ها احتمالاً افتاده)؛ چون دو گزینه‌ی یکسان نمی‌توانند پاسخ متفاوت باشند و بر اساس جزوه جهش شاخص آستروسیتوم‌های درجه‌ی پایین <bdi>IDH1</bdi> (و <bdi>IDH2</bdi>) است، گزینه‌ی د انتخاب شد.","lesson":"<ul><li>گلیوبلاستوما: از دست دادن عملکرد <strong><bdi>p53</bdi></strong> و <strong><bdi>Rb</bdi></strong>؛ افزایش عملکرد در مسیرهای <strong><bdi>PI3K</bdi></strong> (و <bdi>EGFR</bdi>).</li><li>آستروسیتوم درجه‌ی پایین: جهش <strong><bdi>IDH1/IDH2</bdi></strong>.</li><li><bdi>IDH</bdi> جهش‌یافته با پیش‌آگهی بهتر و مولکول 2-<bdi>HG</bdi> همراه است (مرجع: <bdi>Robbins</bdi>، در جزوه نبود).</li><li>پیلوسیتیک: <bdi>BRAF</bdi>؛ الیگودندروگلیوم: <bdi>IDH</bdi> + کودلیشن 1<bdi>p/19q</bdi>.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دام: در سؤال‌های «جهش شایع‌تر در درجه‌ی پایین» به جای <bdi>p53</bdi> و <bdi>Rb</bdi> (که یادآور بدخیمی‌اند)، <bdi>IDH1</bdi> را انتخاب کنید.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش ژنتیک آستروسیتوم و گلیوبلاستوما</p>","steps":"<p>صورت سؤال «جهش شایع‌تر در آستروسیتوم درجه‌ی پایین نسبت به <bdi>GBM</bdi>» را می‌پرسد.</p>\n<p>در <bdi>GBM</bdi> مسیرهای <bdi>p53</bdi> و <bdi>Rb</bdi> از دست می‌روند، پس گزینه‌های الف و ب (که هر دو <bdi>p53</bdi> هستند) و ج کنار می‌روند.</p>\n<p>جهش شاخص تومورهای درجه‌ی پایین‌تر <bdi>IDH1</bdi> (و <bdi>IDH2</bdi>) است.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دام: در سؤال‌های «جهش شایع‌تر در درجه‌ی پایین» به جای <bdi>p53</bdi> و <bdi>Rb</bdi> (که یادآور بدخیمی‌اند)، <bdi>IDH1</bdi> را انتخاب کنید."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p4q10","session":"p4","full":false,"num":60,"text":"در بررسی هیستوپاتولوژی تومور بطن چهارم مغز پسر بچه 10 ساله‌ای سلولهای تومورال با هسته‌های گرد و منظم با کروماتین گرانولار به همراه ساختارهای <bdi>Rosettes</bdi> & <bdi>perivascular pseudorosettes</bdi> رویت شد. کدام تشخیص مطرح می‌گردد؟","opts":["<bdi>Ependymoma</bdi>","<bdi>oligodendroglioma</bdi>","<bdi>pilocytic astrocytoma</bdi>","<bdi>Glioblastoma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی 96A","nums":[20]}],"answer":0,"explain":"","flag":"","lesson":"","steps":"","traps":[],"dupOf":"p4q23","dupNote":"<p>این سوال تکرار <a class=\"xref\" href=\"#/q/p4q23\">سوال ۷۳</a> است. پاسخ تشریحی و درس‌نامه را زیر همان سوال ببین.</p>","xrefs":["p4q23"]},{"id":"p4q11","session":"p4","full":false,"num":61,"text":"کدامیک از سندرم‌های پارانئوپلاستیک با علایم سیستم عصبی بیشتر در تراتوم تخمدانی و به دلیل ساخته شدن آنتی‌بادی علیه <bdi>NMDA</bdi> گیرنده ایجاد می‌شود؟","opts":["<bdi>Limbic encephalitis</bdi>","<bdi>Subacute sensory neuropathy</bdi>","<bdi>Subacute cerebellar degeneration</bdi>","<bdi>Syndrome of rapid-onset psychosis</bdi>, <bdi>catatonia</bdi>, <bdi>epilepsy</bdi>, …"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی 96A","nums":[21]}],"answer":3,"explain":"<p><strong>انسفالیت آنتی‌<bdi>NMDAR</bdi></strong> در زنان جوان با <strong>تراتوم تخمدانی</strong> همراه است (آنتی‌بادی علیه گیرنده‌ی <bdi>NMDA</bdi>) و با <strong>شروع سریع روان‌پریشی، کاتاتونی، تشنج</strong> (و گاهی هیپوونتیلاسیون) تظاهر می‌کند؛ این همان سندرم گزینه‌ی د است.</p>\n<ul><li><strong>الف) <bdi>Limbic encephalitis</bdi>:</strong> با آنتی‌بادی‌های ضد نورونی دیگر (مثل <bdi>anti-Hu</bdi>) و غالباً با کارسینوم ریه‌ی سلول کوچک همراه است، نه تراتوم تخمدانی با <bdi>NMDA</bdi>.</li><li><strong>ب) <bdi>Subacute sensory neuropathy</bdi>:</strong> با <bdi>anti-Hu</bdi> و کارسینوم ریه‌ی سلول کوچک دیده می‌شود.</li><li><strong>ج) <bdi>Subacute cerebellar degeneration</bdi>:</strong> با <bdi>anti-Yo</bdi> (<bdi>Purkinje</bdi>) و سرطان‌های تخمدان/پستان/ریه مطرح می‌شود، نه گیرنده‌ی <bdi>NMDA</bdi>.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی متن گزینه‌ی د ناقص است («…»)؛ این گزینه توصیف بالینی انسفالیت آنتی‌<bdi>NMDAR</bdi> (روان‌پریشی، کاتاتونی و تشنج ناگهانی) است که با تراتوم تخمدانی همراه است؛ بنابراین گزینه‌ی د پاسخ است.","lesson":"<ul><li>سندرم‌های پارانئوپلاستیک عصبی: <strong><bdi>Limbic encephalitis</bdi></strong>، <strong><bdi>Subacute cerebellar degeneration</bdi></strong>، <strong><bdi>Opsoclonus-myoclonus</bdi></strong>، <strong><bdi>Subacute sensory neuropathy</bdi></strong>.</li><li><bdi>anti-NMDAR</bdi>: زن جوان + <strong>تراتوم تخمدانی</strong> + روان‌پریشی/کاتاتونی/تشنج؛ با برداشتن تومور و ایمونوتراپی بهبود می‌یابد.</li><li><bdi>Limbic encephalitis</bdi> و <bdi>Subacute sensory neuropathy</bdi>: <bdi>SCLC</bdi> با <bdi>anti-Hu</bdi>؛ <bdi>Cerebellar degeneration</bdi>: <bdi>anti-Yo</bdi>.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دام: «تراتوم تخمدانی + <bdi>NMDA</bdi>» را با <bdi>Limbic encephalitis</bdi> عوض نکنید؛ در تابلوی <bdi>NMDAR</bdi>، روان‌پریشی و کاتاتونی و تشنج مهم‌ترند.</p><p class=\"ref\">مرجع: <bdi>Robbins</bdi> (در جزوه نبود)، بخش سندرم‌های پارانئوپلاستیک سیستم عصبی</p>","steps":"<p>کلیدواژه‌ها: تراتوم تخمدانی و آنتی‌بادی علیه گیرنده‌ی <bdi>NMDA</bdi>؛ یعنی انسفالیت آنتی‌<bdi>NMDAR</bdi>.</p>\n<p>بالینی آن روان‌پریشی ناگهانی، کاتاتونی و تشنج است که در گزینه‌ی د (ناقص) آمده است.</p>\n<p><bdi>Limbic encephalitis</bdi>، نوروپاتی حسی و دژنراسیون مخچه با آنتی‌بادی‌های دیگر (<bdi>anti-Hu</bdi> و <bdi>anti-Yo</bdi>) همراه‌اند.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دام: «تراتوم تخمدانی + <bdi>NMDA</bdi>» را با <bdi>Limbic encephalitis</bdi> عوض نکنید؛ در تابلوی <bdi>NMDAR</bdi>، روان‌پریشی و کاتاتونی و تشنج مهم‌ترند."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p4q12","session":"p4","full":false,"num":62,"text":"در نمای هیستوپاتولوژی بافت مغز کدام نوع انسفالیت قارچی زیر نمای \"<bdi>soap bubble-like appearance</bdi>\" دیده می‌شود.","opts":["<bdi>Cryptococcus neoformans</bdi>","<bdi>Mucormycosis</bdi>","<bdi>Aspergillus fumigatus</bdi>","<bdi>Candida albicans</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[10]},{"name":"تلفیقی 96A","nums":[22]}],"answer":0,"explain":"<p>نمای «<strong><bdi>soap bubble</bdi></strong>» در بافت مغز مخصوص <strong><bdi>Cryptococcus neoformans</bdi></strong> است: مخمرهای کپسول‌دار در فضاهای دور عروقی (<bdi>Virchow-Robin</bdi>) تجمع می‌کنند و کپسول موسینی ژلاتینی آن‌ها حفرات حبابی می‌سازد، با واکنش التهابی ناچیز.</p>\n<ul><li><strong>ب) <bdi>Mucormycosis</bdi>:</strong> هیف‌های پهن و بدون سپتوم، با زوایای راست و تهاجم عروقی (به‌خصوص در دیابت و اسیدوز) و انفارکتوس و نکروز؛ نمای حباب صابونی ندارد.</li><li><strong>ج) <bdi>Aspergillus fumigatus</bdi>:</strong> هیف‌های سپتدار با انشعاب زاویه‌ی حاد (۴۵ درجه)، تهاجم عروقی و خونریزی/انفارکتوس.</li><li><strong>د) <bdi>Candida albicans</bdi>:</strong> مخمر همراه با سودوهیف، میکروآبسه‌های متعدد و گرانولوم.</li></ul>","flag":"","lesson":"<div class=\"tw\"><table><thead><tr><th>قارچ</th><th>نمای شاخص <bdi>CNS</bdi></th></tr></thead><tbody><tr><td><bdi>Cryptococcus</bdi></td><td>کپسول موسینی، <strong><bdi>soap bubble</bdi></strong>، مننژیت مزمن، رنگ <bdi>India ink/mucicarmine</bdi></td></tr><tr><td><bdi>Mucor</bdi></td><td>هیف پهن بدون سپتوم، زاویه‌ی ۹۰ درجه، تهاجم عروقی</td></tr><tr><td><bdi>Aspergillus</bdi></td><td>هیف سپتدار، زاویه‌ی ۴۵ درجه، آبسه</td></tr><tr><td><bdi>Candida</bdi></td><td>مخمر + سودوهیف، میکروآبسه</td></tr></tbody></table></div>\n<ul><li><bdi>Cryptococcus</bdi>: بیشتر در نقص ایمنی (<bdi>AIDS</bdi>)؛ مننژیت مزمن.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>دام: حباب صابونی = کریپتوکوک؛ ماکور (دیابتی) و آسپرژیلوس هیف دارند، نه مخمر کپسول‌دار.</p><p class=\"ref\">مرجع: <bdi>Robbins</bdi> (در جزوه نبود)، بخش عفونت‌های قارچی <bdi>CNS</bdi></p>","steps":"<p>کلیدواژه‌ی سؤال «<bdi>soap bubble-like appearance</bdi>» در مغز است.</p>\n<p>این نما از کپسول موسینی ژلاتینی مخمر کریپتوکوک در فضاهای دور عروقی می‌آید.</p>\n<p>ماکور و آسپرژیلوس هیف دارند و کاندیدا مخمر با سودوهیف است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>دام: حباب صابونی = کریپتوکوک؛ ماکور (دیابتی) و آسپرژیلوس هیف دارند، نه مخمر کپسول‌دار."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p4q13","session":"p4","full":false,"num":63,"text":"شایع‌ترین نئوپلاسم مغز در مبتلایان به نقص سیستم ایمنی کدام گزینه می‌باشد","opts":["<bdi>Primary CNS lymphoma</bdi>","<bdi>Oligodendroglioma</bdi>","<bdi>Glioblastoma</bdi>","<bdi>Metastatic Tumor</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[23]},{"name":"تلفیقی 96A","nums":[23]}],"answer":0,"explain":"<p>در نقص ایمنی (به‌ویژه <bdi>AIDS</bdi> و پیوند عضو)، شایع‌ترین نئوپلاسم <bdi>CNS</bdi> <strong>لنفوم اولیه‌ی <bdi>CNS</bdi></strong> است که تقریباً همیشه <strong><bdi>EBV</bdi> مثبت</strong> و از نوع <strong><bdi>Diffuse Large B-cell</bdi></strong> است. ویژگی میکروسکوپی مهم آن تجمع سلول‌های مونومورف لنفوئید <strong>دور رگ</strong> (<bdi>angiocentric</bdi>) است.</p>\n<ul><li><strong>ب) <bdi>Oligodendroglioma</bdi>:</strong> تومور گلیال بزرگسالان جوان تا میانسال در لوب فرونتال با دلیشن 1<bdi>p/19q</bdi> است و ارتباطی با نقص ایمنی ندارد.</li><li><strong>ج) <bdi>Glioblastoma</bdi>:</strong> شایع‌ترین تومور اولیه‌ی بدخیم مغز در بزرگسالان عادی است، ولی در زمینه‌ی نقص ایمنی شایع‌ترین نئوپلاسم نیست.</li><li><strong>د) <bdi>Metastatic Tumor</bdi>:</strong> متاستاز در جمعیت عمومی بزرگسالان شایع است (ریه، پستان، ملانوم، کلیه، <bdi>GI</bdi>)، اما سؤال درباره‌ی «نقص ایمنی» است و پاسخ اختصاصی آن لنفوم اولیه است.</li></ul>","flag":"","lesson":"<ul><li>لنفوم اولیه‌ی <bdi>CNS</bdi>: بیشتر بعد از ۶۰ سالگی در افراد بدون نقص ایمنی؛ در افراد دچار نقص ایمنی تقریباً همیشه <bdi>EBV</bdi> مثبت.</li><li>تیپ هیستولوژیک معمول: <bdi>Diffuse Large B-cell lymphoma</bdi> (<bdi>CD20</bdi> مثبت)؛ رشد دور رگ و ندول‌های متعدد در عمق (خاکستری عمقی، اطراف بطن‌ها).</li><li>رفتار: تهاجمی با پاسخ نسبتاً ضعیف؛ در <bdi>EBV</bdi> مثبت‌ها نواحی وسیع نکروز دیده می‌شود.</li><li>تجمع سلول‌های لنفوم دور رگ را با <strong><bdi>pseudorosette</bdi></strong> اپاندیموم اشتباه نگیرید (در سودوروزت زوائد سیتوپلاسمی بدون هسته به سمت رگ می‌روند).</li><li>متاستازها معمولاً متعدد و کاملاً مرزدار هستند؛ تومورهای اولیه‌ی بدخیم مغز انفیلتراتیو و منفرد.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>«نقص ایمنی + تومور مغزی» یعنی لنفوم اولیه‌ی <bdi>CNS</bdi> (<bdi>EBV</bdi>)؛ نه گلیوبلاستوم و نه الیگودندروگلیوم.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش لنفوم اولیه‌ی <bdi>CNS</bdi> و تومورهای متاستاتیک</p>","steps":"<p>کلیدواژه‌ی سؤال «نقص ایمنی» و «شایع‌ترین نئوپلاسم مغز» است.</p>\n<p>در نقص ایمنی (<bdi>AIDS</bdi>، پیوند) تومور مرتبط با <bdi>EBV</bdi> لنفوم <bdi>B-cell</bdi> اولیه‌ی <bdi>CNS</bdi> است.</p>\n<p>گلیوبلاستوم و الیگودندروگلیوم به نقص ایمنی ربطی ندارند.</p>\n<p>متاستاز در جمعیت عمومی شایع است، اما سؤال اختصاصاً درباره‌ی نقص ایمنی است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>«نقص ایمنی + تومور مغزی» یعنی لنفوم اولیه‌ی <bdi>CNS</bdi> (<bdi>EBV</bdi>)؛ نه گلیوبلاستوم و نه الیگودندروگلیوم."],"dupOf":null,"dupNote":"","xrefs":["p4q24","p4q25"]},{"id":"p4q14","session":"p4","full":false,"num":64,"text":"در بررسی هیستوپاتولوژی تومور مغزی آقای 70 ساله‌ای دستجات سلولهای بزرگ با پلئومورفیسم هسته‌ای برجسته همراه با نکروز با نمای <bdi>pseudopalisading nuclei</bdi> و پرولیفراسیون عروقی دیده می‌شود. کدام تشخیص مطرح می‌گردد و میتوز فراوان؟","opts":["<bdi>multiforme Glioblastoma</bdi>","<bdi>pilocytic astrocytoma</bdi>","<bdi>Anaplastic astrocytomas</bdi>","<bdi>Well-differentiated astrocytomas</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی 96A","nums":[24]}],"answer":0,"explain":"<p>سلول‌های بزرگ با <strong>پلئومورفیسم هسته‌ای</strong> برجسته، <strong>نکروز با نمای <bdi>pseudopalisading</bdi></strong>، <strong>پرولیفراسیون عروقی (میکروواسکولار)</strong> و میتوز فراوان سه‌گانه‌ی تشخیصی <strong>گلیوبلاستوم (<bdi>GBM</bdi>؛ آستروسیتوم درجه‌ی ۴)</strong> است؛ سن ۷۰ سال هم با اوج بروز آن (دهه‌ی ۶ تا ۷) سازگار است.</p>\n<ul><li><strong>ب) <bdi>Pilocytic astrocytoma</bdi>:</strong> تومور خوش‌خیم (درجه‌ی ۱) کودکان با سلول‌های دوقطبی مومانند و <bdi>Rosenthal fiber</bdi> است و معمولاً نکروز و میتوز ندارد.</li><li><strong>ج) <bdi>Anaplastic astrocytoma</bdi>:</strong> آستروسیتوم درجه‌ی ۳ با سلولاریته و میتوز زیاد و شروع پرولیفراسیون عروقی است، ولی <strong>نکروز ندارد</strong>.</li><li><strong>د) <bdi>Well-differentiated astrocytoma</bdi>:</strong> درجه‌ی ۲ با سلولاریته و میتوز کم و بدون نکروز است.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی انتهای صورت سؤال («و میتوز فراوان») اضافه و ناقص نوشته شده است؛ این عبارت را باید یکی از ویژگی‌های توصیف‌شده در نمای میکروسکوپی خواند و پاسخ را تغییر نمی‌دهد.","lesson":"<div class=\"tw\"><table><thead><tr><th>درجه</th><th>نوع</th><th>ویژگی کلیدی</th></tr></thead><tbody><tr><td>۲</td><td>آستروسیتوم متمایز</td><td>سلولاریته‌ی کم، میتوز کم، بدون نکروز</td></tr><tr><td>۳</td><td>آناپلاستیک</td><td>سلولاریته و میتوز زیاد، شروع پرولیفراسیون عروقی، بدون نکروز</td></tr><tr><td>۴</td><td>گلیوبلاستوم</td><td>میتوز بسیار زیاد + نکروز (پالیسیدینگ) + پرولیفراسیون میکروواسکولار</td></tr></tbody></table></div>\n<ul><li>سه ویژگی <bdi>GBM</bdi>: میتوز بسیار زیاد، نکروز و پرولیفراسیون میکروواسکولار؛ هر چه تمایز کمتر، درجه بالاتر.</li><li>در طبقه‌بندی جدید <bdi>WHO</bdi> تفکیک نهایی <bdi>GBM</bdi> از آستروسیتوم درجه‌ی ۴ با ویژگی‌های مولکولی (مثل وضعیت <bdi>IDH</bdi>) انجام می‌شود، ولی در حد مورفولوژی <bdi>GBM</bdi> همان درجه‌ی ۴ است.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>نکروز یا پرولیفراسیون میکروواسکولار = <bdi>GBM</bdi>؛ آناپلاستیک (درجه‌ی ۳) نکروز ندارد.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش آستروسیتوم و گلیوبلاستوما</p>","steps":"<p>کلیدواژه‌ها: نکروز با <bdi>pseudopalisading</bdi>، پرولیفراسیون عروقی و پلئومورفیسم.</p>\n<p>نکروز یعنی درجه‌ی ۴؛ آستروسیتوم متمایز (درجه‌ی ۲) و آناپلاستیک (درجه‌ی ۳) نکروز ندارند.</p>\n<p>پیلوسیتیک تومور خوش‌خیم کودکان است و سن ۷۰ سال با آن نمی‌خواند.</p>\n<p>پس تشخیص گلیوبلاستوم است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>نکروز یا پرولیفراسیون میکروواسکولار = <bdi>GBM</bdi>؛ آناپلاستیک (درجه‌ی ۳) نکروز ندارد."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p4q15","session":"p4","full":false,"num":65,"text":"در بررسی <bdi>CSF</bdi> (بیمار مشکوک به منژیت) نتایج زیر مشاهده گردید: <bdi>lymphocytosis</bdi>, <bdi>moderate protein elevation</bdi>, <bdi>and a normal glucose level</bdi>. کدام عامل بیشتر مطرح می‌گردد؟","opts":["<bdi>Aseptic</bdi>(<bdi>Viral</bdi>) <bdi>Meningitis</bdi>","<bdi>pyogenic meningitis</bdi>","<bdi>Tuberculous Meningitis</bdi>","<bdi>meningitis chronic Spirochetal</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[9]},{"name":"تلفیقی 96A","nums":[25]}],"answer":0,"explain":"<p>افزایش <strong>لنفوسیت‌ها</strong>، <strong>افزایش متوسط پروتئین</strong> و <strong>گلوکز طبیعی</strong> الگوی کلاسیک <strong>مننژیت آسپتیک (ویروسی)</strong> است.</p>\n<ul><li><strong>ب) <bdi>Pyogenic meningitis</bdi>:</strong> <bdi>CSF</bdi> دارای نوتروفیل فراوان، پروتئین بسیار بالا و گلوکز پایین است.</li><li><strong>ج) <bdi>Tuberculous meningitis</bdi>:</strong> اگرچه سلول‌ها تک‌هسته‌ای هستند، پروتئین معمولاً به‌شدت بالا و گلوکز <strong>کاهش‌یافته</strong> است.</li><li><strong>د) <bdi>Chronic spirochetal meningitis</bdi> (مثل نوروسیفلیس):</strong> پیشرفتی مزمن و تحت‌حاد دارد و <bdi>CSF</bdi> تک‌هسته‌ای (لنفوسیت و پلاسماسل) با پروتئین بالا می‌دهد؛ ولی ترکیب «لنفوسیتوز + پروتئین متوسط + گلوکز طبیعی» در سؤال‌های مرسوم الگوی مننژیت آسپتیک (ویروسی) است.</li></ul>","flag":"","lesson":"<div class=\"tw\"><table><thead><tr><th>نوع</th><th>سلول <bdi>CSF</bdi></th><th>پروتئین</th><th>گلوکز</th></tr></thead><tbody><tr><td>چرکی (باکتریال حاد)</td><td>نوتروفیل</td><td>بسیار بالا</td><td>پایین</td></tr><tr><td>ویروسی (آسپتیک)</td><td>لنفوسیت</td><td>کمی تا متوسط بالا</td><td>طبیعی</td></tr><tr><td>مزمن (سل)</td><td>تک‌هسته‌ای</td><td>بالا (اغلب شدید)</td><td>پایین</td></tr></tbody></table></div>\n<ul><li>در مننژیت ویروسی فشار <bdi>CSF</bdi> طبیعی تا کمی بالاست و بیماری معمولاً خودمحدود است.</li><li>گلوکز <bdi>CSF</bdi> را با گلوکز هم‌زمان خون مقایسه می‌کنند؛ مصرف گلوکز توسط نوتروفیل و باکتری باعث افت آن می‌شود.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>لنفوسیتوز در <bdi>CSF</bdi> به‌تنهایی یعنی «ویروسی» نیست؛ گلوکز پایین و پروتئین بسیار بالا به سل و عفونت‌های مزمن می‌خورد.</p><p class=\"ref\">مرجع: <bdi>Robbins</bdi> (در جزوه نبود)</p>","steps":"<p>سه جزء <bdi>CSF</bdi> را بخوانید: لنفوسیتوز، پروتئین کمی تا متوسط بالا و گلوکز طبیعی.</p>\n<p>چرکی نوتروفیل و گلوکز پایین می‌دهد، پس حذف می‌شود.</p>\n<p>سل با گلوکز پایین و پروتئین بالاتر همراه است؛ گلوکز طبیعی با آن نمی‌خواند.</p>\n<p>مننژیت آسپتیک (ویروسی) الگوی کلاسیک این سه جزء است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>لنفوسیتوز در <bdi>CSF</bdi> به‌تنهایی یعنی «ویروسی» نیست؛ گلوکز پایین و پروتئین بسیار بالا به سل و عفونت‌های مزمن می‌خورد."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p4q16","session":"p4","full":false,"num":66,"text":"در بررسی هیستوپاتولوژی توده مخچه بیماری سلولهای گلیال با زوائد موئی در همراهی با <bdi>Rosenthal fibers</bdi>, <bdi>eosinophilic granular bodies</bdi> ساختارهایی رویت شد. کدام تشخیص مطرح می‌گردد؟","opts":["<bdi>pilocytic astrocytoma</bdi>","<bdi>Oligodendroglioma</bdi>","<bdi>Ependymoma</bdi>","<bdi>Medulloblastoma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی 96A","nums":[26]}],"answer":0,"explain":"<p>سلول‌های گلیال با <strong>زوائد مومانند (<bdi>hair-like</bdi>)</strong>، <strong><bdi>Rosenthal fibers</bdi></strong> و <strong><bdi>eosinophilic granular bodies</bdi></strong> در توده‌ی <strong>مخچه</strong> تصویر <strong>آستروسیتوم پیلوسیتیک</strong> (درجه‌ی ۱) است.</p>\n<ul><li><strong>ب) <bdi>Oligodendroglioma</bdi>:</strong> هسته‌ی گرد با هاله‌ی روشن (<bdi>fried egg</bdi>) و کلسیفیکاسیون در نیمکره‌های مخ (فرونتال و تمپورال) دارد.</li><li><strong>ج) <bdi>Ependymoma</bdi>:</strong> روزت و پری‌واسکولار سودوروزت دارد، نه <bdi>Rosenthal fiber</bdi>.</li><li><strong>د) <bdi>Medulloblastoma</bdi>:</strong> تومور امبریونال با سلول‌های کوچک آبی، میتوز زیاد و <bdi>Homer Wright rosette</bdi> است.</li></ul>","flag":"","lesson":"<ul><li>آستروسیتوم پیلوسیتیک: <bdi>WHO</bdi> درجه‌ی ۱، کودکان و جوانان، محل: مخچه، بطن سوم، مسیر بینایی، نخاع.</li><li>ماکروسکوپی: کیستیک با ندول جداری (<bdi>mural nodule</bdi>)؛ نکروز و میتوز معمولاً ندارد.</li><li>میکروسکوپی: سلول‌های <strong>دوقطبی</strong> مومانند (<bdi>GFAP</bdi> مثبت)، <strong><bdi>Rosenthal fibers</bdi></strong> (اجسام ائوزینوفیلیک) و <bdi>eosinophilic granular bodies</bdi>.</li><li>ژنتیک: جهش فعال‌کننده‌ی <strong><bdi>BRAF</bdi></strong>.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span><bdi>Rosenthal fiber</bdi> در این تومور مشخص‌ترین نشانه است، ولی تشخیص با مورفولوژی تنها کافی نیست (<bdi>IHC</bdi> و مولکولار).</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش آستروسیتوم پیلوسیتیک</p>","steps":"<p>کلیدواژه‌ها: مخچه، زوائد مومانند و <bdi>Rosenthal fiber</bdi>.</p>\n<p><bdi>Rosenthal fiber</bdi> و <bdi>eosinophilic granular body</bdi> ویژه‌ی آستروسیتوم پیلوسیتیک است.</p>\n<p>اپاندیموم روزت دارد و مدولوبلاستوما سلول کوچک آبی؛ الیگودندروگلیوم در مخ است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span><bdi>Rosenthal fiber</bdi> در این تومور مشخص‌ترین نشانه است، ولی تشخیص با مورفولوژی تنها کافی نیست (<bdi>IHC</bdi> و مولکولار)."],"dupOf":null,"dupNote":"","xrefs":["f15"]},{"id":"p4q17","session":"p4","full":false,"num":67,"text":"در میکروسکوپی تومور ندول مانند پوستی، وجود سلولهای دوکی با هسته مواج مخلوط با فیبروبلاستها در زمینه میکسوئید جلب نظر می‌کند. همچنین لابه لای سلولهای تومورال الیاف کلاژنهای (<bdi>carrot shavings</bdi>) وجود دارد. تشخیص کدامیک از گزینه‌های زیر می‌باشد؟","opts":["<bdi>PNET</bdi>","نوروفیبروم","شوانوم","<bdi>MPNST</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی پاییز ۱۴۰۰","nums":[7]}],"answer":1,"explain":"<p>تومور <strong>ندولی پوستی</strong> با سلول‌های دوکی با هسته‌ی مواج، مخلوط با فیبروبلاست‌ها در زمینه‌ی <strong>میکزوئید</strong> و <strong>کلاژن موج‌دار (<bdi>carrot shavings</bdi>)</strong> تصویر <strong>نوروفیبروم</strong> است؛ شوانوما فقط سلول شوان دارد، ولی نوروفیبروم ترکیبی از سلول شوان، فیبروبلاست‌مانند، ماست‌سل و سلول‌های شبیه پری‌نوریال است.</p>\n<ul><li><strong>الف) <bdi>PNET</bdi>:</strong> تومور امبریونال سلول‌های کوچک آبی است و نمای دوکی میکزوئید یا کلاژن موج‌دار ندارد.</li><li><strong>ج) شوانوم:</strong> کپسول‌دار با نواحی <bdi>Antoni A</bdi> و <bdi>B</bdi>، جسم <bdi>Verocay</bdi> و عروق هیالینیزه است؛ <bdi>carrot shavings</bdi> در آن ویژگی افتراقی نوروفیبروم است.</li><li><strong>د) <bdi>MPNST</bdi>:</strong> سلولاریته، پلئومورفیسم و میتوز زیاد و مرز نامشخص دارد؛ سؤال تومور ندولی خوش‌خیم با سلول‌های مواج بدون آتیپی را شرح می‌دهد.</li></ul>","flag":"","lesson":"<div class=\"tw\"><table><thead><tr><th>ویژگی</th><th>شوانوما</th><th>نوروفیبروما</th></tr></thead><tbody><tr><td>کپسول</td><td>دارد</td><td>ندارد</td></tr><tr><td>سلول‌ها</td><td>فقط سلول شوان</td><td>شوان + ماست‌سل + فیبروبلاست‌مانند + پری‌نوریال‌مانند</td></tr><tr><td>نمای اختصاصی</td><td><bdi>Antoni A/B</bdi>، <bdi>Verocay</bdi>، عروق هیالینیزه</td><td>کلاژن موج‌دار (<bdi>carrot shavings</bdi>)</td></tr><tr><td>ژنتیک</td><td><bdi>NF2</bdi> (دوطرفه‌ی وستیبولار)</td><td><bdi>NF1</bdi> (نوع پلکسی‌فورم)</td></tr></tbody></table></div>\n<ul><li>نوروفیبروم پلکسی‌فورم برای <bdi>NF1</bdi> پاتوگنومونیک است و منشأ شایع <bdi>MPNST</bdi> (حدود نیمی از <bdi>MPNST</bdi>ها در <bdi>NF1</bdi>).</li><li><bdi>MPNST</bdi>: <bdi>S100</bdi> و <bdi>SOX10</bdi> ضعیف و کانونی؛ در نوروفیبروم و شوانوما مثبت‌اند (در شوانوما قوی و منتشر).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span><bdi>carrot shavings</bdi> یعنی نوروفیبروم؛ <bdi>Verocay</bdi> و کپسول یعنی شوانوما.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش نوروفیبروما و شوانوما</p>","steps":"<p>کلیدواژه‌ی سؤال <bdi>carrot shavings</bdi> است.</p>\n<p>این کلاژن موج‌دار نوروفیبروما را از شوانوما جدا می‌کند.</p>\n<p><bdi>MPNST</bdi> آتیپی و میتوز زیاد دارد و <bdi>PNET</bdi> سلول کوچک آبی است.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span><bdi>carrot shavings</bdi> یعنی نوروفیبروم؛ <bdi>Verocay</bdi> و کپسول یعنی شوانوما."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p4q18","session":"p4","full":false,"num":68,"text":"در میکروسکوپی تومور منژیوم در آقای 45 ساله، تهاجم به مغز زیرین جلب نظر می‌کند. از نظر گریدینگ <bdi>WHO</bdi> به این تومور چه گریدی اطلاق می‌شود؟","opts":["گرید <bdi>II</bdi>","گرید <bdi>IV</bdi>","گرید <bdi>III</bdi>","گرید <bdi>I</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی پاییز ۱۴۰۰","nums":[18]}],"answer":0,"explain":"<p>بیشتر مننژیوم‌ها از مغز زیرین جدا می‌شوند، اما <strong>تهاجم به بافت مغز</strong> معیار افزایش درجه است. در <bdi>WHO 2021</bdi> نفوذ به مغز (<bdi>brain invasion</bdi>) به‌تنهایی مننژیوم را <strong>درجه‌ی ۲ (آتیپیک)</strong> می‌کند؛ مننژیوم درجه‌ی ۱ تودهٔ مرزدار متصل به دورا است که به مغز تهاجم نمی‌کند.</p>\n<ul><li><strong>ب) گرید <bdi>IV</bdi>:</strong> در طبقه‌بندی <bdi>WHO 2021</bdi> برای مننژیوم گرید ۴ وجود ندارد؛ بیشترین درجه ۳ است.</li><li><strong>ج) گرید <bdi>III</bdi>:</strong> مننژیوم آناپلاستیک (بدخیم) است و نیازمند میتوز بسیار زیاد (حداقل ۲۰ در ۱۰ <bdi>HPF</bdi>)، آناپلازی آشکار یا ویژگی‌های مولکولی (<bdi>TERT promoter</bdi>، <bdi>CDKN2A/B</bdi>) است، نه فقط تهاجم به مغز.</li><li><strong>د) گرید <bdi>I</bdi>:</strong> مرزدار، بدون تهاجم به مغز و دارای میتوز کم است.</li></ul>","flag":"","lesson":"<div class=\"tw\"><table><thead><tr><th>درجه</th><th>نوع</th><th>معیارها</th></tr></thead><tbody><tr><td>۱</td><td>خوش‌خیم</td><td>مرزدار، بدون تهاجم به مغز، میتوز کم</td></tr><tr><td>۲</td><td>آتیپیک</td><td>تهاجم به مغز، یا میتوز ۴ تا ۱۹ در ۱۰ <bdi>HPF</bdi>، یا دست‌کم ۳ مورد از ۵ ویژگی (هستک برجسته، سلولاریته‌ی بالا، رشد بدون الگو، سلول کوچک، نکروز)</td></tr><tr><td>۳</td><td>آناپلاستیک</td><td>میتوز ≥ ۲۰ در ۱۰ <bdi>HPF</bdi>، آناپلازی، (<bdi>TERT promoter</bdi> یا حذف <bdi>CDKN2A/B</bdi>)</td></tr></tbody></table></div>\n<ul><li>مننژیوم از سلول‌های مننگوتلیال آراکنوئید منشأ می‌گیرد؛ بیشتر بزرگسالان، با ارتباط <bdi>NF2</bdi> (جهش کروموزوم 22<bdi>q</bdi>).</li><li>تهاجم به مغز با افزایش خطر عود همراه است.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>تهاجم به مغز فقط درجه‌ی ۲ می‌کند؛ درجه‌ی ۳ برای میتوز و آناپلازی بسیار زیاد است.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش مننژیوم (اسلاید درجه‌بندی)؛ <bdi>WHO CNS 2021</bdi></p>","steps":"<p>تهاجم به بافت مغز در مننژیوم معیار افزایش درجه است.</p>\n<p>درجه‌ی ۱ تهاجم به مغز ندارد.</p>\n<p>درجه‌ی ۳ نیاز به میتوز بسیار زیاد یا آناپلازی دارد و درجه‌ی ۴ در مننژیوم تعریف نشده است.</p>\n<p>پس تهاجم به مغز یعنی آتیپیک، درجه‌ی ۲.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>تهاجم به مغز فقط درجه‌ی ۲ می‌کند؛ درجه‌ی ۳ برای میتوز و آناپلازی بسیار زیاد است."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p4q19","session":"p4","full":false,"num":69,"text":"کدام یک از انواع تومورهای مغزی بیشتر در سنین کودکی بروز پیدا می‌کند؟","opts":["<bdi>Meningiomas</bdi>","<bdi>pilocytic astrocytoma</bdi>","<bdi>Glioblastoma</bdi>","<bdi>oligodendroglioma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[7]}],"answer":1,"explain":"<p><strong>آستروسیتوم پیلوسیتیک</strong> (<bdi>WHO</bdi> درجه‌ی ۱) تومور خوش‌خیمی است که معمولاً در <strong>بچه‌ها</strong> و جوانان دیده می‌شود؛ بقیه‌ی گزینه‌ها تومورهای بزرگسالان‌اند.</p>\n<ul><li><strong>الف) <bdi>Meningiomas</bdi>:</strong> بیشتر در بزرگسالان (به‌ویژه زنان میانسال) دیده می‌شود.</li><li><strong>ج) <bdi>Glioblastoma</bdi>:</strong> شایع‌ترین تومور اولیه‌ی بدخیم مغز بزرگسالان با اوج بروز در دهه‌ی ۶ تا ۷ است.</li><li><strong>د) <bdi>Oligodendroglioma</bdi>:</strong> تومور نیمکره‌های مخ (فرونتال و تمپورال) در بزرگسالان است.</li></ul>","flag":"","lesson":"<ul><li>تومورهای شایع کودکی: آستروسیتوم پیلوسیتیک (مخچه، بطن سوم، مسیر بینایی) و مدولوبلاستوما (خط وسط مخچه) و اپاندیموم (بطن چهارم در دو دهه‌ی اول).</li><li>تومورهای شایع بزرگسالان: گلیوبلاستوم، مننژیوم، متاستاز، لنفوم اولیه‌ی <bdi>CNS</bdi>.</li><li>در کودکان حدود ۲۰ درصد تمام تومورها <bdi>CNS</bdi> هستند و مورفولوژی و محل تومورها با بزرگسالان فرق دارد.</li><li>پیلوسیتیک: <bdi>BRAF</bdi>، سلول دوقطبی و <bdi>Rosenthal fiber</bdi>.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span><bdi>GBM</bdi> و مننژیوم و الیگودندروگلیوم مربوط به بزرگسالان هستند؛ پیلوسیتیک تومور کودکان است.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش آستروسیتوم پیلوسیتیک</p>","steps":"<p>از بین گزینه‌ها دنبال تومور کودکان بگردید.</p>\n<p>مننژیوم، گلیوبلاستوم و الیگودندروگلیوم همه تومورهای بزرگسالان‌اند.</p>\n<p>آستروسیتوم پیلوسیتیک خوش‌خیم است و بیشتر در بچه‌ها دیده می‌شود.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span><bdi>GBM</bdi> و مننژیوم و الیگودندروگلیوم مربوط به بزرگسالان هستند؛ پیلوسیتیک تومور کودکان است."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p4q20","session":"p4","full":false,"num":70,"text":"در بررسی توده مخچه کودک 10 ساله‌ای نمای زیر دیده می‌شود: دستجات هایپرسلولار از سلولهای ئوپلاستیک که در آن سلولهای تومورال هسته هایپرکروم و سیتوپلاسم اندک دارند. همچنین میتوز فراوان و بصورت پراکنده ساختارهای روزت هومر (<bdi>Homer Wright or neuroballistic rosette</bdi>) نیز یافت می‌شود. کدام تشخیص مطرح می‌گردد؟","opts":["<bdi>Medulloblastoma</bdi>","<bdi>Glioblastoma</bdi>","<bdi>pilocytic astrocytoma</bdi>","<bdi>oligodendroglioma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[11]}],"answer":0,"explain":"<p>توده‌ی <strong>مخچه‌ی کودک ۱۰ ساله</strong> با سلول‌های <strong>هایپرسلولار</strong>، هسته‌ی هایپرکروم، سیتوپلاسم اندک، <strong>میتوز فراوان</strong> و <strong><bdi>Homer Wright rosette</bdi></strong> تصویر <strong>مدولوبلاستوما</strong> (تومور امبریونال) است.</p>\n<ul><li><strong>ب) <bdi>Glioblastoma</bdi>:</strong> تومور بزرگسالان با نکروز پالیسیدینگ و پرولیفراسیون میکروواسکولار است، نه روزت.</li><li><strong>ج) <bdi>Pilocytic astrocytoma</bdi>:</strong> سلول دوقطبی و <bdi>Rosenthal fiber</bdi> دارد و معمولاً میتوز ندارد.</li><li><strong>د) <bdi>Oligodendroglioma</bdi>:</strong> تومور بزرگسالان در نیمکره‌های مخ با نمای <bdi>fried egg</bdi> است.</li></ul>","flag":"","lesson":"<ul><li>مدولوبلاستوما: کودکان، خط وسط مخچه (در بزرگسالان بیشتر لترال).</li><li>«سلول کوچک آبی» (<bdi>small blue cell</bdi>): نسبت هسته به سیتوپلاسم بالا، میتوز بسیار زیاد؛ هر چه تمایز کمتر، درجه بالاتر.</li><li><strong><bdi>Homer Wright rosette</bdi></strong>: سلول‌ها دور تا دور، سیتوپلاسم در وسط، بدون لومن و بدون رگ.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>ساختار</th><th>تومور</th></tr></thead><tbody><tr><td><bdi>Homer Wright rosette</bdi></td><td>مدولوبلاستوما</td></tr><tr><td><bdi>Perivascular pseudorosette</bdi></td><td>اپاندیموم</td></tr><tr><td><bdi>Rosette</bdi> (لومن حقیقی)</td><td>اپاندیموم</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span><bdi>Homer Wright</bdi> (بدون لومن و رگ) = مدولوبلاستوما؛ پری‌واسکولار سودوروزت = اپاندیموم.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش تومورهای امبریونال و مدولوبلاستوما</p>","steps":"<p>کلیدواژه‌ها: کودک، مخچه، سلول کوچک هایپرکروم، میتوز فراوان و <bdi>Homer Wright rosette</bdi>.</p>\n<p><bdi>Homer Wright rosette</bdi> مشخصه‌ی مدولوبلاستوما است.</p>\n<p>گلیوبلاستوم و الیگودندروگلیوم تومورهای بزرگسالان‌اند و پیلوسیتیک میتوز ندارد.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span><bdi>Homer Wright</bdi> (بدون لومن و رگ) = مدولوبلاستوما؛ پری‌واسکولار سودوروزت = اپاندیموم."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p4q21","session":"p4","full":false,"num":71,"text":"در بررسی هیستوپاتولوژیک تومور مغزی خانم 50 ساله‌ای دستجات تومورال متشکل از سلولهای گرد و یک شکل بدون آتیپی و میتوز مشاهده گردید. همچنین تعداد فراوانی اجسام <bdi>psammoma</bdi> دیده میشود. کدام تشخیص مطرح می‌گردد؟","opts":["<bdi>Schwannomas</bdi>","<bdi>Glioblastoma</bdi>","<bdi>Meningioma</bdi>","<bdi>Medulloblastoma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[21]}],"answer":2,"explain":"<p>تومور مغزی <strong>زن ۵۰ ساله</strong> با دسته‌های سلولی یکنواخت بدون آتیپی و میتوز و تعداد زیاد <strong>اجسام <bdi>psammoma</bdi></strong> (کلسیفیکاسیون متحدالمرکز روی سلول‌های دژنره، <strong>نوع <bdi>psammomatous</bdi></strong>) تصویر <strong>مننژیوم</strong> درجه‌ی ۱ است.</p>\n<ul><li><strong>الف) <bdi>Schwannomas</bdi>:</strong> سلول اسپیندل با <bdi>Antoni A/B</bdi>، جسم <bdi>Verocay</bdi> و عروق هیالینیزه دارد، نه <bdi>psammoma</bdi> فراوان.</li><li><strong>ب) <bdi>Glioblastoma</bdi>:</strong> پلئومورفیسم، میتوز و نکروز فراوان دارد؛ این ویژگی‌ها در تصویر سؤال نیست.</li><li><strong>د) <bdi>Medulloblastoma</bdi>:</strong> تومور سلول کوچک آبی کودکان با میتوز زیاد است.</li></ul>","flag":"","lesson":"<ul><li>مننژیوم از سلول‌های مننگوتلیال (آراکنوئید) منشأ می‌گیرد؛ بیشتر بزرگسالان؛ مرزدار و متصل به دورا و جدا شدن آسان از مغز.</li><li>الگوها: سینسیشیال (گردابی، <bdi>whorled</bdi>)، فیبروبلاستیک، ترنزیشنال، <strong><bdi>psammomatous</bdi></strong>، سکرتوری (<bdi>PAS</bdi> مثبت، اجسام <bdi>pseudopsammoma</bdi>).</li><li><bdi>psammoma</bdi> یعنی کلسیفیکاسیون روی سلول‌های دژنره به‌صورت دوایر متحدالمرکز؛ وقتی یک میدان پر از آن باشد «<bdi>psammomatous</bdi>» می‌گوییم.</li><li>ارتباط با <bdi>NF2</bdi> (22<bdi>q</bdi>)؛ تومورهای <bdi>NF2</bdi>: شوانوما، مننژیوم و اپاندیموم.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>اجسام <bdi>psammoma</bdi> را به شوانوما یا تومورهای گلیال نسبت ندهید؛ «سلول یکنواخت + <bdi>psammoma</bdi> فراوان + زن بزرگسال» یعنی مننژیوم.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش مننژیوم</p>","steps":"<p>کلیدواژه‌ها: زن ۵۰ ساله، سلول‌های یکنواخت بدون آتیپی و اجسام <bdi>psammoma</bdi> فراوان.</p>\n<p><bdi>psammoma</bdi> در مننژیوم شایع است (نوع <bdi>psammomatous</bdi>).</p>\n<p><bdi>GBM</bdi> آتیپی و میتوز دارد، مدولوبلاستوما تومور کودکان است و شوانوما <bdi>Antoni A/B</bdi> دارد.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>اجسام <bdi>psammoma</bdi> را به شوانوما یا تومورهای گلیال نسبت ندهید؛ «سلول یکنواخت + <bdi>psammoma</bdi> فراوان + زن بزرگسال» یعنی مننژیوم."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p4q22","session":"p4","full":false,"num":72,"text":"در بررسی هیستوپاتولوژی تومور مغزی آقای 60 ساله‌ای صفحات سلولهای بزرگ پلئومورفیک همراه با نکروز با نمای <bdi>pseudo palisading nuclei</bdi> و خونریزی و پرولیفراسیون عروقی دیده می‌شود. کدام تشخیص مطرح می‌گردد؟","opts":["<bdi>pilocytic astrocytoma</bdi>","<bdi>Well-differentiated astrocytoma</bdi>","<bdi>Anaplastic astrocytoma</bdi>","<bdi>multiform Glioblastoma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[24]}],"answer":3,"explain":"<p>صفحات سلول‌های بزرگ <strong>پلئومورفیک</strong> همراه با <strong>نکروز با <bdi>pseudopalisading nuclei</bdi></strong>، <strong>خونریزی</strong> و <strong>پرولیفراسیون عروقی</strong> (میکروواسکولار) در بزرگسال ۶۰ ساله یعنی <strong>گلیوبلاستوم (آستروسیتوم درجه‌ی ۴)</strong>.</p>\n<ul><li><strong>الف) <bdi>Pilocytic astrocytoma</bdi>:</strong> تومور خوش‌خیم درجه‌ی ۱ کودکان با سلول دوقطبی و <bdi>Rosenthal fiber</bdi> است و نکروز و میتوز ندارد.</li><li><strong>ب) <bdi>Well-differentiated astrocytoma</bdi>:</strong> درجه‌ی ۲ با سلولاریته و میتوز کم و بدون نکروز است.</li><li><strong>ج) <bdi>Anaplastic astrocytoma</bdi>:</strong> درجه‌ی ۳ با میتوز و پلئومورفیسم زیاد و شروع پرولیفراسیون عروقی است، اما نکروز ندارد.</li></ul>","flag":"","lesson":"<ul><li>سه ویژگی <bdi>GBM</bdi>: میتوز بسیار زیاد، نکروز (اغلب با هسته‌های پالیسیدینگ) و پرولیفراسیون میکروواسکولار.</li><li>ماکروسکوپی: انفیلتراتیو و بدون مرز مشخص؛ نکروز و خونریزی دارد (نواحی زرد و قرمز).</li><li><bdi>GBM</bdi> همان آستروسیتوم درجه‌ی ۴ است؛ هر چه تمایز کمتر، تومور بدتر و میتوز بیشتر.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>درجه</th><th>تومور</th></tr></thead><tbody><tr><td>۱</td><td>پیلوسیتیک</td></tr><tr><td>۲</td><td>آستروسیتوم متمایز</td></tr><tr><td>۳</td><td>آناپلاستیک</td></tr><tr><td>۴</td><td>گلیوبلاستوم</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>اگر در سؤال «نکروز» ذکر شده، گزینه‌ی آناپلاستیک (درجه‌ی ۳) را کنار بگذارید.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش آستروسیتوم و گلیوبلاستوما</p>","steps":"<p>کلیدواژه‌ها: نکروز با <bdi>pseudopalisading</bdi>، خونریزی و پرولیفراسیون عروقی.</p>\n<p>این سه‌گانه برای گلیوبلاستوم (درجه‌ی ۴) است.</p>\n<p>آناپلاستیک و آستروسیتوم متمایز نکروز ندارند و پیلوسیتیک خوش‌خیم کودکان است.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>اگر در سؤال «نکروز» ذکر شده، گزینه‌ی آناپلاستیک (درجه‌ی ۳) را کنار بگذارید."],"dupOf":null,"dupNote":"","xrefs":[]},{"id":"p4q23","session":"p4","full":false,"num":73,"text":"در بررسی هیستوپاتولوژی تومور بطن چهارم مغز پسر بچه 7 ساله‌ای سلولهای تومورال با هسته‌های گرد و منظم با کروماتین گرانولار به همراه ساختارهای <bdi>Rosettes</bdi> & <bdi>perivascular pseudorosettes</bdi> رویت شد. کدام تشخیص مطرح می‌گردد؟","opts":["<bdi>pilocytic astrocytoma</bdi>","<bdi>Glioblastoma</bdi>","<bdi>oligodendroglioma</bdi>","<bdi>Ependymoma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۰","nums":[26]}],"answer":3,"explain":"<p>تومور <strong>بطن چهارم</strong> در <strong>کودک ۷ ساله</strong> با هسته‌های گرد و منظم، کروماتین گرانولار و <strong><bdi>rosette</bdi></strong> و <strong><bdi>perivascular pseudorosette</bdi></strong> تصویر <strong>اپاندیموم</strong> است.</p>\n<ul><li><strong>الف) <bdi>Pilocytic astrocytoma</bdi>:</strong> سلول دوقطبی مومانند و <bdi>Rosenthal fiber</bdi> دارد و روزت و پری‌واسکولار سودوروزت ندارد.</li><li><strong>ب) <bdi>Glioblastoma</bdi>:</strong> تومور بزرگسالان با نکروز پالیسیدینگ و میتوز زیاد است.</li><li><strong>ج) <bdi>Oligodendroglioma</bdi>:</strong> تومور نیمکره‌های مخ با نمای <bdi>fried egg</bdi> است و بطن چهارم محل آن نیست.</li></ul>","flag":"","lesson":"<ul><li>اپاندیموم: در دو دهه‌ی اول زندگی معمولاً <strong>بطن چهارم</strong>؛ در بزرگسالان نخاع (ارتباط با <bdi>NF2</bdi>).</li><li>ماکروسکوپی: توده‌ی سالید و پاپیلری در بطن چهارم که ممکن است به کف بطن گسترش یابد.</li><li>میکروسکوپی: هسته‌ی گرد تا بیضی، کروماتین گرانولار، زمینه‌ی فیبریلری.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>ساختار</th><th>توضیح</th></tr></thead><tbody><tr><td>پری‌واسکولار سودوروزت</td><td>زوائد سیتوپلاسمی بدون هسته به سمت لومن رگ</td></tr><tr><td><bdi>Rosette</bdi></td><td>زوائد به سمت لومن حقیقی (بدون رگ)</td></tr></tbody></table></div>\n<ul><li>درجه‌ی بالا (آناپلاستیک): سلولاریته، میتوز و نکروز بیشتر.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>سودوروزت = دور رگ، روزت = دور لومن حقیقی؛ <bdi>Homer Wright</bdi> (بدون لومن) مربوط به مدولوبلاستوما است.</p><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش اپاندیموم</p>","steps":"<p>کلیدواژه‌ها: بطن چهارم، کودک، <bdi>rosette</bdi> و <bdi>perivascular pseudorosette</bdi>.</p>\n<p>این ساختارها مخصوص اپاندیموم است.</p>\n<p>پیلوسیتیک، <bdi>GBM</bdi> و الیگودندروگلیوم این ساختارها را ندارند.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>سودوروزت = دور رگ، روزت = دور لومن حقیقی؛ <bdi>Homer Wright</bdi> (بدون لومن) مربوط به مدولوبلاستوما است."],"dupOf":null,"dupNote":"","xrefs":["f09","p4q10"]},{"id":"p4q24","session":"p4","full":false,"num":74,"text":"شایع‌ترین لنفوم مغزی چیست؟","opts":["<bdi>Diffuse large B-cell lymphoma</bdi>","<bdi>Hodgkin lymphoma</bdi>","<bdi>Follicular lymphoma</bdi>","<bdi>Burkitt lymphoma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۱","nums":[]}],"answer":0,"explain":"<p>در منبع آزمون فقط صورت این سوال چاپ شده بود و گزینه‌ها نیامده بود؛ گزینه‌ها را برای تمرین خودمان ساخته‌ایم.</p>\n<p>طبق جزوه، لنفوم اولیه‌ی مغز معمولاً از نوع <strong><bdi>Large B-cell lymphoma</bdi></strong> است؛ یعنی شایع‌ترین لنفوم مغزی <strong><bdi>Diffuse large B-cell lymphoma</bdi> (<bdi>DLBCL</bdi>)</strong> است و بیشتر در افراد با <strong>نقص ایمنی</strong> و مرتبط با <strong><bdi>EBV</bdi></strong> دیده می‌شود.</p>\n<ul><li><strong>ب) <bdi>Hodgkin lymphoma</bdi>:</strong> لنفوم هوچکین به‌ندرت <bdi>CNS</bdi> را به‌صورت اولیه درگیر می‌کند؛ لنفوم اولیه‌ی مغز طبق جزوه از نوع <bdi>Large B-cell</bdi> است.</li><li><strong>ج) <bdi>Follicular lymphoma</bdi>:</strong> لنفوم ندولار و تنبل گره‌های لنفاوی است؛ لنفوم اولیه‌ی <bdi>CNS</bdi> شایع‌ترین نوعش نیست.</li><li><strong>د) <bdi>Burkitt lymphoma</bdi>:</strong> جزوه تأکید می‌کند هر <bdi>Large B-cell</bdi> را برکیت نمی‌گوییم؛ برکیت نمای <strong><bdi>Starry Sky</bdi></strong> و بازآرایی <bdi>c-MYC</bdi> با <bdi>Ki-67</bdi> بسیار بالا دارد و نوع شایع لنفوم مغزی نیست.</li></ul>","flag":"","lesson":"<ul><li><strong>لنفوم اولیه‌ی <bdi>CNS</bdi>:</strong> شایع‌ترین نئوپلاسم <bdi>CNS</bdi> در افراد با نقص ایمنی؛ تقریباً همیشه <strong><bdi>EBV</bdi> مثبت</strong> در بیماران دچار نقص ایمنی. ۱ درصد تومورهای داخل جمجمه و ۲ درصد لنفوم‌های خارج‌گره‌ای.</li><li>بیشتر بیماران <strong>بالای ۶۰ سال</strong>؛ بیماری تهاجمی با پاسخ نسبتاً ضعیف؛ اغلب چند ندول تومورال در پارانشیم مغز؛ محل: ساختارهای عمقی (ماده‌ی خاکستری، ماده‌ی سفید، کورتکس) و اغلب اطراف بطن؛ در تومورهای مرتبط با <bdi>EBV</bdi> نواحی وسیع <strong>نکروز</strong>.</li><li><strong>ریزنما (بسیار مهم):</strong> سلول‌های <strong>مونومورف</strong> که <strong>دور رگ</strong> تجمع می‌کنند؛ آن را با <strong>سودوروزت اپاندیموم</strong> اشتباه نگیرید (در سودوروزت زوائد بدون هسته‌ی سلول‌های اپاندیمال به سمت رگ آمده‌اند).</li></ul>\n<div class=\"tw\"><table><thead><tr><th>ویژگی</th><th><bdi>DLBCL</bdi></th><th><bdi>Burkitt</bdi></th></tr></thead><tbody><tr><td>سلول منشأ</td><td><bdi>B-cell</bdi>، <bdi>CD20</bdi> مثبت</td><td><bdi>B-cell</bdi>، <bdi>CD20</bdi> مثبت</td></tr><tr><td>نما</td><td>سلول‌های بزرگ؛ دور رگ در <bdi>CNS</bdi></td><td><strong><bdi>Starry Sky</bdi></strong>؛ بازآرایی <bdi>c-MYC</bdi>؛ <bdi>Ki-67</bdi> بسیار بالا</td></tr><tr><td>نکته</td><td>شایع‌ترین لنفوم اولیه‌ی <bdi>CNS</bdi></td><td>هر <bdi>Large B-cell</bdi> برکیت نیست</td></tr></tbody></table></div>\n<ul><li>طبق جزوه: <bdi>Ki-67</bdi> بسیار بالا + میتوز زیاد + نمای <bdi>Starry Sky</bdi> ← برکیت؛ <bdi>Large B-cell</bdi> با ویژگی‌های مولکولی خاص (بازآرایی <bdi>c-MYC</bdi>، <bdi>BCL-2</bdi>، <bdi>BCL-6</bdi>) ← <strong><bdi>High-grade large B-cell</bdi></strong>؛ این‌ها را باید بررسی کرد.</li><li>تشخیص افتراقی تصویربرداری در ایدز: توکسوپلاسموز (ضایعات حلقه‌ای)؛ درمان لنفوم اولیه‌ی <bdi>CNS</bdi> با متوترکسات با دوز بالا (<bdi>high-dose methotrexate</bdi>) است (<bdi>Robbins</bdi>/بالین).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: هر لنفوم تهاجمی با سلول بزرگ و <bdi>Ki-67</bdi> بالا را «برکیت» نامیدن؛ و فکر کردن «لنفوم مغزی = هوچکین».</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) شایع‌ترین نوع لنفوم اولیه‌ی <bdi>CNS</bdi>؟ (۲) لنفوم اولیه‌ی مغز با کدام ویروس مرتبط است؟ (۳) تجمع سلول‌های مونومورف دور رگ در کدام تومور <bdi>CNS</bdi>؟ (۴) تفاوت سودوروزت اپاندیموم با لنفوم چیست؟</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش «لنفوم اولیه‌ی <bdi>CNS</bdi> و تومورهای متاستاتیک» (نوع <bdi>Large B-cell</bdi>، ارتباط با <bdi>EBV</bdi> و نقص ایمنی، تجمع سلول‌ها دور رگ، تفاوت با برکیت). مرجع: <bdi>Robbins</bdi> (در جزوه نبود) برای محل، درمان و تشخیص افتراقی تصویربرداری.</p>","steps":"<p>کلیدواژه‌ی سوال «شایع‌ترین لنفوم مغزی» است؛ جزوه می‌گوید لنفوم اولیه‌ی مغز معمولاً از نوع <bdi>Large B-cell lymphoma</bdi> است.</p>\n<p>پس شایع‌ترین نوع <bdi>Diffuse large B-cell lymphoma</bdi> است و در افراد با نقص ایمنی و مرتبط با <bdi>EBV</bdi> بیشتر دیده می‌شود.</p>\n<p>هوچکین و فولیکولار نوع شایع لنفوم اولیه‌ی <bdi>CNS</bdi> نیستند.</p>\n<p>برکیت نمای <bdi>Starry Sky</bdi> و بازآرایی <bdi>c-MYC</bdi> دارد؛ جزوه تأکید می‌کند هر <bdi>Large B-cell</bdi> را برکیت نمی‌گوییم.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: هر لنفوم تهاجمی با سلول بزرگ و <bdi>Ki-67</bdi> بالا را «برکیت» نامیدن؛ و فکر کردن «لنفوم مغزی = هوچکین»."],"dupOf":null,"dupNote":"","xrefs":["p4q13"]},{"id":"p4q25","session":"p4","full":false,"num":75,"text":"احتمال عفونت با کدام ویروس در مبتلایان به لنفوم مغزی بیشتر است؟","opts":["<bdi>Cytomegalovirus</bdi> (<bdi>CMV</bdi>)","<bdi>Epstein-Barr virus</bdi> (<bdi>EBV</bdi>)","<bdi>Herpes simplex virus</bdi> (<bdi>HSV</bdi>)","<bdi>Human papillomavirus</bdi> (<bdi>HPV</bdi>)"],"labels":["الف","ب","ج","د"],"exams":[{"name":"تلفیقی بهار ۱۴۰۱","nums":[]}],"answer":1,"explain":"<p>در منبع آزمون فقط صورت این سوال چاپ شده بود و گزینه‌ها نیامده بود؛ گزینه‌ها را برای تمرین خودمان ساخته‌ایم.</p>\n<p>طبق جزوه، <strong>لنفوم اولیه‌ی مغز</strong> بیشتر در افراد با نقص ایمنی دیده می‌شود و با <strong>ویروس <bdi>EBV</bdi></strong> ارتباط دارد (در بیماران دچار نقص ایمنی تقریباً همیشه <bdi>EBV</bdi> مثبت)؛ پس ویروس مورد نظر <strong><bdi>EBV</bdi></strong> است.</p>\n<ul><li><strong>الف) <bdi>CMV</bdi>:</strong> در بیماران با نقص ایمنی (ایدز) رتینیت و انسفالیت ایجاد می‌کند، ولی عامل لنفوم مغزی نیست.</li><li><strong>ج) <bdi>HSV</bdi>:</strong> عامل انسفالیت (به‌ویژه درگیری لوب تمپورال) است، نه لنفوم.</li><li><strong>د) <bdi>HPV</bdi>:</strong> با زگیل و سرطان‌های سنگفرشی دهانه‌ی رحم و اوروفارنکس مرتبط است؛ ارتباطی با لنفوم مغزی ندارد.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی عبارت «احتمال عفونت» در صورت سوال مبهم است؛ آن را به‌صورت «کدام ویروس با لنفوم اولیه‌ی مغز (<bdi>CNS</bdi>) همراه است» خوانده‌ایم.","lesson":"<ul><li><strong>لنفوم اولیه‌ی <bdi>CNS</bdi>:</strong> بیشتر <strong><bdi>Large B-cell</bdi></strong> (<bdi>DLBCL</bdi>)، شایع‌ترین نئوپلاسم <bdi>CNS</bdi> در نقص ایمنی؛ در این افراد <strong>تقریباً همیشه <bdi>EBV</bdi> مثبت</strong>؛ سن بیشتر بالای ۶۰ سال. بدون نقص ایمنی معمولاً <bdi>EBV</bdi> منفی است (<bdi>Robbins</bdi>).</li><li>در تومورهای مرتبط با <bdi>EBV</bdi> نواحی وسیع <strong>نکروز</strong> دیده می‌شود؛ ریزنما: تجمع سلول‌های مونومورف دور رگ (نه سودوروزت).</li></ul>\n<div class=\"tw\"><table><thead><tr><th>ویروس</th><th>تومور / بیماری مرتبط</th></tr></thead><tbody><tr><td><bdi>EBV</bdi></td><td>لنفوم اولیه‌ی <bdi>CNS</bdi> (نقص ایمنی)، لنفوم برکیت (آندمیک)، هوچکین، کارسینوم نازوفارنکس، لنفوم پس از پیوند (<bdi>PTLD</bdi>)</td></tr><tr><td><bdi>HHV8</bdi></td><td>سارکوم کاپوزی (جزوه‌ی بافت نرم)</td></tr><tr><td><bdi>HPV</bdi></td><td>کارسینوم دهانه‌ی رحم و اوروفارنکس</td></tr><tr><td><bdi>HTLV-1</bdi></td><td>لوسمی/لنفوم <bdi>T</bdi> بزرگسالان</td></tr><tr><td><bdi>CMV</bdi></td><td>رتینیت و انسفالیت در نقص ایمنی</td></tr><tr><td><bdi>HSV</bdi></td><td>انسفالیت لوب تمپورال</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: انتخاب ویروس‌هایی که در بیماران ایدزی <bdi>CNS</bdi> را درگیر می‌کنند (<bdi>CMV/HSV/JC</bdi>) به‌جای ویروس مولد لنفوم؛ «بیماری <bdi>CNS</bdi> در ایدز» با «تومور <bdi>CNS</bdi> در ایدز» فرق دارد.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) لنفوم اولیه‌ی مغز در بیمار ایدزی با کدام ویروس همراه است؟ (۲) کدام ویروس با برکیت و کارسینوم نازوفارنکس مرتبط است؟ (۳) کدام ویروس با سارکوم کاپوزی همراه است؟ (۴) کدام ویروس در لنفوم‌های پس از پیوند عضو (<bdi>PTLD</bdi>) نقش دارد؟</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش لنفوم اولیه‌ی <bdi>CNS</bdi> (ارتباط با <bdi>EBV</bdi> در افراد دچار نقص ایمنی). مرجع: <bdi>Robbins</bdi> (در جزوه نبود) برای مقایسه با سایر ویروس‌های انکوژن و بیماری‌زای <bdi>CNS</bdi>؛ جزوه‌ی بافت نرم برای <bdi>HHV8</bdi> و کاپوزی.</p>","steps":"<p>کلیدواژه‌ی سوال «ویروس» و «لنفوم مغزی» است؛ یعنی کدام ویروس با لنفوم اولیه‌ی <bdi>CNS</bdi> ارتباط دارد.</p>\n<p>در جزوه آمده: لنفوم اولیه‌ی مغز بیشتر در افراد با نقص ایمنی است و با <bdi>EBV</bdi> ارتباط دارد.</p>\n<p><bdi>CMV</bdi> و <bdi>HSV</bdi> عامل عفونت‌های <bdi>CNS</bdi> (رتینیت/انسفالیت) هستند، نه لنفوم.</p>\n<p><bdi>HPV</bdi> با سرطان‌های سنگفرشی (دهانه‌ی رحم، اوروفارنکس) مرتبط است و به لنفوم مغزی ربطی ندارد.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: انتخاب ویروس‌هایی که در بیماران ایدزی <bdi>CNS</bdi> را درگیر می‌کنند (<bdi>CMV/HSV/JC</bdi>) به‌جای ویروس مولد لنفوم؛ «بیماری <bdi>CNS</bdi> در ایدز» با «تومور <bdi>CNS</bdi> در ایدز» فرق دارد."],"dupOf":null,"dupNote":"","xrefs":["p4q13"]},{"id":"f01","session":"full","full":true,"num":1,"text":"تومور بافت نرم آقای 50 ساله در برش میکروسکوپی دارای ماده زمینه ای فراوان و یک شبکه مویرگی غنی که در ان سلولهای چربی نابالغ به صورت پراکنده و سلولهای ابتدایی تر ستاره ای شکل قرار دارند تشخیص کدام است ؟","opts":["لیپوسارکوم با تمایز خوب","لیپوسارکوم میگزوئید","لیپوسارکوم پلئومورفیک","لیپوم"],"labels":["الف","ب","ج","د"],"exams":[],"answer":1,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی ۲۰ مهر ۱۴۰۱ (سوال 14)</p><p>کلیدواژه‌ی «میگزوئید لیپوسارکوم» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p>در بیمار ۵۰ ساله، زمینه‌ی <strong>میکزوئید</strong> (شل و ول و کم‌رنگ آبی‌مایل) فراوان، <strong>عروق شبکه‌ی مرغی</strong> و <strong>لیپوبلاست‌ها</strong> (واکوئل‌دار با هسته‌ی بزرگ‌تر از سلول چربی)، تصویر کلاسیک <strong>لیپوسارکوم میکزوئید</strong> است.</p>\n<ul><li><strong>الف) و ج) سایر انواع لیپوسارکوم:</strong> جزوه سه‌گانه‌ی لیپوبلاست + عروق شبکه‌ی مرغی + زمینه‌ی میکزوئید را فقط برای نوع میکزوئید آورده است و <bdi>t</bdi>(12;16) هم فقط به نوع «میکزوئید و سلول گرد» نسبت داده شده است.</li><li><strong>د) لیپوم:</strong> تومور خوش‌خیم است که همه‌ی سلول‌هایش مثل چربی طبیعی با هسته‌ی کوچک کناری‌اند؛ لیپوبلاست و زمینه‌ی میکزوئید ندارد.</li></ul>","flag":"","lesson":"<ul><li><strong>لیپوم</strong> شایع‌ترین تومور بافت نرم و خوش‌خیم است: توده‌ی زرد، با کپسول بسیار نازک، کاملاً شبیه چربی طبیعی؛ زیر میکروسکوپ همه‌ی سلول‌ها شبیه چربی‌اند با هسته‌ی بسیار کوچک کنار سلول. انواع لیپوم همه خوش‌خیم‌اند (حتی اگر غضروف یا مغز استخوان داشته باشند).</li><li><strong>لیپوسارکوم</strong> همتای بدخیم لیپوم است و انواع مختلف دارد؛ آنچه استاد توضیح داد <strong>لیپوسارکوم میکزوئید</strong> است.</li><li><strong>محل:</strong> محل اصلی لیپوسارکوم <strong>رتروپریتوئن</strong> است (توده‌ی بزرگ رتروپریتوئن می‌سازد)؛ ممکن است جاهای دیگر مثل اندام تحتانی هم باشد.</li><li><strong>لیپوبلاست:</strong> برخلاف لیپوم، در سارکوم سلول‌هایی هستند که در سیتوپلاسم واکوئل دارند و می‌کوشند شبیه سلول چربی شوند، اما <strong>هسته‌ی بزرگ‌تر</strong> از لیپوسیتِ با هسته‌ی کوچک کناری دارند.</li><li><strong>زمینه:</strong> میکزوئید = <strong>شل و ول و کم‌رنگ آبی‌مایل</strong>.</li><li><strong>عروق:</strong> عروقی شبیه توری لانه‌ی مرغ = <strong>عروق شبکه‌ی مرغی (<bdi>chicken-wire vessels</bdi>)</strong>.</li><li><strong>«نکات تأکیدی استاد»:</strong> لیپوسارکوم میکزوئید <strong>سه جزء</strong> دارد: <strong>لیپوبلاست، عروق شبکه‌ی مرغی و استرومای میکزوئید</strong>؛ محل اصلی آن رتروپریتوئن است.</li><li><strong>ژنتیک:</strong> در جدول ترنسلوکیشن‌ها، لیپوسارکوم <strong>نوع میکزوئید و سلول گرد</strong> با <strong><bdi>t</bdi>(12;16)(<bdi>q13</bdi>;<bdi>p11</bdi>)</strong> و ژن همجوش <strong><bdi>CHOP/TLS</bdi></strong> آمده است.</li><li>در همان جدول، برای مقایسه: سینوویال سارکوم <bdi>t</bdi>(<bdi>X</bdi>;18) (<bdi>SYT-SSX</bdi>)؛ رابدومیوسارکوم آلوئولار <bdi>t</bdi>(2;13) (<bdi>PAX3-FKHR</bdi>)؛ سارکوم یوئینگ <bdi>t</bdi>(11;22) (<bdi>EWS-FLI1</bdi>).</li></ul>\n<div class=\"tw\"><table><thead><tr><th>تومور</th><th>نکته‌ی شاخص</th></tr></thead><tbody><tr><td>لیپوم</td><td>همه‌ی سلول‌ها شبیه چربی، هسته‌ی کوچک کناری، کپسول نازک، خوش‌خیم</td></tr><tr><td>لیپوسارکوم</td><td>لیپوبلاست (واکوئل + هسته‌ی بزرگ‌تر)، محل اصلی رتروپریتوئن</td></tr><tr><td>لیپوسارکوم میکزوئید</td><td>لیپوبلاست + عروق شبکه‌ی مرغی + زمینه‌ی میکزوئید؛ <bdi>t</bdi>(12;16)</td></tr></tbody></table></div>\n<ul><li>جزوه یادآوری می‌کند که لیپوسارکومِ پلئومورفیک‌شده یا دی‌دیفرانسیه‌شده شبیه سارکوم پلئومورفیک تمایزنیافته می‌شود.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: دیدن «چربی» در تومور را لیپوم گرفتن؛ در لیپوم همه‌ی سلول‌ها چربی بالغ‌اند و لیپوبلاست یا زمینه‌ی میکزوئید دیده نمی‌شود.</p>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>سه جزء میکزوئید (لیپوبلاست، شبکه‌ی مرغی، استرومای میکزوئید) را با هم بخوانید؛ <bdi>t</bdi>(12;16) به نوع میکزوئید/سلول گرد مربوط است.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) تصویر بافت‌شناسی با زمینه‌ی میکزوئید، لیپوبلاست و عروق ظریف؛ (۲) کدام لیپوسارکوم با <bdi>t</bdi>(12;16) همراه است؟ (۳) عروق شبکه‌ی مرغی (<bdi>chicken-wire</bdi>) در کدام تومور چربی؛ (۴) سه جزء لیپوسارکوم میکزوئید؛ (۵) محل اصلی لیپوسارکوم؛ (۶) کدام یافته در لیپوم دیده نمی‌شود؟</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی تومورهای استخوان و بافت نرم (دکتر پناهی)، بخش لیپوم و لیپوسارکوم (لیپوسارکوم میکزوئید، لیپوبلاست، عروق شبکه‌ی مرغی، جدول ترنسلوکیشن‌های سارکوم‌ها).</p>","steps":"<p>در صورت سوال دنبال سه سرنخ بگردید: «ماده‌ی زمینه‌ای فراوان» (میکزوئید)، «شبکه‌ی مویرگی غنی» (عروق شبکه‌ی مرغی) و «سلول‌های چربی نابالغ» (لیپوبلاست).</p>\n<p>هر سه با یک تومور بدخیم چربی می‌خواند، پس لیپوم (د) که فقط چربی بالغ دارد حذف می‌شود.</p>\n<p>الف و ج از انواع دیگر لیپوسارکوم‌اند، ولی سه‌گانه‌ی لیپوبلاست + عروق شبکه‌ی مرغی + زمینه‌ی میکزوئید در جزوه ویژه‌ی نوع میکزوئید است.</p>\n<p>زمینه‌ی میکزوئید + عروق ظریف + لیپوبلاست = لیپوسارکوم میکزوئید.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: دیدن «چربی» در تومور را لیپوم گرفتن؛ در لیپوم همه‌ی سلول‌ها چربی بالغ‌اند و لیپوبلاست یا زمینه‌ی میکزوئید دیده نمی‌شود.","<span class=\"tag\">نکته‌ی دام</span>سه جزء میکزوئید (لیپوبلاست، شبکه‌ی مرغی، استرومای میکزوئید) را با هم بخوانید؛ <bdi>t</bdi>(12;16) به نوع میکزوئید/سلول گرد مربوط است."],"dupOf":null,"dupNote":"","xrefs":["p3q10"]},{"id":"f02","session":"full","full":true,"num":2,"text":"در کدامیک از بیماری‌های زیر حجم استخوان افزایش می‌یابد؟","opts":["ریکتز","آکندروپلازی","پاژه","استئوژنز ایمپرفکتا"],"labels":["الف","ب","ج","د"],"exams":[],"answer":2,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی پاییز ۱۴۰۰ (سوال 13) — تلفیقی بهار ۱۴۰۰ (سوال 13) — تلفیقی 96A (سوال 14)</p><p>کلیدواژه‌ی «پاژه: افزایش حجم استخوان» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p>در <strong>بیماری پاژه (<bdi>osteitis deformans</bdi>)</strong> فعالیت نابه‌جا و تکراری استئوکلاست و سپس استئوبلاست باعث <strong>افزایش توده/حجم استخوان</strong> می‌شود، ولی استخوان تازه نامنظم، ضخیم و بی‌استحکام است (استخوان موزاییکی/جیگساو).</p>\n<ul><li><strong>الف) ریکتز:</strong> نقص مینرالیزاسیون صفحه‌ی رشد به‌علت کمبود ویتامین <bdi>D</bdi> است؛ استخوان نرم می‌ماند (تجمع استئوئید بدون کلسیم)، نه اینکه حجم واقعی استخوان معدنی‌شده زیاد شود.</li><li><strong>ب) آکندروپلازی:</strong> ژنِ لازم برای ساخت غضروف صفحه‌ی رشد معیوب است، الگو ساخته نمی‌شود و استخوان‌سازی اندوکندرال کند یا ناممکن می‌شود؛ نتیجه کوتولگی است، نه افزایش حجم.</li><li><strong>د) استئوژنزیس ایمپرفکتا:</strong> نقص کلاژن تیپ ۱ است؛ استخوان شکننده با شکستگی‌های مکرر، نه افزایش توده.</li></ul>","flag":"","lesson":"<ul><li><strong>تعریف (جزوه):</strong> افزایش توده‌ی استخوانی، ولی استخوان تازه‌ساخته <strong>نامنظم و بدون استحکام</strong> است؛ دوره‌های مکرر فعالیت استئوکلاستی منطقه‌ای و تخریب استخوان که با <strong>تشکیل پرحرارت استخوان</strong> دنبال می‌شود و در پایان فعالیت سلولی تمام می‌شود (مرحله‌ی «سوخته» <bdi>burned-out</bdi>). استخوان ظاهراً متراکم ولی بی‌فایده است: «استخوان جیگساو/موزاییکی». بیماری با <strong>اختلال عملکرد استئوکلاست</strong> شروع می‌شود.</li><li><strong>سن:</strong> میانسالی؛ شیوع در جمعیت‌های مختلف بسیار متفاوت است.</li><li><strong>سه مرحله:</strong> ۱) <strong>لیتیک</strong> (استئوکلاست‌های متعدد و بزرگ، تخریب شدید) ← ۲) <strong>مختلط</strong> (استئوبلاست‌های برجسته و بسیار فعال، کلاژن فراوان با حاشیه‌ی نامنظم، مغز استخوان جایگزین‌شده با بافت همبند شل) ← ۳) <strong>اسکلروتیک</strong> (استخوان متراکم ولی ضعیف و نامنظم، پایان فعالیت سلولی). مراحل ممکن است هم‌زمان در بخش‌های مختلف یک استخوان باشند.</li><li><strong>بافت‌شناسی:</strong> <strong>خطوط سیمانی (<bdi>cement lines</bdi>) نامنظم</strong> و <strong>الگوی موزاییکی (<bdi>mosaic</bdi>)</strong> = مشخصه‌ی پاتوگنومونیک بافت‌شناسی (ولی تشخیص معمولاً قبل از آن با رادیوگرافی و آزمایش خون گذاشته می‌شود).</li><li><strong>پاتوژنز:</strong> علت ناشناخته؛ عفونت با پارامیکسوویروس (ترشح <bdi>IL-1</bdi> و <bdi>M-CSF</bdi> از سلول‌های آلوده ← فعال شدن استئوکلاست)؛ حساسیت ذاتی استئوکلاست به <bdi>RANKL</bdi> و ویتامین <bdi>D</bdi>؛ جهش‌های ژنتیکی (مثلاً <bdi>SQSTM1</bdi>).</li><li><strong>درگیری:</strong> تک‌استخوانی حدود ۱۵ درصد (تیبیا، ایلیوم، فمور، جمجمه، مهره، هومروس)؛ چنداستخوانی ۸۰ تا ۸۵ درصد (لگن، ستون مهره‌ها، جمجمه، فمور پروگزیمال)؛ دنده، فیبولا و استخوان‌های کوچک دست و پا غیرمعمول‌اند. بیشتر موارد خفیف و اتفاقی کشف می‌شوند.</li><li><strong>علائم:</strong> درد ناشی از <strong>میکروفراکچر</strong> (از اولین یافته‌ها)، ضعف عضلانی و کیفوز (نیرو روی استخوان نامنظم درست وارد نمی‌شود)، گیرافتادگی عصبی (بسته شدن سوراخ‌های عبور عصب)، گرمی پوست روی ضایعه، <strong>پای پرانتزی (<bdi>bowlegs</bdi>)</strong>، <strong><bdi>Leontiasis ossea</bdi></strong> (چهره‌ی شیرمانند)، سردرد و اختلال بینایی و شنوایی در درگیری جمجمه، نارسایی قلبی با برون‌ده بالا در درگیری چنداستخوانی گسترده.</li><li><strong>تشخیص:</strong> <strong><bdi>ALP</bdi> سرم بالا</strong> و افزایش دفع هیدروکسی‌پرولین ادرار؛ رادیوگرافی: ضایعات لیتیک (فاز لیتیک) و ضخیم شدن قشر؛ <bdi>bone scan</bdi> جذب افزایش‌یافته؛ بیوپسی برای رد بدخیمی.</li><li><strong>عارضه:</strong> <strong>سارکوم (استئوسارکوم) در حدود ۱ درصد</strong> بیماران؛ استئوسارکوم ثانویه (بعد از پاژه، سن بالای ۴۰، فمور/هومروس/لگن، چنداستخوانی) تهاجمی‌تر است و پیش‌آگهی بدتر دارد.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>بیماری</th><th>وضعیت استخوان</th><th>نکته‌ی شاخص</th></tr></thead><tbody><tr><td>پاژه</td><td>حجم زیاد، کیفیت بد</td><td>موزاییک، <bdi>ALP</bdi> بالا، اختلال استئوکلاست</td></tr><tr><td>استئوپتروزیس</td><td>حجم زیاد، شکننده (مرمری)</td><td>نقص عملکرد استئوکلاست (کربنیک آنهیدراز <bdi>II</bdi>)، پان‌سیتوپنی، فشار بر اعصاب جمجمه‌ای، «استخوان در استخوان»</td></tr><tr><td>ریکتز</td><td>نرم، مینرالیزاسیون کم</td><td>کمبود ویتامین <bdi>D</bdi> کودکان</td></tr><tr><td>آکندروپلازی</td><td>نقص ساخت غضروف</td><td>کوتولگی</td></tr><tr><td>استئوژنزیس ایمپرفکتا</td><td>شکننده</td><td>کلاژن تیپ ۱</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: «متراکم = قوی». استخوان پاژه حجم زیاد ولی استحکام کم دارد.</p>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>اگر در گزینه‌ها <strong>استئوپتروزیس</strong> بود: آن هم استخوان را حجیم و اسکلروتیک و شکننده می‌کند (استئوکلاست‌ها درست کار نمی‌کنند، اسکلروز متقارن منتشر)، ولی پاژه با <bdi>ALP</bdi> بالا، موزاییک و خطوط سیمانی شناخته می‌شود.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) در کدام بیماری حجم/توده‌ی استخوان افزایش می‌یابد؟ (۲) الگوی موزاییکی و خطوط سیمانی نامنظم؛ (۳) <bdi>ALP</bdi> بالا، پای پرانتزی یا چهره‌ی شیرمانند؛ (۴) استئوسارکوم ثانویه بر زمینه‌ی کدام بیماری؟ (۵) کدام بیماری با اختلال استئوکلاست شروع می‌شود؟</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش بیماری پاژه (استئیت دفورمانس)؛ آکندروپلازی، استئوژنزیس ایمپرفکتا، ریکتز و استئومالاسی، استئوپتروزیس.</p>","steps":"<p>سوال می‌پرسد در کدام بیماری حجم/توده‌ی استخوان زیاد می‌شود؛ باید بیماری را پیدا کنید که استخوان اضافه می‌سازد.</p>\n<p>ریکتز (الف) نقص مینرالیزاسیون و استخوان نرم است؛ آکندروپلازی (ب) نقص غضروف و کوتولگی است؛ استئوژنزیس ایمپرفکتا (د) توده‌ی کم و شکننده است.</p>\n<p>فقط بیماری پاژه با فعالیت پرحرارت استئوکلاست و استئوبلاست استخوان متراکم ولی نامنظم و ضعیف (موزاییکی) می‌سازد و توده را زیاد می‌کند.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: «متراکم = قوی». استخوان پاژه حجم زیاد ولی استحکام کم دارد.","<span class=\"tag\">نکته‌ی دام</span>اگر در گزینه‌ها <strong>استئوپتروزیس</strong> بود: آن هم استخوان را حجیم و اسکلروتیک و شکننده می‌کند (استئوکلاست‌ها درست کار نمی‌کنند، اسکلروز متقارن منتشر)، ولی پاژه با <bdi>ALP</bdi> بالا، موزاییک و خطوط سیمانی شناخته می‌شود."],"dupOf":null,"dupNote":"","xrefs":["p3q17"]},{"id":"f03","session":"full","full":true,"num":3,"text":"کدام ارگانیسم ویژه‌ی استئومیلیت در بیماران مبتلا به کم‌خونی داسی‌شکل (<bdi>sickle cell</bdi>) است؟","opts":["<bdi>Staphylococcus aureus</bdi>","<bdi>Salmonella</bdi>","<bdi>Pseudomonas aeruginosa</bdi>","<bdi>Mycobacterium tuberculosis</bdi>"],"labels":["الف","ب","ج","د"],"exams":[],"answer":1,"explain":"<p>این سوال برای کلیدواژه‌ی «سالمونلا (استئومیلیت)» طراحی شده است؛ متن اصلی سوال آزمون در دسترس نبود.</p>\n<p>در جزوه آمده است که میکروب استئومیلیت بر اساس <strong>بیماری زمینه‌ای</strong> تغییر می‌کند و برای <strong>کم‌خونی داسی‌شکل</strong> پاسخ <strong><bdi>Salmonella</bdi></strong> است.</p>\n<ul><li><strong>الف) <bdi>Staphylococcus aureus</bdi>:</strong> سردسته‌ی همه‌ی استئومیلیت‌ها و شایع‌ترین عامل در کل است، ولی «ویژه‌ی» بیمار داسی‌شکل نیست.</li><li><strong>ج) <bdi>Pseudomonas</bdi>:</strong> از گرم‌منفی‌های شاخص در <strong>سوءمصرف‌کننده‌ی داروی تزریقی</strong> و عفونت ادراری (<bdi>Pseudomonas</bdi>، <bdi>E. coli</bdi>، <bdi>Klebsiella</bdi>).</li><li><strong>د) سل:</strong> استئومیلیت سلی نوع دیگری از عفونت استخوان است با گرانولوم (بیماری پات در مهره، «استئومیلیت سرد»)؛ در جزوه به بیماری داسی‌شکل ربط داده نشده است.</li></ul>","flag":"","lesson":"<ul><li><strong>راه‌های ورود:</strong> خونی (<bdi>hematogenous</bdi>)، شکستگی (به‌ویژه باز) و راه مستقیم (زخمی که تا استخوان پیش برود). راه خونی بیشتر در <strong>کودکان</strong> است (استخوان نرم، قشر حساس به عفونت هماتوژن)؛ در بزرگسالان بیشتر عارضه‌ی شکستگی باز، جراحی و <strong>پای دیابتی</strong>.</li><li><strong><bdi>Staphylococcus aureus</bdi> «سردسته»ی میکروارگانیسم‌هاست</strong> و میکروب بر اساس <strong>بیماری زمینه‌ای</strong> تغییر می‌کند. «نکات تأکیدی استاد»: راه‌های ورود و میکروارگانیسم بر اساس بیماری زمینه‌ای (استاف اورئوس سردسته؛ گرم‌منفی‌ها در تزریق‌کنندگان؛ <strong>سالمونلا در داسی‌شکل</strong>؛ پای دیابتی) حتماً سؤال می‌شود.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>بیماری زمینه‌ای</th><th>میکروب شاخص</th></tr></thead><tbody><tr><td>شرایط عمومی</td><td><bdi>Staphylococcus aureus</bdi> (سردسته)</td></tr><tr><td><strong>کم‌خونی داسی‌شکل</strong></td><td><strong><bdi>Salmonella</bdi></strong></td></tr><tr><td>سوءمصرف داروی تزریقی / عفونت ادراری</td><td>گرم‌منفی‌ها: <bdi>Pseudomonas</bdi>، <bdi>E. coli</bdi>، <bdi>Klebsiella</bdi></td></tr><tr><td>نوزادان</td><td><bdi>Haemophilus influenzae</bdi> و استرپتوکوک گروه <bdi>B</bdi></td></tr><tr><td>شکستگی باز</td><td>بی‌هوازی‌ها یا عفونت مختلط</td></tr><tr><td>پای دیابتی</td><td>واسکولوپاتی + نوروپاتی ← زخم تا استخوان می‌رسد؛ رساندن آنتی‌بیوتیک به استخوان دشوار، گاه قطع عضو</td></tr></tbody></table></div>\n<ul><li><strong>استئومیلیت چرکی (<bdi>pyogenic</bdi>):</strong> استاف، <bdi>E. coli</bdi>، سودوموناس، کلبسیلا، سالمونلا؛ راه ورود خونی، مجاورت (مثلاً مفصل مجاور) یا کاشت مستقیم. در حدود ۵۰ درصد موارد هیچ ارگانیسمی جدا نمی‌شود. در نوزادان و کودکان آرتریت چرکی همراه، آبسه‌ی ساب‌پریوستال و سینوس تخلیه‌کننده ممکن است دیده شود.</li><li><strong>تشخیص:</strong> رادیوگرافی و <bdi>bone scan</bdi>؛ بافت‌شناسی: نفوذ نوتروفیل‌ها و نکروز استخوان.</li><li><strong>مزمن‌شدن:</strong> ۵ تا ۲۵ درصد موارد حل نمی‌شوند؛ <strong><bdi>Sequestrum</bdi></strong> (استخوان مرده) و <strong><bdi>Involucrum</bdi></strong> (استخوان زنده‌ی تازه اطراف آن). عوامل: تأخیر در تشخیص، نکروز وسیع، درمان آنتی‌بیوتیکی کوتاه‌شده، دبریدمان ناکافی، ضعف دفاع میزبان.</li><li><strong>عوارض:</strong> آبسه‌ی ساب‌پریوستال، سینوس تخلیه‌کننده، درگیری مفصل؛ در مزمن: عود حاد، شکستگی پاتولوژیک، آمیلوئیدوز ثانویه، اندوکاردیت، سپسیس، کارسینوم سلول سنگفرشی در مسیر سینوس و به‌ندرت استئوسارکوم.</li><li><strong>استئومیلیت سلی/بیماری پات:</strong> از ریه یا خون؛ نشانه‌ی مشخصه گرانولوم؛ «استئومیلیت سرد» (بدون ورم و تب، مزمن)؛ کلاپس مهره، آبسه‌ی عضله‌ی سوآس و نقص عصبی؛ گاهی فقط نمونه‌برداری گرانولوم را نشان می‌دهد.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: انتخاب <bdi>S. aureus</bdi> چون «سردسته» است؛ وقتی در صورت سوال «کم‌خونی داسی‌شکل» آمده، پاسخ <bdi>Salmonella</bdi> است.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) استئومیلیت در بیمار داسی‌شکل؛ (۲) کدام میکروب با بیماری زمینه‌ای درست جفت شده؟ (۳) گرم‌منفی‌ها در کدام گروه؟ (۴) عامل استئومیلیت نوزادی؛ (۵) <bdi>Sequestrum</bdi> و <bdi>Involucrum</bdi>؛ (۶) بیماری پات.</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش عفونت استخوان (استئومیلیت: راه‌های ورود و عوامل بیماری‌زا، استئومیلیت چرکی، استئومیلیت سلی و بیماری پات).</p>","steps":"<p>کلید سوال عبارت «ویژه‌ی کم‌خونی داسی‌شکل» است؛ یعنی باید میکروب مخصوص بیماری زمینه‌ای را بیابید، نه شایع‌ترین میکروب.</p>\n<p><bdi>S. aureus</bdi> (الف) سردسته‌ی همه‌ی استئومیلیت‌هاست ولی اختصاصی نیست؛ <bdi>Pseudomonas</bdi> (ج) از گرم‌منفی‌های شاخص در تزریق‌کنندگان داروست؛ سل (د) الگوی مزمن گرانولومایی دارد.</p>\n<p>در جزوه جفت مشهور: کم‌خونی داسی‌شکل ← <bdi>Salmonella</bdi>.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: انتخاب <bdi>S. aureus</bdi> چون «سردسته» است؛ وقتی در صورت سوال «کم‌خونی داسی‌شکل» آمده، پاسخ <bdi>Salmonella</bdi> است."],"dupOf":null,"dupNote":"","xrefs":["p3q04","p3q16"]},{"id":"f04","session":"full","full":true,"num":4,"text":"کودک ۲ ساله‌ای با کمبود ویتامین <bdi>D</bdi> دچار تغییر شکل پاها (پای پرانتزی)، برجستگی اتصال استخوان-غضروف دنده‌ها (<bdi>rachitic rosary</bdi>) و نرمی استخوان‌های جمجمه (<bdi>craniotabes</bdi>) شده است. تشخیص کدام است؟","opts":["ریکتز","استئومالاسی","بیماری پاژه","استئوپروز"],"labels":["الف","ب","ج","د"],"exams":[],"answer":0,"explain":"<p>این سوال برای کلیدواژه‌ی «ریکتز (<bdi>Rickets</bdi>)» طراحی شده است؛ متن اصلی سوال آزمون در دسترس نبود.</p>\n<p>کودک در حال رشد (۲ ساله) + کمبود <strong>ویتامین <bdi>D</bdi></strong> = اختلال دوران کودکی که در آن رسوب استخوان در <strong>صفحه‌ی رشد</strong> مختل است، یعنی <strong>ریکتز</strong>؛ تغییر شکل‌های رشدی (مثل پای پرانتزی) هم با آن می‌خواند.</p>\n<ul><li><strong>ب) استئومالاسی:</strong> همتای بزرگسالان است؛ استخوانی که هنگام بازسازی ساخته می‌شود کم‌مینرالیزه است و مستعد شکستگی؛ شرح‌حال کلاسیک آن دختر نوجوان/زن جوان با درد زانو است.</li><li><strong>ج) بیماری پاژه:</strong> بیماری میانسالان و سالمندان با اختلال استئوکلاست و الگوی موزاییکی؛ با کمبود ویتامین <bdi>D</bdi> کودک ارتباطی ندارد.</li><li><strong>د) استئوپروز:</strong> سلول‌ها و مینرالیزاسیون طبیعی است ولی استخوان کم است؛ در ریکتز/استئومالاسی مینرالیزاسیون ناکافی است.</li></ul>","flag":"","lesson":"<ul><li><strong>تعریف:</strong> ریکتز و استئومالاسی هر دو تظاهر <strong>کمبود ویتامین <bdi>D</bdi> یا متابولیسم غیرطبیعی آن</strong> هستند. <strong>ریکتز = اختلال دوران کودکی</strong> که در آن رسوب استخوان در <strong>صفحه‌ی رشد</strong> مختل می‌شود؛ <strong>استئومالاسی = همتای بزرگسالان</strong>.</li><li><strong>نقص اصلی:</strong> اختلال مینرالیزاسیون و <strong>تجمع ماتریکس مینرالیزه‌نشده (<bdi>osteoid</bdi>)</strong>.</li><li><strong>مکانیسم:</strong> برای ساخت استخوان ابتدا ماتریکس پروتئینی ساخته می‌شود و سپس کلسیم روی آن رسوب می‌کند؛ اگر کلسیم رسوب نکند (مثلاً چون به‌دلیل کمبود ویتامین <bdi>D</bdi> جذب نشده)، استخوان درست مینرالیزه نمی‌شود و <strong>نرم می‌ماند</strong> = نرمی استخوان (<bdi>osteomalacia</bdi>).</li><li><strong>چرا حوالی بلوغ؟</strong> در انفجار رشد، استخوان‌ها می‌خواهند بلند شوند و همه‌ی کلسیم را مصرف می‌کنند؛ اگر ویتامین <bdi>D</bdi> کم باشد کلسیم خوب جذب نمی‌شود.</li><li><strong>بالینی (استئومالاسی):</strong> استخوان نرم نمی‌تواند مفاصل را به‌خوبی تحمل کند؛ شرح‌حال اصلی <strong>زن جوان یا دختر نوجوان با درد زانو</strong> است و اولین چیزی که باید به ذهن برسد <strong>کمبود ویتامین <bdi>D</bdi></strong> است («نکات تأکیدی استاد»).</li><li><strong>مقایسه با استئوپروز:</strong> در استئوپروز سلول‌ها و <strong>مینرالیزاسیون طبیعی</strong> است ولی استخوان کم است (ترابکول‌های کم و نازک)؛ در استئوماالسی مینرالیزاسیون ناکافی است.</li><li><strong>جایگاه در طبقه‌بندی:</strong> ریکتز و استئومالاسی در گروه «بیماری‌های همراه با اختلال هموستاز مواد معدنی (<bdi>Ca</bdi>++)» هستند، کنار هایپرپاراتیروئیدیسم و استئودیستروفی کلیوی.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>بیماری</th><th>ماهیت</th></tr></thead><tbody><tr><td>ریکتز</td><td>کودک؛ رسوب استخوان در صفحه‌ی رشد مختل؛ <bdi>osteoid</bdi> مینرالیزه‌نشده</td></tr><tr><td>استئومالاسی</td><td>بزرگسال/نوجوان؛ استخوان کم‌مینرالیزه و مستعد شکستگی؛ درد زانو</td></tr><tr><td>استئوپروز</td><td>مینرالیزاسیون طبیعی، توده‌ی کم</td></tr><tr><td>پاژه</td><td>میانسال؛ اختلال استئوکلاست، موزاییک</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: گمان اینکه کمبود ویتامین <bdi>D</bdi> کودک «کم‌استخوان» (استئوپروز) می‌دهد؛ مشکل مینرالیزاسیون است، نه کمبود توده با مینرالیزاسیون طبیعی.</p>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>جزوه برای ریکتز شرح‌حال و علائم جزئی‌تری نمی‌دهد؛ کلید سوال «کودک + ویتامین <bdi>D</bdi> + صفحه‌ی رشد» است.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) کمبود ویتامین <bdi>D</bdi> در کودک کدام بیماری را می‌دهد؟ (۲) همتای بزرگسالان ریکتز کدام است؟ (۳) تجمع <bdi>osteoid</bdi> مینرالیزه‌نشده؛ (۴) دختر نوجوان با درد زانو؛ (۵) تفاوت با استئوپروز (مینرالیزاسیون طبیعی).</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش ریکتز و استئومالاسی (اختلال هموستاز مواد معدنی) و مقایسه با استئوپروز و پاژه.</p>","steps":"<p>سرنخ‌ها را جمع کنید: کودک، کمبود ویتامین <bdi>D</bdi> و تغییر شکل‌های رشدی.</p>\n<p>استئوپروز (د) مینرالیزاسیون طبیعی با توده‌ی کم است؛ پاژه (ج) بیماری میانسالان با اختلال استئوکلاست است.</p>\n<p>استئومالاسی (ب) همان نقص ویتامین <bdi>D</bdi> ولی در بزرگسال است، پس برای کودک ۲ ساله مناسب نیست.</p>\n<p>کودک + کمبود ویتامین <bdi>D</bdi> + اختلال صفحه‌ی رشد = ریکتز.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: گمان اینکه کمبود ویتامین <bdi>D</bdi> کودک «کم‌استخوان» (استئوپروز) می‌دهد؛ مشکل مینرالیزاسیون است، نه کمبود توده با مینرالیزاسیون طبیعی.","<span class=\"tag\">نکته‌ی دام</span>جزوه برای ریکتز شرح‌حال و علائم جزئی‌تری نمی‌دهد؛ کلید سوال «کودک + ویتامین <bdi>D</bdi> + صفحه‌ی رشد» است."],"dupOf":null,"dupNote":"","xrefs":["p3q17"]},{"id":"f05","session":"full","full":true,"num":5,"text":"آقای 15 ساله با ضایعه متافیزی لیتیک با حاشیه مشخص در استخوان تیبیا مراجعه کرده است در نمای میکروسکوپی دارای فضاهای سیستیک حاوی خون که با یک جدار فیبروز حاوی فیبروبلاستهای تکثیری و سلولهای چند هسته ای و استخوان واکنشی در هم بافته احاطه شده است دیده می شود .تشخیص کدام است ؟","opts":["<bdi>osteoma</bdi>","<bdi>Aneurysmal bone cyst</bdi>","<bdi>Osteoid osteoma</bdi>","<bdi>Osteochondroma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[],"answer":1,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی ۲۰ مهر ۱۴۰۱ (سوال 10) — تلفیقی بهار ۱۴۰۱ — تلفیقی پاییز ۱۴۰۰ (سوال 14)</p><p>کلیدواژه‌ی «<bdi>ABC</bdi> (کیست آنوریسمی استخوان)» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p>نوجوان ۱۵ ساله + ضایعه‌ی لیتیک <strong>متافیزی</strong> با حاشیه‌ی مشخص + <strong>فضاهای کیستیک پر از خون</strong> با دیواره‌ی فیبروز دارای فیبروبلاست، <strong>سلول غول‌آسای چندهسته‌ای</strong> و <strong>استخوان واکنشی در هم بافته</strong> = <strong><bdi>Aneurysmal bone cyst</bdi></strong>.</p>\n<ul><li><strong>الف) <bdi>Osteoma</bdi>:</strong> رشد اگزوفیتیک سخت و آهسته روی سطح استخوان (شایع‌ترین محل سر و گردن، میانسالی)، بافت‌شناسی شبیه استخوان طبیعی؛ ضایعات متعدد مشخصه‌ی سندرم گاردنر است؛ کیست خونی ندارد.</li><li><strong>ج) <bdi>Osteoid osteoma</bdi>:</strong> ضایعه‌ی کوچک‌تر از ۲ سانتی‌متر با <bdi>nidus</bdi> مرکزی و اسکلروز اطراف، درد شبانه که با <bdi>NSAID</bdi> بهبود می‌یابد؛ فضای کیستیک پر از خون ندارد.</li><li><strong>د) <bdi>Osteochondroma</bdi>:</strong> زائده‌ی استخوانی با کلاهک غضروفی (اگزوستوز) که مغز استخوانش با استخوان مجاور پیوسته است؛ نه ضایعه‌ی کیستیک خونی.</li></ul>","flag":"","lesson":"<ul><li><strong>ماهیت (جزوه):</strong> چند فضای کیستیک پر از خون با دیواره‌های نازک (سپتا)؛ نکته‌ی کلیدی: فضاها <strong>با اندوتلیوم پوشیده نشده‌اند</strong>.</li><li><strong>سن و محل:</strong> معمولاً <strong>دو دهه‌ی اول</strong>؛ <strong>متافیز استخوان‌های بلند</strong> و <strong>عناصر خلفی مهره‌ها</strong>.</li><li><strong>ریزنما:</strong> دیواره‌ی نازک از <strong>فیبروبلاست‌های چاق</strong>، <strong>سلول‌های غول‌آسای شبیه استئوکلاست</strong> و <strong>استخوان وُون واکنشی</strong>؛ فضاهای پر از خون و سپتاهای نازک.</li><li><strong>پاتوژنز (ژنتیک):</strong> بازآرایی <strong>17<bdi>p13</bdi></strong> و همجوشی <strong><bdi>USP6</bdi></strong> با پروموتر ژن‌هایی که در استئوبلاست‌ها بیان بالایی دارند ← بیش‌بیانی <bdi>USP6</bdi> (پروتئاز اوبیکوئیتین که <bdi>NF</bdi>-κ<bdi>B</bdi> را تنظیم می‌کند) ← افزایش <strong><bdi>MMP</bdi></strong> و تحلیل کیستیک استخوان.</li><li><strong>مقایسه با تومور سلول غول‌آسا:</strong> <bdi>GCT</bdi> خوش‌خیم ولی تهاجمی موضعی؛ <strong>۲۰ تا ۴۰ سال</strong>، <strong>اپی‌فیز</strong> استخوان‌های بلند اطراف زانو؛ ضایعه‌ی بزرگ، کاملاً لیتیک و خارج از مرکز؛ <strong>عود ۴۰ تا ۶۰ درصد</strong>، متاستاز به ریه ۴ درصد؛ توده‌ی قرمز-قهوه‌ای با دژنراسیون کیستیک؛ سلول‌های غول‌آسای نوع استئوکلاست (حتی بیش از ۱۰۰ هسته) + سلول‌های تک‌هسته‌ای یکنواخت بیضی؛ بدون استخوان یا غضروف.</li><li><strong>مقایسه با <bdi>Osteoid osteoma</bdi>:</strong> کوچک‌تر از ۲ سانتی‌متر، <bdi>nidus</bdi> مرکزی با اسکلروز اطراف، درد شبانه و پاسخ به <bdi>NSAID</bdi>؛ متافیز فمور و تیبیا، ۱۰ تا ۲۰ سال.</li><li><strong>مقایسه با <bdi>Osteochondroma</bdi>:</strong> زائده‌ی استخوانی با کلاهک غضروفی؛ متافیز استخوان‌های بلند، ۱۰ تا ۳۰ سال؛ مغز استخوان تومور با استخوان پیوسته است؛ خطر بدخیمی (کندروسارکوم) اگر متعدد باشد، جزو سندروم‌ها باشد یا کلاهک بزرگ‌تر از ۳ سانتی‌متر شود.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>ضایعه</th><th>نکته‌ی شاخص</th></tr></thead><tbody><tr><td><bdi>ABC</bdi></td><td>فضاهای پر از خون بدون اندوتلیوم، <bdi>USP6</bdi>، متافیز/مهره، دو دهه‌ی اول</td></tr><tr><td>تومور سلول غول‌آسا</td><td>اپی‌فیز، ۲۰ تا ۴۰ سال، لیتیک خارج از مرکز، عود ۴۰ تا ۶۰ درصد</td></tr><tr><td><bdi>Osteoid osteoma</bdi></td><td>کمتر از ۲ سانتی‌متر، <bdi>nidus</bdi>، درد شبانه و پاسخ به <bdi>NSAID</bdi></td></tr><tr><td><bdi>Osteochondroma</bdi></td><td>اگزوستوز با کلاهک غضروفی؛ ۱۰ تا ۳۰ سال</td></tr><tr><td><bdi>Osteoma</bdi></td><td>رشد اگزوفیتیک سطحی، سر و گردن، ۴۰ تا ۵۰ سال</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: دیدن سلول غول‌آسا و گفتن «تومور سلول غول‌آسا»؛ سلول غول‌آسا در <bdi>ABC</bdi> هم هست؛ مشخصه‌ی <bdi>GCT</bdi> محل اپی‌فیز، سن ۲۰ تا ۴۰ و عود است.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) نوجوان با ضایعه‌ی لیتیک متافیزی و فضاهای پر از خون؛ (۲) کدام ضایعه اندوتلیوم ندارد؟ (۳) <bdi>USP6</bdi> و 17<bdi>p13</bdi> در کدام ضایعه؟ (۴) افتراق از تومور سلول غول‌آسا (محل و سن)؛ (۵) سپتاهای نازک با فیبروبلاست، سلول غول‌آسا و استخوان وُون واکنشی.</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش تومورهای استخوان‌ساز، غضروف‌ساز و «سایر تومورها و ضایعات شبیه تومور» (کیست استخوانی آنوریسمی، تومور سلول غول‌آسا).</p>","steps":"<p>سرنخ‌ها: نوجوان، ضایعه‌ی لیتیک متافیزی با حاشیه‌ی مشخص، فضاهای کیستیک پر از خون و سلول غول‌آسا در دیواره‌ی فیبروز.</p>\n<p><bdi>Osteoma</bdi> (الف) رشد اگزوفیتیک جمجمه/صورت است؛ <bdi>Osteochondroma</bdi> (د) اگزوستوز با کلاهک غضروفی است؛ <bdi>Osteoid osteoma</bdi> (ج) ضایعه‌ی کوچک با <bdi>nidus</bdi> و درد شبانه است و فضای پر از خون ندارد.</p>\n<p>فضای کیستیک پر از خون بدون اندوتلیوم در متافیز نوجوان = کیست آنوریسمال استخوان.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: دیدن سلول غول‌آسا و گفتن «تومور سلول غول‌آسا»؛ سلول غول‌آسا در <bdi>ABC</bdi> هم هست؛ مشخصه‌ی <bdi>GCT</bdi> محل اپی‌فیز، سن ۲۰ تا ۴۰ و عود است."],"dupOf":null,"dupNote":"","xrefs":["p3q06"]},{"id":"f06","session":"full","full":true,"num":6,"text":"ضایعه ی تومورال دردناک ستون فقرات در کودک 12 ساله به سایز یک سانتی متر نمایانگر ترابکولهای استخوانی <bdi>woven</bdi> می‌باشد که با یک ردیف استئوبلاست پوشیده شده اند. در بین ترابکولها بافت همبندی عروقی شلی دیده میشود. کدام تشخیص محتملتر است؟","opts":["<bdi>Osteosarcoma</bdi>","<bdi>Osteoblastoma</bdi>","<bdi>Osteoid osteoma</bdi>","<bdi>Osteochondroma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[],"answer":2,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی ۲۰ مهر ۱۴۰۱ (سوال 6) — تلفیقی بهار ۱۴۰۱ — تلفیقی پاییز ۱۴۰۰ (سوال 11) — تلفیقی بهار ۱۴۰۰ (سوال 22) — تلفیقی 96A (سوال 10)</p><p>کلیدواژه‌ی «<bdi>Osteoid osteoma</bdi>» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p>کودک ۱۲ ساله با ضایعه‌ی دردناک <strong>۱ سانتی‌متری</strong> که از <strong>ترابکول‌های <bdi>woven</bdi></strong> پوشیده با یک ردیف <strong>استئوبلاست</strong> (<bdi>rimming</bdi>) و <strong>بافت همبند عروقی شل</strong> تشکیل شده است، تصویر <strong><bdi>Osteoid osteoma</bdi></strong> است؛ اندازه‌ی زیر ۲ سانتی‌متر و درد، آن را از استئوبلاستوما جدا می‌کند.</p>\n<ul><li><strong>الف) <bdi>Osteosarcoma</bdi>:</strong> تومور بدخیمی است که سلول‌های بدخیمش استئوئید می‌سازند؛ رشد به خارج و داخل دارد و قشر را پاره می‌کند، در حالی که این ضایعه حاشیه‌ی منظم دارد.</li><li><strong>ب) <bdi>Osteoblastoma</bdi>:</strong> ریزنمای بسیار مشابه دارد ولی ضایعه <strong>بزرگ‌تر از ۲ سانتی‌متر</strong>، معمولاً مهره (قوس خلفی)، <strong>بدون <bdi>nidus</bdi></strong> و درد آن به آسپرین/<bdi>NSAID</bdi> پاسخ نمی‌دهد؛ رقیب اصلی در اینجا به‌علت ذکر ستون فقرات است، ولی اندازه‌ی ۱ سانتی‌متر آن را رد می‌کند.</li><li><strong>د) <bdi>Osteochondroma</bdi>:</strong> اگزوستوز با کلاهک غضروفی و پیوستگی مغز استخوان با استخوان مجاور؛ جزو تومورهای غضروف‌ساز است و نه ترابکول <bdi>woven</bdi> با <bdi>rimming</bdi> استئوبلاستی.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی ذکر «ستون فقرات» در صورت سوال بیشتر یادآور استئوبلاستوماست؛ با این حال اندازه‌ی ۱ سانتی‌متر (استئوبلاستوما بزرگ‌تر است؛ استئوئید استئوما کوچک‌تر از ۲ سانتی‌متر) و درد، گزینه‌ی ج را مناسب‌تر می‌کند.","lesson":"<ul><li><strong>تعریف:</strong> ضایعه‌ی کوچک‌تر از <strong>۲ سانتی‌متر</strong> با <strong>درد موضعی</strong> که به <bdi>NSAID</bdi>/آسپرین پاسخ می‌دهد؛ تومور خوش‌خیم استخوان‌ساز (جدول: «تومور قشری با درد؛ ترابکول‌های درهم‌بافته‌ی استخوان وُون»).</li><li><strong>سن/جنس:</strong> نوجوان و دهه‌ی بیست (۱۰ تا ۲۰ سال)؛ مرد بیش از زن.</li><li><strong>محل:</strong> بیشتر <strong>پروگزیمال فمور و تیبیا (قشری)</strong>؛ متافیز فمور و تیبیا.</li><li><strong>شرح‌حال کلیدی:</strong> <strong>درد شبانه‌ی استخوانی که به <bdi>NSAID</bdi> پاسخ می‌دهد</strong> (مثلاً «درد دارم که با بروفن خوب می‌شود»)؛ در پاتوفیزیولوژی تومور <strong>پروستاگلاندین‌ها</strong> نقش دارند و <bdi>NSAID</bdi> با اثر روی پروستاگلاندین درد را آرام می‌کند.</li><li><strong>تصویربرداری (رادیوگرافی و <bdi>CT</bdi>):</strong> ضایعه‌ی اسکلروتیک قشری با <strong><bdi>nidus</bdi></strong> (نقطه‌ی ناف‌مانند) مرکزی؛ اطراف را اسکلروز فراگرفته.</li><li><strong>ریزنما:</strong> تیغه‌های استخوانی نامنظم <bdi>woven</bdi> با <strong>حاشیه‌ی استئوبلاستی (<bdi>osteoblastic rimming</bdi>)</strong> در بافت فیبروز؛ <bdi>nidus</bdi> <strong>عروقی و بافت نرم</strong> است و هرچه به اطراف بروید اسکلروتیک‌تر می‌شود.</li><li><strong>سیر:</strong> خوش‌خیم؛ <strong>حاشیه‌ی منظم دارد و قشر را پاره نمی‌کند</strong>.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>ویژگی</th><th><bdi>Osteoid osteoma</bdi></th><th><bdi>Osteoblastoma</bdi></th></tr></thead><tbody><tr><td>پاسخ درد به آسپرین/<bdi>NSAID</bdi></td><td>بله</td><td>خیر</td></tr><tr><td>محل</td><td>پروگزیمال فمور و تیبیا (قشری)</td><td>ستون مهره‌ها (قوس خلفی؛ زوائد عرضی و خاری)</td></tr><tr><td>اندازه</td><td>کمتر از ۲ <bdi>cm</bdi></td><td>بزرگ‌تر</td></tr><tr><td><bdi>nidus</bdi> و واکنش استخوانی</td><td>دارد؛ واکنش استخوانی مشخص</td><td>ندارد</td></tr><tr><td>سن/جنس</td><td>نوجوان و دهه‌ی بیست؛ مرد بیشتر از زن</td><td>نوجوان و دهه‌ی بیست؛ مرد بیشتر از زن</td></tr><tr><td>اهمیت</td><td>خوش‌خیم</td><td>ممکن است بسیار بزرگ شود و به بدخیمی (استئوسارکوم) برسد</td></tr></tbody></table></div>\n<ul><li><strong>افتراق:</strong> استئوسارکوم سلول‌های بدخیم دارد، به خارج و داخل رشد می‌کند و قشر را پاره می‌کند (۱۰ تا ۲۰ سال، متافیز فمور دیستال/تیبیا)؛ <strong>استئوما (<bdi>Osteoma</bdi>)</strong> رشد اگزوفیتیک سطحی در سر و گردن میانسالان است (جزوه استئوما را از کتاب دانشجویان حذف‌شده می‌داند).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: وقتی «مهره» در سوال می‌آید خودکار «استئوبلاستوما» انتخاب کنید؛ تصمیم با اندازه (کمتر از ۲ <bdi>cm</bdi>)، <bdi>nidus</bdi> و پاسخ به <bdi>NSAID</bdi> است.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) نوجوان با درد شبانه که با ایبوپروفن خوب می‌شود؛ (۲) ضایعه‌ی کوچک‌تر از ۲ سانتی‌متر با <bdi>nidus</bdi> و اسکلروز اطراف؛ (۳) تیغه‌های <bdi>woven</bdi> با <bdi>rimming</bdi> استئوبلاستی؛ (۴) تفاوت با استئوبلاستوما (اندازه، <bdi>nidus</bdi>، پاسخ به آسپرین، محل)؛ (۵) نقش پروستاگلاندین در درد این تومور.</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش تومورهای استخوان‌ساز: استئوئید استئوما و استئوبلاستوما (جدول مقایسه).</p>","steps":"<p>سرنخ‌ها: کودک ۱۲ ساله، درد، اندازه‌ی ۱ سانتی‌متر، ترابکول <bdi>woven</bdi> با <bdi>rimming</bdi> استئوبلاستی در بافت همبند عروقی شل ← تومور خوش‌خیم استخوان‌ساز.</p>\n<p>استئوسارکوم (الف) بدخیم است و سلول‌های آتیپیک دارد؛ استئوکندروما (د) کلاهک غضروفی دارد.</p>\n<p>بین استئوئید استئوما و استئوبلاستوما اندازه تصمیم می‌گیرد: زیر ۲ سانتی‌متر ← استئوئید استئوما؛ بزرگ‌تر و مهره‌ای بدون <bdi>nidus</bdi> ← استئوبلاستوما.</p>\n<p>اندازه‌ی ۱ سانتی‌متر و درد = <bdi>Osteoid osteoma</bdi>.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: وقتی «مهره» در سوال می‌آید خودکار «استئوبلاستوما» انتخاب کنید؛ تصمیم با اندازه (کمتر از ۲ <bdi>cm</bdi>)، <bdi>nidus</bdi> و پاسخ به <bdi>NSAID</bdi> است."],"dupOf":null,"dupNote":"","xrefs":["p3q02"]},{"id":"f07","session":"full","full":true,"num":7,"text":"در گریدینگ <bdi>WHO</bdi> به آستروسیتوم آناپلاستیک چه گریدی اطلاق می شود؟","opts":["گرید <bdi>I</bdi>","گرید <bdi>II</bdi>","گرید <bdi>III</bdi>","گرید <bdi>IV</bdi>"],"labels":["الف","ب","ج","د"],"exams":[],"answer":2,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی ۲۰ مهر ۱۴۰۱ (سوال 23) — تلفیقی بهار ۱۴۰۱ — تلفیقی پاییز ۱۴۰۰ (سوال 8)</p><p>کلیدواژه‌ی «آناپلاستیک: گرید ۳» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p>در درجه‌بندی <bdi>WHO</bdi>، آستروسیتوم‌ها از درجه‌ی ۲ تا ۴ هستند: آستروسیتوم با تمایز خوب = درجه‌ی ۲، <strong>آستروسیتوم آناپلاستیک = درجه‌ی ۳</strong>، گلیوبلاستوما = درجه‌ی ۴.</p>\n<ul><li><strong>الف) گرید <bdi>I</bdi>:</strong> درجه‌ی ۱ مربوط به <strong>آستروسیتوم پیلوسیتیک</strong> (نسبتاً خوش‌خیم، کودکان) است؛ جزو آستروسیتوم منتشر (درجه‌ی ۲ تا ۴) نیست.</li><li><strong>ب) گرید <bdi>II</bdi>:</strong> آستروسیتوم با تمایز خوب (سلولاریته، میتوز و پلئومورفیسم کمتر، بدون نکروز)، نه آناپلاستیک.</li><li><strong>د) گرید <bdi>IV</bdi>:</strong> گلیوبلاستوما (<bdi>GBM</bdi>) است: میتوز بسیار زیاد، <strong>نکروز (پالیسیدینگ)</strong> و پرولیفراسیون میکروواسکولار.</li></ul>","flag":"","lesson":"<ul><li><strong>آستروسیتوم منتشر:</strong> شایع‌ترین تومور گلیال بزرگسالان (حدود ۸۰ درصد گلیوم‌های بزرگسالان)؛ دهه‌ی چهارم تا ششم (جزوه: دهه‌ی دوم تا ششم)؛ نیمکره‌های مخ؛ تظاهر با تشنج، سردرد و نقص عصبی کانونی؛ مرز نامشخص و نفوذ به بافت اطراف.</li><li><strong>درجه‌بندی <bdi>WHO</bdi></strong> بر اساس <strong>پلئومورفیسم، نکروز و میتوز</strong>؛ آستروسیتوم‌ها از درجه‌ی ۲ تا ۴. «تمایز بیشتر = تومور بهتر»؛ هرچه تمایز کمتر و درجه بالاتر، میتوز بیشتر.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>درجه</th><th>نام</th><th>ویژگی‌ها</th></tr></thead><tbody><tr><td><bdi>I</bdi></td><td>پیلوسیتیک (<bdi>BRAF</bdi>)</td><td>نسبتاً خوش‌خیم، کودکان، کیستیک با ندول جداری</td></tr><tr><td><bdi>II</bdi></td><td>آستروسیتوم با تمایز خوب</td><td>سلولاریته، میتوز و پلئومورفیسم کمتر؛ بدون نکروز</td></tr><tr><td><bdi>III</bdi></td><td><strong>آناپلاستیک</strong></td><td>سلولاریته‌ی بیشتر، پلئومورفیسم زیاد، میتوز زیاد؛ <strong>پرولیفراسیون عروقی شروع می‌شود ولی هنوز نکروز ندارد</strong></td></tr><tr><td><bdi>IV</bdi></td><td>گلیوبلاستوما (<bdi>GBM</bdi>)</td><td>سلولاریته‌ی خیلی زیاد، میتوز بسیار زیاد، <strong>نکروز (پالیسیدینگ)</strong>، پرولیفراسیون میکروواسکولار</td></tr></tbody></table></div>\n<ul><li><strong>جزئیات درجه‌ی ۲:</strong> نسبت به بافت طبیعی سلولاریته‌ی بیشتر دارد ولی نسبت به درجه‌ی ۳ و ۴ کمتر؛ در درجه‌ی ۲ پلئومورفیسم بیشتر می‌شود، نسبت <bdi>N/C</bdi> بالا می‌رود و تومور در <strong>زمینه‌ی فیبریلری</strong> دیده می‌شود (ویژگی اصلی سلول‌های گلیال).</li><li><strong>ژنتیک:</strong> <bdi>GBM</bdi>: از دست رفتن عملکرد <strong><bdi>p53</bdi></strong> و <strong><bdi>Rb</bdi></strong> و جهش افزایش عملکرد در مسیر <strong><bdi>PI3K</bdi></strong>؛ درجات پایین‌تر: جهش <strong><bdi>IDH1/IDH2</bdi></strong>.</li><li>در <bdi>WHO</bdi> جدید، آستروسیتوم درجه‌ی ۴ و گلیوبلاستوما از نظر مورفولوژی شبیه هم‌اند و تفکیک آنها مولکولی است؛ استاد: «در حد مورفولوژی بلد باشید: گلیوبلاستوما همان آستروسیتوم درجه‌ی ۴ است».</li><li>حتی تومور درجه‌ی پایین (<bdi>low grade</bdi>) هم می‌تواند به قسمت‌های دیگر مغز نفوذ کند.</li><li><strong>ماکروسکوپی:</strong> بدون حدود مشخص، خاکستری و انفیلتراتیو؛ <bdi>GBM</bdi>: نواحی زرد (نکروز) و خونریزی.</li><li><strong>«نکات تأکیدی استاد»:</strong> سه ویژگی <bdi>GBM</bdi> و تفاوت درجه‌های ۲، ۳ و ۴ را باید بتوانید روی تصویر تشخیص دهید.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: «آناپلاستیک = بدترین = <bdi>IV</bdi>»؛ آناپلاستیک درجه‌ی ۳ است و <bdi>IV</bdi> فقط برای گلیوبلاستوماست. درجه‌ی ۱ هم جزو آستروسیتوم منتشر نیست.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) آستروسیتوم آناپلاستیک کدام گرید است؟ (۲) کدام تومور سلولاریته‌ی بالا و میتوز زیاد ولی بدون نکروز دارد؟ (۳) پرولیفراسیون عروقی شروع می‌شود ولی نکروز نیست، کدام درجه؟ (۴) درجه‌ی <bdi>GBM</bdi> یا آستروسیتوم با تمایز خوب؟ (۵) پیلوسیتیک چه درجه‌ای است؟</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش گلیوم‌ها/آستروسیتوم منتشر و جدول درجه‌بندی <bdi>WHO</bdi>؛ بخش آستروسیتوم پیلوسیتیک.</p>","steps":"<p>آستروسیتوم‌های منتشر در <bdi>WHO</bdi> درجه‌ی ۲، ۳ و ۴ دارند.</p>\n<p>آستروسیتوم با تمایز خوب = <bdi>II</bdi>، آناپلاستیک = <bdi>III</bdi>، گلیوبلاستوما = <bdi>IV</bdi>؛ درجه‌ی <bdi>I</bdi> مخصوص پیلوسیتیک است.</p>\n<p>آناپلاستیک سلولاریته، پلئومورفیسم و میتوز زیاد و شروع پرولیفراسیون عروقی دارد ولی هنوز نکروز ندارد؛ پس <bdi>IV</bdi> نیست.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: «آناپلاستیک = بدترین = <bdi>IV</bdi>»؛ آناپلاستیک درجه‌ی ۳ است و <bdi>IV</bdi> فقط برای گلیوبلاستوماست. درجه‌ی ۱ هم جزو آستروسیتوم منتشر نیست."],"dupOf":null,"dupNote":"","xrefs":["p4q07"]},{"id":"f08","session":"full","full":true,"num":8,"text":"کدامیک از موارد زیر از کرایتریای لازم برای تشخیص گلیوبلاستوما می باشد؟","opts":["نکروز پالیسید","هیپرکرومازی هسته","میتوز چند قطبی","اجسام روزنتال"],"labels":["الف","ب","ج","د"],"exams":[],"answer":0,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی ۲۰ مهر ۱۴۰۱ (سوال 17) — تلفیقی پاییز ۱۴۰۰ (سوال 24)</p><p>کلیدواژه‌ی «نکروز پالیسیدینگ» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p>از ویژگی‌های اصلی <strong>گلیوبلاستوما</strong> (آستروسیتوم درجه‌ی ۴) <strong>نکروز</strong> است که اغلب با <strong>هسته‌های پالیسیدینگ</strong> دیده می‌شود؛ نواحی زرد ماکروسکوپی همان نکروز است و جزوه می‌گوید «وجود نکروز ویژگی اصلی گلیوبلاستوما است».</p>\n<ul><li><strong>ب) هیپرکرومازی هسته:</strong> جزو سه‌گانه‌ی <bdi>GBM</bdi> در جزوه نیست (در جزوه برای لیومیوسارکوم و سارکوم پلئومورفیک آمده است)؛ معیار گلیوبلاستوما نیست.</li><li><strong>ج) میتوز چندقطبی:</strong> در جزوه معیار <bdi>GBM</bdi> «میتوز بسیار زیاد» است، نه شکل خاص میتوز.</li><li><strong>د) اجسام روزنتال (<bdi>Rosenthal fibers</bdi>):</strong> یافته‌ی <strong>آستروسیتوم پیلوسیتیک</strong> (درجه‌ی ۱) است، نه گلیوبلاستوما.</li></ul>","flag":"","lesson":"<ul><li><strong><bdi>GBM</bdi> = آستروسیتوم درجه‌ی <bdi>IV</bdi> (<bdi>WHO</bdi>)؛ سه ویژگی اصلی:</strong> ۱) <strong>میتوز بسیار زیاد</strong> ۲) <strong>نکروز</strong> (پالیسیدینگ) ۳) <strong>پرولیفراسیون میکروواسکولار</strong> (رگ‌های کوچک). «نکات تأکیدی استاد»: این سه ویژگی و تفاوت درجه‌های ۲، ۳ و ۴ را باید روی تصویر تشخیص دهید.</li><li>جزوه: «وجود نکروز ویژگی اصلی گلیوبلاستوما است». بافت‌شناسی <bdi>GBM</bdi> شبیه آستروسیتوم آناپلاستیک است <strong>به‌علاوه‌ی نکروز (اغلب با هسته‌های پالیسیدینگ) یا پرولیفراسیون عروقی</strong>. در گزینه‌های این سوال فقط نکروز آمده است.</li><li><strong>ماکروسکوپی:</strong> حدود مشخصی ندارد، خاکستری و انفیلتراتیو؛ در <bdi>GBM</bdi> نکروز و خونریزی هم دیده می‌شود و <strong>نواحی زرد در تصویر ماکروسکوپی همان نکروز</strong> هستند.</li><li><strong>ریزنما:</strong> سلولاریته‌ی خیلی زیاد، پلئومورفیسم شدید، میتوز بسیار زیاد در <strong>زمینه‌ی فیبریلری</strong>؛ نکروز با هسته‌های پالیسیدینگ؛ پرولیفراسیون میکروواسکولار.</li><li><strong>ژنتیک:</strong> از دست رفتن عملکرد <strong><bdi>p53</bdi></strong> و <strong><bdi>Rb</bdi></strong>، جهش افزایش عملکرد در مسیر <strong><bdi>PI3K</bdi></strong>؛ در آستروسیتوم‌های درجه‌ی پایین‌تر: جهش <strong><bdi>IDH1/IDH2</bdi></strong>.</li><li><strong>افتراق از آناپلاستیک (درجه‌ی ۳):</strong> پرولیفراسیون عروقی شروع شده ولی هنوز <strong>نکروز ندارد</strong>؛ در <bdi>GBM</bdi> نکروز هست.</li><li><strong>پیلوسیتیک (درجه‌ی ۱):</strong> کودکان، <bdi>BRAF</bdi>، ندول جداری کیستیک، سلول دوقطبی + <strong>فیبر روزنتال</strong> (اجسام ائوزینوفیلیک گرانولر)، <bdi>GFAP</bdi> مثبت؛ نکروز و میتوز معمولاً ندارد.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>یافته</th><th>تومور</th></tr></thead><tbody><tr><td>نکروز پالیسیدینگ + پرولیفراسیون میکروواسکولار + میتوز بسیار زیاد</td><td>گلیوبلاستوما</td></tr><tr><td>فیبر روزنتال + سلول دوقطبی</td><td>آستروسیتوم پیلوسیتیک (<bdi>BRAF</bdi>)</td></tr><tr><td>پالیسیدینگ هسته‌ها در <bdi>Antoni A</bdi> (اجسام <bdi>Verocay</bdi>)</td><td>شوانوما</td></tr><tr><td>پری‌واسکولار سودوروزت</td><td>اپاندیموما</td></tr><tr><td>اجتماع سلول‌های مونومورف دور رگ</td><td>لنفوم اولیه‌ی <bdi>CNS</bdi></td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: پالیسیدینگ هسته‌ها در <bdi>Antoni A</bdi> شوانوما (<bdi>Verocay</bdi>) با «نکروز پالیسیدینگ» <bdi>GBM</bdi> یکی نیست.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) کدام یافته معیار گلیوبلاستوماست؟ (۲) نواحی زرد ماکروسکوپی در توده‌ی مغزی یعنی؟ (۳) تفاوت آناپلاستیک و درجه‌ی ۴ آستروسیتوم؛ (۴) سه ویژگی اصلی <bdi>GBM</bdi>؛ (۵) کدام جزو معیارهای <bdi>GBM</bdi> نیست (فیبر روزنتال)؟</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش آستروسیتوم و گلیوبلاستوما (سه ویژگی اصلی: میتوز زیاد، نکروز، پرولیفراسیون میکروواسکولار)؛ بخش آستروسیتوم پیلوسیتیک (فیبرهای روزنتال).</p>","steps":"<p>سوال معیار تشخیص گلیوبلاستوما (آستروسیتوم درجه‌ی ۴) را می‌خواهد؛ سه‌گانه‌ی <bdi>GBM</bdi>: میتوز بسیار زیاد، نکروز (پالیسیدینگ) و پرولیفراسیون میکروواسکولار.</p>\n<p>اجسام روزنتال (د) مربوط به پیلوسیتیک است؛ هیپرکرومازی (ب) و میتوز چندقطبی (ج) جزو سه‌گانه‌ی <bdi>GBM</bdi> در جزوه نیستند.</p>\n<p>تنها گزینه‌ای که با سه‌گانه‌ی <bdi>GBM</bdi> می‌خواند، نکروز پالیسید است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: پالیسیدینگ هسته‌ها در <bdi>Antoni A</bdi> شوانوما (<bdi>Verocay</bdi>) با «نکروز پالیسیدینگ» <bdi>GBM</bdi> یکی نیست."],"dupOf":null,"dupNote":"","xrefs":["p4q01"]},{"id":"f09","session":"full","full":true,"num":9,"text":"در بررسی هیستوپاتولوژی تومور بطن چهارم مغز پسر بچه 7 ساله‌ای سلولهای تومورال با هسته‌های گرد و منظم با کروماتین گرانولار به همراه ساختارهای <bdi>Rosettes</bdi> & <bdi>perivascular pseudorosettes</bdi> رویت شد. کدام تشخیص مطرح می‌گردد؟","opts":["<bdi>pilocytic astrocytoma</bdi>","<bdi>Glioblastoma</bdi>","<bdi>oligodendroglioma</bdi>","<bdi>Ependymoma</bdi>"],"labels":["الف","ب","ج","د"],"exams":[],"answer":3,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی بهار ۱۴۰۰ (سوال 26)</p><p>کلیدواژه‌ی «اپاندیموما» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p><strong>بطن چهارم</strong> در کودک + سلول‌هایی با <strong>هسته‌ی گرد و منظم و کروماتین گرانولار</strong> + <strong><bdi>Rosette</bdi></strong> و <strong><bdi>perivascular pseudorosette</bdi></strong> = <strong><bdi>Ependymoma</bdi></strong>.</p>\n<ul><li><strong>الف) <bdi>Pilocytic astrocytoma</bdi>:</strong> درجه‌ی ۱، کیستیک با ندول جداری، سلول‌های دوقطبی مومانند، <strong>فیبر روزنتال</strong>، جهش <bdi>BRAF</bdi>؛ سودوروزت ندارد.</li><li><strong>ب) <bdi>Glioblastoma</bdi>:</strong> آستروسیتوم درجه‌ی ۴ با میتوز بسیار زیاد، نکروز (پالیسیدینگ) و پرولیفراسیون میکروواسکولار؛ روزت و سودوروزت ندارد.</li><li><strong>ج) <bdi>Oligodendroglioma</bdi>:</strong> سلول‌های هسته‌ی گرد با هاله‌ی روشن («نیمرو»، <bdi>Fried egg</bdi>)، کاپیلری‌های <bdi>Chicken wire</bdi>، کلسیفیکاسیون، لوب فرونتال/تمپورال و کودلیشن 1<bdi>p/19q</bdi>؛ روزت و سودوروزت در جزوه برای آن نیامده است.</li></ul>","flag":"","lesson":"<ul><li><strong>تعریف:</strong> سلول‌های اپاندیمال اگر تومورال شوند اپاندیموم می‌سازند؛ محل اصلی <strong>بطن‌ها</strong> (سیستم بطنی اپاندیم‌دار) و کانال مرکزی نخاع.</li><li><strong>سن/محل:</strong> در <strong>دو دهه‌ی اول</strong> نزدیک <strong>بطن چهارم</strong> (۵ تا ۱۰ درصد تومورهای اولیه‌ی مغز)؛ در <strong>بزرگسالان نخاع</strong> (کانال نخاعی) شایع‌ترین محل است و ارتباط با <strong>نوروفیبروماتوز ۲ (<bdi>NF2</bdi>)</strong> دارد.</li><li><strong>ماکروسکوپی:</strong> توده‌ی <strong>سالید و پاپیلری</strong> در بطن چهارم که ممکن است به کف بطن گسترش یابد.</li><li><strong>ریزنما:</strong> سلول‌های هسته‌ی گرد و بیضی با <strong>کروماتین دانه‌دار فراوان</strong> در <strong>زمینه‌ی فیبریلری</strong>؛ روزت‌ها و کانال‌ها شبیه کانال اپاندیمال جنینی‌اند و زوائد ظریف و بلند به لومن می‌فرستند.</li><li><strong><bdi>perivascular pseudorosette</bdi>:</strong> زوائد سیتوپلاسمی <strong>بدون هسته</strong> که به سمت <strong>لومن رگ</strong> کشیده شده‌اند.</li><li><strong><bdi>Rosette</bdi> (روزت):</strong> به‌جای رگ، یک <strong>لومن واقعی</strong> (رگ نیست) هست و زوائد به سمت آن کشیده شده‌اند. قاعده: اگر در لومن رگ باشد سودوروزت، اگر رگ نباشد روزت.</li><li><strong>اپاندیموم آناپلاستیک:</strong> تمایز اپاندیمی کمتر؛ مثل آستروسیتوم و الیگودندروگلیوم با افزایش سلولاریته، میتوز و نکروز مشخص می‌شود.</li><li>«نکات تأکیدی استاد»: اپاندیموم = پری‌واسکولار سودوروزت (زوائد به سمت رگ)، روزت (فقط لومن، بدون رگ) و زمینه‌ی فیبریلری؛ مدولوبلاستوما = هومر رایت روزت؛ لنفوم = تجمع سلول‌ها دور رگ که ربطی به سودوروزت ندارد.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>ساختار</th><th>توضیح</th><th>تومور</th></tr></thead><tbody><tr><td><bdi>perivascular pseudorosette</bdi></td><td>زوائد سیتوپلاسمی بدون هسته به سمت لومن رگ</td><td>اپاندیموما</td></tr><tr><td><bdi>Rosette</bdi></td><td>اطراف یک لومن واقعی (رگ نیست)</td><td>اپاندیموما</td></tr><tr><td><bdi>Homer Wright rosette</bdi></td><td>سلول‌ها دور تا دور، سیتوپلاسم وسط، بدون رگ و بدون لومن</td><td>مدولوبلاستوما</td></tr><tr><td>تجمع سلول‌های مونومورف دور رگ</td><td>سلول‌های لنفاوی بدخیم دور رگ</td><td>لنفوم اولیه‌ی <bdi>CNS</bdi> (<bdi>EBV</bdi>، <bdi>Large B-cell</bdi>، نقص ایمنی)</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: لنفوم اولیه‌ی مغز هم دور رگ تجمع می‌کند؛ در سودوروزت زوائد بدون هسته‌ی سلول‌های اپاندیمال به سمت رگ می‌آیند، در لنفوم تکثیر سلول‌های لنفاوی بدخیم دور رگ است.</p>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: بطن چهارم + کودک را مدولوبلاستوما گرفتن؛ مدولوبلاستوما <bdi>Homer Wright rosette</bdi> (بدون رگ و بدون لومن) دارد.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) سودوروزت دورعروقی از مشخصات کدام تومور است؟ (۲) کودک با تومور بطن چهارم؛ (۳) تومور مرتبط با <bdi>NF2</bdi> در نخاع بزرگسال؛ (۴) روزت با لومن واقعی در برابر <bdi>Homer Wright</bdi>؛ (۵) کدام تومور از سلول‌های اپاندیمال می‌آید؟</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش اپاندیموم (پری‌واسکولار سودوروزت، روزت) و جدول مقایسه‌ی روزت/سودوروزت/هومر رایت روزت؛ بخش الیگودندروگلیوم و لنفوم اولیه‌ی <bdi>CNS</bdi>.</p>","steps":"<p>سرنخ‌ها: کودک، بطن چهارم، هسته‌ی گرد منظم با کروماتین گرانولار، <bdi>Rosette</bdi> و <bdi>perivascular pseudorosette</bdi>.</p>\n<p>فیبر روزنتال و سلول دوقطبی = پیلوسیتیک (الف)؛ نکروز پالیسیدینگ = <bdi>GBM</bdi> (ب)؛ «نیمرو» با <bdi>Chicken wire</bdi> = الیگودندروگلیوما (ج).</p>\n<p>سودوروزت دور عروقی و روزت از آن اپاندیموماست.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: لنفوم اولیه‌ی مغز هم دور رگ تجمع می‌کند؛ در سودوروزت زوائد بدون هسته‌ی سلول‌های اپاندیمال به سمت رگ می‌آیند، در لنفوم تکثیر سلول‌های لنفاوی بدخیم دور رگ است.","<span class=\"tag\">نکته‌ی دام</span>خطای رایج: بطن چهارم + کودک را مدولوبلاستوما گرفتن؛ مدولوبلاستوما <bdi>Homer Wright rosette</bdi> (بدون رگ و بدون لومن) دارد."],"dupOf":null,"dupNote":"","xrefs":["p4q04","p4q23"]},{"id":"f10","session":"full","full":true,"num":10,"text":"نوجوان ۱۵ ساله با درد و تورم زانو مراجعه کرده است. در رادیوگرافی ضایعه‌ی مخرب در متافیز دیستال فمور همراه با مثلث کودمن (<bdi>Codman triangle</bdi>) دیده می‌شود و در بافت‌شناسی سلول‌های آتیپیک، ماتریکس استئوئید تولید می‌کنند. تشخیص کدام است؟","opts":["<bdi>Osteosarcoma</bdi>","<bdi>Ewing sarcoma</bdi>","<bdi>Chondrosarcoma</bdi>","<bdi>Giant cell tumor of bone</bdi>"],"labels":["الف","ب","ج","د"],"exams":[],"answer":0,"explain":"<p>این سوال برای کلیدواژه‌ی «استئوسارکوم» طراحی شده است؛ متن اصلی سوال آزمون در دسترس نبود.</p>\n<p>نوجوان ۱۵ ساله + <strong>متافیز دیستال فمور</strong> (اطراف زانو) + ضایعه‌ی مخرب با <strong>مثلث کادمن</strong> + سلول‌های آتیپیک که <strong>ماتریکس استئوئید</strong> می‌سازند = <strong><bdi>Osteosarcoma</bdi></strong>. دیدن استئوئید برای تشخیص ضروری است.</p>\n<ul><li><strong>ب) <bdi>Ewing sarcoma</bdi>:</strong> تومور سلول گرد کوچک (<bdi>small round blue cell</bdi>) با <bdi>t</bdi>(11;22) و <bdi>EWS-FLI1</bdi>، بیشتر <strong>دیافیز</strong> استخوان‌های بلند (و استخوان‌های پهن لگن)، رادیوگرافی «پوست پیازی» و علائم سیستمیک؛ استئوئید نمی‌سازد.</li><li><strong>ج) <bdi>Chondrosarcoma</bdi>:</strong> تومور بدخیم غضروف‌ساز، ۴۰ تا ۶۰ سال، شانه، لگن، فمور پروگزیمال و دنده‌ها؛ از خوب‌تمایزیافته تا آناپلاستیک؛ در گروه غضروف‌ساز است نه استخوان‌ساز.</li><li><strong>د) <bdi>Giant cell tumor of bone</bdi>:</strong> خوش‌خیم ولی تهاجمی موضعی، <strong>اپی‌فیز</strong> در سن ۲۰ تا ۴۰ سال، لیتیک و خارج از مرکز، عود ۴۰ تا ۶۰ درصد؛ میکروسکوپی فاقد استخوان یا غضروف است.</li></ul>","flag":"","lesson":"<ul><li><strong>تعریف:</strong> تومور بدخیمی که <strong>ماتریکس استخوانی (استئوئید)</strong> می‌سازد؛ <strong>دیدن استئوئید برای تشخیص ضروری است</strong>.</li><li><strong>سن/جنس:</strong> ۷۵ درصد بیماران <strong>زیر ۲۰ سال</strong>؛ <strong>پیک دوم بالای ۷۰ سال</strong> (در بیماران مبتلا به پاژه، انفارکت استخوانی یا سابقه‌ی پرتودرمانی)؛ مرد بیش از زن. جدول: استئوسارکوم اولیه ۱۰ تا ۲۰ سال، <strong>متافیز فمور دیستال و تیبیای پروگزیمال</strong>، رشد به خارج و داخل.</li><li><strong>محل:</strong> معمولاً <strong>متافیز</strong> استخوان‌های بلند اطراف زانو، شانه و فک؛ توزیع: <strong>زانو ۶۰٪</strong>، اطراف لگن ۱۵٪، شانه ۱۰٪، فک ۸٪. علت: فعالیت رشدی بسیار زیاد (بیشترین قد از فمور).</li><li><strong>بالینی/رادیولوژی:</strong> توده‌ی دردناک در حال بزرگ شدن؛ حاشیه‌ی نامنظم، قشر پاره شده و گسترش به بافت نرم؛ <strong>مثلث کادمن</strong> در محل بالا آمدن پریوست (<strong>اختصاصی استئوسارکوم نیست</strong>، در پدیده‌هایی که قشر را بالا می‌برند دیده می‌شود).</li><li><strong>متاستاز:</strong> هماتوژن؛ <strong>ریه</strong> جایگاه اصلی؛ ۱۰ تا ۲۰ درصد هنگام تشخیص متاستاز ریوی دارند.</li><li><strong>پاتوژنز:</strong> جهش <strong><bdi>RB</bdi></strong> در ۷۰٪ موارد اسپورادیک (بیماران رتینوبلاستوم ارثی هزار برابر مستعدترند)؛ <strong><bdi>TP53</bdi></strong> (سندرم <bdi>Li-Fraumeni</bdi>)؛ غیرفعال شدن <strong><bdi>INK4a</bdi></strong> (کدکننده‌ی <bdi>p16</bdi> و <bdi>p14</bdi>)؛ <strong><bdi>MDM2</bdi> و <bdi>CDK4</bdi></strong> (مهارکننده‌ی عملکرد <bdi>p53</bdi> و <bdi>RB</bdi>) در بسیاری از انواع کم‌درجه بیش‌بیان می‌شوند.</li><li><strong>ریزنما:</strong> نکروز + ماتریکس استخوانی ناکامل (شبکه‌های نامنظم و تیغه‌های نازک)؛ <strong>استئوئید صورتی شبیه هایف قارچ</strong>. هرچه تمایز بهتر، شبکه‌ها منظم‌تر و سلول بدخیم کمتر؛ هرچه تمایز کمتر، سلول بیشتر و استئوئید کمتر. شایع‌ترین زیرگروه: اولیه، منفرد، داخل مدولاری و کم‌تمایز در متافیز استخوان‌های بلند با ماتریکس غالباً استخوانی. انواع بافت‌شناختی: استئوبلاستیک، کندروبلاستیک، فیبروبلاستیک، تلانژکتاتیک، سلول کوچک، سلول غول‌آسا.</li><li><strong>درمان:</strong> ابتدا <strong>شیمی‌درمانی</strong>، سپس جراحی (قطع عضو یا برداشتن)؛ نمونه‌ی جراحی پس از دکلسیفیکاسیون بررسی می‌شود تا <strong>درصد نکروز</strong> معلوم شود؛ نکروز کامل بدون متاستاز ← بقا ۶۰ تا ۷۰٪. <strong>استئوسارکوم ثانویه</strong> (بعد از پاژه و مانند آن؛ جدول: بالای ۴۰ سال، فمور، هومروس، لگن، چنداستخوانی) تهاجمی‌تر است و به درمان خوب جواب نمی‌دهد.</li></ul>\n<div class=\"tw\"><table><thead><tr><th>تومور</th><th>سن/محل</th><th>نکته‌ی شاخص</th></tr></thead><tbody><tr><td>استئوسارکوم</td><td>۱۰ تا ۲۰ سال، متافیز فمور دیستال/تیبیا</td><td>سلول بدخیم + استئوئید، کادمن</td></tr><tr><td>ایوینگ</td><td>۱۰ تا ۲۰ سال، دیافیز و متافیز</td><td><bdi>t</bdi>(11;22) (<bdi>EWS-FLI1</bdi>)، سلول گرد کوچک، پوست پیازی، علائم سیستمیک</td></tr><tr><td>کندروسارکوم</td><td>۴۰ تا ۶۰ سال، شانه، لگن، فمور پروگزیمال، دنده</td><td>غضروف‌ساز، از خوب‌تمایزیافته تا آناپلاستیک</td></tr><tr><td>سلول غول‌آسا</td><td>۲۰ تا ۴۰ سال، اپی‌فیز</td><td>لیتیک خارج از مرکز، عود ۴۰ تا ۶۰٪</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>خطای رایج: مثلث کادمن را فقط مخصوص استئوسارکوم دانستن؛ تشخیص استئوسارکوم با دیدن استئوئید توسط سلول‌های بدخیم است.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) نوجوان با درد زانو، کادمن و استئوئید؛ (۲) توزیع استئوسارکوم (۶۰٪ زانو)؛ (۳) تومور استخوان با سابقه‌ی رتینوبلاستوم یا <bdi>Li-Fraumeni</bdi>؛ (۴) سالمند پاژه‌ای با توده‌ی استخوانی؛ (۵) کدام تومور برای تشخیص استئوئید نیاز دارد؟ (۶) درمان: شیمی‌درمانی و بررسی نکروز.</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش استئوسارکوم (سن، محل، کادمن، استئوئید، <bdi>RB/TP53/MDM2/CDK4</bdi>، درمان) و جدول تومورهای استخوانی؛ بخش «سایر تومورها» برای ایوینگ/تومور سلول غول‌آسا؛ جزوه‌ی تومورهای استخوان و بافت نرم برای ایوینگ.</p>","steps":"<p>سرنخ‌ها: ۱۵ ساله، درد زانو، متافیز دیستال فمور، مثلث کادمن، و سلول‌هایی که ماتریکس استئوئید می‌سازند.</p>\n<p>ایوینگ (ب) دیافیز و پوست پیازی دارد؛ کندروسارکوم (ج) در سنین ۴۰ تا ۶۰ و غضروف‌ساز است؛ تومور سلول غول‌آسا (د) در اپی‌فیز بزرگسال جوان و بدون استئوئید است.</p>\n<p>تولید استئوئید توسط سلول‌های بدخیم در متافیز زانوی نوجوان = استئوسارکوم.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>خطای رایج: مثلث کادمن را فقط مخصوص استئوسارکوم دانستن؛ تشخیص استئوسارکوم با دیدن استئوئید توسط سلول‌های بدخیم است."],"dupOf":null,"dupNote":"","xrefs":["p3q03"]},{"id":"f11","session":"full","full":true,"num":11,"text":"خانم 22 ساله به توده پایه‌دار دو سانتی‌متری اپی‌فیز استخوان فمور مراجعه کرده است که دارای یک کلاهک غضروفی دیده می‌شود بهترین تشخیص کدام است؟","opts":["استئوکندروم","دیسپلازی فیبرو","کندروما","استئوبلاستوما"],"labels":["الف","ب","ج","د"],"exams":[],"answer":0,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی پاییز ۱۴۰۰ (سوال 21) — تلفیقی بهار ۱۴۰۰ (سوال 19) — تلفیقی 96A (سوال 15)</p><p>کلیدواژه‌ی «استئوکندروما» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p>زائده‌ی <strong>شاخ‌مانند</strong> روی استخوان بلند در سن جوانی با <strong>کلاهک غضروفی</strong> روی آن، تعریف <strong>استئوکندروم (اگزوستوز)</strong> است؛ مغز استخوان تومور با مدولای استخوان زیرین پیوسته است.</p>\n<ul><li><strong>ب) دیسپلازی فیبرو:</strong> ضایعه‌ای با جهش فعال‌کننده‌ی <bdi>GNAS1</bdi> و اسپیکول‌های نازک خمیده در استرومای فیبروز است؛ زائده‌ی شاخ‌مانند با کلاهک غضروفی نمی‌سازد.</li><li><strong>ج) کندروما:</strong> تومور خوش‌خیم غضروف‌ساز با غضروف شبیه غضروف طبیعی در استخوان‌های کوچک دست و پاست؛ زائده‌ی بیرون‌زده‌ی متصل به مدولا نیست.</li><li><strong>د) استئوبلاستوما:</strong> تومور استخوان‌ساز با نمای میکروسکوپی مشابه استئوئید استئوما ولی بزرگ‌تر از ۲ سانتی‌متر است که بیشتر قوس خلفی مهره را درگیر می‌کند؛ کلاهک غضروفی ندارد.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی محل «اپی‌فیز» در متن سوال دقیق نیست (در جزوه استئوکندروم از متافیز استخوان‌های بلند بیرون می‌زند و در شکل جزوه از غضروف اپی‌فیزی رشد می‌کند)؛ با توجه به توده‌ی شاخ‌مانند دارای کلاهک غضروفی، پاسخ استئوکندروم است.","lesson":"<ul><li><strong>تعریف:</strong> استئوکندروما (اگزوستوز) در ارتوپدی بسیار شایع است؛ بر اساس اسلاید جزوه، استئوکندروما و نقص قشری فیبروز <strong>شایع‌ترین ضایعات خوش‌خیم</strong> استخوان‌اند. کلیدواژه‌ی امتحانی: <strong>زائده‌ی شاخ‌مانند + کلاهک غضروفی + راه مدولا به مدولا</strong>.</li><li><strong>سن و محل:</strong> معمولاً <strong>اواخر نوجوانی و ابتدای بزرگسالی</strong>؛ <strong>متافیز استخوان‌های بلند</strong>، معمولاً استخوان‌های کوتاه لوله‌ای را درگیر نمی‌کند (اسلاید: استخوان‌های کوتاه دست و پا نادر؛ گاهی لگن، کتف و دنده‌ها به‌صورت سسیل). ممکن است با سندرم‌ها همراه باشد.</li><li><strong>بالین:</strong> بیمار با درد استخوانی اطراف زانو می‌آید یا یافته‌ی اتفاقی است (برای مشکل دیگری عکس گرفته شده): متافیز زائده‌ای شاخ‌مانند درآورده است.</li><li><strong>نام‌گذاری و بافت‌شناسی:</strong> نام آن از <strong>کلاهک غضروفی</strong> می‌آید که زیر آن اندکی استخوانی شده است (استخوانی‌شدن آندوکندرال). <strong>مشخصه: مغز استخوان تومور و استخوان مادر پیوسته‌اند (راه مدولا).</strong> در بیوپسی پاتولوژیست غضروف را با استخوان زیرین می‌بیند.</li><li><strong>رادیوگرافی (شکل جزوه):</strong> زائده‌ی استخوانی از متافیز با راه مدولاری؛ در شکل ۵۶ رشد آن از غضروف اپی‌فیزی به‌صورت کلاهک غضروفی روی استخوان نشان داده شده است.</li><li><strong>ژنتیک (اسلاید):</strong> اگزوستوزهای ارثی با جهش‌های از دست دادن عملکرد ژرم‌لاین در <strong><bdi>EXT1</bdi> یا <bdi>EXT2</bdi></strong> همراه‌اند؛ <bdi>EXT</bdi> ژن سرکوبگر تومور است که گلیکوزیل‌ترانسفرازهای ضروری برای پلیمریزاسیون هپاران‌سولفات را رمز می‌کند. انواع متعدد در کودکی آشکار می‌شوند.</li><li><strong>خطر بدخیمی (نکته‌ی تأکیدی استاد):</strong> تبدیل به <strong>کندروسارکوم</strong> اگر <strong>کلاهک غضروفی بزرگ‌تر از ۳ سانتی‌متر</strong> باشد یا ضایعه <strong>متعدد/سندرمی</strong> باشد.</li><li><strong>افتراق از شبیه‌ها:</strong></li></ul>\n<div class=\"tw\"><table><thead><tr><th>تومور</th><th>نکته‌ی افتراقی (طبق جزوه)</th></tr></thead><tbody><tr><td>استئوکندروم</td><td>متافیز، شاخ‌مانند، کلاهک غضروفی، مدولای مشترک، خطر کندروسارکوم</td></tr><tr><td>کندروما (انکندروما)</td><td>غضروف خوش‌خیم شبیه غضروف طبیعی؛ استخوان‌های کوچک دست و پا؛ یافته‌ی اتفاقی؛ رادیوگرافی: ضایعه‌ی مرزدار و دانه‌دانه؛ اسلاید: بیماری اولیر (متعدد) و سندرم مافوچی (به‌علاوه‌ی آنژیوم)، جهش <bdi>IDH1/IDH2</bdi></td></tr><tr><td>کندروسارکوم</td><td>میانسال (۴۰ سال یا بیشتر) و بیشتر آقایان، لگن/شانه/دنده، ماکروسکوپی شفاف و آبی‌خاکستری، تمایز = گرید و گرید تعیین‌کننده‌ی پیش‌آگهی</td></tr><tr><td>استئوبلاستوما</td><td>استخوان‌ساز؛ بزرگ‌تر از ۲ سانتی‌متر، قوس خلفی مهره، به آسپرین پاسخ نمی‌دهد، نایدوس ندارد</td></tr><tr><td>دیسپلازی فیبرو</td><td>جهش <bdi>GNAS1</bdi>، اسپیکول‌های نازک خمیده، بدون حاشیه‌ی استئوبلاستی</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: «کندروما» و «استئوکندروما» را یکی نگیرید؛ کندروما غضروف خوش‌خیم استخوان‌های کوچک دست و پاست، استئوکندروما زائده‌ی شاخ‌مانند متافیز با کلاهک غضروفی است. اندازه‌ی ۳ سانتی‌متر کلاهک مرز هشدار بدخیمی است.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) نوجوان با زائده‌ی شاخ‌مانند اطراف زانو + کلاهک غضروفی؛ (۲) «کدام ضایعه‌ی خوش‌خیم استخوان راه مدولا با استخوان مادر دارد»؛ (۳) «اگزوستوز» یا «جهش <bdi>EXT1/EXT2</bdi>»؛ (۴) «کلاهک غضروفی بیش از ۳ سانتی‌متر چه خطری دارد؟» (کندروسارکوم)؛ (۵) تشخیص افتراقی توده‌ی غضروف‌ساز.</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش تومورهای غضروف‌ساز و بخش «فقط در اسلاید» (ژن‌های <bdi>EXT1/EXT2</bdi>، سایر ضایعات استخوانی)</p>","steps":"<p>در صورت سوال به دنبال کلیدواژه‌ها بگردید: توده‌ی <strong>شاخ‌مانند/پایه‌دار</strong>، <strong>کلاهک غضروفی</strong>، محل متافیز استخوان فمور، سن جوان.</p>\n<p>«زائده‌ی شاخ‌مانند با کلاهک غضروفی» یعنی زائده‌ی بیرون‌زده از سطح استخوان که مدولایش به مدولای استخوان مادر وصل است: <strong>استئوکندروم (اگزوستوز)</strong>.</p>\n<p>کندروما (ج) غضروف خوش‌خیم استخوان‌های کوچک دست است، دیسپلازی فیبرو (ب) با <bdi>GNAS1</bdi> و اسپیکول‌های خمیده شناخته می‌شود و استئوبلاستوما (د) استخوان‌ساز است و کلاهک غضروفی ندارد.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: «کندروما» و «استئوکندروما» را یکی نگیرید؛ کندروما غضروف خوش‌خیم استخوان‌های کوچک دست و پاست، استئوکندروما زائده‌ی شاخ‌مانند متافیز با کلاهک غضروفی است. اندازه‌ی ۳ سانتی‌متر کلاهک مرز هشدار بدخیمی است."],"dupOf":null,"dupNote":"","xrefs":["p3q18"]},{"id":"f12","session":"full","full":true,"num":12,"text":"کدامیک از تغییرات زیر جز یافته‌های بافت شناسی آرتریت روماتوئید نمی باشد ؟","opts":["صیقلی شدن استخوان مفصلی","هیپرپلازی سلولهای سینویال","تشکیل پانوس","جوش خوردگی استخوانی مفصل"],"labels":["الف","ب","ج","د"],"exams":[],"answer":0,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی ۲۰ مهر ۱۴۰۱ (سوال 11) — تلفیقی بهار ۱۴۰۱ — تلفیقی پاییز ۱۴۰۰ (سوال 23) — تلفیقی بهار ۱۴۰۰ (سوال 16) — تلفیقی 96A (سوال 16)</p><p>کلیدواژه‌ی «صیقلی شدن مفصل (<bdi>eburnation</bdi>)» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p><strong>صیقلی شدن (<bdi>eburnation</bdi>)</strong> سطح استخوان زیرغضروفی لخت‌شده، تغییر دژنراتیو مفصل (نوع استئوآرتریت) است و جزو یافته‌های التهابی آرتریت روماتوئید (<bdi>RA</bdi>) نیست؛ پس این گزینه یافته‌ی <bdi>RA</bdi> نیست.</p>\n<ul><li><strong>ب) هیپرپلازی سلول‌های سینوویال:</strong> تغییر سینوویوم مفصل در <bdi>RA</bdi> است و جزو یافته‌های آن شمرده می‌شود.</li><li><strong>ج) تشکیل پانوس:</strong> پانوس (بافت التهابی سینوویال که روی سطح مفصل می‌خزد) علامت مشخصه‌ی <bdi>RA</bdi> است.</li><li><strong>د) جوش خوردگی استخوانی مفصل:</strong> آنکیلوز پیامد دیررس التهاب مزمن مفصل است و جزو یافته‌های <bdi>RA</bdi> پیشرفته به‌شمار می‌آید؛ پاسخ سوال نیست.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی جزوه‌ی موجود به‌صراحت درباره‌ی صیقلی شدن مفصل (<bdi>eburnation</bdi>) و یافته‌های آرتریت روماتوئید مطلبی نمی‌گوید؛ پاسخ از متن سوال و گزینه‌ها به‌دست می‌آید.","lesson":"<ul><li><strong>نکته‌ی جزوه:</strong> در جزوه‌ی دکتر پناهی بحث مستقل استئوآرتریت یا آرتریت روماتوئید نیامده است؛ فقط نکات مرتبط زیر در جزوه هست.</li><li><strong>ارتباط با بیماری دژنراتیو مفصل:</strong> انفارکت‌های <strong>زیرغضروفی</strong> در استئونکروز اغلب فرومی‌ریزند و می‌توانند به <strong>بیماری دژنراتیو شدید مفصل</strong> برسند؛ در این حالت غضروف مفصلی هم می‌ریزد و بین غضروف و استخوان فاصله ایجاد می‌شود.</li><li><strong>مفصل کاذب (<bdi>pseudoarthrosis</bdi>):</strong> در عدم جوش خوردن شکستگی، سطح حفره می‌تواند با سلول‌های شبیه سینوویال پوشیده شود.</li><li><strong>درمان موضعی:</strong> کرم/ژل موضعی <bdi>NSAID</bdi> برای <strong>آرتروز (به‌ویژه زانو)</strong> به‌صورت مالشی روی مفصل مصرف می‌شود و جذب موضعی دارد.</li><li><strong>نتیجه برای امتحان:</strong> <bdi>eburnation</bdi> را یافته‌ی تخریب دژنراتیو (آرتروز) و پانوس/هیپرپلازی سینوویال را یافته‌ی التهابی <bdi>RA</bdi> بدانید؛ چون پاسخ سوال از خود گزینه‌ها به‌دست می‌آید.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: در سوال «کدام یافته‌ی <bdi>RA</bdi> نیست؟» گزینه‌ای را انتخاب کنید که نشانه‌ی ساییدگی/تخریب دژنراتیو سطح مفصل است، نه گزینه‌هایی که التهاب سینوویال (هیپرپلازی، پانوس) را نشان می‌دهند.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) «کدام جزو یافته‌های <bdi>RA</bdi> نیست؟» ← <bdi>eburnation</bdi>؛ (۲) «سطح صیقلی استخوان زیرغضروفی در کدام بیماری؟» ← آرتروز (دژنراتیو)؛ (۳) پانوس و هیپرپلازی سینوویال ← <bdi>RA</bdi>.</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش استئونکروز و ترمیم شکستگی؛ جزوه‌ی داروسازی (دکتر رحیمی‌مقدم)، بخش کاربرد ضددرد موضعی</p>","steps":"<p>در صورت «جز یافته‌ها نمی‌باشد» را پیدا کنید: باید گزینه‌ای را بیابید که یافته‌ی <bdi>RA</bdi> نیست.</p>\n<p>هیپرپلازی سینوویال (ب) و پانوس (ج) از یافته‌های التهابی <bdi>RA</bdi> هستند؛ جوش خوردگی (آنکیلوز) مفصل (د) پیامد دیررس التهاب مزمن مفصل است.</p>\n<p>صیقلی شدن (<bdi>eburnation</bdi>) سطح استخوان زیرغضروفی تغییر دژنراتیو (آرتروز) است، نه یافته‌ی <bdi>RA</bdi>.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: در سوال «کدام یافته‌ی <bdi>RA</bdi> نیست؟» گزینه‌ای را انتخاب کنید که نشانه‌ی ساییدگی/تخریب دژنراتیو سطح مفصل است، نه گزینه‌هایی که التهاب سینوویال (هیپرپلازی، پانوس) را نشان می‌دهند."],"dupOf":null,"dupNote":"","xrefs":["p3q07"]},{"id":"f13","session":"full","full":true,"num":13,"text":"کدامیک از انواع استئونکروز معمولا علامتدار شده و منجر به استئوآرتریت می‌شود؟","opts":["انفارکتوس مدولاری","انفارکتوس کورتکس","انفارکتوس ساب کندرال","انفارکتوس ساب پریوستال"],"labels":["الف","ب","ج","د"],"exams":[],"answer":2,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی بهار ۱۴۰۰ (سوال 14) — تلفیقی 96A (سوال 8)</p><p>کلیدواژه‌ی «انفارکتوس ساب‌کندرال» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p>در استئونکروز، <strong>انفارکت زیرغضروفی (<bdi>subchondral</bdi>)</strong> است که ابتدا با <strong>درد هنگام فعالیت</strong> علامت‌دار می‌شود، با گذر زمان فرومی‌ریزد و می‌تواند به <strong>بیماری دژنراتیو شدید مفصل</strong> برسد.</p>\n<ul><li><strong>الف) انفارکتوس مدولاری:</strong> معمولاً <strong>بی‌علامت</strong> است مگر بزرگ باشد (مثل بیماری گوشه و کم‌خونی داسی‌شکل).</li><li><strong>ب) انفارکتوس کورتکس:</strong> طبق جزوه در استئونکروز قشر معمولاً درگیر نمی‌شود، پس علامت‌دار نمی‌شود.</li><li><strong>د) انفارکتوس ساب‌پریوستال:</strong> در جزوه نوع شناخته‌شده‌ی استئونکروز نیست؛ انواع نام‌برده‌شده زیرغضروفی و مدولاری‌اند.</li></ul>","flag":"","lesson":"<ul><li><strong>تعریف:</strong> استئونکروز (نکروز آواسکولار یا آسپتیک): علت <strong>ایسکمی</strong> است.</li><li><strong>علل:</strong> تروما، <strong>استروئیدها</strong>، ترومبوز/آمبولی، آسیب رگی (مثلاً پرتودرمانی)، افزایش فشار داخل استخوان با فشار روی عروق و پرفشاری وریدی. بیشتر موارد به دنبال <strong>شکستگی یا مصرف کورتیکواستروئید</strong> رخ می‌دهند.</li><li><strong>بیماری‌های همراه (جدول جزوه):</strong> ایدیوپاتیک، تروما، کورتیکواستروئید، عفونت، <strong>بیماری کیسون (<bdi>dysbarism</bdi>)</strong>، <strong>کم‌خونی داسی‌شکل</strong> و سایر کم‌خونی‌ها، <strong>بیماری گوشه</strong>، پرتودرمانی، بیماری‌های بافت همبند، حاملگی، اعتیاد به الکل، پانکراتیت مزمن، تومورها، بیماری‌های اپی‌فیزی، بیس‌فسفونات‌ها (به‌ویژه استخوان فک).</li><li><strong>الگو (نکته‌ی جزوه):</strong> <strong>قشر معمولاً درگیر نمی‌شود.</strong> <strong>انفارکت‌های زیرغضروفی</strong> در ابتدا با <strong>درد هنگام فعالیت</strong> بروز می‌کنند که با گذر زمان پایدارتر می‌شود؛ اغلب فرومی‌ریزند و می‌توانند به <strong>بیماری دژنراتیو شدید مفصل</strong> برسند. <strong>انفارکت‌های مدولاری معمولاً بی‌علامت</strong> هستند مگر بزرگ باشند (مثل بیماری گوشه و کم‌خونی داسی‌شکل).</li><li><strong>میکروسکوپی:</strong> استخوان مرده با <strong>صابون کلسیمی</strong> نامحلول؛ استئوکلاست‌ها ترابکول‌های نکروتیک را تحلیل می‌برند و <strong>جایگزینی خزنده (<bdi>creeping substitution</bdi>)</strong> رخ می‌دهد.</li><li><strong>انفارکت زیرغضروفی:</strong> سرعت این جایگزینی <strong>بسیار کند</strong> است و استخوان نکروتیک فرومی‌ریزد، تغییر شکل و شکستگی رخ می‌دهد و حتی غضروف مفصلی می‌ریزد.</li><li><strong>شکل جزوه (سر فمور):</strong> انفارکت زیرغضروفی <strong>گوه‌ای شکل</strong>؛ فضای بین غضروف مفصلی و استخوان به دلیل شکستگی ترابکول‌ها بدون ترمیم است.</li><li><strong>مقایسه:</strong></li></ul>\n<div class=\"tw\"><table><thead><tr><th>نوع انفارکت</th><th>علامت</th><th>سرانجام</th></tr></thead><tbody><tr><td>زیرغضروفی</td><td>درد با فعالیت</td><td>فروریزش ← بیماری دژنراتیو شدید مفصل</td></tr><tr><td>مدولاری</td><td>بی‌علامت مگر بزرگ باشد</td><td>—</td></tr><tr><td>کورتکس</td><td>قشر معمولاً درگیر نمی‌شود</td><td>—</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: «انفارکت مدولاری» را علامت‌دار نکنید (مگر وسیع)؛ هرگاه صحبت از درد فعالیتی، فروریزش و بیماری دژنراتیو مفصل بود، پاسخ انفارکت زیرغضروفی است.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) «کدام نوع استئونکروز علامت‌دار و منجر به بیماری دژنراتیو مفصل می‌شود؟»؛ (۲) بیمار با سابقه‌ی مصرف استروئید یا شکستگی؛ (۳) «در بیماری گوشه یا کم‌خونی داسی‌شکل کدام انفارکت بی‌علامت است؟» (مدولاری)؛ (۴) «کدام یافته‌ی میکروسکوپی: صابون کلسیمی، جایگزینی خزنده»؛ (۵) سر فمور با انفارکت گوه‌ای زیر غضروف.</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، بخش استئونکروز (نکروز آواسکولار) در «فقط در اسلاید»</p>","steps":"<p>عبارت کلیدی سوال: استئونکروزی که <strong>علامت‌دار</strong> می‌شود و به <strong>بیماری دژنراتیو مفصل</strong> می‌رسد.</p>\n<p>انفارکت مدولاری معمولاً بی‌علامت است (مگر بزرگ باشد) و قشر معمولاً درگیر نمی‌شود؛ «ساب‌پریوستال» نوع نام‌برده‌شده در جزوه نیست.</p>\n<p>فقط انفارکت <strong>زیرغضروفی</strong> با درد فعالیتی شروع می‌شود، فرومی‌ریزد و به بیماری دژنراتیو مفصل می‌رسد.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: «انفارکت مدولاری» را علامت‌دار نکنید (مگر وسیع)؛ هرگاه صحبت از درد فعالیتی، فروریزش و بیماری دژنراتیو مفصل بود، پاسخ انفارکت زیرغضروفی است."],"dupOf":null,"dupNote":"","xrefs":["p3q13"]},{"id":"f14","session":"full","full":true,"num":14,"text":"در کدامیک از تومورهای زیر جا بجایی متعادل کروموزم (<bdi>q24</bdi>:<bdi>q12</bdi>)(11:22) دیده می شود؟","opts":["<bdi>Osteosarcoma</bdi>","<bdi>Chondrosarcoma</bdi>","<bdi>Ewing sarcoma</bdi>","<bdi>Giant cell tumor of bone</bdi>"],"labels":["الف","ب","ج","د"],"exams":[],"answer":2,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی ۲۰ مهر ۱۴۰۱ (سوال 12) — تلفیقی بهار ۱۴۰۱ — تلفیقی پاییز ۱۴۰۰ (سوال 20) — تلفیقی بهار ۱۴۰۰ (سوال 17) — تلفیقی 96A (سوال 18)</p><p>کلیدواژه‌ی «یوئینگ» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p>جابه‌جایی <strong><bdi>t</bdi>(11;22)(<bdi>q24</bdi>;<bdi>q12</bdi>)</strong> (همجوشی ژن‌های <bdi>EWS</bdi> و <bdi>FLI1</bdi>) علامت اختصاصی <strong>سارکوم یوئینگ</strong> است؛ استاد صریحاً تأکید کرد که این ترنسلوکیشن را به خاطر بسپارید.</p>\n<ul><li><strong>الف) <bdi>Osteosarcoma</bdi>:</strong> در جزوه با جهش‌های <bdi>RB</bdi> و <bdi>TP53</bdi> (و <bdi>CDK4/MDM2</bdi>) همراه است و تشخیص آن به دیدن استئوئید وابسته است، نه <bdi>t</bdi>(11;22).</li><li><strong>ب) <bdi>Chondrosarcoma</bdi>:</strong> در جزوه با تمایز غضروفی (گرید) و محل لگن/شانه/دنده شناخته می‌شود؛ ترنسلوکیشن <bdi>t</bdi>(11;22) برای آن ذکر نشده است.</li><li><strong>د) <bdi>Giant cell tumor of bone</bdi>:</strong> تومور اپی‌فیزی، موضعاً مهاجم با سلول‌های غول‌آسا و عود زیاد است؛ ترنسلوکیشن <bdi>t</bdi>(11;22) برای آن ذکر نشده است.</li></ul>","flag":"<span class=\"tag\">بررسی کلید</span>کلید رسمی آزمون ثبت نشده است، ولی نوشتار جابه‌جایی در متن سوال به‌هم‌ریخته است؛ آن را <bdi>t</bdi>(11;22)(<bdi>q24</bdi>;<bdi>q12</bdi>) می‌خوانیم که مخصوص سارکوم یوئینگ است.","lesson":"<ul><li><strong>تعریف:</strong> سارکوم یوئینگ = تومور بدخیم <strong>سلول گرد کوچک</strong> (از سلول‌های گرد ابتدایی) با درجه‌ای از <strong>تمایز نورواکتودرمی</strong>؛ در <bdi>PNET</bdi> تمایز عصبی وجود دارد و در <bdi>EWS</bdi> تومور تمایزنیافته است. «خانواده‌ی یوئینگ»: هم در استخوان و هم در بافت نرم دیده می‌شود و ممکن است <bdi>PNET</bdi> نیز نامیده شود.</li><li><strong>سن:</strong> معمولاً <strong>۱۰ تا ۱۵ سال</strong>؛ <strong>۸۰٪ بیماران زیر ۲۰ سال</strong>.</li><li><strong>ژنتیک (نکته‌ی تأکیدی استاد: حتماً به خاطر بسپارید):</strong> <strong><bdi>t</bdi>(11;22)(<bdi>q24</bdi>;<bdi>q12</bdi>)</strong> با ژن همجوش <strong><bdi>EWS-FLI1</bdi></strong> و (کمتر مهم) <strong><bdi>t</bdi>(21;22)(<bdi>q22</bdi>;<bdi>q12</bdi>)</strong> با <bdi>EWS-ERG</bdi>؛ پروتئین کایمریک ← فاکتور رونویسی فعال ← میتوزهای پشت‌سرهم و تکثیر زیاد.</li><li><strong>بالین:</strong> توده‌ی دردناک و بزرگ‌شونده در <strong>دیافیز</strong> استخوان‌های بلند (بیشتر فمور یا اطراف شانه) و گاهی لگن و استخوان‌های پهن؛ <strong>علائم سیستمیک</strong> (تب یا علائم شبیه آنفلوآنزا، مثل لنفوم‌ها) در بعضی بیماران.</li><li><strong>رادیولوژی:</strong> الگوی <strong>پوست‌پیازی (<bdi>onion-skin</bdi>)</strong> از واکنش پریوست.</li><li><strong>میکروسکوپی:</strong> سلول‌های گرد کوچک، هسته‌ها کنار هم، <strong>سیتوپلاسم بسیار کم</strong>، استرومای مشخص ندارند و شبیه لایه‌ی نورواکتودرم جنین‌اند.</li><li><strong>تشخیص افتراقی:</strong> گروه تومورهای سلول گرد کوچک شامل لنفوم، رابدومیوسارکوم و تومورهای نوروآندوکرین است؛ زیر میکروسکوپ قطعی نمی‌شود و باید ایمونوهیستوشیمی، سیتوژنتیک (ترنسلوکیشن مشخص)، محل تومور و سن بیمار را کنار هم گذاشت.</li><li><strong>پیش‌آگهی:</strong> بقای ۵ ساله حدود ۷۵٪ در صورت تشخیص درست. دومین بدخیمی شایع استخوان در کودکان (اسلاید).</li><li><strong>جدول ترنسلوکیشن‌ها (از جدول جزوه):</strong></li></ul>\n<div class=\"tw\"><table><thead><tr><th>تومور</th><th>ترنسلوکیشن</th><th>ژن همجوش</th></tr></thead><tbody><tr><td>سارکوم یوئینگ خارج‌استخوانی و <bdi>PNET</bdi></td><td><bdi>t</bdi>(11;22)(<bdi>q24</bdi>;<bdi>q12</bdi>)</td><td><bdi>FLI-1</bdi>–<bdi>EWS</bdi></td></tr><tr><td>همان تومور</td><td><bdi>t</bdi>(21;22)(<bdi>q22</bdi>;<bdi>q12</bdi>)</td><td><bdi>ERG</bdi>–<bdi>EWS</bdi></td></tr><tr><td>سینوویال سارکوم</td><td><bdi>t</bdi>(<bdi>X</bdi>;18)(<bdi>p11</bdi>;<bdi>q11</bdi>)</td><td><bdi>SYT-SSX</bdi></td></tr><tr><td>لیپوسارکوم میکزوئید و سلول گرد</td><td><bdi>t</bdi>(12;16)(<bdi>q13</bdi>;<bdi>p11</bdi>)</td><td><bdi>CHOP/TLS</bdi></td></tr><tr><td>رابدومیوسارکوم آلوئولار</td><td><bdi>t</bdi>(2;13)(<bdi>q35</bdi>;<bdi>q14</bdi>)</td><td><bdi>PAX3-FKHR</bdi></td></tr><tr><td>تومور سلول گرد کوچک دسموپلاستیک</td><td><bdi>t</bdi>(11;22)(<bdi>p13</bdi>;<bdi>q12</bdi>)</td><td><bdi>EWS-WT1</bdi></td></tr><tr><td>سارکوم سلول روشن</td><td><bdi>t</bdi>(12;22)(<bdi>q13</bdi>;<bdi>q12</bdi>)</td><td><bdi>EWS-ATF1</bdi></td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: چند تومور دیگر هم ژن <bdi>EWS</bdi> و کروموزوم ۲۲ دارند (دسموپلاستیک، سلول روشن و ...) ولی یوئینگ = <strong><bdi>t</bdi>(11;22)(<bdi>q24</bdi>;<bdi>q12</bdi>)</strong>؛ محل = <strong>دیافیز</strong> (برخلاف تومور سلول غول‌آسا = اپی‌فیز).</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) «در کدام تومور <bdi>t</bdi>(11;22) دیده می‌شود؟»؛ (۲) نوجوان با درد، تب و توده‌ی دیافیز فمور و پوست‌پیازی؛ (۳) «تومور سلول گرد کوچک بدخیم جوانان در استخوان و بافت نرم»؛ (۴) «<bdi>EWS-FLI1</bdi>»؛ (۵) محل دیافیز + علائم سیستمیک + شبیه لنفوم.</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی تومورهای استخوان و بافت نرم (دکتر پناهی)، بخش سارکوم یوئینگ و جدول ترنسلوکیشن‌ها؛ جزوه‌ی پاتولوژی استخوان و مفاصل، «فقط در اسلاید»</p>","steps":"<p>ترنسلوکیشن <strong><bdi>t</bdi>(11;22)(<bdi>q24</bdi>;<bdi>q12</bdi>)</strong> را در ذهن به نام تومور وصل کنید.</p>\n<p>استئوسارکوم (<bdi>RB/TP53</bdi>)، کندروسارکوم (گرید غضروفی) و تومور سلول غول‌آسا (اپی‌فیز، عود زیاد) هر کدام ویژگی دیگری دارند و <bdi>t</bdi>(11;22) برایشان ذکر نشده است.</p>\n<p>این ترنسلوکیشن مخصوص <strong>سارکوم یوئینگ</strong> (<bdi>EWS-FLI1</bdi>) است.</p>\n<p>جواب: <strong>ج</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: چند تومور دیگر هم ژن <bdi>EWS</bdi> و کروموزوم ۲۲ دارند (دسموپلاستیک، سلول روشن و ...) ولی یوئینگ = <strong><bdi>t</bdi>(11;22)(<bdi>q24</bdi>;<bdi>q12</bdi>)</strong>؛ محل = <strong>دیافیز</strong> (برخلاف تومور سلول غول‌آسا = اپی‌فیز)."],"dupOf":null,"dupNote":"","xrefs":["p3q08"]},{"id":"f15","session":"full","full":true,"num":15,"text":"در میکروسکوپی تومور کیستیک با مورال ندول در مخچه کودک 5 ساله، آستروسیتوم های کشیده موئی دیده می شوند که جا به جا در مابینشان اجسام روزنتال قرار دارد. میتوز نیز دیده نمی شود. تشخیص تومور کدامیک از موارد زیر می باشد؟","opts":["دیفیوز آستروسیتوم","پیلوسیتیک آستروسیتوم","گلیوبلاستوم","گانگلیوگلیوما"],"labels":["الف","ب","ج","د"],"exams":[],"answer":1,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی ۲۰ مهر ۱۴۰۱ (سوال 18) — تلفیقی پاییز ۱۴۰۰ (سوال 5)</p><p>کلیدواژه‌ی «آستروسیتوم پیلوسیتیک» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p>کودک، <strong>مخچه</strong>، تومور <strong>کیستیک با ندول جداری (<bdi>mural nodule</bdi>)</strong>، سلول‌های دوقطبی با زوائد <strong>موئی (<bdi>hair-like</bdi>)</strong> و <strong>فیبرهای روزنتال</strong> و <strong>بدون میتوز</strong> ← <strong>آستروسیتوم پیلوسیتیک</strong> (<bdi>WHO</bdi> گرید ۱).</p>\n<ul><li><strong>الف) دیفیوز آستروسیتوم:</strong> شایع‌ترین تومور گلیال بزرگسالان (دهه‌ی دوم تا ششم) در نیمکره‌های مخ، با نفوذ به بافت اطراف و زمینه‌ی فیبریلری و جهش <bdi>IDH1/IDH2</bdi> در درجه‌های پایین‌تر؛ فیبر روزنتال و ندول جداری ندارد.</li><li><strong>ج) گلیوبلاستوما:</strong> گرید ۴ با میتوز بسیار زیاد، نکروز (پالیسیدینگ) و پرولیفراسیون میکروواسکولار؛ در سوال میتوز دیده نمی‌شود.</li><li><strong>د) گانگلیوگلیوما:</strong> مخلوطی از سلول‌های گلیال و سلول‌های نورونال (گانگلیون سل با هسته‌ی کناری و سیتوپلاسم زیاد) است و با تشنج تظاهر می‌کند؛ دوقطبی‌های موئی و فیبر روزنتال شاخص آن نیست.</li></ul>","flag":"","lesson":"<ul><li><strong>تعریف:</strong> آستروسیتوم پیلوسیتیک <strong><bdi>WHO</bdi> گرید ۱</strong>، تومور <strong>نسبتاً خوش‌خیم</strong>، معمولاً در <strong>کودکان</strong> (و جوانان) دیده می‌شود.</li><li><strong>محل:</strong> <strong>مخچه</strong>، بطن سوم، <strong>مسیرهای بینایی</strong>، ساقه‌ی مغز، نخاع و گاهی نیمکره‌های مخ (در مغز، نخاع و بطن‌ها).</li><li><strong>ژنتیک:</strong> جهش‌های فعال‌کننده‌ی کیناز سرین–ترئونین <strong><bdi>BRAF</bdi></strong>؛ استاد تأکید کرد که این جهش <strong>معمولاً سوال امتحانی</strong> است.</li><li><strong>ماکروسکوپی:</strong> معمولاً <strong>کیستیک</strong> با <strong>ندول جداری (<bdi>mural nodule</bdi>)</strong> (کیستیک–سالید)؛ اگر سالید باشد معمولاً مرز مشخص دارد.</li><li><strong>میکروسکوپی (دو ویژگی بسیار مهم):</strong> (۱) <strong>سلول‌های دوقطبی (<bdi>bipolar</bdi>)</strong>: در یک قطب هسته و در قطب دیگر زائده‌ی سیتوپلاسمی نازک و موئی (<bdi>hair-like</bdi>)، <strong><bdi>GFAP</bdi> مثبت</strong>؛ (۲) <strong>فیبرهای روزنتال</strong> (اجسام ائوزینوفیلیک و گرانولر). ناحیه‌ی <strong>میکروسیستیک</strong> هم دیده می‌شود؛ <strong>نکروز و میتوز</strong> معمولاً ندارد.</li><li><strong>نکته‌ی تأکیدی استاد:</strong> ویژگی‌ها = گرید ۱، سلول دوقطبی، فیبر روزنتال، <bdi>BRAF</bdi> و <bdi>GFAP</bdi> مثبت؛ فقط با مورفولوژی نمی‌شود تشخیص داد، ابتدا <bdi>IHC</bdi> و در بسیاری موارد مولکولار لازم است.</li><li><strong>مقایسه:</strong></li></ul>\n<div class=\"tw\"><table><thead><tr><th>تومور</th><th>سن/محل</th><th>شاخص (طبق جزوه)</th></tr></thead><tbody><tr><td>پیلوسیتیک</td><td>کودک؛ مخچه و ...</td><td>گرید ۱، کیست + ندول جداری، دوقطبی موئی، روزنتال، <bdi>BRAF</bdi></td></tr><tr><td>مدولوبلاستوما</td><td>کودک؛ خط وسط مخچه</td><td><bdi>small blue cell</bdi>، میتوز بسیار زیاد، <bdi>Homer Wright rosette</bdi></td></tr><tr><td>دیفیوز آستروسیتوم</td><td>بزرگسال؛ نیمکره‌های مخ</td><td>نفوذی، زمینه‌ی فیبریلری، <bdi>IDH1/IDH2</bdi></td></tr><tr><td>گلیوبلاستوما</td><td>بزرگسال</td><td>گرید ۴، میتوز زیاد، نکروز، پرولیفراسیون میکروواسکولار</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: فیبر روزنتال در جزوه به‌عنوان جسم ائوزینوفیلیک آستروسیتوم پیلوسیتیک آمده است؛ «دوقطبی موئی + روزنتال + کودک/مخچه» یعنی پیلوسیتیک. پیلوسیتیک گرید ۱ است و با دیفیوز آستروسیتوم (گرید ۲ تا ۴) فرق دارد.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) کودک با تومور کیستیک مخچه و ندول جداری؛ (۲) «اجسام روزنتال / سلول‌های موئی (<bdi>hair-like</bdi>)»؛ (۳) «جهش <bdi>BRAF</bdi> در کدام گلیوم»؛ (۴) «کدام آستروسیتوم گرید ۱ است؟»؛ (۵) «در کدام تومور میتوز و نکروز معمولاً دیده نمی‌شود؟»</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش آستروسیتوم پیلوسیتیک و آستروسیتوم منتشر</p>","steps":"<p>سرنخ‌ها را بخوانید: کودک، <strong>مخچه</strong>، کیست با <strong>ندول جداری</strong>، سلول‌های <strong>موئی (<bdi>hair-like</bdi>)</strong> و اجسام <strong>روزنتال</strong>، بدون میتوز.</p>\n<p>دیفیوز آستروسیتوم تومور بزرگسالان با زمینه‌ی فیبریلری و نفوذی است، گلیوبلاستوما میتوز بسیار زیاد و نکروز دارد، و گانگلیوگلیوما ترکیب سلول گلیال و گانگلیون سل است.</p>\n<p>این ترکیب یعنی <strong>آستروسیتوم پیلوسیتیک</strong> (گرید ۱، <bdi>BRAF</bdi>).</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: فیبر روزنتال در جزوه به‌عنوان جسم ائوزینوفیلیک آستروسیتوم پیلوسیتیک آمده است؛ «دوقطبی موئی + روزنتال + کودک/مخچه» یعنی پیلوسیتیک. پیلوسیتیک گرید ۱ است و با دیفیوز آستروسیتوم (گرید ۲ تا ۴) فرق دارد."],"dupOf":null,"dupNote":"","xrefs":["p4q02","p4q16"]},{"id":"f16","session":"full","full":true,"num":16,"text":"وجود اجسام وروکی(<bdi>Verocay bodies</bdi>) از مشخصات کدامیک از تومورهای اعصاب محیطی می باشد؟","opts":["شوانوم","نوروفیبروم","<bdi>MPNST</bdi>","<bdi>PNET</bdi>"],"labels":["الف","ب","ج","د"],"exams":[],"answer":0,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی ۲۰ مهر ۱۴۰۱ (سوال 19) — تلفیقی بهار ۱۴۰۱ — تلفیقی پاییز ۱۴۰۰ (سوال 17)</p><p>کلیدواژه‌ی «وروکی-شوانوم» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p><strong>جسم وروکای (<bdi>Verocay body</bdi>)</strong> در ناحیه‌ی <strong>آنتونی <bdi>A</bdi></strong> شوانوما دیده می‌شود: هسته‌ها در ردیف‌های مشخص قرار می‌گیرند و بین آن‌ها ناحیه‌ای با زوائد سیتوپلاسمی بدون هسته است.</p>\n<ul><li><strong>ب) نوروفیبروم:</strong> سلول شوان + ماست‌سل + سلول‌های شبیه فیبروبلاست و پرینوریال در زمینه‌ی دسته‌های کلاژن (<bdi>carrot shavings</bdi>)، بدون کپسول؛ جسم وروکای ندارد.</li><li><strong>ج) <bdi>MPNST</bdi>:</strong> تومور بدخیم بزرگ با مرز نامشخص، پرسلول با پلئومورفیسم و میتوز، <bdi>S100</bdi> و <bdi>SOX10</bdi> در آن فقط ضعیف و کانونی؛ جسم وروکای ندارد.</li><li><strong>د) <bdi>PNET</bdi>:</strong> تومور سلول گرد کوچک ابتدایی با سلول‌های آبی کوچک و هسته‌ی غالب است؛ ردیف‌شدن پالیسیدینگ هسته با نوار بدون هسته ندارد.</li></ul>","flag":"","lesson":"<ul><li><strong>تعریف:</strong> شوانوما = تومور سلول‌های شوان غلاف عصب محیطی (از مهم‌ترین تومورهای بافت نرم)؛ <strong>خوش‌خیم، کپسول‌دار (<bdi>encapsulated</bdi>) و مرزدار</strong>.</li><li><strong>محل:</strong> هر جای سیستم عصبی محیطی و همه‌ی بافت‌ها، اعضای داخلی یا ریشه‌های عصبی نخاع. اگر در عصب مغزی شماره‌ی ۸ (بخش وستیبولار) باشد ← <strong>شوانومای وستیبولار</strong> با <strong>وزوز گوش و کاهش شنوایی</strong>.</li><li><strong>ژنتیک:</strong> معمولاً <strong>اسپورادیک</strong>؛ حدود ۱۰٪ با <strong>نوروفیبروماتوز ۲ (<bdi>NF2</bdi>)</strong> مرتبط‌اند. در <bdi>NF2</bdi> شوانوما، <strong>مننژیوم</strong> و <strong>اپاندیموم</strong> بیشتر دیده می‌شوند. <strong>شوانومای وستیبولار دوطرفه = نشانه‌ی کلاسیک <bdi>NF2</bdi>.</strong></li><li><strong>ماکروسکوپی:</strong> توده‌ی مرزدار مجاور عصب؛ خونریزی یا تغییر کیستیک.</li><li><strong>میکروسکوپی (نکات تأکیدی استاد):</strong> تومور سلول <strong>اسپیندل</strong> با نواحی پرسلول و کم‌سلول (میکزوئید): (۱) <strong>کپسول</strong>؛ (۲) <strong>آنتونی <bdi>A</bdi></strong> (پرسلول؛ سلول‌های ردیفی با زوائد سیتوپلاسمی؛ سلول‌های اسپیندل در دسته‌های متقاطع؛ <strong>جسم وروکای</strong> = ردیف‌های هسته‌ها با ناحیه‌ی بدون هسته بین آن‌ها، پالیسیدینگ) و <strong>آنتونی <bdi>B</bdi></strong> (کم‌سلول)؛ (۳) <strong>عروق هیالینیزه</strong> (دیواره‌ی ضخیم و هیالینیزه)؛ (۴) <bdi>IHC</bdi>: <strong><bdi>S100</bdi> و <bdi>SOX10</bdi></strong> مثبت (نشانگرهای عصبی).</li><li><strong>مقایسه با نوروفیبروما:</strong></li></ul>\n<div class=\"tw\"><table><thead><tr><th>ویژگی</th><th>شوانوما</th><th>نوروفیبروما</th></tr></thead><tbody><tr><td>کپسول</td><td>دارد</td><td>ندارد</td></tr><tr><td>سلول‌ها</td><td>فقط سلول شوان</td><td>شوان + ماست‌سل + شبیه فیبروبلاست + شبیه پرینوریال</td></tr><tr><td>زمینه</td><td>آنتونی <bdi>A/B</bdi>، وروکای، عروق هیالینیزه</td><td>دسته‌های کلاژن موج‌دار (<bdi>carrot shavings</bdi>)، رشد آشفته‌تر</td></tr><tr><td>ژنتیک</td><td><bdi>NF2</bdi> (وستیبولار دوطرفه)</td><td><bdi>NF1</bdi> (پلکسی‌فرم پاتوگنومونیک)</td></tr></tbody></table></div>\n<ul><li><strong><bdi>MPNST</bdi>:</strong> نوروفیبروم بدخیم‌شده (معمولاً از پلکسی‌فرم)، بزرگ، <bdi>poorly defined</bdi>، <bdi>S100/SOX10</bdi> فقط کانونی و ضعیف؛ حدود نیمی در بیماران <bdi>NF1</bdi> (اسلاید).</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: «پلکسی‌فرم = <bdi>NF1</bdi> (نوروفیبروم)» و «وستیبولار دوطرفه = <bdi>NF2</bdi> (شوانوما)»؛ این دو را جابه‌جا نکنید. جسم وروکای مشخصه‌ی شوانوما (آنتونی <bdi>A</bdi>) است.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) «کدام تومور اجسام وروکای دارد؟»؛ (۲) ردیف‌شدن پالیسیدینگ هسته‌ها با نوار بدون هسته؛ (۳) «آنتونی <bdi>A</bdi> و <bdi>B</bdi> / عروق هیالینیزه»؛ (۴) وزوز گوش و کاهش شنوایی + شوانومای وستیبولار دوطرفه ← <bdi>NF2</bdi>؛ (۵) «کدام تومور غلاف عصب کپسول دارد؟»</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> و تومورهای غلاف عصب محیطی (دکتر صداقتی)، بخش شوانوما، نوروفیبروما و <bdi>MPNST</bdi></p>","steps":"<p>«اجسام وروکای» را با ردیف‌شدن پالیسیدینگ هسته‌ها در <strong>آنتونی <bdi>A</bdi></strong> معادل کنید.</p>\n<p>نوروفیبروم کلاژن موج‌دار و بدون کپسول دارد، <bdi>MPNST</bdi> بدخیم و مرز نامشخص است و <bdi>PNET</bdi> تومور سلول گرد کوچک است.</p>\n<p>این ساختار فقط در <strong>شوانوم</strong> دیده می‌شود.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: «پلکسی‌فرم = <bdi>NF1</bdi> (نوروفیبروم)» و «وستیبولار دوطرفه = <bdi>NF2</bdi> (شوانوما)»؛ این دو را جابه‌جا نکنید. جسم وروکای مشخصه‌ی شوانوما (آنتونی <bdi>A</bdi>) است."],"dupOf":null,"dupNote":"","xrefs":["p4q03"]},{"id":"f17","session":"full","full":true,"num":17,"text":"کدامیک از پترن های میکروسکوپی زیر در الیگودندروگلیوما دیده نمی شود؟","opts":["میکروکلسیفیکاسیون","عروق ریز زمینه","سلولهای شبیه تخم مرغی","زمینه نوروپیل"],"labels":["الف","ب","ج","د"],"exams":[],"answer":3,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی ۲۰ مهر ۱۴۰۱ (سوال 21) — تلفیقی بهار ۱۴۰۱ — تلفیقی پاییز ۱۴۰۰ (سوال 22)</p><p>کلیدواژه‌ی «زمینه‌ی نوروپیل» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p>در الیگودندروگلیوما <strong>کلسیفیکاسیون</strong>، <strong>هاله‌ی روشن دور هسته (<bdi>fried egg</bdi>)</strong> و <strong>کاپیلری‌های آناستوموزکننده‌ی ظریف (<bdi>chicken wire</bdi>)</strong> دیده می‌شود؛ <strong>زمینه‌ی نوروپیل</strong> در جزوه مربوط به تومور نورونی (نوروسیتوم مرکزی) است و در توصیف الیگودندروگلیوما نیامده.</p>\n<ul><li><strong>الف) میکروکلسیفیکاسیون:</strong> در حدود ۹۰٪ موارد دیده می‌شود (کلسیفیکاسیون داخل تومور).</li><li><strong>ب) عروق ریز زمینه:</strong> کاپیلری‌های آناستوموزکننده‌ی ظریف (<bdi>chicken wire</bdi>) از هالمارک‌های میکروسکوپی است.</li><li><strong>ج) سلول‌های شبیه تخم‌مرغی:</strong> همان هاله‌ی روشن دور هسته (<bdi>fried egg</bdi>) است و هالمارک الیگودندروگلیوما محسوب می‌شود.</li></ul>","flag":"","lesson":"<ul><li><strong>تعریف:</strong> تومور سلول‌های الیگودندروسیت؛ ۵ تا ۱۵٪ گلیوم‌ها، دهه‌ی چهارم و پنجم زندگی، <strong>نیمکره‌های مخ، معمولاً لوب فرونتال و تمپورال</strong> (محل، به‌ویژه فرونتال، برای تشخیص مهم است).</li><li><strong>ژنتیک:</strong> <strong>کودلیشن 1<bdi>p/19q</bdi></strong>؛ همراه با <strong>پاسخ بسیار خوب به شیمی‌درمانی و رادیوتراپی</strong>؛ پیش‌آگهی بهتر از آستروسیتوم هم‌درجه.</li><li><strong>ماکروسکوپی:</strong> مثل بقیه‌ی گلیال‌ها <strong>انفیلتراتیو</strong> (مرز مشخص ندارد)، ژلاتینی و خاکستری؛ ممکن است کیستیک یا خونریزی‌دهنده باشد و مهم‌تر از همه <strong>کلسیفیکاسیون</strong> دارد.</li><li><strong>میکروسکوپی (هالمارک‌ها):</strong> ورقه‌هایی از سلول‌های منظم با <strong>هسته‌ی گرد کروی</strong> و کروماتین ریزدانه؛ <strong>هاله‌ی روشن (<bdi>clear halo</bdi>، <bdi>fried egg</bdi>)</strong> دور هسته؛ <strong><bdi>chicken wire</bdi></strong> = کاپیلری‌های آناستوموزکننده (با پرولیفراسیون میکروواسکولار گلیوبلاستوما فرق دارد)؛ <strong>کلسیفیکاسیون</strong> (۹۰٪ موارد)؛ فعالیت میتوزی معمولاً کم.</li><li><strong>گرید:</strong> مثل آستروسیتوم به گریدهای ۲، ۳ و ۴ تقسیم می‌شود و بر اساس سلولاریته، میتوز، پلئومورفیسم و پرولیفراسیون میکروواسکولار تعیین می‌شود؛ نوع <strong>آناپلاستیک</strong> تهاجمی‌تر است (سلولاریته‌ی بیشتر، آناپلازی هسته، فعالیت میتوزی).</li><li><strong>زمینه‌ی نوروپیل کجاست؟</strong> <strong>نوروسیتوم مرکزی</strong> (تومور نورونی، معمولاً درجه‌ی پایین و نزدیک بطن‌ها): سلول‌های گرد یکنواخت در زمینه‌ای از نوروپیل (هسته‌های گرد تا بیضی در <strong>جزایر نوروپیل</strong>). تشخیص افتراقی آن الیگودندروگلیوما است که با <bdi>IHC</bdi> و محل جدا می‌شود (نوروسیتوم نزدیک بطن‌ها، الیگودندروگلیوما در لوب فرونتال و تمپورال).</li><li><strong>جدول الگوی میکروسکوپی شاخص (از جزوه):</strong></li></ul>\n<div class=\"tw\"><table><thead><tr><th>تومور</th><th>الگوی شاخص</th></tr></thead><tbody><tr><td>الیگودندروگلیوما</td><td><bdi>fried egg</bdi>، <bdi>chicken wire</bdi>، کلسیفیکاسیون</td></tr><tr><td>آستروسیتوم</td><td>زمینه‌ی فیبریلری</td></tr><tr><td>پیلوسیتیک</td><td>دوقطبی موئی + فیبر روزنتال</td></tr><tr><td>اپاندیموم</td><td>پری‌واسکولار سودوروزت، روزت</td></tr><tr><td>مدولوبلاستوما</td><td><bdi>Homer Wright rosette</bdi></td></tr><tr><td>نوروسیتوم مرکزی</td><td>سلول‌های گرد یکنواخت در زمینه‌ی نوروپیل</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: هاله‌ی روشن (<bdi>fried egg</bdi>) را «ناموجود» نخوانید؛ آن همان سلول شبیه تخم‌مرغ و از هالمارک‌های الیگودندروگلیوما است. زمینه‌ی نوروپیل (جزایر نوروپیل) را به نوروسیتوم مرکزی بسپارید.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) «کدام الگو در الیگودندروگلیوما دیده نمی‌شود؟»؛ (۲) «کدام ویژگی هالمارک الیگودندروگلیوما است؟» (کلسیفیکاسیون، <bdi>fried egg</bdi>)؛ (۳) «<bdi>chicken wire</bdi> چه چیزی را نشان می‌دهد؟»؛ (۴) تفاوت <bdi>chicken wire</bdi> با پرولیفراسیون میکروواسکولار گلیوبلاستوما؛ (۵) افتراق نوروسیتوم مرکزی از الیگودندروگلیوما.</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش الیگودندروگلیوم و تومورهای نورونی (نوروسیتوم مرکزی)</p>","steps":"<p>سوال «دیده <strong>نمی‌شود</strong>» است؛ پس سه گزینه‌ی دیده‌شونده را کنار بگذارید.</p>\n<p>کلسیفیکاسیون، عروق ظریف (<bdi>chicken wire</bdi>) و سلول‌های شبیه تخم‌مرغ (<bdi>fried egg</bdi>) هالمارک‌های الیگودندروگلیوما هستند.</p>\n<p><strong>زمینه‌ی نوروپیل</strong> در جزوه مخصوص تومورهای نورونی (مثل نوروسیتوم مرکزی) است و در الیگودندروگلیوما نیامده.</p>\n<p>جواب: <strong>د</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: هاله‌ی روشن (<bdi>fried egg</bdi>) را «ناموجود» نخوانید؛ آن همان سلول شبیه تخم‌مرغ و از هالمارک‌های الیگودندروگلیوما است. زمینه‌ی نوروپیل (جزایر نوروپیل) را به نوروسیتوم مرکزی بسپارید."],"dupOf":null,"dupNote":"","xrefs":["p4q05"]},{"id":"f18","session":"full","full":true,"num":18,"text":"کدام مولکول که توسط استئوبلاست‌ها ساخته می‌شود، به‌عنوان گیرنده‌ی تله (<bdi>decoy receptor</bdi>) به <bdi>RANKL</bdi> متصل شده و تمایز و فعالیت استئوکلاست را مهار می‌کند؟","opts":["استئوپروتگرین (<bdi>OPG</bdi>)","<bdi>RANK</bdi>","<bdi>M-CSF</bdi>","اینترلوکین ۶"],"labels":["الف","ب","ج","د"],"exams":[],"answer":0,"explain":"<p>این سوال برای کلیدواژه‌ی «استئوپروتگرین (<bdi>OPG</bdi>)» طراحی شده است؛ متن اصلی سوال آزمون در دسترس نبود.</p>\n<p><strong>استئوپروتگرین (<bdi>OPG</bdi>)</strong> را استئوبلاست‌ها می‌سازند و به‌عنوان <strong>گیرنده‌ی تله (<bdi>decoy receptor</bdi>)</strong> در برابر <bdi>RANKL</bdi> عمل می‌کند و از اتصال <bdi>RANKL</bdi> به <bdi>RANK</bdi> جلوگیری می‌کند؛ پس تمایز استئوکلاست مهار می‌شود.</p>\n<ul><li><strong>ب) <bdi>RANK</bdi>:</strong> گیرنده‌ی روی <strong>پیش‌سازهای استئوکلاست</strong> است که با اتصال <bdi>RANKL</bdi>، <bdi>NF</bdi>-κ<bdi>B</bdi> را فعال می‌کند و برای تولید و بقای استئوکلاست ضروری است؛ مهارکننده نیست.</li><li><strong>ج) <bdi>M-CSF</bdi>:</strong> در استئوبلاست ساخته می‌شود و برای تولید و بقای استئوکلاست لازم است؛ گیرنده‌ی تله نیست.</li><li><strong>د) اینترلوکین ۶:</strong> سیتوکین التهابی است که در یائسگی با افزایش بیان <bdi>RANK/RANKL</bdi> فعالیت استئوکلاست را بالا می‌برد.</li></ul>","flag":"","lesson":"<ul><li><strong>نکته‌ی تأکیدی استاد:</strong> شکل کتاب درباره‌ی مسیر <strong><bdi>RANK</bdi></strong> (مسیر بین استئوبلاست و استئوکلاست و عواملی که آن را بالا و پایین می‌برند) <strong>حتماً سوال می‌شود</strong>.</li><li><strong>مسیر:</strong> روی <strong>سلول استرومال/استئوبلاست</strong> لیگاند <strong><bdi>RANKL</bdi></strong> و روی <strong>پیش‌ساز استئوکلاست</strong> گیرنده‌ی <strong><bdi>RANK</bdi></strong> قرار دارد. اتصال آن‌ها (مثلاً در اثر ترشح زیاد <bdi>PTH</bdi>) ← پیش‌ساز بالغ می‌شود و به استئوکلاست تمایز می‌یابد. فعال شدن <bdi>RANK</bdi> ← <strong><bdi>NF</bdi>-κ<bdi>B</bdi></strong> که برای تولید و بقای استئوکلاست ضروری است؛ <strong><bdi>M-CSF</bdi></strong> (ساخته‌شده در استئوبلاست) هم لازم است.</li><li><strong><bdi>OPG</bdi> (اوستئوپروتژرین):</strong> توسط <strong>استئوبلاست‌ها</strong> ساخته می‌شود، <strong>گیرنده‌ی تله (<bdi>decoy receptor</bdi>)</strong> است و با مهار اتصال <bdi>RANKL</bdi> به <bdi>RANK</bdi> عمل می‌کند. پروتئین‌های <strong><bdi>WNT</bdi></strong> تولید <bdi>OPG</bdi> را تحریک می‌کنند.</li><li><strong>تعادل:</strong> افزایش نسبت <strong><bdi>RANK</bdi>:<bdi>RANKL</bdi> به <bdi>OPG</bdi></strong> (فعالیت بیشتر) ← <strong>تحلیل بیشتر</strong>؛ افزایش <bdi>OPG</bdi> ← <strong>ساخت استخوان</strong> ترجیح داده می‌شود.</li><li><strong>عوامل افزایش‌دهنده‌ی تمایز استئوکلاست و گردش استخوان:</strong> <strong><bdi>PTH</bdi>، <bdi>IL-1</bdi></strong> و <strong>گلوکوکورتیکوئیدها</strong>؛ سیستمیک: <strong>ویتامین <bdi>D</bdi></strong> و سیتوکین‌های التهابی.</li><li><strong>عوامل مهارکننده:</strong> <strong><bdi>BMP</bdi>ها</strong> و <strong>هورمون‌های جنسی (استروژن، تستوسترون)</strong> با <strong>افزایش بیان <bdi>OPG</bdi></strong> تمایز استئوکلاست را مهار می‌کنند؛ فرض بر این است که این عوامل با تغییر سطح <strong><bdi>RANK/NF</bdi>-κ<bdi>B</bdi></strong> و <strong><bdi>WNT</bdi>/β-<bdi>catenin</bdi></strong> در استئوبلاست‌ها عمل می‌کنند. شکل ۱۳ جزوه: عوامل مکانیکی، هورمون‌ها، سیتوکین‌ها، <bdi>BMP</bdi>، <bdi>Wnt</bdi> و اسکلروستین تعادل را تنظیم می‌کنند.</li><li><strong>یائسگی:</strong> کاهش استروژن سرم و افزایش <strong><bdi>IL-1</bdi>، <bdi>IL-6</bdi> و <bdi>TNF</bdi></strong> ← افزایش بیان <bdi>RANK/RANKL</bdi> و افزایش فعالیت استئوکلاست.</li><li><strong>جهش‌ها:</strong> جهش‌های ژرم‌لاین در <strong><bdi>OPG</bdi>، <bdi>RANK</bdi> و <bdi>RANKL</bdi></strong> بیماری‌های شدید استخوان ایجاد می‌کنند.</li><li><strong>جدول نقش مولکول‌ها:</strong></li></ul>\n<div class=\"tw\"><table><thead><tr><th>مولکول</th><th>محل/تولید</th><th>اثر</th></tr></thead><tbody><tr><td><bdi>RANKL</bdi></td><td>استرومال/استئوبلاست</td><td>لیگاند؛ تحریک تمایز استئوکلاست</td></tr><tr><td><bdi>RANK</bdi></td><td>پیش‌ساز استئوکلاست</td><td>گیرنده؛ فعال‌سازی <bdi>NF</bdi>-κ<bdi>B</bdi></td></tr><tr><td><bdi>M-CSF</bdi></td><td>استئوبلاست</td><td>لازم برای تولید و بقای استئوکلاست</td></tr><tr><td><bdi>OPG</bdi></td><td>استئوبلاست</td><td>گیرنده‌ی تله برای <bdi>RANKL</bdi>؛ مهار</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: «<bdi>RANK</bdi>» و «<bdi>OPG</bdi>» را اشتباه نگیرید؛ <bdi>RANK</bdi> گیرنده‌ی فعال‌کننده روی پیش‌ساز استئوکلاست است، <bdi>OPG</bdi> گیرنده‌ی تله از استئوبلاست. شکل مسیر <bdi>RANK</bdi> حتماً سوال می‌شود.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) «کدام مولکول گیرنده‌ی تله برای <bdi>RANKL</bdi> است؟»؛ (۲) «کدام عامل نسبت <bdi>RANK</bdi>:<bdi>RANKL</bdi> به <bdi>OPG</bdi> را زیاد می‌کند؟»؛ (۳) «<bdi>WNT</bdi> چگونه تحلیل استخوان را کم می‌کند؟» (↑<bdi>OPG</bdi>)؛ (۴) «جهش‌های ژرم‌لاین <bdi>OPG/RANK/RANKL</bdi>»؛ (۵) کاهش استروژن و <bdi>IL-1/IL-6/TNF</bdi> در یائسگی.</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی استخوان و مفاصل (دکتر پناهی)، مسیر <bdi>RANK/RANKL/OPG</bdi> (نکته‌ی تأکیدی استاد، شکل ۱۲ و ۱۳ و بخش «فقط در اسلاید»)</p>","steps":"<p>جمله‌ی کلیدی: «گیرنده‌ی تله (<bdi>decoy receptor</bdi>) به <bdi>RANKL</bdi>» که استئوبلاست می‌سازد.</p>\n<p><bdi>RANK</bdi> گیرنده‌ی فعال‌کننده است، <bdi>M-CSF</bdi> برای تولید و بقای استئوکلاست لازم است و <bdi>IL-6</bdi> بیان <bdi>RANK/RANKL</bdi> را بالا می‌برد.</p>\n<p>مولکولی که <bdi>RANKL</bdi> را می‌گیرد و استئوکلاست را مهار می‌کند <strong><bdi>OPG</bdi></strong> است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: «<bdi>RANK</bdi>» و «<bdi>OPG</bdi>» را اشتباه نگیرید؛ <bdi>RANK</bdi> گیرنده‌ی فعال‌کننده روی پیش‌ساز استئوکلاست است، <bdi>OPG</bdi> گیرنده‌ی تله از استئوبلاست. شکل مسیر <bdi>RANK</bdi> حتماً سوال می‌شود."],"dupOf":null,"dupNote":"","xrefs":["p3q15"]},{"id":"f19","session":"full","full":true,"num":19,"text":"حذف کروموزوم‌های 1<bdi>p and 19q</bdi> از مشخصات کدام تومور سیستم عصبی مرکزی می باشد؟","opts":["مننژیوم","الیگودندروگلیوما","پیلوسیتیک آستروسیتوما","گلیوبلاستوما"],"labels":["الف","ب","ج","د"],"exams":[],"answer":1,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی ۲۰ مهر ۱۴۰۱ (سوال 24)</p><p>کلیدواژه‌ی «الیگودندروگلیوما: 1<bdi>p</bdi> و 19<bdi>q</bdi>» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p><strong>کودلیشن 1<bdi>p</bdi> و 19<bdi>q</bdi></strong> (دلیشن هم‌زمان بازوی <bdi>p</bdi> از کروموزوم ۱ و بازوی <bdi>q</bdi> از ۱۹) ویژگی بسیار مهم مولکولی <strong>الیگودندروگلیوم</strong> است و برای تشخیص قطعی باید حتماً بررسی شود.</p>\n<ul><li><strong>الف) مننژیوم:</strong> در جزوه با نوروفیبروماتوز ۲ و جهش از دست دادن عملکرد در کروموزوم ۲۲ مرتبط است، نه 1<bdi>p/19q</bdi>.</li><li><strong>ج) پیلوسیتیک آستروسیتوما:</strong> با جهش فعال‌کننده‌ی <bdi>BRAF</bdi> مشخص می‌شود.</li><li><strong>د) گلیوبلاستوما:</strong> جهش از دست دادن عملکرد در <bdi>p53</bdi> و <bdi>Rb</bdi> و جهش افزایش عملکرد در مسیرهای انکوژنیک <bdi>PI3K</bdi>؛ 1<bdi>p/19q</bdi> مطرح نشده است.</li></ul>","flag":"","lesson":"<ul><li><strong>تعریف:</strong> الیگودندروگلیوم = تومور سلول‌های الیگودندروسیت؛ <strong>۵ تا ۱۵٪ گلیوم‌ها</strong>، دهه‌ی چهارم و پنجم زندگی، <strong>نیمکره‌های مخ، معمولاً فرونتال و تمپورال</strong>.</li><li><strong>ویژگی مولکولی مهم:</strong> <strong>دلیشن کروموزوم 1<bdi>p</bdi> و 19<bdi>q</bdi> (<bdi>co-deletion</bdi>)</strong>؛ <bdi>p</bdi> و <bdi>q</bdi> بازوهای کروموزوم هستند؛ <strong>هم‌زمانی دلیشن هر دو</strong> تشخیص را قطعی می‌کند.</li><li><strong>نکته‌ی تأکیدی استاد (تشخیص):</strong> گاهی الیگودندروگلیوم از آستروسیتوم قابل افتراق <strong>نیست</strong>؛ برای تشخیص قطعی باید حتماً دلیشن را بررسی کنیم. اگر مورفولوژی الیگودندروگلیوم باشد ولی دلیشن نداشته باشد، نمی‌توانیم اسم الیگودندروگلیوم بگذاریم.</li><li><strong>پیش‌آگهی/درمان:</strong> کودلیشن 1<bdi>p/19q</bdi> با <strong>پاسخ بسیار خوب به شیمی‌درمانی و رادیوتراپی</strong> همراه است؛ پیش‌آگهی بهتر از آستروسیتوم هم‌درجه (آستروسیتوم‌های درجه‌ی پایین هم پیش‌آگهی خوبی دارند، اما این بهتر است).</li><li><strong>ماکروسکوپی:</strong> انفیلتراتیو، ژلاتینی-خاکستری؛ ممکن است کیستیک یا خونریزی‌دهنده باشد و <strong>کلسیفیکاسیون</strong> دارد.</li><li><strong>میکروسکوپی:</strong> سلول‌های منظم با هسته‌ی گرد کروی و <strong>هاله‌ی روشن (<bdi>fried egg</bdi>)</strong>، <strong><bdi>chicken wire</bdi></strong>، <strong>کلسیفیکاسیون</strong> (۹۰٪)، فعالیت میتوزی معمولاً کم؛ نوع آناپلاستیک (درجه‌ی <bdi>III/IV</bdi>): سلولاریته‌ی بالاتر، آناپلازی هسته، فعالیت میتوزی.</li><li><strong>گرید:</strong> مثل آستروسیتوم به گریدهای ۲ و ۳ و ۴ تقسیم می‌شود و بر اساس سلولاریته، میتوز، پلئومورفیسم و پرولیفراسیون میکروواسکولار تعیین می‌گردد.</li><li><strong>جدول نشانگرهای مولکولی تومورهای <bdi>CNS</bdi> (طبق جزوه):</strong></li></ul>\n<div class=\"tw\"><table><thead><tr><th>تومور</th><th>نشانگر</th></tr></thead><tbody><tr><td>الیگودندروگلیوم</td><td>کودلیشن 1<bdi>p/19q</bdi></td></tr><tr><td>پیلوسیتیک آستروسیتوم</td><td>جهش <bdi>BRAF</bdi></td></tr><tr><td>آستروسیتوم درجه‌ی پایین</td><td>جهش <bdi>IDH1/IDH2</bdi></td></tr><tr><td>گلیوبلاستوما</td><td>از دست دادن <bdi>p53</bdi> و <bdi>Rb</bdi>؛ افزایش عملکرد <bdi>PI3K</bdi></td></tr><tr><td>مننژیوم</td><td><bdi>NF2</bdi>؛ جهش در کروموزوم 22</td></tr></tbody></table></div>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: 1<bdi>p/19q</bdi> را به آستروسیتوم نسبت ندهید (در جزوه آستروسیتوم درجه‌ی پایین = <bdi>IDH1/IDH2</bdi>). «دلیشن هر دو» تشخیص را قطعی می‌کند، نه یکی از آن‌ها.</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) «دلیشن 1<bdi>p</bdi> و 19<bdi>q</bdi> از مشخصات کدام تومور <bdi>CNS</bdi> است؟»؛ (۲) «تشخیص قطعی الیگودندروگلیوم نیازمند چه مطالعه‌ای است؟»؛ (۳) «<bdi>fried egg + chicken wire</bdi> + کلسیفیکاسیون»؛ (۴) «کدام تومور گلیال پیش‌آگهی بهتر از آستروسیتوم هم‌درجه و پاسخ خوب به شیمی‌درمانی دارد؟»؛ (۵) نشانگر مولکولی هر تومور <bdi>CNS</bdi>.</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش الیگودندروگلیوم، آستروسیتوم، گلیوبلاستوما، مننژیوم</p>","steps":"<p>«دلیشن 1<bdi>p</bdi> و 19<bdi>q</bdi>» یک سرنخ مولکولی قطعی است.</p>\n<p>مننژیوم با <bdi>NF2</bdi>/کروموزوم ۲۲، پیلوسیتیک با <bdi>BRAF</bdi> و گلیوبلاستوما با <bdi>p53/Rb</bdi> و <bdi>PI3K</bdi> شناخته می‌شوند.</p>\n<p>تومور دارای کودلیشن 1<bdi>p/19q</bdi> <strong>الیگودندروگلیوم</strong> است.</p>\n<p>جواب: <strong>ب</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: 1<bdi>p/19q</bdi> را به آستروسیتوم نسبت ندهید (در جزوه آستروسیتوم درجه‌ی پایین = <bdi>IDH1/IDH2</bdi>). «دلیشن هر دو» تشخیص را قطعی می‌کند، نه یکی از آن‌ها."],"dupOf":null,"dupNote":"","xrefs":["p4q08"]},{"id":"f20","session":"full","full":true,"num":20,"text":"شایعترین ژرم سل تومور اولیه مغزی، در غده پینه آل کدامیک از موارد زیر است؟","opts":["ژرمینوما","مننزیوما","اپاندیموما","تراتوم"],"labels":["الف","ب","ج","د"],"exams":[],"answer":0,"explain":"<p class=\"src\">تکرار در آزمون‌ها: تلفیقی ۲۰ مهر ۱۴۰۱ (سوال 22)</p><p>کلیدواژه‌ی «ژرمینوما» را با این سوال نشان داده‌ایم؛ سوال اصلی آزمون ممکن است با این متن فرق داشته باشد.</p>\n<p><strong>ژرمینوم</strong> شایع‌ترین تومور سلول زایای اولیه‌ی <bdi>CNS</bdi> است؛ تومورهای سلول زایا تومور افراد جوان و خط وسط‌اند و محل‌های آن‌ها <strong>پینه‌آل</strong> و <strong>ناحیه‌ی سوپراسلار</strong> است (در پینه‌آل غلبه‌ی جنس مرد).</p>\n<ul><li><strong>ب) مننژیوما:</strong> تومور سلول‌های مننگوتلیال پرده‌ی مننژ است (بیشتر در بزرگسالان)، نه سلول زایا.</li><li><strong>ج) اپاندیموما:</strong> تومور سلول‌های اپاندیمال بطن‌ها (بطن چهارم در دو دهه‌ی اول) است و پری‌واسکولار سودوروزت دارد؛ سلول زایا نیست.</li><li><strong>د) تراتوم:</strong> در جزوه شایع‌ترین تومور سلول زایای اولیه‌ی <bdi>CNS</bdi> ژرمینوم معرفی شده است، نه تراتوم.</li></ul>","flag":"","lesson":"<ul><li><strong>جایگاه در دسته‌بندی:</strong> دسته‌های تومورهای اولیه‌ی <bdi>CNS</bdi> در اسلاید: گلیوم‌ها؛ تومورهای نورونی؛ امبریونال (پریمیتیو)؛ <strong>تومورهای سلول زایا (<bdi>Germ Cell</bdi>)</strong>؛ مننژیوم‌ها؛ لنفوم.</li><li><strong>سن/جنس:</strong> تومور <strong>افراد جوان</strong> (۹۰٪ در دو دهه‌ی اول)؛ در <strong>ناحیه‌ی پینه‌آل غلبه‌ی جنس مرد</strong>.</li><li><strong>محل:</strong> <strong>خط وسط</strong>؛ <strong>پینه‌آل</strong> و <strong>ناحیه‌ی سوپراسلار</strong>.</li><li><strong>فراوانی:</strong> ۰٫۲ تا ۱٪ تومورهای مغزی.</li><li><strong>کلید امتحانی:</strong> <strong>شایع‌ترین تومور سلول زایای اولیه‌ی <bdi>CNS</bdi> = ژرمینوم.</strong></li><li><strong>مقایسه با تومورهای دیگر در گزینه‌ها:</strong> مننژیوم از سلول‌های مننگوتلیال و بیشتر در بزرگسالان است؛ اپاندیموم از سلول‌های اپاندیمال بطن‌ها (بطن چهارم در دو دهه‌ی اول) با پری‌واسکولار سودوروزت؛ مدولوبلاستوما تومور امبریونال کودکان در مخچه با <bdi>Homer Wright rosette</bdi>.</li></ul>\n<p class=\"trap\"><span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: در پینه‌آل غلبه‌ی جنس مرد و سن جوان را فراموش نکنید؛ «سلول زایا» یعنی ژرمینوم (شایع‌ترین).</p>\n<ul><li><strong>الگوهای سوال:</strong> (۱) «شایع‌ترین تومور سلول زایای اولیه‌ی <bdi>CNS</bdi>؟»؛ (۲) «تومور افراد جوان، خط وسط، پینه‌آل و سوپراسلار»؛ (۳) «در پینه‌آل غلبه با کدام جنس است؟» (مرد)؛ (۴) «۹۰٪ در دو دهه‌ی اول زندگی».</li></ul><p class=\"ref\">منبع: جزوه‌ی پاتولوژی <bdi>CNS</bdi> (دکتر صداقتی)، بخش تومورهای سلول زایا («فقط در اسلاید»)، همراه با دسته‌بندی تومورهای اولیه‌ی <bdi>CNS</bdi></p>","steps":"<p>عبارت «ژرم سل تومور» و «غده‌ی پینه‌آل» را بگیرید.</p>\n<p>مننژیوما و اپاندیموما سلول زایا نیستند؛ در جزوه شایع‌ترین تومور سلول زایای <bdi>CNS</bdi> ژرمینوم است، نه تراتوم.</p>\n<p>شایع‌ترین تومور سلول زایای <bdi>CNS</bdi> و پینه‌آل <strong>ژرمینوم</strong> است.</p>\n<p>جواب: <strong>الف</strong></p>","traps":["<span class=\"tag\">نکته‌ی دام</span>تله‌ی رایج: در پینه‌آل غلبه‌ی جنس مرد و سن جوان را فراموش نکنید؛ «سلول زایا» یعنی ژرمینوم (شایع‌ترین)."],"dupOf":null,"dupNote":"","xrefs":["p4q06"]}],"cfg":{"storageKey":"rheumqb","title":"بانک سوالات تلفیقی روماتولوژی","kicker":"INTEGRATED RHEUMATOLOGY · QUESTION BANK","h1a":"بانک سوالات","h1b":"تلفیقی روماتولوژی","credit":"@mhya_s","lastLabel":"آخرین دوره تابستان ۱۴۰۵","lastShort":"آخرین دوره","lastSub":"تابستان ۱۴۰۵","lastSlug":"summer-1405","exams":[["summer-1405","آخرین دوره تابستان ۱۴۰۵","mustard"],["mehr1401","تلفیقی ۲۰ مهر ۱۴۰۱","navy"],["spring1401","تلفیقی بهار ۱۴۰۱","mustard"],["fall1400","تلفیقی پاییز ۱۴۰۰","rust"],["spring1400","تلفیقی بهار ۱۴۰۰","teal"],["t96a","تلفیقی 96A","ink"],["pharma-96a","فارما 96A","navy"]],"exportPrefix":"rheum-qb-progress","examKindPrefix":{},"searchExample":"«آسپرین» یا «astrocytoma»"}};